\section{Fredholm Theory for Moduli Spaces}\label{Chapter1}
In this section, we establish that our moduli spaces of interest are given as zeros of a Fredholm map. Under the assumption of transversality, this means that they are smooth manifolds of finite dimension.
\subsection{The Infinite Dimensional Setup}\label{SecInfDimSetup}
Let $(M,\omega)$ be an exact symplectic manifold together with a time-independent Hamiltonian $H\in C^\infty(M,\R)$. Writing $\S\vcentcolon =\R/\Z$, the \emph{loop space}  of $M$ is $\loops{M} \vcentcolon = C^\infty(\S,M)$.  

\definition\label{defFuncs} Let $\omega =\d\lambda$. The \emph{(negative) symplectic area functional} is given by
\begin{align*}
\act{} : \loops{M} \nach \R,\text{ } &\gamma\auf -\int\limits_{\S} \gamma\star\lambda,
\intertext{and the \emph{(Hamiltonian) mean value functional} by} 
h : \loops{M} \nach \R, \text{ }&\gamma\auf \int\limits_0^1 H(\gamma(t))\d t. 
\end{align*} 

To fix notation, we state the following standard definition and result:
\definition An \emph{almost complex structure} on $(M,\omega)$ is a smooth section\linebreak $J\in\Gamma\ndo{\tang{}{M}}$ with the property $J^2 = -\id$. It is called \emph{$\omega$-compatible}, if $\omega(\cdot,J\cdot)$ is a Riemannian metric on $M$.

\begin{lemma}\label{lemGrad} There exists a unique vector field $X_H\in\vec{M}$ with $\d H = \omega(\cdot,X_H)$. Similarly, for any Riemannian metric $g$ on $M$, there exists a unique vector field $\nabla H\in\vec{M}$ with $\d H = g(\nabla H,\cdot)$. Further, if $g=\omega(\cdot,J\cdot)$ for some almost complex structure $J$, then $\nabla H = -JX_H$.\end{lemma}

Since $\loops{M}$ is only a Fréchet space, we trade smoothness for completeness:

\theorem\label{thmBanach} For $p> 1$, the \emph{weak loop space}  $\loops[p]{M} \vcentcolon = W^{1,p}(\S,M)$ is a Banach manifold. Its tangent space at $\gamma\in\loops[p]{M}$ is given by the Banach space
\begin{equation*}
\tang{\gamma}{\loops[p]{M}} = W^{1,p}(\S,\gamma\star\tang{}{M})  =\menge{X \in W^{1,p}(\S,\tang{}{M}) : X(t)\in\tang{\gamma(t)}{M} \text{ for all }t\in\S}.
\end{equation*} 
\proof  This is a standard result in Floer and Morse theory: 
It relies on the fact that at every point $x\in M$ of a Riemannian manifold $(M,g)$, there exists a $r(x)>0$ called the \emph{injectivity radius}, as well as an open neighborhood $U\subset M$ of $x$, so that $\exp_x : B_{r(x)}(0)\subset\tang{x}{M}\nach U$ is a bijection. So for $\gamma\in\loops[p]{M}$, any $X$ in \begin{equation}\label{eqDefCharts}V_\gamma\vcentcolon =\{X\in W^{1,p}(\S,\gamma\star\tang{}{M}) : X(t)\in B_{r(\gamma(t))}(0) \text{ for all } t\in\S\}\end{equation} gives rise to a unique loop via $ X\auf \exp_\gamma X$ (in particular,  $0\auf\gamma$). This map is well defined for $p>1$: By Morrey's theorem\footnote{Cf. \cite{Brezis}, Theorem 9.12.}, each equivalence class in $W^{1,p}(\S,M)$ has a representative in $C^0(\S,M)$. The local charts\footnote{For more details like compatibility, see e.g. \cite{SchwarzMorse}, Appendix A.} of $\loops[p]{M}$ are then given by $(V_\gamma,\exp_\gamma)$, and from this the characterization of the tangent space also follows.\qed

Despite being defined for smooth loops, $\act{}$ and $h$ still work in the weak setting:

\lemma\label{lemDiff}  For $p>1$, the two functionals from \aref{defFuncs} are well-defined on $\loops[p]{M}$, 
and their differentials at $\gamma\in\loops[p]{M}$ are given by
\begin{align*}
\d \act{}_\gamma : \tang{\gamma}{\loops[p]{M}}\nach\R,\text{ } &X\auf \int\limits_0^1 \omega_{\gamma(t)}(\partial_t \gamma(t),X(t))\d t,\\
\d h_\gamma : \tang{\gamma}{\loops[p]{M}}\nach\R,\text{ } &X\auf \int\limits_0^1 \d H_{\gamma(t)}(X(t))\d t. 
\end{align*} 
\proof  See \aref{secAuxProofs}.\qed

\notation When the specific choice of $p>1$ from   \aref{thmBanach} and  \aref{lemDiff} is not important, we will also use $\loops{M}$ to denote the weak loop space $\loops[p]{M}$.

\lemma\label{lemReg} If $0$ is a \emph{regular value} of $H$, i.e. if $\d H_x$ is surjective at all $x\in H\inv(0)$, then $\d h_\gamma(\nabla H|_\gamma)>0$ for all $\gamma\in h\inv(0)$. In particular, $0$ is also a regular value of $h$.
\proof If $h(\gamma)=0$, then by the intermediate value theorem\footnote{Like in the proof of   \aref{thmBanach}, $\gamma\in\loops[p]{M}$ is assumed to be continuous.} for $t\auf H(\gamma(t))$, there has to exist at least one $t_0\in\S$ with $H(\gamma(t_0))=0$. Surjectivity of $\d H_{\gamma(t_0)}$ translates into  $\nabla H(\gamma(t_0))\neq 0$ due to   \aref{lemGrad}, and so continuity yields an $\eps>0$ as well as a constant $C>0$, so that $\norm{\nabla H(\gamma(t))}^2\geq C> 0$ for all $t\in (t_0-\eps,t_0+\eps)$, implying:
\begin{align*}
\d h_\gamma(\nabla H|_\gamma) &= \int\limits_0^1 \d H_{\gamma(t)} (\nabla H(\gamma(t)))\d t\\
&= \int\limits_0^1 \underbrace{g(\nabla H(\gamma(t)),\nabla H(\gamma(t)))}_{\geq 0}\d t\\
&\geq \int\limits_{t_0-\eps}^{t_0+\eps} \underbrace{\norm{\nabla H(\gamma(t))}^2}_{\geq C}\d t\\
&\geq 2C\eps \\
&>0
\end{align*}\nopagebreak
This already shows surjectivity, since $\d h_\gamma$ is linear and $\dim(\im\d h_\gamma) = 1$.\qed

\remark For the rest of the section, we assume that $0$ is a regular value of $H$.

\theorem\label{thmSub} The \emph{constrained loop space} $\H \vcentcolon = h\inv(0)$ is a Banach submanifold of $\loops{M}$ with codimension $1$. Its tangent space at $\gamma\in\H$ is given by the Banach space
\begin{equation*}
    \tang{\gamma}{\H} = \ker\d h_\gamma = \{X\in\tang{\gamma}{\loops{M}} : \d h_\gamma(X) = 0\}.
\end{equation*}
\proof \aref{lemReg} implies $\d h_\gamma(\nabla H|_\gamma)\neq 0$ for all $\gamma\in\H$, so \aref{thmBanachSub} applies.\qed

\corollary\label{cor4.3} At every $\gamma\in\H$, the following decomposition holds:
\begin{align}\label{eqSplitting2}\nonumber T_\gamma \loops{M} &= T_\gamma\H\oplus\langle\nabla H|_\gamma\rangle\\
&\cong T_\gamma\H\times\R\end{align}
\proof  Follows immediately from  \aref{lemReg} and (the proof of) \aref{thmBanachSub}.\qed

\definition \begin{enumerate}
    \item  The \emph{(mean value)-constrained action functional} is defined as $$\act{H} \vcentcolon = \act{}|_\H.$$
    \item At any $\gamma\in\loops{M}$, the \emph{$L^2$-scalar product} on $\tang{\gamma}{\loops{M}}$ is given by
   $$\langle \cdot,\cdot\rangle  \vcentcolon = \int\limits_{\S} g_{\gamma(t)}(\cdot,\cdot)\d t.$$
If $\gamma\in\H$, then the \emph{induced scalar product} on $\tang{\gamma}{\H}$ is given by
    $$\langle\cdot,\cdot\rangle_\H \vcentcolon = \langle \iota \cdot,\iota\cdot\rangle,$$
where $\iota:\tang{\gamma}{\H}\nach\tang{\gamma}{\loops{M}}$ is the canonical identification $w\auf w$.
    \item The \emph{gradient} $\nabla\act{H}(\gamma)$ of $\act{H}$ at $\gamma\in\H$ is defined by $$\d\act{H}_\gamma=\langle\nabla\act{H}(\gamma),\cdot\rangle_\H.$$
\end{enumerate}
\remark The gradient of $\act{}$ at some $\gamma\in\H$ will usually lie in $\tang{\gamma}{\loops{M}}$, so we have to subtract \glqq the part orthogonal to $\H$\grqq{} to get $\nabla\act{H}(\gamma)\in\tang{\gamma}{\H}$: 
\lemma Let $\gamma\in\H$, then \begin{equation}\label{grada} \nabla\act{H}(\gamma) = J(\gamma)\partial_t \gamma +\mult(\gamma) \nabla H|_\gamma\end{equation} holds with the \emph{constraint factor}\begin{equation}\label{defMult}\mult(\gamma) \vcentcolon= -\dfrac{\d\act{}_\gamma( \nabla H|_\gamma)}{\d h_\gamma( \nabla H|_\gamma)}.\end{equation}
\proof From \aref{lemDiff} and $g=\omega(\cdot,J\cdot)$, it is immediate that $\nabla\act{}(\gamma) = J(\gamma)\partial_t \gamma$ and $\nabla h(\gamma)= \nabla H|_\gamma$, so the result follows from \aref{thmGradBanach}.\qed

Now we can state the main motivation for considering $\act{H}$ in the first place: It allows us to find (smooth) periodic orbits of $X_H$ that live inside the zero-set of $H$.

\definition\label{defCrit} The \emph{critical points} of $\act{H}$ are defined as \begin{align*}
    \crit{\act{H}} &\vcentcolon = \menge{\gamma\in\H : \d\act{H}_\gamma = 0}\\
    &\hphantom{:}= \menge{\gamma\in\H : \nabla\act{H}(\gamma)=0}.
\end{align*} 

\theorem\label{thmHam} A loop $\gamma\in\H$ is a critical point of $\act{H}$, if and only if $\gamma \in C^\infty(\S,M)$  is a solution of \begin{equation}\label{eqHam}\partial_t\gamma(t)=\mult(\gamma) X_H(\gamma(t))\end{equation} with $\gamma(t)\in H\inv(0)$ for all $t\in\S$.

\proof  With $\nabla H = -JX_H$ from   \aref{lemGrad}, it is evident that in the case of $\nabla\act{H}(\gamma)=0$, \labelcref{grada} is equivalent to \labelcref{eqHam}. However,  $\gamma$ a priori only has $W^{1,p}$-regularity.

To prove smoothness, we use a technique known as \emph{bootstrapping}: As was already used in the proofs of   \aref{thmBanach} and   \aref{lemDiff}, $\gamma$ can be assumed to be continuous. This in turn means that $$t\auf \mult(\gamma)X_H(\gamma(t))$$ is also continuous, so because of \labelcref{eqHam} this property also follows for $t\auf \partial_t\gamma(t)$.\newline
In other words, we have shown that $\gamma\in W^{2,p}(\S,M)$. Repeating this reasoning inductively, we see that $\gamma$ has arbitrarily high  (weak) regularity and so  the Sobolev embedding theorem guarantees even classical smoothness.

Now, \labelcref{eqHam} implies that $t\auf H(\gamma(t))$ is constant due to
\begin{align*}
    \ddt{t} H(\gamma(t)) &= \d H_{\gamma(t)}(\partial_t\gamma(t))\\
    &= \omega_{\gamma(t)}(\partial_t\gamma(t),X_H(\gamma(t)))\\
    &\overset{\labelcref{eqHam}}{=} \mult(\gamma)\omega_{\gamma(t)}(X_H(\gamma(t)),X_H(\gamma(t)))\\
    &= 0,
\end{align*}
and because of $$h(\gamma)=\int\limits_0^1 H(\gamma(t))\d t=0,$$ this constant has to be $0$.\qed







