\subsection{Completions of Liouville Domains}\label{secSympSetup}
Before proceeding with the Fredholm theory, let us fix the type of manifold we are interested in and define a canonical form of $H$.
\definition Let $(W,\omega)$ be a compact symplectic manifold with boundary. A \emph{Liouville vector field} is a $\liou\in\vec{M}$ so that $\lambda\vcentcolon =\iota_\liou\omega$ satisfies\footnote{Clearly, the existence of a Liouville vector field is equivalent to exactness of $M$.} $\d\lambda = \omega$.  If $\liou$ is transverse to the boundary $\partial W$ and outward pointing, the tuple $(W,\liou,\lambda)$ is called a \emph{Liouville domain}.

\lemma\label{lemCoords} Let $(W,\liou,\lambda)$ be a Liouville domain, and write $\Sigma \vcentcolon = \partial W$ as well as $M^+\vcentcolon =[0,\infty)\times\Sigma$ with coordinates $(r,x)$. Further, let $$M\vcentcolon =W\sqcup_\Sigma M^+$$ be the manifold obtained by identifying $\partial W$ with $\partial M^+$, as well as $\liou|_\Sigma$ with $\partial_r|_{\{0\}\times\Sigma}$. The triple $(M,\Sigma,\lambda)$ is called \emph{completion} of $(W,\liou,\lambda)$, 
Then there exists an $\eps>0$, an open set $U_\eps\subset M$ containing $M^+$, and coordinates $(-\eps,\infty)\times\Sigma \nach U_\eps$, so that 
\begin{align*}
 (-\eps,0)\times\Sigma&\inach U_\eps\cap(W\setminus\Sigma),\\
\{0\}\times\Sigma&\inach \Sigma,\\
(0,\infty)\times\Sigma&\inach M^+\setminus\Sigma.
\end{align*}Further, there exists an exact symplectic form $\bar\omega$ defined on all of $M$ that coincides with $\omega$ on $W$ and can be written in coordinates  as 
\begin{equation}\label{eqOmega}\bar\omega_{r} = e^r(\d\lambda|_\Sigma+\d r\wedge \lambda|_\Sigma)\end{equation}for all $r\in(-\eps,\infty)$. Its primitive is given by $\bar\lambda_r = e^r\lambda|_\Sigma$.

\proof Since $\liou$ is transversal to the hypersurface $\Sigma$, there exists an $\eps>0$ and an open neighborhood $U_\eps\subset M$ of $\Sigma$ so that the flow $\Phi_\liou: (-\eps,\eps)\times\Sigma\nach U_\eps$ is a diffeomorphism\footnote{This is a standard result called \emph{Flowout theorem}, see e.g. \cite{LeeSmooth}, Theorem 9.20(d).}. For  $r\geq 0$, we also have $\liou=\partial_r$ and thus $\Phi_\liou^r(x)=(r,x)$ for all $x\in\Sigma$, i.e. $\Phi_\liou$ can be extended to a diffeomorphism from $[0,\infty)\times\Sigma$ to itself. Transversality and outward-pointing of $\liou$ further implies that $(-\eps,0)\times\Sigma$ is contained in $W\setminus\Sigma $. Next, for $(r,x)\in(-\eps,0]\times\Sigma$,  observe that 
\begin{align}
\nonumber\tilde\lambda_{(r,x)} &\vcentcolon=(\Phi^r_\liou(x))\star\lambda\\
\nonumber&= e^r\lambda_{\Phi^0_\liou(x)}\\
&= e^r\lambda_{x},\label{eqLambdaTilde}
 \end{align}
where the second equality follows from a short calculation involving the Lie derivative\footnote{See e.g. the proof of (2.17) in \cite{ThreeBody}.}. $\tilde\lambda$  can be extended to all $r\in(-\eps,\infty)$ using \labelcref{eqLambdaTilde}, so   $\bar\omega\vcentcolon=(\Phi^{-r}_\liou)\star\d\tilde\lambda$ is defined on all of $U_\eps$. Finally, pullback and differential commute, so $\bar\omega$ agrees with $\omega$ on $U_\eps\cap W$ due to the definition of $\tilde\lambda$ and can be extended to all of $W$ using $\omega$.\qed

\remark In the following, we will neither distinguish between the symplectic form $\omega$ on $W$ and its extension $\bar\omega$ to all of $M$, nor between $\lambda$ and $\bar\lambda$.

\definition The \emph{Reeb flow} of a contact manifold $(\Sigma,\alpha)$ is implicitly defined by $\iota_R\alpha = 1$ and $\iota_R\d\alpha = 0$. If $\Sigma\subset M$ is a hypersurface inside a symplectic manifold $(M,\omega)$ with $\d\alpha=\omega|_\Sigma$, then $H\in C^\infty(M,\R)$ is called a \emph{defining Hamiltonian} for $(\Sigma,\alpha)$ if it has $0$ as a regular value, $\Sigma = H\inv(0)$, and $X_H=R$.

\lemma\label{lem1.29} If $(M,\Sigma,\lambda)$ is the completion of a Liouville domain, then $(\Sigma,\lambda|_\Sigma)$ is a contact manifold. 
A defining Hamiltonian for $\Sigma$ is given by any $H\in C^\infty(M,\R)$ with $\Sigma = H\inv(0)$ and $$H(r,x)= e^r-1$$ in an open neighborhood around $\Sigma$ (and using the coordinates from \aref{lemCoords}).
\proof
 The first property is a standard result, see e.g. Lemma 2.6.3 in \cite{ThreeBody}. For the second, note that because of $\d H = e^r \d r$, the condition $\d H = \omega(\cdot,X_H)$ with $\omega$ as in \labelcref{eqOmega} immediately implies that $\iota_{X_H}\d\lambda |_\Sigma =0$ and $\iota_{X_H}\lambda|_\Sigma =1$.
\qed 

\definition\label{defSFTlikeJ} Let $(M,\Sigma,\lambda)$ be the completion of a Liouville domain and let $\xi\vcentcolon =\ker\lambda|_\Sigma$ be the contact distribution of the contact manifold $(\Sigma,\lambda|_\Sigma)$. A $\d\lambda$-compatible almost complex structure $J$ on $M$ is called \emph{SFT-like} if $J\liou=R$, 
$J|_\xi$ is $\d\lambda|_\xi$-compatible, and $J_{(r,x)}=J_{(0,x)}$ for all $(r,x)\in (-\eps,\infty)\times\Sigma$. 

\begin{remark} Clearly, any $\d\lambda|_\xi$-compatible almost complex structure $J_\xi$ on $\xi$ can be extended to an SFT-like almost complex structure $J$ on $M$. 
\end{remark}

\corollary\label{corGrad}  The gradient of any defining Hamiltonian $H$ as in \aref{lem1.29} with respect to the scalar product  induced by an SFT-like almost complex structure satisfies $$\nabla H = \liou$$ in a neighborhood around $\Sigma$. In particular, \begin{equation}\label{eqNormNablaH}\norm{\nabla H(r,\cdot)}^2 = \norm{\liou(r,\cdot)}^2=e^r\end{equation} holds for all  $r\geq -r_0$ with $r_0\in (0,\eps)$.
\proof Obvious from $\d H = e^r\d r$ and \aref{defSFTlikeJ}.\qed 







