\section{Compactness of Moduli Spaces}\label{secCompMod}
In this section, we always suppose \aref{assSymp} holds.
\subsection{A Bound on the Constraint Factor}\label{secBoundConstraint}
To achieve a mean value of zero, i.e. $$\int\limits_0^1 H(\gamma(t))\d t=0,$$ it is clear that every $\gamma\in\H$ has to spend some time in a region of $M$ where $\nabla H>0$, as $0$ is a regular value of $H$ However, it might be possible that a sequence $(\gamma_n)_{n\in\N}\subset\H$ exists for which $\d h_{\gamma_n} (\nabla H|_{\gamma_n})$ tends to zero. In the following lemma, we will show that this in fact cannot happen by providing a uniform version of \aref{lemReg}:
\lemma\label{lemBoundDiff} For any $H$ as in \aref{lem1.29}, there exists a constant $c>0$, so that
$$\d h_\gamma(\nabla H|_\gamma)>c\ \forall\gamma\in\H.$$ 

\proof For arbitrary $\gamma\in\H$, we can define (using the coordinates $(r,x)$ from \aref{lemCoords})
\begin{align*}
G^+ &\vcentcolon=\menge{ t\in [0,1] : H(\gamma(t))\geq 0},\\
    G^- &\vcentcolon= \menge{ t\in [0,1] : H(\gamma(t))< 0},\\
    \widetilde G\hphantom{^-} &\vcentcolon= \menge{t\in G^- : r(\gamma(t))>-r_0}.
\shortintertext{From the fact that $h(\gamma)=0$, we immediately get}
\int\limits_{G^+} H(\gamma(t))\d t &= -\int\limits_{G^-} H(\gamma(t))\d t,
\shortintertext{and from \aref{corGrad}, we already know that $\norm{\nabla H(r,\cdot)}^2 =e^r$ for $r>-r_0$. Thus,}
\int\limits_{G^+}\norm{ \nabla H(\gamma(t))}^2\d t &= \hphantom{-}\int\limits_{G^+} e^{r(\gamma(t))}\d t\\
&= \hphantom{-}\int\limits_{G^+} H(\gamma(t))+ 1\d t\\
&= -\int\limits_{G^-} H(\gamma(t))\d t + \int\limits_{G^+} 1\d t\\
&= -\int\limits_{\widetilde G} \underbrace{H(\gamma(t))}_{\geq 0} \d t - \int\limits_{G^-\setminus \widetilde G} \underbrace{H(\gamma(t))}_{\leq -a}\d t + \mu( G^+)\\
&\geq a\mu(G^-\setminus \widetilde G) + \mu(G^+)
\shortintertext{using the Lebesgue measure $\mu$ and a constant}
 a &\vcentcolon= -\max \menge{H(z) : z\in W\setminus \{(r,x) \in U_\eps : r >-r_0\}}
 \shortintertext{which is independent of $\gamma$ and positive: $M$ and $\Sigma =H\inv(0)$ are both connected, so $W\setminus\Sigma =H\inv( (-\infty,0))$ and because $W\setminus \{z \in W : r(z)>-r_0\}$ is compact, $H$  attains a maximum there which is strictly smaller than $0$. Similarly, we have}
\int\limits_{G^-} \norm{\nabla H (\gamma(t))}^2\d t &= \int\limits_{\widetilde G} \norm{\nabla H (\gamma(t))}^2\d t + \int\limits_{G^-\setminus\widetilde G} \norm{\nabla H (\gamma(t))}^2\d t\\
 &\geq b\mu(\widetilde G),
 \shortintertext{for another constant}
 b &\vcentcolon= \min\menge{\norm{\nabla H(r,\cdot)} : r>-r_0}\\
 &= e^{-r_0}\\
 &>0.
 \shortintertext{Putting all of this together, we can estimate}
\d h_\gamma(\nabla H|_\gamma) &= \int\limits_0^1 \norm{ \nabla H(\gamma(t))}^2\d t\\
&= \int\limits_{G^+} \norm{ \nabla H(\gamma(t))}^2\d t + \int\limits_{G^-} \norm{ \nabla H(\gamma(t))}^2\d t \\
 &\geq a\mu(G^-\setminus \widetilde G) + \mu(G^+) + b\mu(\widetilde G)\\
 &\geq c\mu([0,1])\\
 &= c
\end{align*}for $c \vcentcolon= \min\menge{a,b,1}>0$, since all three sets are disjoint.\qed 

\lemma\label{lemBoundConstraint} If $H\in C^\infty(M,\R)$ satisfies $\nabla H =\liou $, then  
$|\mult | \leq \frac{1}{c} |\act{H} |.$ In particular,
\begin{equation}\label{eqBoundConstraint}
\max\limits_{s\in\R} |\mult(u(s))| \leq C(x^\pm,H)
\end{equation}holds for all $u\in\M(x^-,x^+)$ and a constant $C$ only dependent on $x^-,x^+$ and $H$. 

\proof The first part follows from the definition of $\mult$ in \labelcref{defMult}, the fact that $\d\act{H}_\gamma(\liou|_\gamma)=\act{H}(\gamma)$, and \aref{lemBoundDiff}. 
For \labelcref{eqBoundConstraint}, recall that $\act{H}(x^-)\geq \act{H}(u(s))\geq \act{H}(x^+)$ for $s\in\R$ and $u\in\M(x^-,x^+)$.\qed

\vspace{-0.75\baselineskip}
\begin{remark} The assumption $\nabla H=\liou$ is a stronger variant of the \emph{Weinstein condition}, which only requires that  $\liou$ be \emph{gradient-like} for $H$, i.e., that $\d H(\liou)>0$ away from critical points. Intuitively, it arises from the non-locality of the gradient flow of $\act{H}$\textup{:} The constraint factor $\mult$ depends on the whole loop. In contrast, the Lagrange multiplier $\lag$ in RFH only depends on $s\in\R$, and so an $L^\infty$-bound can be deduced from the gradient flow equation itself (cf. \textup{\cite{ExactContact}}, Proposition 3.2).\nopagebreak
\end{remark}




