\section{Auxiliary Proofs}\label{secAuxProofs}
For a better reading flow, some proofs have been moved to this section.\vspace{\baselineskip}

\textit{Proof of }\aref{lemDiff}. Let $\gamma\in\loops[p]{M}$. It can be assumed to be continuous, so $t\auf H(\gamma(t))$ is continuous too and $$h(\gamma) = \int\limits_0^1 H(\gamma(t))\d t$$ is well-defined. For $\act{}$, we use that $\lambda = \omega(\liou,\cdot) = g(J\liou,\cdot)$ and \begin{align}\nonumber\act{}(\gamma) &= -\int\limits_\S \lambda_{\gamma(t)}(\partial_t\gamma) \\
&=-\int\limits_\S g_{\gamma(t)}(J\liou(\gamma(t)),\partial_t\gamma(t)).\label{eqA1}\end{align}
So even though $t\auf\partial_t\gamma(t)$ may not be well-defined, the integral \labelcref{eqA1} naturally is.

For their differentials, let $v\in W^{1,p}((-\eps_0,\eps_0),\loops{M}),\ \eps\auf v_\eps$ with $v_0=\gamma$ be a (weak) variation of $\gamma$. By construction of $\loops{M}$ via charts, there exists a unique \emph{continuous} vector field $X\in W^{1,p}(\S,\gamma\star\tang{}{M})$ with $v_\eps = \exp_\gamma \eps X$, i.e. $$\dbei{\eps}{0} v_\eps =X$$ in the \emph{classical} sense. Thus we can say:

\begin{align*}
\dbei{\eps}{0} h(v_\eps)&=\dbei{\eps}{0}\int\limits_0^1 H(v_\eps(t))\d t\\ 
&= \int\limits_0^1 \pbei{\eps}{0}H(v_\eps(t))\d t\\
&= \int\limits_0^1 H\left(\pbei{\eps}{0}v_\eps(t)\right)\d t\\
    &= \int\limits_0^1 \d H_{\gamma(t)} (X(t))\d t
\end{align*}

The calculation for $\dbei{\eps}{0}\act{}(v_\eps)$ works the same but involves the Lie derivative and Cartan's magic. Again, the \emph{classical} differentiability of $\eps\auf v_\eps$ is essential.\qed

\newpage 
The following should be read with the setting of \aref{thmSub} in mind, but it holds  for general Banach manifolds:
\theorem\label{thmBanachSub} Let $\L$ be a Banach manifold, $h\in C^1(\L,\R)$, and assume that at every $\gamma\in\H\vcentcolon =h\inv(0)$, there exists $v\in\tang{\gamma}{\L}$ with $\d h_\gamma(v) \neq 0$. Then $\H$ is a codimension $1$ submanifold of $\L$ and $\tang{\gamma}{\H}=\ker\d h_\gamma$. 
\proof
The assumption on $\d h$ already implies that every $\gamma\in h\inv(0)$ is a regular value. To use the infinite-dimensional version of the \emph{regular value theorem}\footnote{See e.g. \cite{Lang}, Chapter II.2, Proposition 2(ii).}, we still need to show that $\ker\d h$ \emph{splits} at every such $\gamma$, i.e.
$$\tang{\gamma}{\L} = \ker \d h_\gamma \oplus V_\gamma$$ for some closed (or just finite-dimensional) subspace $V_\gamma$. To this end, let $v\in \tang{\gamma}{\L}$ with $\d h_\gamma(v)\neq 0$, then
$$\pi : \tang{\gamma}{\L}\nach\tang{\gamma}{\L},\ w\auf w-  \frac{\d h_\gamma(w)}{\d h_\gamma(v)}v$$
is a linear map satisfying
\begin{enumerate}
    \item $\ker\pi = \langle v\rangle$,
    \item $\im\pi = \ker\d h_\gamma$,
    \item $\pi |_{\ker\d h_\gamma} = \id|_{\ker\d h_\gamma}$,
\end{enumerate} in other words $$\tang{\gamma}{\L} = \ker\d h_\gamma\oplus \langle v\rangle$$ via $$w = \pi(w) + v\frac{\d h_\gamma(w)}{\d h_\gamma(v)}$$ for $w\in \tang{\gamma}{\L}$. \qed

\remark In the proof of \aref{thmBanachSub}, every choice of $v\in\tang{\gamma}{\L}$ with $\d h_\gamma(v)\neq 0$ amounts to a different projection $\pi_v : \tang{\gamma}{\L}\nach\tang{\gamma}{\H}$. However, a right-inverse to all such projections is given by the identification map $$\iota : \tang{\gamma}{\H}\nach\tang{\gamma}{\L},\ w\auf w.$$

\theorem\label{thmGradBanach} Let $(\L,g)$ be a Hilbert manifold, $h\in C^1(\L,\R)$ have $0$ as a regular value, and $\H\vcentcolon=h\inv(0)$. Then $\tilde g \vcentcolon= g(\iota\cdot,\iota\cdot)$ defines a canonical scalar product on $\H$, and for any $f\in C^\infty(\L,\R)$ with $\tilde f \vcentcolon= f|_\H$, one has
\begin{equation*}\nabla \tilde f = \nabla f + \mult\nabla h,\end{equation*}
where $\mult : \H\nach\R$ is given by $$\mult(\gamma) \vcentcolon = -\frac{\d f_\gamma(\nabla h (\gamma))}{\d h_\gamma(\nabla h(\gamma))}.$$

\proof The first part is trivial. For the second part, we note that on $\tang{\gamma}{\H}$, $$\d \tilde f_\gamma = \d f_\gamma \circ\iota,$$ and so
\begin{align*}
    \tilde g(\nabla \tilde f,\cdot) &= \d \tilde f \\
    &= \d f_\gamma \circ\iota \\
    &= g(\nabla f, \iota\cdot) \\
    &= g(\iota\pi_v(\nabla f)+ (\nabla f-\iota \pi_v(\nabla f)),\iota \cdot)\\
    &= \tilde g(\pi_v(\nabla f),\cdot) + \frac{\d h (\nabla f)}{\d h (v)}g(v,\iota\cdot).
\end{align*} The second term vanishes, as soon as we choose a $v\in\tang{\gamma}{\L}$ with $\d h_\gamma(v)\neq0$ that is $g$-orthogonal to $\tang{\gamma}{\H}=\ker \d h$; for example $v = \nabla h(\gamma)$. In other words, \begin{align*}\nabla \tilde f &= \pi_{\nabla h}(\nabla f)\\
&= \nabla f - \frac{\d h(\nabla f)}{\d h(\nabla h)}\nabla h\\
&= \nabla f - \frac{\d f(\nabla h)}{\d h(\nabla h)}\nabla h.\end{align*}\qed






