\title{Long-Range Interacting Particles on a Helix: A Statistical and Correlation Analysis of Equilibrium Configurations}

\author{J. M. Dörre}\email{jan.mathis.doerre@studium.uni-hamburg.de}
  \affiliation{Zentrum für Optische Quantentechnologien, Fachbereich Physik, Universität Hamburg, Luruper Chaussee 149, 22761 Hamburg Germany}
