\section{Deformation vector field $G$}

In this section, we investigate structural properties of the quasi-homogeneous vector field \( G \), which commutes with the integrable vector field \( F \) and induces a deformation of its Laurent series solutions. While \( F \) determines the leading-order singular behavior, the role of \( G \) is to generate parameter flows consistent with the quasi-homogeneous symmetry and the integrability conditions. Our goal is to characterize the expansion of \( G(x(z)) \) around a principal indicial locus and to determine the algebraic constraints imposed by the commutation relation and the scaling degrees. These results lay the analytic foundation for understanding the flow of deformation parameters and the emergence of nontrivial singular structures in the subsequent sections.


To consider the vector field $G = (g_1, \cdots ,g_m)$, we prepare several formulae and notations.
The derivative of (A1) at $\lambda =1$ yields
\begin{align}
\sum^m_{j=1}a_jx_j \frac{\partial f_i}{\partial x_j}(x) = (a_i+1)f_i(x), \quad
\sum^m_{j=1}a_jx_j \frac{\partial g_i}{\partial x_j}(x) = (a_i+\gamma )g_i(x).
\label{3-1}
\end{align}
Putting  $x=c$ to the latter one, we obtain
\begin{align}
-\sum^m_{j=1} f_j(c) \frac{\partial g_i}{\partial x_j}(c) = (a_i+\gamma )g_i(c).
\label{3-2}
\end{align}
The derivative of (A1) by $x_j$ gives
\begin{equation}
\left\{ \begin{array}{l}
\displaystyle \frac{\partial f_i}{\partial x_j}(\lambda ^{a_1}x_1,\cdots ,\lambda ^{a_m}x_m)
 = \lambda ^{a_i+1-a_j}\frac{\partial f_i}{\partial x_j}(x_1, \cdots ,x_m),  \\[0.3cm]
\displaystyle \frac{\partial g_i}{\partial x_j}(\lambda ^{a_1}x_1,\cdots ,\lambda ^{a_m}x_m)
 = \lambda ^{a_i+\gamma -a_j}\frac{\partial g_i}{\partial x_j}(x_1, \cdots ,x_m).
\end{array} \right.
\label{3-3}
\end{equation}
As before, we assume that $c$ is a principle locus so that there is a Laurent series solution
\begin{equation}
x_i(z) = (z -\alpha _0)^{-a_i} \left( c_i + \sum^\infty_{k=1} d_{i,k}(A) (z-\alpha _0)^k \right)
 =: (z -\alpha _0)^{-a_i}y_i(z)
\label{3-4}
\end{equation}
including $m$ free parameters $A = (\alpha _0, \cdots ,\alpha _{m-1})$.
Substituting this solution into $g_i(x)$ gives
\begin{align}
g_i(x(z)) &= (z_1-\alpha _0)^{-a_i-\gamma } g_i(y_1, \cdots ,y_m) \nonumber \\
& =  (z_1-\alpha _0)^{-a_i-\gamma } \sum^\infty_{k=0}g_{i,k}(A) (z-\alpha _0)^k,
\label{3-5}
\end{align}
where $g_{i,k}(A)$ is the coefficient of the Taylor expansion of $g_i(y_1, \cdots ,y_m)$ in $z-\alpha _0$.
We denote $G_k := (g_{1,k}, \cdots ,g_{m,k})$.
In particular $g_{i,0} = g_i(c)$ and $G_0 = G(c)$.
\\

\begin{proposition}
For a given indicial locus $c$, the identity $(K(c) + \gamma ) G(c) = 0$ holds.
In particular, if $-\gamma $ is not a K-exponent, then $G(c) = 0$
(here, we need not assume that $c$ is principle).
\end{proposition}
\begin{proof}
(A2) and (\ref{3-2}) provide
\begin{align*}
0 = \sum^m_{j=1}\left( f_j(c) \frac{\partial g_i}{\partial x_j}(c) 
     - g_j(c) \frac{\partial f_i}{\partial x_j}(c)  \right) 
= - \sum^m_{j=1} \frac{\partial f_i}{\partial x_j}(c) g_j(c) - (a_i + \gamma ) g_i(c),
\end{align*}
which proves the proposition.
\end{proof}

\begin{remark}
The identity \( (K(c) + \gamma)G(c) = 0 \) implies that the deformation vector field \( G \) must lie in the kernel of the shifted Kovalevskaya matrix. Since quasi-homogeneous integrable systems often have all K-exponents except \( -1 \) non-negative, this condition is typically incompatible unless \( -\gamma \) is an actual K-exponent. Hence, for systems with the Painlevé property, it is common for \( G(c) \) to vanish.
\end{remark}


\begin{corollary}
Suppose $c$ is a principle indicial locus.
\\
(i) If $\gamma \geq 2$, $G(c) = 0$.
\\
(ii) If $\gamma =1$, $G(c) = k (a_1c_1, \cdots ,a_m c_m)$ for some $k\in \C$.
\end{corollary}

\begin{proof}
(i) By the assumption, there are no negative K-exponents other than $\kappa_0 = -1$.
(ii) When $\gamma =1$, $G(c) = 0$ or $G(c)$ is an eigenvector of $\kappa_0 = -1$.
 Since $\kappa_0 = -1$ is a simple eigenvalue by the assumption, the statement (ii) follows from Prop.2.3.
\end{proof} 
\begin{remark}
In the special case \( \gamma = 1 \), the vector \( G(c) \) may be nonzero, and in fact lies in the eigenspace corresponding to the translation exponent \( -1 \). This means \( G \) induces a deformation that includes the location of the singularity \( \alpha_0 \), while for \( \gamma \geq 2 \), the singularity location remains fixed under the flow of \( G \).
\end{remark}

More generally, the next theorem holds.
\\

\begin{theorem}
Let $c$ be a principle indicial locus.
\\
The equality $(K(c)+\gamma -k)G_k = 0$ holds for $k=0,1,\cdots ,\gamma -1$.
\\
\end{theorem}
\begin{corollary}
When $\gamma \geq 2$,
$G_0 = G_1= \cdots  = G_{\gamma -2}= 0$ and $G_{\gamma -1}$ is of the form
$G_{\gamma -1} = h (A) \cdot (a_1c_1, \cdots ,a_mc_m)$, where $h(A)$ is a certain polynomial
of $\alpha _1 , \cdots ,\alpha _{m-1}$.
\end{corollary}

\begin{proof}
The case $\gamma =1$ (i.e. $k=0$ in the theorem) had been proved in Prop.3.1.
Thus we consider $\gamma \geq 2$.


Since $x(z)$ in (\ref{3-4}) is a solution of $dx/dz = f(x)$,
\begin{align*}
f_j(x(z)) &= -a_jc_j(z-\alpha _0)^{-a_j-1} - \sum^\infty_{k=1} (a_j-k)d_{j,k}(z-\alpha _0)^{-a_j+k-1} \\
&= -(z-\alpha _0)^{-1}a_jx_j + \sum^\infty_{k=1} k d_{j,k} (z-\alpha _0)^{-a_j+k-1}.
\end{align*}
Eq.(\ref{3-3}) shows
\begin{align*}
\frac{\partial f_i}{\partial x_j}(x(z)) = (z-\alpha _0)^{a_j-a_i-1}\frac{\partial f_i}{\partial x_j}(y),
\quad \frac{\partial g_i}{\partial x_j}(x(z)) = (z-\alpha _0)^{a_j-a_i-\gamma }\frac{\partial g_i}{\partial x_j}(y),
\end{align*}
where $y = (y_1, \cdots ,y_m)$ is defined in (\ref{3-4}).
Substituting them into (A2), we have
\begin{align*}
0 &= \sum^m_{j=1}\left( (z-\alpha _0)^{a_j-a_i-1} \frac{\partial f_i}{\partial x_j}(y) \cdot
(z-\alpha _0)^{-a_j-\gamma }\sum^\infty_{k=0} g_{j,k}(z-\alpha _0)^{k} \right) \\
& \qquad + \sum^m_{j=1}  \frac{\partial g_i}{\partial x_j}(x)  
\left(  a_jx_j (z-\alpha _0)^{-1} 
   - \sum^\infty_{k=1}k d_{j,k} (z-\alpha _0)^{-a_j+k-1} \right) \\
&= \sum^m_{j=1} (z-\alpha _0)^{-a_i-\gamma -1}\frac{\partial f_i}{\partial x_j}(y) \sum^\infty_{k=0}g_{j,k} (z-\alpha _0)^{k} \\
& \quad + (a_i + \gamma )  (z-\alpha _0)^{-a_i-\gamma -1}\sum^\infty_{k=0} g_{i,k} (z-\alpha _0)^{k} \\
& \qquad -\sum^m_{j=1} (z-\alpha _0)^{a_j-a_i-\gamma } \frac{\partial g_i}{\partial x_j}(y)\sum^\infty_{k=1}kd_{j,k} (z-\alpha _0)^{-a_j+k-1},
\end{align*}
where (\ref{3-1}) is used.
This is rewritten as  
\begin{equation}
\sum^\infty_{k=0} (z-\alpha _0)^{k}\sum^m_{j=1} \left(  \frac{\partial f_i}{\partial x_j}(y) + (a_j + \gamma ) \delta _{i,j} \right) g_{j,k}
-\sum^m_{j=1} \frac{\partial g_i}{\partial x_j}(y)\sum^\infty_{k=1}kd_{j,k} (z-\alpha _0)^{k}=0.
\label{3-6}
\end{equation}
To estimate the last term, we use induction. Recall that we consider $\gamma \geq 2$.
Assume that $(K(c) +\gamma -k)G_k = 0$ holds for $k=0,1,\cdots ,n-1$, where $n\leq \gamma -1$.
Then $G_0 = G_1 = \cdots = G_{n-1}= 0$ holds because $-\gamma , -\gamma +1, \cdots , -\gamma + n -1\, (\leq -2)$
are not K-exponents.
Hence, (\ref{3-6}) gives 
\begin{equation*}
\sum^\infty_{k=n} (z-\alpha _0)^{k}\sum^m_{j=1} \left(  \frac{\partial f_i}{\partial x_j}(y) + (a_j + \gamma ) \delta _{i,j} \right) g_{j,k}
-\sum^m_{j=1} \frac{\partial g_i}{\partial x_j}(y)\sum^\infty_{k=1}kd_{j,k} (z-\alpha _0)^{k}=0
\end{equation*}
(the first summation starts from $k=n$). Divide  by $(z-\alpha _0)^n$ and consider the limit $z\to \alpha _0$:
\begin{equation}
\sum^m_{j=1} \left(  \frac{\partial f_i}{\partial x_j}(c) + (a_j + \gamma ) \delta _{i,j} \right) g_{j,n}
-\lim_{z\to \alpha _0} \sum^m_{j=1} \frac{\partial g_i}{\partial x_j}(y)\sum^\infty_{k=1}kd_{j,k}
\frac{(z-\alpha _0)^k}{(z-\alpha _0)^n}=0.
\label{3-7}
\end{equation}
By the definition of $g_{i,k}$, we have
\begin{align*}
g_i(y_1, \cdots ,y_m) = \sum^\infty_{k=0} g_{i,k}(z-\alpha _0)^k, 
\quad y_j = c_j + \sum^\infty_{k=1} d_{j,k} (z-\alpha _0)^k.
\end{align*}
The derivation of both sides by $z$ yields
\begin{align*}
& \sum^m_{j=1} \frac{\partial g_i}{\partial x_j}(y_1,\cdots ,y_m)\sum^\infty_{k=1}k d_{j,k} (z-\alpha _0)^{k-1}
 = \sum^\infty_{k=n} k g_{i,k} (z-\alpha _0)^{k-1} \\
\Rightarrow & \sum^m_{j=1} \frac{\partial g_i}{\partial x_j}(y_1,\cdots ,y_m)\sum^\infty_{k=1}k d_{j,k} 
\frac{(z-\alpha _0)^{k-1}}{(z-\alpha _0)^{n-1}}
 = ng_{i,n} + O(z-\alpha _0). 
\end{align*}
As $z\to \alpha _0$,
\begin{equation*}
\lim_{z\to \alpha _0}\sum^m_{j=1} \frac{\partial g_i}{\partial x_j}(y_1,\cdots ,y_m)\sum^\infty_{k=1}k d_{j,k} 
\frac{(z-\alpha _0)^{k}}{(z-\alpha _0)^{n}}
 = ng_{i,n}
\end{equation*}
This and (\ref{3-7}) gives
\begin{equation}
\sum^m_{j=1} \left(  \frac{\partial f_i}{\partial x_j}(c) + (a_j + \gamma -n) \delta _{i,j} \right) g_{j,n}=0.
\end{equation}
This proves that $(K(c) +\gamma -k)G_k(c) = 0$ holds for $k=n$.
The induction step continues up to $k=\gamma -1$. 
\end{proof}

\begin{remark}
The theorem above implies that the first non-constant term appearing after the constant term \(G_0 = G(c)\) in the Laurent expansion of \(G(x(z))\) occurs at order \(\gamma - 1\). In other words, the coefficients \(G_k\) vanish for all \(k < \gamma - 1\), making \(G_{\gamma - 1}\) the next allowable term consistent with the quasi-homogeneous structure and the commutation condition.
\end{remark}

Even when the degree $\gamma $ of a given quasi-homogeneous equation is larger than $1$,
the K-exponents are defined in a similar manner as follows.
Let us consider $dx_i/dz_2 = g_i(x)$ given in (A1) having the degree $\gamma $.
We consider the Puiseux series solution of the form
\begin{equation}
x_i(z_2) = p_i (z_2-\beta_0)^{-a_i/\gamma }
 + \sum^\infty_{k=1} q_{i,k}(z_2-\beta_0)^{(-a_i+k)/\gamma }, \quad i=1,\cdots ,m,
\end{equation}
where $\beta_0$ is a singularity and $p_i,\, q_{i,k}$ are constants to be determined.
Substituting it into the equation, it turns out that an indicial locus $p=(p_1, \cdots ,p_m)$
 is given as a root the equation
\begin{equation}
-\frac{a_i}{\gamma }p_i = g_i(p_1, \cdots ,p_m), \quad i=1,\cdots ,m.
\label{3-10}
\end{equation}
For a given $p$, $q_j = (q_{1,j}, \cdots ,q_{m,j})$ is iteratively determined as a solution of
\begin{equation}
(K_\gamma (p) - \frac{j}{\gamma }\cdot I ) q_j = \text{(polynomial of $p$ and $q_{k}$ for $k=1,\cdots ,j-1$)},
\label{3-11}
\end{equation}
where the K-matrix $K_\gamma (p)$ is defined by
\begin{equation}
K_\gamma (p) = \left\{ \frac{\partial g_i}{\partial x_j}(p) + \frac{a_i}{\gamma } \delta _{i,j} \right\}_{i,j=1}^m.
\label{3-12}
\end{equation}
The eigenvalues $\rho_0, \rho_1, \cdots  ,\rho_{m-1}$ are called the K-exponents.
If $j/\gamma $ is a K-exponent, $q_j$ includes a free parameter.
As in Prop.3.3, $\rho_0 = -1$ is always a K-exponent with the eigenvector $(a_1p_1, \cdots , a_mp_m)$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Flow of the free parameters}

Let $\varphi ^F_{z_1}$ and $\varphi ^G_{z_2}$ be the flow of $F$ and $G$, respectively;
$\varphi ^F_{z_1}$ maps $x(0)$ to $x(z_1)$ along the orbit of vector field $F$.
To obtain a solution of the system (\ref{2-1}) as a function of $z_1$ and $z_2$,
for a solution $x(z_1; A) = \varphi ^F_{z_1} \circ \Phi (A)$ of $\partial x/\partial z_1 = F(x)$, 
we assume that $A = A(z_2)$ is a function of $z_2$.
Let us substitute this $x$ into the second equation $\partial x / \partial z_2 = G(x)$.
\begin{equation*}
\text{(left hand side)} = \frac{\partial \varphi ^F_{z_1}}{\partial x}(\Phi (A))\frac{d\Phi}{dz_2}(A)
= \frac{\partial \varphi ^F_{z_1}}{\partial x}(\Phi (A)) 
\sum^{m-1}_{l=0} \frac{\partial \Phi}{\partial \alpha _l}(A)\frac{d\alpha _l}{dz_2}.
\end{equation*}
It is known that (A2) is equivalent to the identity 
$\varphi ^F_t \circ \varphi ^G_s = \varphi ^G_s \circ \varphi ^F_t$.
The derivative of it at $s = 0$ gives
\begin{equation*}
\frac{\partial \varphi ^F_t}{\partial x}(x) G(x) = G(\varphi ^F_t (x)).
\end{equation*}
Hence, 
\begin{equation*}
\text{(right hand side)} = G(x(z_1; A)) = G(\varphi ^F_{z_1} \circ \Phi (A))
 = \frac{\partial \varphi ^F_{z_1}}{\partial x} (\Phi (A)) G(\Phi (A)).
\end{equation*}
This proves
\begin{equation}
\sum^{m-1}_{l=0} \frac{\partial \Phi}{\partial \alpha _l}(A)\frac{d\alpha _l}{d z_2} = G(\Phi (A))
\quad \Rightarrow \quad \frac{dA}{dz_2} = \left( \frac{\partial \Phi}{ \partial A}(A)\right)^{-1}G(\Phi (A)),
\label{4-1}
\end{equation}
that gives the flow of $A(z_2)$.
\begin{proposition}
The right hand side of (\ref{4-1}) is \\
(i) independent of $\alpha _0$ and polynomial in $\alpha _1, \cdots ,\alpha _{m-1}$, \\
(ii) quasi-homogeneous of degree $\gamma $ with respect to the weight $(\kappa_0, \cdots , \kappa_{m-1})$.
\end{proposition}

\begin{proof}
(i) Denote $c_i = d_{i,0}$ for simplicity to express (\ref{2-5}) as 
$x_i(z_1) = \sum^\infty_{j=0}d_{i,j}(z_1-\alpha _0)^{-a_i + j}$.
By substituting it to $\partial x_i/\partial z_2 = g_i(x)$, we obtain
\begin{align*}
\text{(left hand side)} &= \sum^\infty_{j=0} (a_i-j)d_{i,j}(z_1-\alpha _0)^{-a_i+j-1}\frac{d\alpha _0}{dz_2}
   + \sum^\infty_{j=0} \frac{dd_{i,j}}{dz_2}(z_1-\alpha _0)^{-a_i+j}, \\
\text{(right hand side)} &= 
(z_1-\alpha _0)^{-a_i-\gamma } g_i(\sum^\infty_{j=0} d_{1,j} (z_1-\alpha _0)^j, 
    \cdots , \sum^\infty_{j=0} d_{m,j} (z_1-\alpha _0)^j), \\
&= (z_1-\alpha _0)^{-a_i-\gamma } \sum^\infty_{j=0}g_{i,j}(\alpha _1, \cdots ,\alpha _{m-1}) \cdot (z_1-\alpha _0)^j,
\end{align*}
where $g_{i,j}$ is a $j$-th coefficient of the Taylor expansion of 
$g_i(\sum^\infty_{j=0} d_{1,j} (z_1-\alpha _0)^j, \cdots )$ in $z_1-\alpha _0$, that was introduced in Sec.3.
This is a polynomial of $\alpha _1, \cdots ,\alpha _{m-1}$ because so is $d_{i,j}$.
Comparing the coefficients of $(z_1-\alpha _0)^{-a_i-1}$ in both sides, we obtain
\begin{equation}
a_ic_i \frac{d\alpha _0}{dz_2} = g_{i, \gamma -1}(\alpha _1,\cdots ,\alpha _{m-1}).
\label{4-2}
\end{equation}
Similarly, coefficients of $(z_1-\alpha _0)^{-a_i + \kappa_l}$ provide
\begin{equation}
(a_i-1-\kappa_l)d_{i,1+\kappa_l} \frac{d\alpha _0}{dz_2}+\frac{d\alpha _l}{dz_2}
 = g_{i, \kappa_l + \gamma }(\alpha _1,\cdots ,\alpha _{m-1}),\quad l=1,\cdots ,m-1,
\label{4-3}
\end{equation}
where we used $\alpha _l = d_{i,\kappa_l}$ for some $i$.
Eq.(\ref{4-2}) shows that $d\alpha _0/dz_2$ is independent of $\alpha _0$.
Thus, (\ref{4-3}) proves that $d\alpha _l/dz_2$ is also independent of $\alpha _0$
and is polynomial in $\alpha _1, \cdots ,\alpha _{m-1}$ for $l=1,\cdots ,m-1$.

(ii) Eq.(\ref{4-2}) and (\ref{4-3}) provide another expression of (\ref{4-1}) as
\begin{equation}
\left\{ \begin{array}{l}
\displaystyle \frac{d\alpha _0}{dz_2} = \frac{g_{i,\gamma -1}(A)}{a_i c_i} =: \hat{g}_0(A),  \\[0.3cm]
\displaystyle \frac{d\alpha _l}{dz_2} = g_{i,\kappa_l+\gamma } (A)
 - (a_i-1-\kappa_l) d_{i,1+\kappa_l}(A) \frac{g_{i,\gamma -1}(A)}{a_i c_i} =:\hat{g}_l(A).
\end{array} \right.
\label{4-4}
\end{equation}
Remark that $g_{i,\gamma -1}(A)/a_i c_i$ is independent of $i$ and well-defined even when $c_i=0$
because of Corollary 3.2 and 3.4 ($\hat{g}_0(A)$ is $h(A)$ there).
As above, we put
\begin{equation*}
g_i(\sum^\infty_{j=0} d_{1,j}(A) (z_1-\alpha _0)^j, 
    \cdots , \sum^\infty_{j=0} d_{m,j}(A) (z_1-\alpha _0)^j)
 = \sum^\infty_{j=0}g_{i,j}(A) \cdot (z_1-\alpha _0)^j.
\end{equation*}
Since $\lambda ^j d_{i,j}(A)= d_{i,j}(\lambda \cdot A)$ by Prop.2.5,
the left hand side above is invariant by $A \mapsto \lambda \cdot A,\, 
\alpha _0\mapsto \lambda ^{-1}\alpha _0$ and $z_1\mapsto \lambda ^{-1}z_1$
(recall that 
$\lambda \cdot A = (\lambda ^{-1}\alpha _0, \lambda^{\kappa_1} \alpha _1, 
\cdots , \lambda^{\kappa_{m-1}} \alpha _{m-1})$).
Thus, we obtain $g_{i,j}(\lambda \cdot A) = \lambda ^j g_{i,j}(A)$ from the right hand side.
This proves
\begin{equation}
\hat{g}_l (\lambda^{\kappa_1} \alpha _1, \cdots , \lambda^{\kappa_{m-1}} \alpha _{m-1})
   = \lambda ^{\kappa_l+\gamma }\hat{g}_l(\alpha _1, \cdots ,\alpha _{m-1})
\label{4-5}
\end{equation}
for $l=0, 1,\cdots ,m-1$. 
\end{proof}

Now we investigate the system (\ref{4-1}) or equivalently (\ref{4-4});
\begin{equation}
\frac{dA}{dz_2} = \left( \frac{\partial \Phi}{ \partial A}(A)\right)^{-1}G(\Phi (A))
\quad \Leftrightarrow \quad
\left\{ \begin{array}{ll}
\displaystyle \frac{d\alpha _0}{dz_2} = \hat{g}_0(A)  \\[0.2cm]
\displaystyle \frac{d\alpha _i}{dz_2} = \hat{g}_i(A), \quad i=1,\cdots ,m-1 \\
\end{array} \right.
\label{4-6}
\end{equation}
satisfying (\ref{4-5}).
\\
\begin{lemma}
Suppose that $\hat{g}_0(A)$ is not a constant function.
Then, there is a tuple of nonnegative integers $(n_1, \cdots ,n_{m-1}) \neq (0,\cdots ,0)$ satisfying 
$\kappa _1 n_1 + \cdots  + \kappa _{m-1}n_{m-1} = \gamma -1$.
For example, when $\gamma =1$,  $\hat{g}_0(A)$ is a constant function.
When $\gamma =2$, there exists a K-exponent $\kappa =1$.
\end{lemma}

\begin{proof}
Consider a monomial $\alpha _1^{n_1} \alpha _2^{n_2} \cdots \alpha _{m-1}^{n_{m-1}}$ included in $\hat{g}_0$.
The lemma immidiately follows from (\ref{4-5}). $\Box$
\end{proof} 

Let $\xi = (\xi_0 ,\cdots ,\xi_{m-1})$ be an indicial locus of (\ref{4-6}) and 
$\rho_0 = -1,\, \rho_1 ,\cdots ,\rho_{m-1}$ its K-exponents.
\\

\begin{lemma}
Besides $\rho_0 = -1$, (\ref{4-6}) has another negative exponent $\rho_1 = -1/\gamma $.
\end{lemma} 

\begin{proof}
The proof is based on the fact that the right hand side of (\ref{4-6}) is independent of $\alpha _0$.
The K-matrix of (\ref{4-6}) defined by (\ref{3-12}) is given as
\begin{equation}
K_\gamma (\Phi^{-1}(p)) = \left(
\begin{array}{@{\,}c|ccc@{\,}}
0 &\partial \hat{g}_0/\partial \alpha _1 \!\!\!\!\!\!\!\!\!\!& \cdots &\!\!\!\!\!\!\!\!\!\! \partial \hat{g}_0/\partial \alpha _{m-1} \\ \hline
 & & & \\
0 & & \quad \displaystyle \left\{ \frac{\partial \hat{g}_i}{\partial \alpha _j} \right\}_{i,j=1}^{m-1} &\\
 & & & 
\end{array}
\right) + \left(
\begin{array}{@{\,}c|ccc@{\,}}
-1/\gamma & & 0 & \\ \hline
& \kappa _1/\gamma   & & \\
0 & &\!\! \ddots & \\
& & &\!\! \kappa _{m-1}/\gamma 
\end{array}
\right).
\label{4-7}
\end{equation}
Hence, its eigenvalues are $-1/\gamma $ and K-exponents of the subsystem 
$d\alpha _i/dz_2 = \hat{g}_i (A),\,\, i=1,\cdots ,m-1$.
Since the subsystem has a K-exponent $-1$, the proof is completed.
\end{proof}

\begin{remark}
The first expression of (\ref{4-6}) implies that it is obtained from $dx/dz_2 = G(x)$, 
given in (A1), by the coordinate transformation $x = \Phi (A)$.
For the system $dx/dz_2 = G(x)$, let $p = (p_1, \cdots , p_m)$ be an indicial locus.
Then, $\xi =  \Phi^{-1}(p)$ is an idencial locus of (\ref{4-6}) as long as 
$\xi$ is in the domain on which $\Phi$ is a diffeomorphism.
In this case, the K-exponents of (\ref{4-6}) at $\Phi^{-1}(p)$ coincide with those of $G$ at $p$
due to Prop.2.5 and Thm.2.6.
Unfortunately, $\Phi (A)$ is not a diffeomorphism at $\alpha_0 = 0$
and this discussion is not applicable when $\xi_0 =0$.
\end{remark}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{The case $\hat{g}_0(A) \equiv 0$}
At first, suppose that $\hat{g}_0$ is equivalent to zero.
So we consider the system
\begin{equation}
\frac{d\alpha _i}{dz_2} = \hat{g}_i (\alpha _1,\cdots ,\alpha _{m-1}), \quad i=1,\cdots ,m-1,
\label{f-8}
\end{equation}
which is of degree $\gamma $ with respect to the weight $(\kappa _1,\cdots , \kappa _{m-1})$.
Let $\xi = (\xi_1,\cdots ,\xi_{m-1})$ be an indicial locus 
and $\rho_0=-1, \rho_2, \cdots ,\rho_{m-1}$ its K-exponents(we skip $\rho_1 = -\frac{1}{\gamma}$ because it arises from the equation of $\alpha_0$).
\\[0.2cm]

\begin{lemma}
Let \(\kappa = (\kappa_1, \ldots, \kappa_{m-1})\) be positive Kovalevskaya exponents associated with parameters \(\alpha_1, \ldots, \alpha_{m-1}\). Suppose there exists a tuple \((n_1, \ldots, n_{m-1}) \in \mathbb{Z}_{\geq 0}^{m-1}\) such that
\[
\sum_{k=1}^{m-1} \kappa_k n_k \in \gamma \mathbb{N}
\]
for some integer \(\gamma \geq 1\).

Then, there exist indices \(i \neq j\) such that
\[
\kappa_i - \kappa_j \in \gamma \mathbb{N}.
\]
\end{lemma}

\begin{proof}
Assume for contradiction that for all \(i \neq j\),
\[
\kappa_i - \kappa_j \notin \gamma \mathbb{N}.
\]

Define the residue classes modulo \(\gamma\):
\[
r_k := \kappa_k \bmod \gamma, \quad r_k \in [0, \gamma).
\]

By assumption, these residues \(r_k\) are all distinct for \(k = 1, \ldots, m-1\).

Consider the weighted sum modulo \(\gamma\):
\[
\sum_{k=1}^{m-1} \kappa_k n_k \equiv \sum_{k=1}^{m-1} r_k n_k \pmod{\gamma}.
\]

Since all \(r_k\) are distinct and \(n_k \geq 0\), the sum \(\sum r_k n_k\) can only be congruent to zero modulo \(\gamma\) if
\[
n_k = 0 \quad \text{for all } k = 1, \ldots, m-1.
\]

Therefore, the only way
\[
\sum_{k=1}^{m-1} \kappa_k n_k \in \gamma \mathbb{N}
\]
holds is if the sum is zero.

This contradicts the existence of a nontrivial tuple \((n_1, \ldots, n_{m-1})\) with the sum in \(\gamma \mathbb{N} \setminus \{0\}\).
\end{proof}


\begin{theorem}
Under the assumptions \textbf{(A1)}--\textbf{(A3)}, suppose the differential system (\ref{2-1})
\[
\frac{\partial x_i}{\partial z_1} = f_i(x), \quad 
\frac{\partial x_i}{\partial z_2} = g_i(x), \quad i = 1, \dots, m,
\]
admits an \( m \)-parameter family of Laurent series solutions in \( z_1 \), whose coefficients depend analytically on \( z_2 \) with possible fractional powers \((z_2 - \beta_0)^{1/\gamma}\), for some minimal integer \(\gamma \geq 1\).

Suppose further that:
\begin{itemize}
    \item \( F \) admits a principal indicial locus associared with K-exp \( \kappa = (-1, \kappa_1, \dots, \kappa_{m-1}) \),
    \item The deformation vector field \( G \) admits a principal balance with \( m-1 \) positive rational Kovalevskaya exponents \( \rho = (\rho_1, \dots, \rho_{m-1})\),
    \item There exists a minimal integer \( \gamma \in \mathbb{Z}_{>0} \) such that \( \gamma \rho_i \in \mathbb{Z} \) for all \( i \).
\end{itemize}
Then:
\begin{enumerate}
    \item The system admits an \( k \)-parameter(\(k\leq m-1\)) family of Laurent series solutions in \( z_1 \), whose coefficients depend on fractional powers of \( (z_2 - \beta_0)^{1/\gamma} \),
    \item In order for the recursion to be consistent, there must exist \( i \ne j \) such that
    \[
    \kappa_{i} - \kappa_{j} \in \gamma \mathbb{N}.
    \]
\end{enumerate}
\end{theorem}

