\subsection{The case $\hat{g}_0(A) \not\equiv 0$}

When $\hat{g}_0(A) \not\equiv 0$, we rewrite (\ref{4-6}) as
\begin{equation}
\frac{d\alpha _i}{d\alpha _0} =h_i(A) := \frac{\hat{g}_i(A)}{\hat{g}_0(A)}, \quad i=1,\cdots ,m-1.
\label{4-13}
\end{equation}
Obviously it has the degree $1$ with respect to the weight $(\kappa _1,\cdots ,\kappa _{m-1})$.
\\

\begin{lemma}
Let $\xi = (\xi_0,\cdots ,\xi_{m-1})$ be an indicial locus of (\ref{4-6})
and suppose that $\hat{g}_0(\xi) \neq 0$.
Then, (\ref{4-13}) has an indicial locus $\widetilde{\xi} = (\widetilde{\xi}_1 ,\cdots , \widetilde{\xi}_{m-1}),\,\,
\widetilde{\xi}_i = \xi_0^{\kappa _i} \xi_i$.
\end{lemma}

\begin{proof}
Since (\ref{4-6}) has the degree $\gamma $, the indicial locus is given by the root of the equation (see (\ref{3-10}))
\begin{equation}
\hat{g}_0(\xi) = -\kappa _0 \xi_0/\gamma = \xi_0 / \gamma ,\quad \hat{g}_i(\xi) = -\kappa _i \xi_i /\gamma,
\label{4-14}
\end{equation}
and an indicial locus of (\ref{4-13}), whose degree is $1$, is given as a root of 
\begin{equation}
\frac{\hat{g}_i(\widetilde{\xi})}{\hat{g}_0(\widetilde{\xi})} = -\kappa _i \widetilde{\xi}_i.
\label{4-15}
\end{equation}
Putting $\widetilde{\xi}_i = \lambda ^{\kappa _i}\xi$ gives
\begin{equation}
\frac{\lambda ^{\kappa _i+\gamma }\hat{g}_i(\xi )}{\lambda ^{-1+\gamma }\hat{g}_0(\xi )} 
= -\lambda ^{\kappa _i}\kappa _i \xi_i.
\label{4-16}
\end{equation}
(\ref{4-14}) is used to show that (\ref{4-16}) is satisfied when $\lambda = \xi_0 \, ( = \gamma \hat{g}_0 (\xi))$.
\end{proof}

\begin{proposition}
Let $\rho_0 = -1,\, \rho_1 = -1/\gamma , \rho_2,\cdots ,\rho_{m-1}$ be K-exponents of (\ref{4-6}) at a locus $\xi$
(see Lemma 4.3).
Then, the K-exponents of (\ref{4-13}) at the locus $\widetilde{\xi}$ above are given by $\rho_0 =-1$
and $\gamma \rho_2 ,\cdots ,\gamma \rho_{m-1}$.
\end{proposition}
\begin{proof}
Denote
\begin{align*}
\mathrm{grad}(\hat{g}_0) =  \left( \frac{\partial \hat{g}_0}{\partial \alpha _1}(\xi) ,\cdots , 
     \frac{\partial \hat{g}_0}{\partial \alpha _{m-1}}(\xi)\right),\quad
(J\hat{g}) = \left\{ \frac{\partial \hat{g}_i}{\partial \alpha _j} (\xi)\right\}^{m-1}_{i,j=1},
\end{align*}
and $\mathrm{diag}(\kappa ) = \mathrm{diag} (\kappa _1,\cdots ,\kappa _{m-1})$.
Then, the K-matrix of (\ref{4-6}) given in (\ref{4-7}) is written as
\begin{equation*}
K_\gamma (\xi) = \left(
\begin{array}{@{\,}c|c@{\,}}
0 & \mathrm{grad}(\hat{g}_0) \\ \hline
0& (J\hat{g})
\end{array}
\right) + \left(
\begin{array}{@{\,}c|c@{\,}}
-1/\gamma & 0 \\ \hline
0 & \mathrm{diag}(\kappa )/\gamma 
\end{array}
\right).
\end{equation*}
Further, put $a = 1/(\gamma  \hat{g}_0(\xi))$ and $v = (\kappa _1 \xi_1 ,\cdots , \kappa _{m-1}\xi_{m-1})^T$,
which is an eigenvector associated with the K-exponent $\rho_0 = -1$ of the subsystem (\ref{f-8}).
Define
\begin{equation*}
P = \left(
\begin{array}{@{\,}c|c@{\,}}
a & 0 \\ \hline
-v & I 
\end{array}
\right).
\end{equation*}
Then, we can verify that 
\begin{equation*}
P^{-1} K_\gamma (\xi)P = \left(
\begin{array}{@{\,}c|c@{\,}}
k_{11} & \mathrm{grad}(\hat{g}_0) / a \\ \hline
k_{21} & k_{22} 
\end{array}
\right),
\end{equation*}
where 
\begin{equation*}
\left\{ \begin{array}{l}
k_{11} = -\mathrm{grad}(\hat{g}_0)\cdot v/a - 1/\gamma ,  \\
k_{21} = -(\mathrm{grad} (\hat{g}_0) \cdot v)v / a- (J\hat{g})v - v/\gamma - \mathrm{diag}(\kappa ) v/\gamma ,  \\
k_{22} = (J\hat{g}) + v\cdot \mathrm{grad}(\hat{g}_0)/a + \mathrm{diag}(\kappa )/\gamma .
\end{array} \right.
\end{equation*}
Since $v$ is an eigenvector of the K-exponent $-1$ of (\ref{f-8}), we have
\begin{align*}
((J\hat{g}_0) + \mathrm{diag}(\kappa )/\gamma )v = -v.
\end{align*}
From the derivative of (\ref{4-5}) at $\lambda =1$, we have
\begin{align*}
\sum^{m-1}_{j=1} \frac{\partial \hat{g}_0}{\partial \alpha _j}(\xi) \kappa _j \xi_i = (-1+\gamma ) \hat{g}_0(\xi).
\end{align*}
By using these two equalities, we can show that $k_{11} = -1$ and $k_{21} = 0$.
Thus, the eigenvalues of $k_{22}$ are $\rho_1 = -1/\gamma $ and $\rho_2, \cdots , \rho_{m-1}$ and the eigenvalues 
of $\gamma \cdot k_{22}$ are $-1$ and $\gamma \rho_2, \cdots , \gamma \rho_{m-1}$.
Hence, it is sufficient to prove that the K-matrix of (\ref{4-13}) at $\widetilde{\xi}$ is conjugate to $\gamma \cdot k_{22}$.

By a straightforward calculation with the aid of (\ref{4-15}), it is easy to see that
the $(i,j)$-component of the K-matrix of (\ref{4-13}) is given by
\begin{align*}
\widetilde{K}(\widetilde{\xi})_{i,j}
 & = \frac{1}{\hat{g}_0 (\widetilde{\xi})} 
   \left( \frac{\partial \hat{g}_i}{\partial \alpha _j}(\widetilde{\xi})
 + \kappa _i \widetilde{\xi}_i \frac{\partial \hat{g}_0}{\partial \alpha _j}(\widetilde{\xi})  \right) 
  + \kappa _i\delta _{ij} \\
&= \frac{\lambda }{\hat{g}_0 (\xi)} 
   \left( \lambda ^{\kappa _i-\kappa _j}\frac{\partial \hat{g}_i}{\partial \alpha _j}(\xi)
 + \lambda ^{\kappa _i-\kappa _j-1} \kappa _i \xi_i \frac{\partial \hat{g}_0}{\partial \alpha _j}(\xi)  \right) 
  + \kappa _i\delta _{ij},
\end{align*}
where $\lambda = \xi_0 = \gamma \hat{g}_0(\xi)$ as in the proof of Lemma 4.5.
Put $Q = \mathrm{diag} (\lambda ^{\kappa _1} , \cdots , \lambda ^{\kappa _{m-1}})$.
Then, we can show that $Q^{-1}\widetilde{K}(\widetilde{\xi}) Q = \gamma k_{22}$. 
\end{proof}


