\section {Quasi-homogeneous Hamiltonian vector field}

In this section, we specialize our general theory to the Hamiltonian setting. We show that the structure of the Hamiltonian imposes a pairing symmetry among the Kovalevskaya exponents, a feature consistently observed in classical Painlevé-type systems. The quasi-homogeneous polynomial structure of Hamiltonians and their role in integrable systems are well studied in the literature \cite{Chi1, Chi4, Bor}.


We consider $2m$-dimensional quasi-homogeneous Hamiltonian system 

\begin{equation}
\frac{d q_{i}}{d z}=\frac{\partial H}{\partial p_{i}}, \quad \frac{d p_{i}}{d z}=-\frac{\partial H}{\partial q_{i}}, \quad i=1, \cdots, m, \label{7-1}
\end{equation}
where $H = H_1,\cdots, H_n(1\leq n \leq m)$.
\\[0.2cm]
We suppose the following.
\\[0.2cm]
\textbf{(A1)}: The Hamiltonian \( H_k(q,p) \) is a quasi-homogeneous polynomial function of \( q = (q_1, \cdots, q_m) \) and \( p = (p_1, \cdots, p_m) \). There exists a tuple of positive integers \( (a_1, \cdots, a_m,b_1, \cdots, b_m) \) and $h_k$ such that for any \( \lambda \in \mathbb{C} \):
\begin{equation}
H_k(\lambda^{a_1} q_1, \ldots, \lambda^{a_m} q_m, \lambda^{b_1} p_1, \ldots,\lambda^{b_m} p_m) = \lambda^{h_k} H_k(q_1, \ldots, q_m, p_1, \ldots, p_m)\label{7-2} 
\end{equation}
where \(h_1 = a_j + b_j + 1\) and $h_1\leq h_k = a_j + b_j + \gamma_k$ for $i = 1,\cdots, n$ and $\gamma_1\leq\gamma_2\leq\cdots\leq\gamma_k$.
\\[0.2cm]
\textbf{(A2)}: The Hamiltonian vector fields \( X_{H_i} \) and \( X_{H_j} \) associated with the Hamiltonians \( H_i \) and \( H_j \) commute, meaning:
\begin{equation}
\{ H_i, H_j \} = \sum^m_{k=1} \left( \frac{\partial H_i}{\partial q_k } \frac{\partial H_j}{\partial p_k}
    - \frac{\partial H_i}{\partial p_k} \frac{\partial H_j}{\partial q_k}\right)= 0, 
\end{equation}
where \( \{ \cdot, \cdot \} \) denotes the Poisson bracket. This implies that the flows generated by \( H_i \) and \( H_j \) preserve each other.
\\[0.2cm]
\textbf{(A3)}: 
The origin is the only fixed point;
$$
\frac{\partial H_{1}}{\partial p_{i}}=\frac{\partial H_{1}}{\partial q_{i}}=0 (i=1, \cdots, m) \Rightarrow\left(q_{1}, \cdots, q_{m}, p_{1}, \cdots, p_{m}\right)=0
$$
\\[0.2cm]
Let us consider the \textit{formal} series solution of (\ref{7-1}) of the form
\begin{equation}
x_i(z) = c_i(z - \alpha _0)^{-a_i} + \sum^\infty_{j=1} d_{i,j} (z - \alpha _0)^{-a_i+j},
\label{7-3}
\end{equation}
where $a_i \in \N$, $\alpha _0$ is a possible singularity and $c_i, d_{i,j} \in \C$ are coefficients.
\\[0.2cm]
Let $c = (c_1, \cdots,c_{2m})$ be an indicial locus determined by $H_1$ as
\begin{equation}
\frac{\partial H_1}{\partial p_i}(c) = -a_ic_i, \quad \frac{\partial H_1}{\partial q_i}(c)=b_ic_{m+i},
\quad i=1,\cdots,m.
\label{7-4}
\end{equation}
The Kovalevskaya matrix at $c$ is 
\begin{eqnarray}
K(c) \!=\!
\left(
\begin{array}{@{\,}cc@{\,}}
\displaystyle \frac{\partial ^2H_1}{\partial p\partial q}(c) \!\!&\! \!
  \displaystyle \frac{\partial ^2H_1}{\partial p\partial p}(c) \\[0.2cm]
-\displaystyle \frac{\partial ^2H_1}{\partial q\partial q}(c) \!\!&\! 
 -\displaystyle \frac{\partial ^2H_1}{\partial q\partial p}(c)
\end{array}
\right)
\!+\!\left(
\begin{array}{@{\,}cc@{\,}}
\mathrm{diag}(a_1,\cdots, a_m) \!\!\!\!&\!\!\!\! 0 \\[0.5cm]
0 \!\!\!\!&\!\!\!\! \mathrm{diag}(b_1, \cdots, b_m)
\end{array}
\right),
\label{7-5}
\end{eqnarray}
where $\partial ^2 /\partial p\partial q
 = \left( \partial ^2 / \partial p_i \partial q_j \right)_{i,j}$. $\Box$
\\[0.2cm]

\begin{remark}
As shown in Proposition 3.3, \(-1\) is always a Kovalevskaya exponent of system \eqref{4-1}. The corresponding eigenvector is proportional to 
\[
(a_1 c_1, \ldots, a_m c_m, b_1 c_{m+1}, \ldots, b_m c_{2m}),
\]
which reflects the underlying scaling symmetry of the quasi-homogeneous system.
\end{remark}

\begin{definition}
Define the gradient of \( H \) as
\[
\nabla H = \left( \frac{\partial H}{\partial q_1}, \dots, \frac{\partial H}{\partial q_m}, \frac{\partial H}{\partial p_1}, \dots, \frac{\partial H}{\partial p_m} \right)^\top.
\]
\end{definition}
\begin{theorem}
Given that \( \nabla H_k(c) \neq 0 \), the value \(-\gamma_k\) is always a Kovalevskaya exponent of system \eqref{7-1} associated with the indicial locus \( c \). The corresponding eigenvector is given by\(\nabla H_k(c)\).
This result was first obtained by Haruo Yoshida in \cite{Yoshida_AlgebraicFirstIntegrals}.
\end{theorem} 
\begin{proof}
This follows directly from Proposition 4.1 and the commutation relation \(\{ H_1, H_k \} = 0\). In particular, the relation
\[
\nabla H_k(c) \left( K(c) + \gamma_k I_{2m} \right) = 0
\]
holds, showing that \(-\gamma_k\) is an eigenvalue of \(K(c)\) with eigenvector \(\nabla H_k(c)\).
\end{proof}
\noindent\textbf{(A4)}: 
The Hamiltonian vector field \( X_H = J \nabla H \) satisfies the infinitesimal symplectic condition:
\[
(DX_H)^\top J + J DX_H = 0,
\]
where \( J = \begin{pmatrix} 0 & I_m \\ -I_m & 0 \end{pmatrix} \) is the standard symplectic matrix.

\vspace{0.2cm}



\begin{lemma}
Under the assumptions \textbf{(A1)}--\textbf{(A3)}, the Hamiltonian vector field \( X_H \) satisfies the infinitesimal symplectic condition \textbf{(A4)}.
\end{lemma}

\begin{proof}
Let \( x = (q_1, \dots, q_m, p_1, \dots, p_m) \in \mathbb{C}^{2m} \). Define the Hessian of \( H \) as
\[
H'' = \left( \frac{\partial^2 H}{\partial x_i \partial x_j} \right)_{1 \leq i,j \leq 2m}.
\]
Then the Hamiltonian vector field is expressed as
\[
X_H = J \nabla H,
\]
and its Jacobian matrix is
\[
DX_H = \frac{\partial X_H}{\partial x} = J H''.
\]
Now, using the symmetry of the Hessian \( H'' \) and the identities \( J^\top = -J \), \( J^2 = -I \), we compute:
\begin{align*}
(DX_H)^\top J + J DX_H 
&= (J H'')^\top J + J (J H'') \\
&= H''^\top J^\top J + J^2 H'' \\
&= H'' (-J) J + (-I) H'' \\
&= -H'' J^2 - H'' \\
&= H'' - H'' = 0.
\end{align*}
Thus, the infinitesimal symplectic condition is satisfied. 
\end{proof}

\begin{remark}
This infinitesimal symplectic condition is classical and can be found in standard references on Hamiltonian systems and symplectic geometry \cite{Magri, Morales}.
\end{remark}



\begin{proposition}
Let \( (X, \omega) \) be a symplectic manifold with coordinates \( x \in \mathbb{C}^{2m} \). We assume:
\begin{itemize}
    \item The vector fields \( F = X_H \) and \( G = X_K \) are Hamiltonian with respect to the symplectic form \( \omega =dx^\top \wedge J dx\), i.e., 
    \[
    F(x) = J \nabla_x H(x), \quad G(x) = J \nabla_x K(x),
    \]
    where \( H(x) \) and \( K(x) \) are the Hamiltonians associated with the vector fields \( F \) and \( G \), respectively.
    \item The flow of \( F \) and \( G \) satisfies the assumptions \textbf{(A1)}–\textbf{(A4)}.
\end{itemize}
Then, the vector field \( \hat{G}(A) \) defined by (\ref{4-1})
\[
\frac{dA}{dz_2} = \hat{G}(A) := \left( \frac{\partial \Phi}{\partial A} \right)^{-1} G(\Phi(A)),
\]
is Hamiltonian with respect to the pullback symplectic form \( \omega_A \), where
\[
\omega_A := \Phi^* \omega = dA^\top \wedge J_A dA, \quad \text{with } J_A := \left( \frac{\partial \Phi}{\partial A} \right)^\top J \left( \frac{\partial \Phi}{\partial A} \right).
\]
The Hamiltonian function governing the parameter flow is \( \hat{K}(A) := K(\Phi(A)) \).

\end{proposition}

\begin{proof}
Let \( x = \Phi(A) \in \mathbb{C}^{2m} \) be a parametrization of an invariant manifold for the original Hamiltonian system. The vector field \( G \) satisfies the Hamiltonian condition
\[
G(x) = J \nabla_x K(x),
\]
where \( K(x) \) is the Hamiltonian of the system.
It follows that the parameter flow is given by
\begin{equation}
    \frac{dA}{dz_2} = \left( \frac{\partial \Phi}{\partial A} \right)^{-1} G(\Phi(A)) = \left( \frac{\partial \Phi}{\partial A} \right)^{-1} J \nabla_x K.
    \label{7-6}
\end{equation}
Define the pulled-back Hamiltonian function
\[
\hat{K}(A) := K(\Phi(A)).
\]
To find the gradient of \( \hat{K}(A) \), we apply the chain rule:
\[
\nabla_A \hat{K} = \left( \frac{\partial \Phi}{\partial A} \right)^\top \nabla_x K.
\]
Substitute the expression for \( \nabla_x K \) in terms of \( \nabla_A \hat{K} \) inside (\ref{7-6}):
\begin{align*}
\frac{dA}{dz_2} &= \left( \frac{\partial \Phi}{\partial A} \right)^{-1} J \left( \left( \frac{\partial \Phi}{\partial A} \right)^{-\top} \nabla_A \hat{K} \right)\\
&= \left[ \left( \frac{\partial \Phi}{\partial A} \right)^\top J \left( \frac{\partial \Phi}{\partial A} \right) \right]^{-1} \nabla_A \hat{K}\\
&= J_A^{-1} \nabla_A \hat{K}.
\end{align*}
Thus, the vector field governing the parameter flow is Hamiltonian with respect to the symplectic form \( \omega_A \), and the Hamiltonian function is \( \hat{K}(A) \).
\end{proof}

\begin{definition}
Let
\(
\Gamma = \operatorname{diag}(-1, \kappa_1, \dots, \kappa_{m-1})
\)
and
\(
\Gamma_x = \operatorname{diag}(a_1, \dots, a_m)
\)
denote the diagonal weight and degree matrix
such that
\[
\Phi_i(\lambda \cdot A) = \lambda^{a_i} \Phi_i(A), \quad \text{for all } \lambda \in \mathbb{C}^*, \quad 1 \leq i \leq m,
\]
under the weighted dilation
\[
\lambda \cdot A := (\lambda^{-1} \alpha_0, \lambda^{\kappa_1} \alpha_1, \dots, \lambda^{\kappa_{m-1}} \alpha_{m-1}).
\]
\end{definition}

\begin{remark}
The infinitesimal symplectic condition (A4) guarantees that the Kovalevskaya exponents for the \( F \)-flow, generated by the Hamiltonian vector field \( X_H = J \nabla H \), occur in symmetric pairs, with the symmetry centered around \( \frac{\mathrm{tr}(\Gamma_x)}{2m} \). For the \( \Hat{G} \)-flow, we will further demonstrate that the exponents exhibit a similar symmetry, but with the center of symmetry at \( \frac{\mathrm{tr}(\Gamma)}{2m\gamma} \).
\end{remark}

\begin{lemma}
The Jacobian matrix $J_\Phi := \frac{\partial \Phi}{\partial A}$ satisfies the identity:
\[
J_\Phi^T \Gamma_x = \Gamma J_\Phi^T.
\]
\end{lemma}

\begin{proof}
Differentiating the quasi-homogeneity condition
\[
\Phi_i(\lambda \cdot A) = \lambda^{a_i} \Phi_i(A)
\]
with respect to $\lambda$ at $\lambda = 1$ gives:
\[
\sum_{j=0}^{m-1} \frac{\partial \Phi_i}{\partial \alpha_j}(A) \cdot \kappa_j \alpha_j = a_i \Phi_i(A).
\]
In vector notation, this becomes:
\[
\left( \frac{\partial \Phi}{\partial A}(A) \cdot \Gamma \cdot A \right)_i = a_i \Phi_i(A),
\]
which implies the matrix equation:
\[
\frac{\partial \Phi}{\partial A} \cdot \Gamma \cdot A = \Gamma_x \cdot \Phi(A).
\]
Differentiating both sides with respect to $A$, we obtain:
\[
\Gamma_x \cdot \frac{\partial \Phi}{\partial A} = \frac{\partial \Phi}{\partial A} \cdot \Gamma.
\]
Taking the transpose yields:
\[
\left( \frac{\partial \Phi}{\partial A} \right)^T \Gamma_x = \Gamma \left( \frac{\partial \Phi}{\partial A} \right)^T.
\]
\end{proof}

\begin{proposition}
Let \( \xi =\Phi^{-1}(c) \in \mathbb{C}^m \) be a fixed point of \( \hat{G} \). 
The linearized vector field $D_\xi \hat{G}$ satisfies
\begin{equation}
    J_A D_\xi \hat{G} + D_\xi \hat{G}^T J_A = \frac{1}{\gamma} J_A \Gamma,
    \label{7-8}
\end{equation}
where $J_A := \left( \frac{\partial \Phi}{\partial A} \right)^T J \left( \frac{\partial \Phi}{\partial A} \right)$ is the pullback symplectic form in coordinates $A$.
\end{proposition}

\begin{proof}
By the chain rule, the Jacobian of $\hat{G}(A) = \left( \frac{\partial \Phi}{\partial A} \right)^{-1} G(\Phi(A))$ at $A = \xi$ is
\[
D_{\xi} \hat{G} = \left( \frac{\partial \Phi}{\partial A} \right)^{-1} D_x G \left( \frac{\partial \Phi}{\partial A} \right),
\]
evaluated at $A = \xi$.

By the quasi-homogeneity of \( G \), the Jacobian \( D_x G \) satisfies the \emph{twisted infinitesimal symplectic condition}:
\begin{equation}
    J D_x G + (D_x G)^T J = \frac{1}{\gamma} J \Gamma_x
    \label{7-7}
\end{equation}
for a constant $\gamma \in \mathbb{C}$ and standard symplectic form $J$.


Multiplying both sides of (\ref{7-7}) on the left and right by the transpose and the matrix of $\frac{\partial \Phi}{\partial A}$, we get:
\[
\begin{aligned}
J_A D_\xi \hat{G} + D_\xi \hat{G}^T J_A 
&= \left( \frac{\partial \Phi}{\partial A} \right)^T J D_x G \left( \frac{\partial \Phi}{\partial A} \right)
+ \left( \frac{\partial \Phi}{\partial A} \right)^T (D_x G)^T J \left( \frac{\partial \Phi}{\partial A} \right) \\
&= \left( \frac{\partial \Phi}{\partial A} \right)^T \left( J D_x G + (D_x G)^T J \right) \left( \frac{\partial \Phi}{\partial A} \right) \\
&= \frac{1}{\gamma} \left( \frac{\partial \Phi}{\partial A} \right)^T J \Gamma_x \left( \frac{\partial \Phi}{\partial A} \right).
\end{aligned}
\]

We substitute Lenna 7.8 into the last expression and get:
\[
J_A D_\xi \hat{G} + D_\xi \hat{G}^T J_A = \frac{1}{\gamma} J_A \Gamma.
\]
\end{proof}

\begin{theorem}
Define the \emph{Kovalevskaya matrix} \( K \) as:
\[
K := D_{\xi} \hat{G} - \frac{1}{2\gamma} \Gamma.
\]
Then, the Kovalevskaya matrix satisfies:
\[
J_A K + K^T J_A = 0,
\]
which implies that the eigenvalues of \( K \), and thus the Kovalevskaya exponents, occur in opposite pairs. In particular, if \( \lambda \) is a Kovalevskaya exponent, then \( \frac{1}{2m\gamma} \mathrm{tr}(\Gamma) - \lambda \) is also a Kovalevskaya exponent.

\end{theorem}

\begin{proof}

We begin with the definition of \( K \):
\[
K := D_{\xi} \hat{G} - \frac{1}{2\gamma} \Gamma.
\]
Then, we compute:
\[
J_A K + K^T J_A = J_A \left( D_{\xi} \hat{G} - \frac{1}{2\gamma} \Gamma \right) + \left( D_{\xi} \hat{G} - \frac{1}{2\gamma} \Gamma \right)^T J_A.
\]
Expanding this expression gives:
\[
J_A K + K^T J_A = J_A D_{\xi} \hat{G} + D_{\xi} \hat{G}^T J_A - \frac{1}{2\gamma} (J_A \Gamma + \Gamma J_A).
\]
Using the twisted infinitesimal symplectic condition (\ref{7-8}), we replace \( J_A D_{\xi} \hat{G} + D_{\xi} \hat{G}^T J_A \) with \( \frac{1}{\gamma} J_A \Gamma \), yielding:
\[
J_A K + K^T J_A = \frac{1}{\gamma} J_A \Gamma - \frac{1}{2\gamma} (J_A \Gamma + \Gamma J_A) = 0.
\]
This proves that \( J_A K + K^T J_A = 0 \), implying that the eigenvalues of \( K \) are symmetric with respect to \( \frac{1}{2m\gamma} \mathrm{tr}(\Gamma) \). Thus, the Kovalevskaya exponents occur in opposite pairs.
\end{proof}

\begin{remark}
The pairing property of the Kovalevskaya exponents implies that the sum of the weights \(a_i\) equals the sum of the Kovalevskaya exponents \(\kappa_k\):

\[
\sum_{i=1}^m a_i = \sum_k \kappa_k.
\]

This is equivalent to the equality of the traces of the degree and weight matrices:

\[
\text{tr}(\Gamma_x) = \text{tr}(\Gamma).
\]

This relationship reflects the scaling symmetry of the system and the consistency between the degrees of the Hamiltonian and the Kovalevskaya exponents.
\end{remark}

The pairing symmetry of Kovalevskaya exponents has been widely studied in the literature, such as in \cite{Chi2, Chi3, Gor, Gor2}. The results presented in this section offer a novel contribution by establishing the equivalence between the sum of the weights \(a_i\) and the sum of the Kovalevskaya exponents \(\kappa_k\), as reflected in the equality \(\text{tr}(\Gamma_x) = \text{tr}(\Gamma)\). Additionally, we show that the \(G\)-flow satisfies the twisted infinitesimal symplectic condition, distinguishing its pairing symmetry from that of the \(F\)-flow. These findings enhance the understanding of scaling properties and symmetries in quasi-homogeneous Hamiltonian systems, extending previous work on integrable systems.

\begin{example}
We consider the Hamiltonians of degree 2:

\begin{equation}
\left\{ \begin{array}{l}
\displaystyle H_1 
= 2p_2p_1 + 3p_2^2q_1 + q_1^4 - q_1^2q_2 - q_2^2,  \\
\displaystyle H_2 
= p_1^2 + 2p_2p_1q_1 - q_1^5 + p_2^2q_2 + 3q_1^3q_2 - 2q_1q_2^2.
\end{array} \right.
\label{5-8}
\end{equation}

These Hamiltonians represent autonomous parts of the system $(\text{P}_\text{I})_2$ as outlined in equation (\ref{1-3}), and are studied in the references \cite{Chi2, Sakai}. They satisfy the assumptions \textbf{(A1)}–\textbf{(A4)} with the weight $\Gamma_x=(a_1, a_2, b_1, b_2) = (2, 4, 5, 3)$, and corresponding Hamiltonian degrees $h_1 = 8$ and $h_2 = 10$, as shown in Table 3. 

We now examine the system at two specific indicial loci:

\begin{itemize}
    \item For $c_1 = (1, 1, 1, -1)$, where $\nabla H_2(c_1) = 0$, the Kovalevskaya exponents are computed as $\kappa_1 = -1, 2, 5, 8$. These exponents are symmetric around \( \frac{\mathrm{tr}(\Gamma_x)}{2} = \frac{2+4+5+3}{2*2} = 3.5 \), as implied by the infinitesimal symplectic condition (A4). Furthermore, it yields a Laurent series solution (\ref{4-6}) that represents a general solution with four free parameters, confirming the validity of the Painlevé test.

    \item For $c_2 = (3, 0, 27, -3)$, where $\nabla H_2(c_2) \neq 0$, Theorem 7.3 gives us the Kovalevskaya exponent $-\gamma_2 = -3$. The complete set of exponents at this locus is \( \kappa_2 = -3, -1, 8, 10 \), and these also exhibit symmetry around \( 3.5 \).
\end{itemize}

Next, we analyze the $G$-flow, which is governed by the indicial locus $\xi = (0, 0, 0, 1)$ and has Kovalevskaya exponents $\rho = \left(-1, -\frac{1}{3}, \frac{8}{3}, \frac{10}{3}\right)$. We observe that the relationship between the exponents is consistent with the pairing property established in Theorem 7.10: $\gamma_2 \cdot \rho = \kappa_2$, where $\gamma_2 = 3$, and $\Gamma = \operatorname{diag}(-1, 2, 5, 8)$. Specifically, the symmetry is around \( \frac{\mathrm{tr}(\Gamma)}{2m\gamma} = \frac{14}{2*2*3} = \frac{7}{6} \).
\end{example}


