\subsection{Simple and Efficient Membership Tests}


\begin{definition}
We define the \defn{set of canonical bigrams} as
\begin{align}
\canonicalBigrams \defeq 
\set{\token \c \tokenp \mid \token, \tokenp \in \tokAlphabet, \canonicalize(\token \c \tokenp) = \token \c \tokenp}.
\end{align}
where $\canonicalize$ is the canonicalization function (\cref{sec:canonicalization-function}).
\end{definition}

\begin{definition}
\label{def:locally-canonical-strings}
We define the \defn{set of bigram-canonical strings} $\B$ as strings composed of only canonical bigrams:
\begin{align}
\B \defeq \{\tokseq \in \tokStrings \colon \bigrams(\tokseq) \subseteq \canonicalBigrams \}.
\end{align}
\end{definition}
In general, it is possible for a token in the token vocabulary not to be canonical. Such tokens can always be removed from the token vocabulary without changing the result of the BPE tokenizer. We assume, for simplicity, that the token vocabulary contains no such tokens.
\begin{assumption}
\label{canonical-tokens-assumption}
For all $\token \in \tokAlphabet$, $\canonicalize(\token) = \token$.
\end{assumption}

\begin{definition}
We define the \defn{truncated canonicalization function} $\canonicalize_T$ as follows:
\begin{center}
\begin{minipage}[t]{.95\linewidth}
\begin{minted}{python}
def @$\canonicalize_T$@(@$\tokseq$@):
  @$\character_1 \cdots \character_{N} \gets \cotokenizer(\tokseq)$@        # decode token string
  @$\tokseq\psup{0} \gets \baseEncoder(\character_1) \cdots  \baseEncoder(\character_{N})$@   # initialize with base tokens
  for @$t = 0, \ldots, (T-1)$@:
     @$\tokseq\psup{t+1} \gets$@ rewrite@$(\tokseq\psup{t}) $@ 
     if @$\tokseq\psup{t+1} = \tokseq\psup{t}$@: return @$\tokseq\psup{t}$@
  return @$\tokseq\psup{T}$@
\end{minted}
\end{minipage}
\end{center}
\end{definition}

\vspace{.5\baselineskip}
\begin{remark}
It is straightforward to verify that $\canonicalize = \canonicalize_{\infty}$, as it is equivalent to code for $\tokenizer(\cotokenizer(\cdot))$ where we have added the option of truncating the number of iterations performed in $\tokenizer$'s fixpoint iteration loop.  Setting $T = \infty$, disables the truncation; thus, $\canonicalize = \canonicalize_{\infty}$.
\end{remark}


\clearpage

\begin{lemma}[Canonicalization process synchronization]
\label{lemma:lockstep}    
Suppose that $\tokWhole \in \D$ or both $\tokLeftMid, \tokMidRight \in \D$. Suppose further that \tokMid is nonempty.
Then, there exists a sequence $\{(a_t, b_t, c_t, d_t, e_t)\}_{t=1}^\infty$ such that the following equations hold for all $t \ge 0$:
\vspace{-0.5\baselineskip}
\begin{align}
P_t \defeq
\begin{cases}
\canonicalize_{t}(\tokWhole) 
=  
\canonicalize_{a_t}(\tokLeft) 
\canonicalize_{b_t}(\tokMid) 
\canonicalize_{c_t}(\tokRight) 
\\
\canonicalize_{d_t}(\tokLeftMid) 
=    
\canonicalize_{a_t}(\tokLeft) 
\canonicalize_{b_t}(\tokMid) 
\\
\canonicalize_{e_t}(\tokMidRight) 
=    
\canonicalize_{b_t}(\tokMid) 
\canonicalize_{c_t}(\tokRight) 
\end{cases}
\end{align}
\end{lemma}
\vspace{-1.5\baselineskip}
\begin{proof}
We will prove \cref{lemma:lockstep} by induction on $t$, and by explicitly constructing the sequence $\{(a_t, b_t, c_t, d_t, e_t)\}_{t=1}^\infty$.

Let $T$ denote the number of distinct iterations of $\canonicalize(\tokWhole)$.

\emph{Base case ($P_0$).}  In this case, it is straightforward to verify that $(a_0, b_0, c_0, d_0, e_0) = (0,0,0,0,0)$ satisfies $P_0$ because each canonicalization call returns precisely the base tokenization of its argument.  Thus, $P_0$ holds.

\emph{Induction step.} 
Suppose $P_0, {\ldots}, P_{j}$ hold.  We seek to show that $P_{j+1}$ holds. 

Since $P_{j}$ holds, there must exist $(a_t, b_t, c_t, d_t, e_t)$ satisfying the equations in $P_t$.  To prove that $P_{t+1}$ holds, we will construct $(a_{t+1}, b_{t+1}, c_{t+1}, d_{t+1}, e_{t+1})$ such that the equations in $P_{t+1}$.

We first observe that at time $t$, $\canonicalize_t(\tokWhole) = \tokLeft\psup{t} \tokMid\psup{t} \tokRight\psup{t}$ where
\begin{itemize}
\item $\tokLeft\psup{t}$ is the tokenization at step $t$ of the substring over the characters in \tokLeft in the canonicalization process for \tokWhole
\item $\tokMid\psup{t}$ is the tokenization at step $t$ of the substring over the characters in \tokMid in the canonicalization process for \tokWhole 
\item $\tokRight\psup{t}$ is the tokenization at step $t$ of the substring over the characters in \tokRight in the canonicalization process for \tokWhole
\end{itemize}

The only way for this observation to be false is for a merge to straddle the boundary between $\tokLeft\psup{t}$ and $\tokMid\psup{t}$ or $\tokMid\psup{t}$ and $\tokRight\psup{t}$, which is impossible because of our premise that $\tokWhole \in \D$ or both $\tokLeftMid, \tokMidRight \in \D$.  More specifically, if there ever were a merge between 
$\tokLeft\psup{t}$ and $\tokMid\psup{t}$ then $\tokLeftMid$ and $\tokWhole$ could not be canonical, as the final tokenization would not respect the boundary between \tokLeft and \tokMid.  Similarly, if there ever were a merge between $\tokMid\psup{t}$ and $\tokRight\psup{t}$, then by analogous reasoning, \tokMidRight and \tokWhole could not be canonical.


We now turn to case analysis:

\begin{enumerate}
\item Suppose $t < T$, then the $(t\!+\!1)$\textsuperscript{th} step of $\canonicalize(\tokWhole)$ applies to the highest-priority\footnote{I.e., the bigram with the lexicographically lowest pair of (position in the merge list, position in the current token string). Note that there can be no ties under this ordering.} bigram of $\tokLeft\psup{t} \tokMid\psup{t} \tokRight\psup{t}$.  Consider the following subcases characterizing the possible positions for this merge:
\begin{enumerate}
\item The merge is in $\tokLeft\psup{t}$. 

Then,
$(a_{t+1}, b_{t+1}, c_{t+1}, d_{t+1}, e_{t+1}) = (a_{t} + 1, b_{t}, c_{t}, d_{t} + 1, e_{t})$
satisfies $P_{t+1}$ because
\begin{itemize}
\item It must also be the highest-priority merge in $\tokLeft\psup{t}$, 
which is step $a_{t+1}$ of $\canonicalize(\tokLeft)$. 

\item It must also be the highest-priority merge in $\tokLeft\psup{t} \tokMid\psup{t}$, 
which is step $d_{t+1}$ of $\canonicalize(\tokLeftMid)$. 

\item The other canonicalization processes are unaffected, so they copy their position on this step.

\end{itemize}


\item The merge is in $\tokMid\psup{t}$. 


Then,
$(a_{t+1}, b_{t+1}, c_{t+1}, d_{t+1}, e_{t+1}) = (a_{t}, b_{t} + 1, c_{t}, d_{t} + 1, e_{t} + 1)$
satisfies $P_{t+1}$
because
\begin{itemize}
\item It must also be the highest-priority merge in $\tokMid\psup{t}$, 
which is step $b_{t+1}$ of $\canonicalize(\tokMid)$. 

\item It must also be the highest-priority merge in $\tokLeft\psup{t} \tokMid\psup{t}$, 
which is step $d_{t+1}$ of $\canonicalize(\tokLeftMid)$. 

\item It must also be the highest-priority merge in $\tokMid\psup{t} \tokRight\psup{t}$, 
which is step $e_{t+1}$ of $\canonicalize(\tokMidRight)$. 

\item The other canonicalization processes are unaffected, so they copy their position on this step.

\end{itemize}


\item The merge is in $\tokRight\psup{t}$. 


Then,
$(a_{t+1}, b_{t+1}, c_{t+1}, d_{t+1}, e_{t+1}) = (a_{t}, b_{t}, c_{t} + 1, d_{t}, e_{t} + 1)$
satisfies $P_{t+1}$
because
\begin{itemize}
\item It must also be the highest-priority merge in $\tokRight\psup{t}$, 
which is step $c_{t+1}$ of $\canonicalize(\tokRight)$. 

\item It must also be the highest-priority merge in $\tokMid\psup{t} \tokRight\psup{t}$, 
which is step $e_{t+1}$ of $\canonicalize(\tokMidRight)$. 

\item The other canonicalization processes are unaffected, so they copy their position on this step.

\end{itemize}

\end{enumerate}


\item Suppose $t \ge T$.  No merges exist.

Then, $(a_{t+1}, b_{t+1}, c_{t+1}, d_{t+1}, e_{t+1}) = (a_{t}, b_{t}, c_{t}, d_{t}, e_{t})$
satisfies $P_{t+1}$ because $\canonicalize_t(\tokWhole) = \canonicalize_T(\tokWhole) = \tokLeft\psup{t} \tokMid\psup{t} \tokRight\psup{t} = \tokLeft\psup{T} \tokMid\psup{T} \tokRight\psup{T}$, by definition of $T$, which implies that no further changes are possible and all processes must copy their position on this step, and continue to do so forever.

\end{enumerate}

Therefore, $P_t$ holds for all $t \ge 0$ by the principle of induction.
\end{proof}
