\begin{lemma}[Interlocking Canonicalization]
\label{lemma:interlocking-derivations}
\begin{align}
\forall \tokLeft \in \tokStrings, \tokMid \in \kleeneplus{\tokAlphabet}, \tokRight \in \tokStrings \colon \tokWhole \in \D \Longleftrightarrow \tokLeftMid \in \D \land  \tokMidRight \in \D
\end{align}
\end{lemma}
\begin{proof}
Fix $\tokLeft \in \tokStrings$, $\tokMid \in \kleeneplus{\tokAlphabet}$, and $\tokRight \in \tokStrings$ arbitrarily.

We will consider the direction of the bi-implication separately.

\textbf{Case ($\Longrightarrow$)}.  Suppose that $\tokWhole \in \D$.  Then, \cref{lemma:lockstep} gives us a sequence $\{(a_t, b_t, c_t, d_t, e_t)\}_{t=1}^\infty$ such that the following equations hold for all $t \ge 0$.
\begin{subequations}
\begin{align}
P_t \defeq
\begin{cases}
\canonicalize_{t}(\tokWhole) 
=  
\canonicalize_{a_l}(\tokLeft) 
\canonicalize_{b_t}(\tokMid) 
\canonicalize_{c_t}(\tokRight) 
\\
\canonicalize_{d_t}(\tokLeftMid) 
=    
\canonicalize_{a_t}(\tokLeft) 
\canonicalize_{b_t}(\tokMid) 
\\
\canonicalize_{e_t}(\tokMidRight) 
=    
\canonicalize_{b_t}(\tokMid) 
\canonicalize_{c_t}(\tokRight) 
\end{cases}
\end{align}
Now, consider $(a_T, b_T, c_t, d_T, e_T)$, which gives
\begin{align}
\begin{cases}
\canonicalize_{T}(\tokWhole) 
=  
\canonicalize_{a_T}(\tokLeft) 
\canonicalize_{b_T}(\tokMid) 
\canonicalize_{c_T}(\tokRight) 
\\
\canonicalize_{d_T}(\tokLeftMid) 
=    
\canonicalize_{a_T}(\tokLeft) 
\canonicalize_{b_T}(\tokMid) 
\\
\canonicalize_{e_T}(\tokMidRight) 
=    
\canonicalize_{b_T}(\tokMid) 
\canonicalize_{c_T}(\tokRight) 
\end{cases}
\end{align}
which implies the following because, at time $T$, \emph{each} of the canonicalization processes has reached its respective fixpoint:
\begin{align}
\begin{cases}
\canonicalize(\tokWhole) 
=  
\canonicalize(\tokLeft) 
\canonicalize(\tokMid) 
\canonicalize(\tokRight) 
\\
\canonicalize(\tokLeftMid) 
=    
\canonicalize(\tokLeft) 
\canonicalize(\tokMid) 
\\
\canonicalize(\tokMidRight) 
=
\canonicalize(\tokMid) 
\canonicalize(\tokRight) 
\end{cases}
\end{align}
which implies the following because each call to $\canonicalize$ must return the canonicalization of its respective argument:
\begin{align}
\begin{cases}
\canonicalize(\tokWhole) 
=  
\tokLeft
\tokMid
\tokRight
\\
\canonicalize(\tokLeftMid) 
=    
\tokLeft
\tokMid
\\
\canonicalize(\tokMidRight) 
=
\tokMid
\tokRight
\end{cases}
\end{align}
Therefore, $\tokLeftMid$ and $\tokMidRight$ are also canonical.
\end{subequations}

\textbf{Case ($\Longleftarrow$)}.
Suppose $\tokLeftMid, \tokMidRight \in \D$.  Then, following an identical argument as the $\Longrightarrow$-case, we can see that $\tokWhole \in \D$.

Thus, the bi-implication holds; thus, \cref{lemma:interlocking-derivations} holds.
\end{proof}

\clearpage
\Cref{bigram-lemma} establishes that a BPE token string is canonical if and only if all of its bigrams are canonical.\footnote{Note that if a string with length less than or equal to one has no bigrams; thus, the property is trivially satisfied, i.e., all length-zero and length-one token strings are canonical.  The latter is thanks to \cref{canonical-tokens-assumption}.}

\begin{theorem}
\label{bigram-lemma}
$\D = \B$.
\end{theorem}
\newcommand{\lengthP}[1]{P(#1)}
\newcommand{\currIndex}{i}
\newcommand{\tokseqLength}{N}
\begin{proof}[Proof]
We seek to prove, for all $\tokseq \in \tokStrings$, that $\tokseq \in \D \Longleftrightarrow \tokseq \in \B$. We do this using induction on prefixes of $\tokseq$ and \cref{lemma:interlocking-derivations}.

Choose $\tokseq = \token_1 \cdots \token_{\tokseqLength} \in \tokStrings \in \tokStrings$ arbitrarily. Let the induction hypothesis $\lengthP{\currIndex}$ be that $\tokseq_{\leq \currIndex} \in \D \Longleftrightarrow \tokseq_{\leq \currIndex} \in \B$.

\emph{Base cases.} We first prove $\lengthP{0}$ and, if $|\tokseq| \geq 1$, $\lengthP{1}$.
\begin{itemize}
\item \textbf{Case $\lengthP{0}$.} To prove $\lengthP{0}$, we seek to show that $\tokseq_{\leq 0} = \varepsilon \in \D \Longleftrightarrow \tokseq_{\leq 0} = \varepsilon \in \B$. Both sides of the bi-implication are always true: $\varepsilon \in \D$ because $\canonicalize(\varepsilon) = \tokenizer(\cotokenizer(\varepsilon)) = \tokenizer(\varepsilon) = \varepsilon$; and $\varepsilon \in \B$ because it contains no bigrams, hence it is vacuously true. Therefore, $\lengthP{0}$ is true. 
\item \textbf{Case $\lengthP{1}$.} To prove that $\lengthP{1}$ is true for cases where $|\tokseq| \geq 1$, we seek to show that $\tokseq_{\leq 1} = \token_1 \in \D \Longleftrightarrow \tokseq_{\leq 1} = \token_1 \in \B$. Again, both sides of the bi-implication are always true. By \cref{canonical-tokens-assumption}, we know that $\token_1 \in \D$ is true. Since $\token_1$ has no bigrams, $\token_1 \in \B$ is vacuously true. Therefore, $\lengthP{1}$ is true.
\end{itemize}


\emph{Induction step.} Assume $\lengthP{\currIndex}$, that $\tokseq_{\leq \currIndex} \in \D \Longleftrightarrow \tokseq_{\leq \currIndex} \in \B$, where $\currIndex \geq 2$. We seek to prove $\lengthP{\currIndex+1}$, that $\tokseq_{\leq \currIndex+1} \in \D \Longleftrightarrow \tokseq_{\leq \currIndex+1} \in \B$. We prove each direction of the bi-implication separately.

\begin{itemize}
\item \textbf{Forward.} We seek to prove $\tokseq_{\leq \currIndex+1} \in \D \Longrightarrow \tokseq_{\leq \currIndex+1} \in \B$. Assume $\tokseq_{\leq \currIndex+1} = \tokseq_{\leq \currIndex-1} \token_{\currIndex} \token_{\currIndex+1} \in \D$. By \cref{lemma:interlocking-derivations}, we know that $\tokseq_{\leq \currIndex-1} \token_{\currIndex} \in \D$ and $\token_{\currIndex} \token_{\currIndex+1} \in \D$. Since $\tokseq_{\leq \currIndex-1} \token_{\currIndex} \in \D$, by $\lengthP{\currIndex}$, we know that $\tokseq_{\leq \currIndex-1} \token_{\currIndex} \in \B$. Since $\tokseq_{\leq \currIndex-1} \token_{\currIndex} \in \B$ and $\token_{\currIndex} \token_{\currIndex+1} \in \D$, all of the bigrams in $\tokseq_{\leq \currIndex-1} \token_{\currIndex} \token_{\currIndex+1} = \tokseq_{\leq \currIndex+1}$ are canonical, so $\tokseq_{\leq \currIndex+1} \in \B$.

\item \textbf{Backward.} We seek to prove $\tokseq_{\leq \currIndex+1} \in \B \Longrightarrow \tokseq_{\leq \currIndex+1} \in \D$. Assume $\tokseq_{\leq \currIndex+1} = \tokseq_{\leq \currIndex-1} \token_{\currIndex} \token_{\currIndex+1} \in \B$. Then $\tokseq_{\leq \currIndex-1} \token_{\currIndex} \in \B$, because it contains only a subset of the bigrams in $\tokseq_{\leq \currIndex-1} \token_{\currIndex} \token_{\currIndex+1}$. Then, by $\lengthP{\currIndex}$, we know that $\tokseq_{\leq \currIndex-1} \token_{\currIndex} \in \D$. From $\tokseq_{\leq \currIndex-1} \token_{\currIndex} \token_{\currIndex+1} \in \B$ and \cref{def:locally-canonical-strings}, we know that $\token_{\currIndex} \token_{\currIndex+1} \in \D$. Since $\tokseq_{\leq \currIndex-1} \token_{\currIndex} \in \D$ and $\token_{\currIndex} \token_{\currIndex+1} \in \D$, by \cref{lemma:interlocking-derivations}, we know that $\tokseq_{\leq \currIndex-1} \token_{\currIndex} \token_{\currIndex+1} = \tokseq_{\leq \currIndex+1} \in \D$.
\end{itemize}

By induction, we know $P(\tokseqLength)$ is true, so $\tokseq \in \D \Longleftrightarrow \tokseq \in \B$, and the proof is complete.
\end{proof}

\clearpage
\begin{lemma}
\label{BPE-is-prefix-closed}
For BPE,\footnote{More generally, \cref{BPE-is-prefix-closed} holds for any tokenization model with a bigram-based canonicality test (i.e., $\tokseq \in \D \Longleftrightarrow \bigrams(\tokseq) \subseteq \canonicalBigrams$.} the set of canonical strings is prefix closed, i.e.,
$\D = \preD$.
\end{lemma}
\begin{proof}
We prove $\D \subseteq \preD$ and $\preD \subseteq \D$.
\begin{itemize}
\item \emph{Part 1} ($\D \subseteq \preD$). Obvious by definition of $\preD$.

\item \emph{Part 2} ($\preD \subseteq \D$). 
\begin{enumerate}
\item Suppose $\tokseq \in \preD$
\item $\Longrightarrow$ by definition of $\preD$, there is a $\tokseqp \in \D$ such that $\tokseq \preceq \tokseqp$
\item $\Longrightarrow$ by \cref{bigram-lemma}, the bigrams of $\tokseqp$ are all canonical
\item $\Longrightarrow$ since $\tokseq \preceq \tokseqp$, its bigrams are a subset of those of $\tokseqp$, so they are also all canonical
\item $\Longrightarrow$ since the bigrams of $\tokseq$ are all canonical, by \cref{bigram-lemma}, $\tokseq \in \D$
\end{enumerate}

\end{itemize}
Therefore, $\preD = \D$.
\end{proof}



