  \path[name path=CB]   (C) -- (B);
  \path[name path=DF]   (D) -- (F);
  \path[name path=FE]   (F) -- (E);
  \path[name path=GI]   (G) -- (I);

  \path[name intersections={of=CB and DF, name=i}];
  \coordinate (star1) at (i-1);

  \path[name intersections={of=FE and GI, name=j}];
