\section{Supporting Proofs and Lemmata}
\begin{proposition}
\label{prop:the-other-half-of-the-bijection}
Suppose that the tokenization model $(\tokenizer, \cotokenizer, \charAlphabet, \tokAlphabet)$ is exact, then 
\begin{equation}
\forall \tokseq\in\tokStrings\colon\ \tokseq \in \D \Longleftrightarrow \canonicalize(\tokseq) = \tokseq    
\end{equation}
\end{proposition} 
\vspace{-\baselineskip}
\begin{proof}
Fix an arbitrary $\tokseq\in\tokStrings$. We consider each direction separately:
\begin{itemize}
\item \textbf{Part 1} ($\tokseq \in \D \Longrightarrow \canonicalize(\tokseq) = \tokseq$):
\begin{enumerate}
\item Suppose $\tokseq \in \D$
\item $\Longrightarrow \exists \charseq \in \charStrings\colon \tokseq = \tokenizer(\charseq)$ by definition of $\D$
\item $\Longrightarrow \cotokenizer(\tokenizer(\charseq)) = \charseq$ by exactness assumption
\item $\Longrightarrow \tokenizer(\cotokenizer(\tokenizer(\charseq))) = \tokenizer(\charseq)$ because $\tokenizer$ is a function
\item $\Longrightarrow \tokenizer(\cotokenizer(\tokseq)) = \tokseq$ substitute $\tokenizer(\charseq) \mapsto \tokseq$
\item $\Longrightarrow \canonicalize(\tokseq) = \tokseq$ by definition of $\canonicalize$
\item Thus, this direction holds.
\end{enumerate}

\item \textbf{Part 2} ($\tokseq \in \D \Longleftarrow \canonicalize(\tokseq) = \tokseq$):
\begin{enumerate}
\item Suppose $\canonicalize(\tokseq) = \tokseq$
\item $\Longrightarrow \tokseq = \tokenizer(\cotokenizer(\tokseq))$
\item $\Longrightarrow \exists \charseq \in \charStrings\colon \tokseq = \tokenizer(\charseq)$; specifically, $\charseq = \tokenizer(\tokseq)$
\item $\Longrightarrow \tokseq \in \D$  by definition of $\D$
\item Thus, this direction holds.
\end{enumerate}

\end{itemize}
Since each directions have been proven, the proposition holds.
\end{proof}

\begin{corollary}
\begin{align}
\D = \{ \canonicalize(\tokseq) \mid \tokseq \in \tokStrings\}
\end{align}
\end{corollary}

\begin{proposition}
\label{prop:canonical-bijection}
Let $(\tokenizer, \cotokenizer)$ be exact.  Then, $(\tokenizer, \cotokenizer)$ is a bijection between $(\charStrings, \D)$.
\end{proposition}
\vspace{-\baselineskip}
\begin{proof}
The bijection follows directly from the following:

\begin{itemize}
\item Exactness means $\forall \charseq\in\charStrings\colon \cotokenizer(\tokenizer(\charseq)) = \charseq$.    

\item \Cref{prop:the-other-half-of-the-bijection} ensures that
$\forall \tokseq\in\D\colon \tokenizer(\cotokenizer(\tokseq)) = \tokseq$.    
\end{itemize}

Thus, we have a bijection, and the proposition holds.
\end{proof}

\begin{proposition}
\label{prop:canonicalization-is-idempotent}
For an exact tokenization model $(\charAlphabet, \tokAlphabet, \tokenizer, \cotokenizer)$, the canonicalization operator is idempotent, i.e.,
\begin{align}
\canonicalize(\tokseq) = \tokseqp \Longrightarrow \canonicalize(\tokseqp) = \tokseqp \text{ for all }\tokseq, \tokseqp \in \tokStrings    
\end{align}
\end{proposition}
\begin{proof}
The proposition is equivalent to $\canonicalize(\canonicalize(\tokseq)) = \canonicalize(\tokseq)$ for all $\tokseq \in \tokStrings$.

Fix $\tokseq, \tokseqp \in \tokStrings$ arbitrarily.

\begin{enumerate}
\item Suppose $\canonicalize(\tokseq) = \tokseqp$
\item $\Longrightarrow$ $\tokenizer(\cotokenizer(\tokseq)) = \tokseqp$ by definition of $\canonicalize$
\item $\Longrightarrow$ $\tokenizer(\cotokenizer(\tokenizer(\cotokenizer(\tokseq)))) = \tokenizer(\cotokenizer(\tokseqp))$ because $\tokenizer$ and $\cotokenizer$ are functions
\item $\Longrightarrow$ $\tokenizer(\cancel{\cotokenizer}(\cancel{\tokenizer}(\cotokenizer(\tokseq)))) = \tokenizer(\cotokenizer(\tokseqp))$ by exactness
\item $\Longrightarrow$ $\tokenizer(\cotokenizer(\tokseq)) = \tokenizer(\cotokenizer(\tokseqp))$
\item $\Longrightarrow$ $\tokenizer(\cotokenizer(\tokseq)) = \tokenizer(\cotokenizer(\canonicalize(\tokseq)))$ substitution $\tokseqp \mapsto \canonicalize(\tokseq)$
\item $\Longrightarrow$ $\canonicalize(\tokseq) = \canonicalize(\canonicalize(\tokseq))$ by definition of $\canonicalize$
\end{enumerate}
\end{proof}

