\ReductionInKLGlobal*
\begin{proof}
\label{proof:prop:reduction-in-KL-global}
\begin{subequations}
\begin{align}
\KL( \pTokensStar \,\|\, \pTokensGlobal ) 
&= 
\sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log \frac{\pTokensStar(\tokseq)}{\pTokensGlobal(\tokseq)}
\\
&= 
-\entropy(\pTokensStar)
- \sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log \frac{\pTokens(\tokseq) \indicator{\tokseq \in \D}}{ Z }
\\
&= 
-\entropy(\pTokensStar)
- 
\sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log \pTokens(\tokseq)
-
\cancelto{0}{\sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log \indicator{\tokseq \in \D}}
+
\sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log Z
\\
&= 
-\entropy(\pTokensStar)
- \sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log \pTokens(\tokseq) 
+ \log Z
\\
&= 
\KL( \pTokensStar \,\|\, \pTokens )
+ \log Z
\end{align}
\end{subequations}
Now, the proposition follows by basic algebra.
\end{proof}


\LocalIsWarped*
\begin{proof}
\label{proof:prop:warp}
\begin{subequations}
\begin{align}
\pTokensLocal(\tokseq)  
&=
\prefixTokensLocal(\eos \mid \tokseq) \prod_{t=1}^{|\tokseq|} \prefixTokensLocal(\token_t \mid \tokseq_{<t})
\\
&=
\frac{\pTokens(\eos \mid \tokseq) \indicator{\tokseq \in \D}}{\prefixTokensLocal(\tokseq)} \prod_{t=1}^{|\tokseq|} 
\frac{\pTokens(\token_t \mid \tokseq_{<t})\,\indicator{ \tokseq_{<t}\c\token_t \in \preD}}{\prefixTokensLocal(\tokseq_{<t})}
 \\
&=
\left[ \pTokens(\eos \mid \tokseq) 
\prod_{t=1}^{|\tokseq|} 
\pTokens(\token_t \mid \tokseq_{<t})
\right]
\left[
\indicator{\tokseq \in \D}
\prod_{t=1}^{|\tokseq|} 
\indicator{ \tokseq_{<t}\c\token_t \in \preD}
\right]
\left[
\prod_{t=1}^{|\tokseq|+1} 
\prefixTokensLocal(\tokseq_{<t})
\right]^{-1}
\\
&=
\pTokens(\tokseq) \, \indicator{\tokseq \in \D}
\Biggr[
\prod_{t=1}^{|\tokseq|+1} 
\prefixTokensLocal(\tokseq_{<t})
\Biggr]^{-1}
\end{align}
\end{subequations}
\end{proof}

\ReductionInKLLocal*
\begin{proof}
\label{proof:prop:reduction-in-KL-local}
\begin{subequations}
\begin{align}
\KL( \pTokensStar \,\|\, \pTokensLocal ) 
&= 
\sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log \frac{\pTokensStar(\tokseq)}{\pTokensLocal(\tokseq)}
\\
&=   
-\entropy(\pTokensStar)
- 
\sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log \pTokensLocal(\tokseq)
\\
&=   
-\entropy(\pTokensStar) 
- 
\sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log \underbrace{\frac{\pTokens(\tokseq) \indicator{\tokseq \in \D}}{\weight(\tokseq)}}_{\text{by \cref{prop:warp}}}
\\
&=
-\entropy(\pTokensStar)
-
\sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log \pTokens(\tokseq)
-
\cancelto{\text{{\scriptsize $0$ by assumption}}}{\sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log \indicator{\tokseq \in \D}}
+
\sum_{\tokseq \in \tokStrings} 
\pTokensStar(\tokseq) \log \weight(\tokseq)
\\
&= \KL( \pTokensStar \,\|\, \pTokens ) 
+ \E[\tokseq \sim \pTokensStar]{ \log \weight(\tokseq) }
\end{align}
\end{subequations}
Now, the proposition follows by algebra.
\end{proof}

\ExpectedWarpIsZ*
\begin{proof}
\label{proof:prop:expected-warp-is-Z}
\begin{subequations}
\begin{align}
Z 
&=
\sum_{\tokseq \in \tokStrings}
\pTokens(\tokseq)
\indicator{\tokseq \in \D}
\\
&=
\sum_{\tokseq \in \D}
\pTokens(\tokseq)
\\
&=
\sum_{\tokseq \in \D}
\pTokensLocal(\tokseq)
\frac{\pTokens(\tokseq)}{\pTokensLocal(\tokseq)}
\\
&=
\sum_{\tokseq \in \D}
\pTokensLocal(\tokseq)
\frac{\pTokens(\tokseq)}{\pTokens(\tokseq) \weight(\tokseq)^{-1}}
\\
&=
\sum_{\tokseq \in \D} 
\pTokensLocal(\tokseq) \, \weight(\tokseq)
\\
&=
\underset{
\tokseq \sim \pTokensLocal
}{\mathbb{E}}
\left[
