\subsection{Arbitrary setting}

Let \( f : \mathbb{R}^q \to \mathbb{R} \) be a measurable function, and let \( \mathfrak{S}_n(f) \) be its approximation using the SK- operators. Then, let us define the following parameters as ;

\subsubsection{\textbf{Point-wise error}} If  $\varsigma_n(x)$ denotes the error between $ \mathfrak{S}_n(f)(x) $ and $f(x) $. Thus, the point error is defined as follows;
\[
\varsigma_n(x) = \left|\mathfrak{S}_n(f)(x) - f(x) \right|.
\]
Similarly, some error metrics in a domain \( D \subset \mathbb{R}^q\)
\begin{itemize}
    \item \textbf{Maximum Error}:
    \[
    \max_{x \in D} \left| \mathfrak{S}_n(f)(x) - f(x) \right|
    \]

    \item \textbf{Minimum Error}:
    \[
    \min_{x \in D} \left| \mathfrak{S}_n(f)(x) - f(x) \right|
    \]

    \item \textbf{Mean \( L^1 \) Error}:
    \[
    \frac{1}{|D|} \int_D \left| \mathfrak{S}_n(f)(x) - f(x) \right| \, dx
    \]

    \item \textbf{Discrete Approximation}:
    \[
    \frac{1}{N} \sum_{i=1}^N \left| \mathfrak{S}_n(f)(x_i) - f(x_i) \right|
    \]
\end{itemize}


\subsubsection{\textbf{Basic classical matrices in image form}}
Let \( f(i,j) \in [0,1] \) represent a grayscale image and \( S_n(f)(i,j) \) its deterministic or stochastic approximation.
\begin{itemize}
    \item \textbf{Max Error}:
    \[
    \max_{(i,j)\in (\mathbb{N}\times \mathbb{N})} \left| \mathfrak{S}_n(f)(i,j) - f(i,j) \right|
    \]
    \item \textbf{Mean Error}:
    \[
    \frac{1}{MN} \sum_{i=0}^{M-1} \sum_{j=0}^{N-1} \left| \mathfrak{S}_n(f)(i,j) - f(i,j) \right|
    \]
    \item \textbf{Structural Similarity Index Measure (SSIM)} %\textbf{Classical Definition:}
\[
\text{SSIM}(f, \hat{f}) = \frac{(2\nu_f \nu_{\hat{f}} + C_1)(2\tau_{f\hat{f}} + C_2)}{(\nu_f^2 + \nu_{\hat{f}}^2 + C_1)(\tau_f^2 + \tau_{\hat{f}}^2 + C_2)},
\]
where \( \nu \), \( \tau \), and \( \tau_{f\hat{f}} \) are local means, standard deviations, and cross-covariance.
\item \textbf{Classical Definition:}
\[
\text{MAE}(f, \hat{f}) = \frac{1}{mn} \sum_{i=1}^m \sum_{j=1}^n \left| f_{i,j} - \hat{f}_{i,j} \right|.
\]
\item \textbf{ Peak Signal-to-Noise Ratio (PSNR):}
\[
\text{PSNR}(f, \hat{f}) = 10 \cdot \log_{10} \left( \frac{L^2}{\text{MSE}(f, \hat{f})} \right),
\]
where \( L \) is the maximum possible pixel value (e.g. \( L = 1 \) for normalized images), and
\[
\text{MSE}(f, \hat{f}) = \frac{1}{mn} \sum_{i=1}^m \sum_{j=1}^n (f_{i,j} - \hat{f}_{i,j})^2.
\]

\end{itemize}%

