\section{Main results and Algorithms}
\subsection{Lemmas and Theorems:}
\begin{theorem} \label{TH1}

%\end{theorem}
%\section*{Theorem (Fundamental Approximation Theorem)}
Let \( f \in L^1(\mathbb{R}^q) \), and let \( \mathfrak{S}_n(f) \) be the classical SK operators defined as \eqref{DSK}.
%\[
%S_n(f)(x) := n^d \sum_{k \in \mathbb{Z}^d} \xi(n x - k) \int_{R_k^n} f(u) \, du,
%\]

Then, the following convergence holds:
\[
\lim_{n \to \infty} \| \mathfrak{S}_n(f) - f \|_{L^1(\mathbb{R}^d)} = 0.
\]
\end{theorem}
For the proof of the above theorem, the reader is requested to go through the article\cite{TH1}.
\begin{lemma}\label{lemma}
Let \( g \in L^1(\mathbb{R}^q) \). Then for SK operators \( \mathfrak{S}_n(g) \), there exists a constant \( L > 0 \), depending only on the kernel \( \xi \), such that
\[
\| \mathfrak{S}_n(g) \|_{L^1} \leq L \| g \|_{L^1},
\]
for all \( n \geq 1 \).
\end{lemma}

\begin{proof}
The classical SK operators are defined by
\[
\mathfrak{S}_n(g)(x) = n^q \sum_{k \in \mathbb{Z}^q} \xi(n x - k) \int_{R_a^n} g(u) \, du,
\]
where \[
D_a^n = \prod_{j=1}^{q} \left[\frac{a_j}{n}, \frac{a_j + 1}{n}\right),
\].

Imposing the \( L^1 \)-norm, we obtain
\begin{eqnarray*}
    \| \mathfrak{S}_n(g) \|_{L^1} &=& \int_{\mathbb{R}^q} \left| n^q \sum_{k \in \mathbb{Z}^q} \xi(n x - k) \int_{D_a^n} g(u) \, du \right| \, dx \\
    &\leq & n^q \sum_{k \in \mathbb{Z}^q} \left( \int_{\mathbb{R}^q} |\xi(n x - k)| \, dx \right) \left( \int_{R_a^n} |g(u)| \, du \right).
\end{eqnarray*}


Assume \( w = n x - k \)  \(\iff \, dw = n^q \, dx \). Thus we have
\[
\int_{\mathbb{R}^q} |\xi(n x - k)| \, dx = \frac{1}{n^d} \int_{\mathbb{R}^q} |\xi(w)| \, dw = \frac{1}{n^w} \|\xi\|_{L^1}.
\]

Substituting, we obtain
\[
\| \mathfrak{S}_n(g) \|_{L^1} \leq \|\xi\|_{L^1} \sum_{k \in \mathbb{Z}^q} \int_{R_k^n} |g(u)| \, du.
\]

Since \( \{R_k^n\} \) forms a partition of \( \mathbb{R}^q \), we have
\[
\sum_{k \in \mathbb{Z}^q} \int_{R_k^n} |g(u)| \, du = \int_{\mathbb{R}^q} |g(u)| \, du.
\]

Thus,
\[
\| \mathfrak{S}_n(g) \|_{L^1} \leq \|\xi\|_{L^1} \| g \|_{L^1},
\]
 setting \( L = \|\xi\|_{L^1} \), thus we have the required results.
\end{proof}
\begin{lemma}
Let \( f \in L^1(\mathbb{R}^q) \) and further let \( \varepsilon_\beth \) be a random perturbation satisfying
\[
\sup_\beth \int_{\mathbb{R}^q} |\varepsilon_\beth(x)| \, dx < \infty.
\]
The PSK-operators are defined as in \eqref{PSK}. 
There exists a constant \( L > 0 \) (depending on the kernel) \( \xi \), such that
\[
\mathfrak{E}\left[ \| \mathfrak{P}_n^\beth(f) \|_{L^1} \right] \leq L \left( \| f \|_{L^1} + \mathfrak{E}\left[ \| \varepsilon_\beth \|_{L^1} \right] \right),
\]
for all \( n \geq 1 \).
\end{lemma}

\begin{proof} Obviously from \eqref{PSK}, the relation between $f(x)$  and perturbation $ \varepsilon_\beth(x)$ is written as follows;
\[
\quad f_\beth(x) = f(x) + \varepsilon_\beth(x),
\]
First, observe that by linearity of \( \mathfrak{S}_n \), we have
\[
\mathfrak{P}_n^\beth(f)(x) = \mathfrak{S}_n(f)(x) + \mathfrak{S}_n(\varepsilon_\beth)(x).
\]

Again, imposing the triangle inequality with respect to \( L^1 \),
\[
\| \mathfrak{P}_n^\beth(f) \|_{L^1} \leq \| \mathfrak{S}_n(f) \|_{L^1} + \| \mathfrak{S}_n(\varepsilon_\beth) \|_{L^1}.
\]

From the previous lemma \eqref{lemma}, we obtain
\[
\| \mathfrak{S}_n(f) \|_{L^1} \leq  L\| f \|_{L^1},
\quad \text{and} \quad
\| \mathfrak{S}_n(\varepsilon_\beth) \|_{L^1} \leq L \| \varepsilon_\beth \|_{L^1},
\]
where \( L = \|\xi\|_{L^1} \) is not dependent on \( n \) and \( \beth \).

Thus,
\[
\| \mathfrak{P}_n^\beth(f) \|_{L^1} \leq L \left( \| f \|_{L^1} + \| \varepsilon_\beth \|_{L^1} \right).
\]

Eventually, operating the expectations on both sides, we have
\[
\mathfrak{E}\left[ \| \mathfrak{P}_n^\beth(f) \|_{L^1} \right] \leq L \left( \| f \|_{L^1} + \mathfrak{E}\left[ \| \varepsilon_\beth \|_{L^1} \right] \right).
\]

By assumption \( \sup_\beth \| \varepsilon_\beth \|_{L^1} < \infty \), the result proved.
\end{proof}

\begin{theorem} \textbf{(Fundamental theorem of approximation)}
    Suppose \( f \in L^1(\mathbb{R}^q) \) and further let us denote the noise process by \( \varepsilon_\beth \) satisfies;
\[
\sup_\beth \int_{\mathbb{R}^d} |\varepsilon_\beth(x)| \, dx < \infty.
\]
Then, from \eqref{PSK} and under the assumption of uniform integrability, we have
\[
\mathfrak{E}\left[ \| \mathfrak{P}_n^\beth(f) - f \|_{L^1} \right] \to 0 \quad \text{as } n \to \infty.
\]
\end{theorem}
\begin{proof}
%We denote by \( S_n(f) \) the classical (deterministic) Sampling Kantorovich operators:
%\[
%S_n(f)(x) = n^d \sum_{k \in \mathbb{Z}^d} \xi(n x - k) \int_{R_k^n} f(u) \, du,
%\]
%and the probabilistic version:
%\[
%\mathfrak{P}_n^\beth(f)(x) = n^d \sum_{k \in \mathbb{Z}^d} \xi(n x - k) \int_{R_k^n} [f(u) + \varepsilon_\beth(u)] \, du.
%\]
%Hence,
 From \eqref{PSK}, we have
\[
\mathfrak{P}_n^\beth(f)(x) = \mathfrak{S}_n(f)(x) + \mathfrak{S}_n(\varepsilon_\beth)(x).
\]

Using linearity property over the expectation operators corresponding to \( L^1 \), we have the following estimation:
\[
\mathfrak{E}\left[ \| \mathfrak{P}_n^\beth(f) - f \|_{L^1} \right]
\leq \| \mathfrak{S}_n(f) - f \|_{L^1} + \mathfrak{E}\left[ \| \mathfrak{S}_n(\varepsilon_\beth) \|_{L^1} \right].
\]

From the classical fundamental theorem with respect to \eqref{TH1} for \( \mathfrak{S}_n(f) \), we know:
\[
\| \mathfrak{S}_n(f) - f \|_{L^1} \to 0 \quad \text{as } n \to \infty.
\] Since \( \varepsilon_\beth \in L^1 \) is uniformly bounded in the expectation sense:
\[
\| \mathfrak{S}_n(\varepsilon_\beth) \|_{L^1} \leq L \int_{\mathbb{R}^q} |\varepsilon_\beth(u)| \, du,
\]
for \( L > 0 \) not dependent on \( \beth \) and \( n \).

Therefore,
\[
\mathfrak{E}\left[ \| \mathfrak{P}_n(\varepsilon_\beth) \|_{L^1} \right] \leq L \, \mathfrak{E}\left[ \int_{\mathbb{R}^q} |\varepsilon_\beth(u)| \, du \right].
\]

By assumption,
\[
\sup_\beth \int_{\mathbb{R}^q} |\varepsilon_\beth(u)| \, du < \infty \quad \Rightarrow \quad \mathfrak{E}\left[ \int_{\mathbb{R}^q} |\varepsilon_\beth(u)| \, du \right] < \infty.
\]
Eventually, by the assumption of uniform integrability and possibly additional assumptions (particularly \( \varepsilon_\beth \to 0 \) in \( L^1 \)), we can conclude:
\[
\lim_{n \to \infty} \mathfrak{E}\left[ \| \mathfrak{P}_n(\varepsilon_\beth) \|_{L^1} \right] = 0.
\]
Thus, we have
\[
\mathfrak{E}\left[ \| \mathfrak{P}_n^\beth(f) - f \|_{L^1} \right] \to 0 \quad \text{as } n \to \infty.
\]

\end{proof}

\subsection{Algorithm 1: Approximating $f(x) = e^{-x^2}$ using Classical and Probabilistic SK-operators} \label{algo}
\vskip 0.15in
\textbf{Input:} Function $f(x) = e^{-x^2}$, domain $x \in [-3, 3]$, number of points $=1000$, $n$-values $= \{5, 15, 25, 35, 45\}$ \\
\textbf{Output:} Approximated functions $\mathfrak{S}_n f(x)$ for Classical and Probabilistic SK operators

\vskip 0.15in
\textbf{Define:} $f(x) = e^{-x^2}$, $x = \text{linspace}(-3, 3, 1000)$

\vskip 0.1in
\textbf{Kernel Function:} For  SK, use the indicator kernel
\[
\xi_{[x_k, x_k + h)}(x) = 
\begin{cases}
1, & \text{if } x \in [x_k, x_k + h) \\
0, & \text{otherwise}
\end{cases}
\]

\vskip 0.1in
\textbf{For each} $n \in \{5, 15, 25, 35, 45\}$ \textbf{do:}
\vskip 0.15in
\hrule
\vskip 0.15in
\textbf{Classical SK Operators:}
\begin{itemize}
    \item Set $h = \frac{1}{n}$
    \item Initialize $\mathfrak{S}_n f(x) = 0$ over all $x$
    \item \textbf{For} $k = -3n$ \textbf{to} $3n$:
    \begin{itemize}
        \item Compute $x_k = k \cdot h$
        \item Compute ${Kr}_k = \frac{1}{h} \int_{x_k}^{x_k + h} f(u)\,du$
        \item \textbf{For each} $x_i$:
        \begin{itemize}
            \item \textbf{If} $x_i \in [x_k, x_k + h)$ \textbf{then} set $\mathfrak{S}_n f(x_i) = Kr_k$
        \end{itemize}
    \end{itemize}
\end{itemize}
\vskip 0.15in
\hrule
\vskip 0.15in
\vskip 0.15in

\textbf{Probabilistic SK Operators:}
\begin{itemize}
    \item Set $h = \frac{1}{n}$
    \item Initialize $\mathfrak{P}_n f(x) = 0$ over all $x$
    \item Initialize Gaussian noise generator ($\varepsilon_\beth$)  (mean = 0, std = 0.02)
    \item \textbf{For} $k = -3n$ \textbf{to} $3n$:
    \begin{itemize}
        \item Compute $x_k = k \cdot h$
        \item Compute $Kr_k = \frac{1}{h} \int_{x_k}^{x_k + h} f(u)\,du$
        \item Sample perturbation $\delta \sim \mathcal{N}(0, 0.02^2)$
        \item \textbf{For each} $x_i$:
        \begin{itemize}
            \item \textbf{If} $x_i \in [x_k, x_k + h)$ \textbf{then} set $\mathfrak{P}_n f(x_i) = Kr_k + \delta$
        \end{itemize}
    \end{itemize}
\end{itemize}

\vskip 0.15in
\hrule
