	\centering
	\includegraphics[width=7cm]{MBSSSimple}
	\caption{Bifurcation at $c^-_{4,1}$.}
	\label{Figure : MBSS simple}
\end{figure}


\begin{thm}\label{Theorem - Index of Degenerate Orbits}
	The Robbin-Salamon index of $\Sigma_{k,l}$-family is $4k-1/2$.
\end{thm}
\begin{proof}
	We separate into two cases.
	The first case is $\Sigma_{k,l}$-family with $L_3<0$, in which case we consider the direct orbit.
	As in the previous example, we perturb Jacobi energy to pass through $c_{k,l}^-$.
	From \Cref{Theorem - Index of planar circular orbits}, we have $\mu_{CZ}(\g_-^{k-l})=4k-2$ at $c_{k,l}^- - \eps$, and $\mu_{CZ}(\g_-^{k-l})=4k+2$ at $c_{k,l}^- + \eps$.
	In addition, $\Sigma_{k,l}$-family appears at $c_{k,l}^-+\eps$.
	Ignoring other orbits, we have two spectral sequences illustrated in the left part of \Cref{Figure - MBSS}.
	Note that the period of $\g_-^{k-l}$ is longer than the period of $\Sigma_{k,l}$, so we can place  $\Sigma_{k,l}$ at $p=0$ and $\g_-^{k-l}$ at $p=1$.
	Since $\Sigma_{k,l}$ is topologically $S^3\times S^1$, the $S^1$-equivariant homology of $\Sigma_{k,l}$ should be equal to the homology of $S^3$.
	From the local invariance of the Floer homology, the shift should be $4k-2$, and we have
		$$
	\mu_{RS}(\Sigma_{k,l}) = (4k-2) + \frac{1}{2}\dim \Sigma_{k,l}/S^1 = 4k - \frac{1}{2},
	$$
	so we get the result.

	The second case is $L_3>0$, in which case we consider the retrograde orbit.
	Let Jacobi energy pass through $c_{k,l}^+$.
	Again from \Cref{Theorem - Index of planar circular orbits}, we have $\mu_{CZ}(\g_+^{k+l})=4k+2$ at $c_{k,l}^+ - \eps$ and $\mu_{CZ}(\g_+^{k+l})=4k-2$ at $c_{k,l}^+ + \eps$.
	In addition, $\Sigma_{k,l}$-family exists at $c_{k,l}^+-\eps$ and disappears at $c_{k,l}^+ + \eps$.
	Again, the shift should be $4k-2$ and we get the result.
	The spectral sequences for this case is illustrated in the right part of \Cref{Figure - MBSS}.
\end{proof}

