\begin{theorem}
\label{Theorem2}
Consider Problem~\ref{Problem1} and definition of the matrix  $\Pi$ in expression \eqref{eq:3:5} presented on the next page. Let $\Lambda \in \mathbb{R}^{\tilde{n} \times \tilde{n}}$ and $\tilde{R} \in \mathbb{R}^{\tilde{q} \times \tilde{q} }$ be positive definite matrices defined by arbitrary factorizations
\begin{equation}
\begin{pmatrix}
\star \\
\end{pmatrix}
\tilde{\Phi}
\begin{pmatrix}
I & A_s & B_s \\
\end{pmatrix}^\top=\Xi \Lambda \Xi^\top,  \quad R=T\tilde{R} T^\top. \nonumber
\end{equation}
Then, the following two statements are equivalent:
\begin{enumerate}
 \item[\emph{i})]
The inequalities
 \begin{subequations}
 \label{eq:3:4}
 \begin{align}
 & P \succ 0, \label{E1} \\ 
 & \begin{pmatrix}
\star
\end{pmatrix}^\top
\begin{pmatrix}
-P & 0 & 0 & 0  \\
0& P & 0 & 0   \\
0 & 0 & Q & S\\
0 & 0 & S^\top & R\\
\end{pmatrix}\begin{pmatrix}
I & 0 \\
\tilde{A} & \tilde{B} \\
0 & I\\
\tilde{C} & \tilde{D}  \\
\end{pmatrix}
\prec 0, \label{E2}
 \end{align}
 \end{subequations}
hold for all matrices $(A,B)\in \Sigma$.
\item[\emph{ii})]
The inequality
\begin{equation}
\label{eq:600:301}
\Pi \succ 0,
\end{equation}
holds for some real scalar $\alpha$, symmetric matrices $X$ and $Y$, unstructured matrices $\tilde{A}_c$, $\tilde{B}_c$, $\tilde{C}_c$ and $D_c$. 
\end{enumerate}
Furthermore, the controller parameters can be reconstructed from \eqref{eq:600:301} as follows
\begin{equation}
\label{eq:3:18}
\begin{gathered}
V^\top=U^{-1}(I-XY), \\
B_c=U^{-1}(\tilde{B}_c-XB_sD_c), \\
C_c=(\tilde{C}_c-D_cCY)V^{-\top}, \\
A_c=U^{-1}(\tilde{A}_c-X(A_sY+B_s\tilde{C}_c)-UB_cCY)V^{-\top},
\end{gathered}
\end{equation}
where $U$ is an arbitrary full rank matrix. 
\end{theorem}
\begin{proof}
The proof is divided in several steps. In step 1, we rewrite the condition for strict dissipativity of the closed-loop system. The newly obtained expression is in a form suitable for applying Theorem~\ref{Theorem1}. In step 2, we apply Theorem~\ref{Theorem1}. In step 3, we transform the previously obtained expression in order to obtain matrix inequalities that do not contain nonlinearly coupled matrix variables. In step 4, we provide the final argumentation for both necessity and sufficiency between the statements (\emph{i}) and (\emph{ii}).

\noindent \emph{Step 1.}
Suppose that  \eqref{eq:3:4} holds. By applying Schur's complement rule on \eqref{eq:3:4} with respect to the matrix $\text{diag}(-\tilde{R},-P)$ (recall that $\tilde{R}$ is also positive definite), we obtain the equivalent expression to \eqref{eq:3:4}:
\begin{equation}
\label{eq:3:12}
\Theta:=
\begin{pmatrix}
\Theta_{11} & \star\\  
\begin{pmatrix}
T^\top \tilde{C} & T^\top \tilde{D} \\
\tilde{A} & \tilde{B}
\end{pmatrix} & \begin{pmatrix}
\tilde{R}^{-1} & 0 \\
0 & P^{-1}
\end{pmatrix}
\end{pmatrix}
 \succ 0,
\end{equation}
where 
\begin{equation}
\nonumber
\Theta_{11}:=
\begin{pmatrix}
\star
\end{pmatrix}^\top
\begin{pmatrix}
P & 0 & 0 \\
0 & -Q & -S \\
0 & -S^\top & 0
\end{pmatrix}
\begin{pmatrix}
I & 0 \\
0 & I \\
\tilde{C} & \tilde{D}
\end{pmatrix}.
\end{equation}
Let 
\begin{equation}
\begin{gathered}
P:=
\begin{pmatrix}
X  & U \\
U^\top & M_{1}
\end{pmatrix}, \quad 
P^{-1}:=
\begin{pmatrix}
Y & V \\
V^\top & M_{2}
\end{pmatrix}, \nonumber \\
\end{gathered}
\end{equation}
where the matrices $X$, $M_1$, $Y$ and $M_2$ are of size $n\times n$.
Next, we apply a congruence transformation on \eqref{eq:3:12} with respect to matrix
$S_1:=\text{diag }(I,\begin{small} \begin{pmatrix} 0 & I_n \\ I_n & 0 \end{pmatrix} \end{small} )$ in order to obtain the equivalent inequality $\tilde{\Theta}:=S_1^\top\Theta S_1\succ 0$. Let $\tilde{\Theta}_{11}$ be the upper left block diagonal matrix of $\tilde{\Theta}$ with size $(3n+p+\tilde{q}) \times  (3n+p+\tilde{q})$. Then, by applying Schur's complement rule on $\tilde{\Theta} \succ 0$ with respect to matrix $\tilde{\Theta}_{11}$, we obtain the equivalent condition
\begin{equation}
\label{eq:300:13}
\Gamma
(\begin{pmatrix} Y & 0 \\ 0 & 0_{n+m} \end{pmatrix}-
\tilde{\Gamma} \tilde{\Theta}_{11}^{-1} 
\tilde{\Gamma}^\top
)
\Gamma^\top 
\succ 0, \quad \tilde{\Theta}_{11}\succ 0,
\end{equation}
where $\Gamma:=\begin{pmatrix} I & A & B \end{pmatrix}$ and
\begin{equation}
\nonumber
\tilde{\Gamma}:=
\begin{pmatrix}
0 & 0 & B_1 & 0_{n\times \tilde{q}} & V \\
I & 0 & 0 & 0 & 0 \\
D_cC & C_c & D_cF & 0 & 0
\end{pmatrix}.
\end{equation}

\noindent \emph{Step 2.}
Matrix inequalities \eqref{eq:2:3} and \eqref{eq:300:13} are in a form suitable for the application of Theorem~\ref{Theorem1}, since Assumptions~\ref{Assumption1} and \ref{Assumption2} hold. Thus, the matrix \begin{small} $\begin{pmatrix}
\tilde{\Phi}_{22} & \tilde{\Phi}_{23} \\ 
\tilde{\Phi}_{23}^\top & \tilde{\Phi}_{33} \end{pmatrix}$ \end{small} defined by \eqref{PhiDef} is negative definite, and $\Sigma$ is a nonempty set.
Note that according to Lemma~\ref{Lemma3}, inequality \eqref{eq:2:3} defines the set of all matrices
$(A,B) \in \Sigma$.
Therefore, we can use Theorem~\ref{Theorem1} to state that \eqref{eq:300:13} holds for all matrices $(A,B) $ that satisfy the inequality  \eqref{eq:2:3}, if and only if there exist $\alpha \geq 0$  such that
\begin{equation}
\label{eq:3:15}
\begin{pmatrix} Y & 0 \\ 0 & 0_{n+m} \end{pmatrix}-\alpha \tilde{\Phi} -
\tilde{\Gamma} \tilde{\Theta}_{11}^{-1} 
\tilde{\Gamma}^\top 
 \succ 0, \quad \tilde{\Theta}_{11} \succ 0.
\end{equation}

\noindent \emph{Step 3.} By applying a congruence transformation on the first inequality in \eqref{eq:3:15} with respect to matrix
\begin{equation}
S_2:=
\begin{pmatrix}
 I & 0 & 0 \\
 A_s^\top & I & 0 \\
 B_s^\top & 0 & I
\end{pmatrix}, \nonumber
\end{equation}
we obtain the equivalent expression
\begin{equation}
\label{eq:333:665}
\begin{pmatrix} Y & 0 \\ 0 & 0_{n+m} \end{pmatrix}-\alpha \bar{\Phi} -
\bar{\Gamma} \tilde{\Theta}_{11}^{-1} 
\bar{\Gamma}^\top 
 \succ 0, \quad \tilde{\Theta}_{11} \succ 0,
\end{equation}
where
\begin{equation}
\nonumber
\begin{split}
\bar{\Phi}:&=
\begin{pmatrix}
 \Xi \Lambda \Xi^\top & \star &   \star  \\ 
  \tilde{\Phi}_{12}^\top+ \tilde{\Phi}_{22}A_s^\top+ \tilde{\Phi}_{23}B_s^\top 
 &  \tilde{\Phi}_{22} &  \star \\
  \tilde{\Phi}_{13}^\top+\tilde{\Phi}_{23}^\top A_s^\top +\tilde{\Phi}_{33} B_s^\top &  \tilde{\Phi}_{23}^\top & \tilde{\Phi}_{33}
\end{pmatrix}, \\
\bar{\Gamma}:&=
\begin{pmatrix}
A_s+B_sD_cC & B_sC_c & B_1+B_sD_cF & 0_{n\times \tilde{q}} & V \\
I & 0 & 0 & 0 & 0 \\
D_cC & C_c & D_cF & 0 & 0
\end{pmatrix}.
\end{split}
\end{equation}
By applying the Schur complement rule on \eqref{eq:333:665} first with respect to matrix $\tilde{\Theta}_{11}^{-1}$, and then to matrix $\frac{1}{\alpha} \Lambda$ (note that $\eqref{eq:333:665}$ implies that $\alpha>0$), we obtain the equivalent expression
\begin{equation}
\label{eq300:600}
\begin{pmatrix}
\tilde{\Theta}_{11}  & \bar{\Gamma}^\top  & 0 \\
\bar{\Gamma} & \bar{\Phi}_{\Lambda}  & \Gamma_\Lambda^\top \\
0 & \Gamma_\Lambda & \alpha \Lambda^{-1}
\end{pmatrix} \succ 0, \quad 
\end{equation}
where $\bar{\Phi}_{\Lambda}:=\text{diag}(Y,0_{n+m})-\alpha \underline{\Phi}$, $\underline{\Phi}$ is matrix $\bar{\Phi}$ with a zero matrix instead of the matrix $\Xi \Lambda \Xi^\top$, and $\Gamma_\Lambda:=\begin{pmatrix} \alpha \Xi^\top & 0 \end{pmatrix}$.
Finally, by applying a congruence transformation on \eqref{eq300:600} with respect to matrix
\begin{equation}
\nonumber
S_3:=
\text{diag}( 
\begin{pmatrix}
I & Y \\
0 & V^\top
\end{pmatrix}
, I_{p+\tilde{q}}, 
\begin{pmatrix}
0 & U^\top \\
I & X 
\end{pmatrix},
I_{n+m+\tilde{n}}
),
\end{equation}
we obtain the equivalent condition \eqref{eq:600:301}. To perform this final step (the congruence transformation with $S_3$ on \eqref{eq300:600} to obtain $\Pi$ in the form of \eqref{eq:3:5}) the following set of equalities is used
\begin{equation}
\label{eq:rekonstrukcija}
P P^{-1}=
\begin{pmatrix} 
XY+UV^\top & XV+UM_2\\
U^\top Y+M_1V^\top  & U^\top V+M_1M_2
\end{pmatrix}=
\begin{pmatrix}
I & 0 \\
0 & I
\end{pmatrix}, 
\end{equation}
\begin{equation}
\nonumber
\begin{pmatrix}
I & 0 \\
Y & V
\end{pmatrix} 
\begin{pmatrix}
X & U  \\
U^T & M_{1} 
\end{pmatrix}
\begin{pmatrix}
I & Y\\
0 & V^T
\end{pmatrix} 
=
\begin{pmatrix}
X & I\\
I & Y
\end{pmatrix},
\end{equation}
\begin{equation}
\nonumber
\tilde{C}
\begin{pmatrix}
I & Y \\
0 & V^\top
\end{pmatrix}=
\begin{pmatrix}
C_1+ED_cC & C_1Y+E\tilde{C}_c
\end{pmatrix}, 
\end{equation}
\begin{equation}
\nonumber
\tilde{C}_c:=D_cCY+C_cV^\top,
\end{equation}
\begin{equation}
\nonumber
\begin{pmatrix}
I & 0 \\
D_cC & C_c
\end{pmatrix}
\begin{pmatrix}
I & Y \\
0 & V^\top
\end{pmatrix}=
\begin{pmatrix}
I & Y\\
D_cC & \tilde{C}_c
\end{pmatrix},
\end{equation}
\begin{equation}
\nonumber
\begin{split}
&
\begin{pmatrix}
0 & I \\
U & X
\end{pmatrix}
\begin{pmatrix}
B_cC & A_c \\
A_s+B_sD_cC & B_sC_c
\end{pmatrix}
\begin{pmatrix}
I & Y \\
0 & V^\top
\end{pmatrix}= \\
&
\begin{pmatrix}
A_s+B_sD_cC & A_sY+B_s\tilde{C}_c \\
XA_s+\tilde{B}_cC& \tilde{A}_c  
\end{pmatrix},
\end{split}
\end{equation}
\begin{equation}
\nonumber
\tilde{B}_c:=
XB_sD_c+UB_c, 
\end{equation}
\begin{equation}
\nonumber
\tilde{A}_c :=X(A_sY+B_s\tilde{C}_c)+U(B_cCY+A_cV^T),
\end{equation}
\begin{equation}
\nonumber
\begin{pmatrix}
0 & I \\
U & X
\end{pmatrix}
\begin{pmatrix}
 B_cF
    \\ B_1+B_sD_cF
 \end{pmatrix}= \begin{pmatrix}
B_1+B_sD_cF \\ XB_1 +\tilde{B}_cF
\end{pmatrix},
\end{equation}
\begin{equation}
\nonumber
\begin{split}
\bar{\Phi}_{12\alpha}:&= -\alpha (\tilde{\Phi}_{12}+A_s  \tilde{\Phi}_{22}+B_s   \tilde{\Phi}_{23}^\top)
\\
\bar{\Phi}_{13\alpha}:& =-\alpha (\tilde{\Phi}_{13}+A_s  \tilde{\Phi}_{23}+B_s   \tilde{\Phi}_{33}),
\end{split}
\end{equation}
\begin{equation}
\nonumber
\begin{pmatrix}
0 & I \\
U & X
\end{pmatrix}
\begin{pmatrix}
0 & 0  \\
\bar{\Phi}_{12\alpha} & \bar{\Phi}_{13\alpha}  
 \end{pmatrix}= 
 \begin{pmatrix}
\bar{\Phi}_{12\alpha} & \bar{\Phi}_{13\alpha}  \\
X\bar{\Phi}_{12\alpha} & X\bar{\Phi}_{13\alpha}  
 \end{pmatrix} ,
\end{equation}
\begin{equation}
\nonumber
\begin{pmatrix}
0 & I \\
U & X
\end{pmatrix}
\begin{pmatrix}
 0 \\
\alpha \Xi
 \end{pmatrix}= 
 \begin{pmatrix}
 \alpha \Xi \\
\alpha X\Xi
 \end{pmatrix} ,
\end{equation}
\begin{equation}
\nonumber
\begin{pmatrix}
0 & I\\
U & X \\
\end{pmatrix}
\begin{pmatrix}
M_2 & V^\top \\
V & Y
\end{pmatrix}
\begin{pmatrix}
