\noindent We now highlight some examples and consequences of Theorem~\ref{thm:Main} for small values of $d$.


\subsubsection*{The case $d=1$}

In the case $d=1$ of Theorem~\ref{thm:Main}, or equivalently the case that $x$ is primitive, the hypotheses simplify considerably. The condition $H_1(\Sigma_d(K))=H_1(S^3)=0$ holds vacuously, as does the second condition, since it reduces to the inequality~$b_2(N) \geq |\sigma(N)|$.

\begin{corollary}
\label{cor:SimpleDisc}
Let \(N\) be a compact, oriented, simply-connected $4$-manifold with boundary~\(S^3\),  let~$x \in H_2(N, \partial N)$ be a nonzero primitive class, and let~\(K\subset S^3\) be a knot.
\begin{itemize}
\item For $x$ ordinary,  $K$ is sliced by a simple disc in $N$ representing $x$.
\item For $x$ characteristic,  $K$ is sliced by a simple disc in $N$ representing $x$ if and only if 
$$\operatorname{Arf}(K)+\ks(N)+\frac{1}{8}(\sigma(N)-x \cdot x) \equiv 0 \ \text{ mod } 2.$$
\end{itemize}
\end{corollary}



This corollary recovers~\cite[Corollary 1.15]{KasprowskiPowellRayTeichnerEmbedding}, which, given a closed simply-connected $4$-manifold $X$, concerns sliceness in $X^\circ:=X\setminus  \operatorname{Int}(B^4)$.
\begin{corollary}
\label{cor:KasprowskiPowellRayTeichnerEmbedding}
For~$X\neq S^4,\C P^2,*\C P^2$ simply-connected, every knot $K\subset \partial X^\circ$ is slice in~$X^\circ$.
\end{corollary}
