\subsubsection*{The case $d=2$}
Next we consider the~$d=2$ case of Theorem~\ref{thm:Main}.
In this case,  the condition~$H_1(\Sigma_2(K))=0$ is equivalent to $|\det(K)|=1$ (see e.g.~\cite[Corollary~9.2]{Lickorish}).
This implies that $\Delta_K(-1) \equiv \pm 1$ mod~$8$ and therefore $\Arf(K)=0$ (see e.g.~\cite[Theorem~10.7]{Lickorish}).

\begin{corollary}
\label{cor:d=2}
Let \(N\) be a compact, oriented, simply-connected $4$-manifold with boundary \(S^3\) and let $x \in H_2(N, \partial N)$ be a nonzero class of divisibility $2$. 
Suppose \(K\subset S^3\) is a knot such that~\(|\det(K)|=1\).
The following are equivalent:
\begin{itemize}
\item The knot $K$ is sliced by a simple disc in $N$ representing $x$.
%, and the disc represents $x$.
\item 
\begin{enumerate}
\item $\ks(N)+\frac{1}{8}(\sigma(N)-x \cdot x) \equiv 0 \ \text{ mod } 2$ \ when $x$ is characteristic, and
\item $b_2(N)\geq \operatorname{max}(\,|\sigma (N)-\frac{1}{2}\,x\cdot x +\sigma(K)|\,,\,|\sigma(N)|\,)$. 
\end{enumerate}
\end{itemize}
\end{corollary}
Here,  $\sigma(K)=\sigma_K(-1)$ denotes the (Murasugi) signature of $K$.


\begin{example}
\label{ex:CP2d=2}
In~$(\C P^2)^\circ$, the second condition can be rewritten as~$1 \geq \operatorname{max}(|-1+\sigma(K)|,1)$.
Since~$2 \in \Z \cong H_2(\C P^2)$ is ordinary and the signature of a knot is even, it follows that~$K$ with~$|\det(K)|=1$ bounds a simple~$\Z_2$-disc in~$\C P^2$ if and only if~$\sigma(K) \in \{0,2\}$.
In~$(\overline{\C P^2})^\circ$, the second condition can be rewritten as~$1 \geq \operatorname{max}(|1+\sigma(K)|,1)$, so this time it follows that~$K$ with~$|\det(K)|=1$ bounds a simple~$\Z_2$-disc if and only if~$\sigma(K) \in \{-2,0\}$.
