\begin{remark}
\label{rem:Trefoil}
The left handed trefoil knot $K$ has nontrivial determinant, and it is not too difficult to verify that it bounds a $\Z_2$-disc in $(\C P^2)^\circ$;  such a disc arises by unknotting $K$ via a single crossing change whose corresponding crossing change disc intersects $K$ twice algebraically, see e.g.~\cite[Figure 3.1]{MarengonMillerRayStipsicz}.
Thus, the assumption $|\det(K)|=1$ is not necessary for the conclusion of Corollary~\ref{cor:d=2} to hold,  and more generally, the assumption $H_1(\Sigma_d(K))=0$ is not necessary to the conclusion of Theorem~\ref{thm:Main}. However, as noted in Theorem~\ref{thm:StableWithBoundaryIntro} and Proposition~\ref{prop:SignatureCondition}, the conditions on the Arf invariant and the signature are necessary for the knot~$K$ to bound a disc $D$ representing $x$.
\end{remark}

\begin{remark}
Theorem~\ref{thm:Main}, its corollaries, and Theorem~\ref{thm:StableWithBoundaryIntro} also hold if $\partial N$ is an integral homology $3$-sphere provided the congruence in the characteristic case is replaced by
$$\operatorname{Arf}(K)+\ks(N)+\frac{1}{8}(\sigma(N)-x \cdot x) \equiv \mu(\partial N) \ \text{ mod } 2,$$
where~$\mu(\partial N)$ denotes the Rochlin invariant of~$\partial N$.
For example, when~$N=X_{\pm 1}(J)$ is the \(4\)-manifold obtained by attaching a \(\pm 1\)-framed \(2\)-handle to \(D^4\), we deduce that a knot~$K$ is sliced by a simple disc representing a primitive class if and only if \(\Arf(K) \equiv \Arf(J) \mod{2}\); indeed Gonz\'alez-Acu\~na proved that~$\mu(S^3_{\pm 1}(J))=\Arf(J)$~\cite{GonzalezAcuna}.
\end{remark}

\subsection{Simple slice discs stably}

We say a knot $K\subset N$ is \emph{stably slice} if it is the boundary of a locally flat disc in~\(N_k := N\#^k (S^2\times S^2)\) for some \(k \geq 0\).
The proof of Theorem~\ref{thm:Main} closely follows the approach of Lee and Wilczy\'nski~\cite{LWCommentarii,LWKtheory}:~the first condition of Theorem~\ref{thm:Main} ensures that $K$ is stably slice, whereas the second condition ensures that the \(S^2\times S^2\) summands can be removed without harming the disc. We record the outcome of this first step as it might be of independent interest.
We say that a homology class~$x \in H_2(N,\partial N)$ is \emph{stably representable} if there is a~$k \geq 0$ such that~$x \oplus 0 \in H_2(N_k,\partial N)$ can be represented by an embedded surface.


\begin{theorem}
\label{thm:StableWithBoundaryIntro}
Let~$N$ be a simply-connected~$4$-manifold with boundary~$S^3$, let~$K\subset S^3$ be a knot.
\begin{enumerate}
\item\label{item:intro1} The knot $K$ is stably sliced by a disc stably representing $x$ if and only if either~$x$ is  ordinary or~$x$ is characteristic and
\begin{equation}
\label{eq:ArfConditionmain}
\operatorname{Arf}(K)+\ks(N)+\frac{1}{8}(\sigma(N)-x \cdot x) \equiv 0 \mod2.
\end{equation}
\item\label{item:intro2} For any~$g > 0$, every class~$x\in H_2(N,\partial N)$ is stably representable by a genus $g$ surface with boundary $K$.
\color{black}
\end{enumerate}
In both \eqref{item:intro1} and \eqref{item:intro2}, the surface may be taken to be simple.
\end{theorem}




Given a class~$x \in H_2(N,\partial N)$, the combination of Theorem~\ref{thm:Main} and Theorem~\ref{thm:StableWithBoundaryIntro} suggests analysing the minimal number of stabilisations needed for a knot~$K$ to bound a disc representing~$x$.
When~$x=0$ and $N=D^4$, this quantity 
%was introduced in~\cite{ConwayNagel} and 
is referred to as the \emph{stabilising number} $\sn(K)$ and has been studied in~\cite{ConwayNagel,KonnoMiyazawaTaniguchiInvolutions,FellerLewarkBalanced,FukumotoTaniguchi}.


\begin{definition}
For $x \in H_2(N,\partial N)$, the \emph{$(x,N)$-stabilising number} of $K$ refers to
\[
 \sn_{x,N}(K)=\min \{\ k \ | \ K  \text{ bounds a disc \(D \subset  N\#^k (S^2\times S^2)\) stably representing } x \}
\]
whereas the \emph{simple $(x,N)$-stabilising number} is 
\[ \sn_{x,N}^{\operatorname{simple}}(K)=\min \{\ k \ | \ K \text{ bounds a simple disc \(D \subset  N\#^k (S^2\times S^2)\) stably representing } x \}.
\]
\end{definition}


\begin{remark}
Clearly, by definition, it is always the case that $\sn_{x,N}(K) \leq \sn_{x,N}^{\operatorname{simple}}(K)$.
\end{remark}


When~$N=D^4$ and~$x=0$, it is known that~$\sn(K)$ is finite if and only if~$\Arf(K)=0$~\cite{SchneidermanStable} (see also~\cite[Theorem 2.9]{ConwayNagel}) in which case~$\sigma_K(\omega) \leq \sn(K) \leq g_4(K)$, where the first inequality holds whenever~$\omega \in S^1$ is not the root of a~$p(t)\in \Z[t^{\pm 1}]$ with~$p(1)=1$~\cite[Theorems~3.10 and~5.15]{ConwayNagel}.
Here, $g_4(K)$ denotes the $4$-genus of $K$.
In this setting, requiring the disc be simple amounts to it having knot group~$\Z$ in which case,~$\sn_{0,D^4}^{\text{simple}}(K)$ is equal to the \emph{$\Z$-stabilising number}~$\sn_\Z(K)$ introduced in~\cite{FellerLewarkBalanced}.
Our results lead to analogous (but stronger) statements in the case where~${x \neq0}$,  as we are able to show that when $d$ is a prime power,  $\sn_{x,N}(K)$ only depends on the algebraic topology of $N$ and on the Levine-Tristram signature of $K$. 


\begin{corollary}
\label{cor:StabilisingNUmber}
Fix a nonzero~$x \in H_2(N,\partial N)$ of divisibility $d$ 
and a knot~$K \subset \partial N$.
Then~$\sn_{x,N}(K)$ is finite if and only if~$\sn^{\operatorname{simple}}_{x,N}(K)$ is finite if and only if~$x$ is ordinary or~$x$ is characteristic and~\eqref{eq:ArfConditionmain} from Theorem~\ref{thm:StableWithBoundaryIntro} holds.

If the stabilising numbers are finite and also $H_1(\Sigma_d(K))=0$, then
\begin{equation}
\label{eq:max}
\sn_{x,N}^{\operatorname{simple}}(K)=\frac{1}{2}\left(\max_{0\leq j<d}\left |\sigma (N)-\frac{2j(d-j)}{d^2} \,x\cdot x+\sigma_K (e^{\frac{2\pi i j}{d}})\right |-b_2(N)\right).
\end{equation}
If, additionally, $d$ is a prime power, then
\[
\sn_{x,N}(K)=\sn_{x,N}^{\operatorname{simple}}(K).
\]
\end{corollary}
\begin{proof}
The characterisation of finite stabilisation numbers follows immediately from Theorem~\ref{thm:StableWithBoundaryIntro}. For the next statements, write~$m$ for the right-hand side of equation \eqref{eq:max}. Applying Theorem~\ref{thm:Main} to the~$4$-manifold~$N\#^m(S^2\times S^2)$ shows that if~$H_1(\Sigma_d(K))=0$, there exists a simple slice disc in~$N\#^m(S^2\times S^2)$ representing~$x\oplus 0$. Thus~$\sn_{x,N}^{\operatorname{simple}}(K)\leq m$ and hence~$\sn_{x,N}(K)\leq m$. The inequality~$\sn_{x,N}^{\operatorname{simple}}(K)\geq m$ follows from Proposition~\ref{prop:SignatureCondition}, which is essentially due to Gilmer~\cite{GilmerConfiguration}. As discussed in the proof of Proposition~\ref{prop:SignatureCondition}, Gilmer requires that~$d$ be a prime power dividing~$x$,
% (but not necessarily the largest such number)}, 
but when the surface is simple and $d$ is the divisibility of $x$,
one can argue that this stipulation can be dropped. 
Whence~$m$ is a lower bound for~$\sn_{x,N}^{\operatorname{simple}}(K)$, and also for~$\sn_{x,N}(K)$ if~$d$ is a prime power. This proves the two claimed equalities.
\end{proof}

\begin{remark}
We do not know whether there exist examples where $H_1(\Sigma_d(K))=0$ and $\sn_{x,N}(K)\neq\sn_{x,N}^{\operatorname{simple}}(K)$. 
It would be interesting to know whether such examples exist, or conversely whether prime power divisibility is a non-necessary condition, just an artefact of the proof.
\end{remark}



\subsection{Examples}


We give some sample applications for some of our results. 
First,  we give examples of knots for which Theorem~\ref{thm:Main} can be used to generate locally flat discs in a homology class, where a smooth disc can be proven to not exist.

\begin{example}
We show that if $K\in\{14n11942, 14n13659\}$ then $K$ bounds a locally flat~$\Z_3$-disc in~\((\overline{\C P}^2)^\circ\) but does not bound a smooth $\Z_3$-disc in~\((\overline{\C P}^2)^\circ\). To see $K$ does not bound a smooth disc, we used KnotJob~\cite{SchuetzKJ} to compute the $s$-invariant is $s(K)=8$, then applied~\cite[Theorem~1.3]{Qin} to the class $3\in H^2(\overline{\C P}^2,S^3)$, noting that $s(K)=8>3^2-3=6$. To see~Theorem~\ref{thm:Main} applies, we first computed that in each case $\left\vert\Delta_K(e^\frac{2\pi i}{3})\cdot\Delta_K(e^\frac{4\pi i}{3}) \right\vert =1$, so by a classical result of Goeritz and Fox~\cite{Goeritz34, Fox-56-iii} we have that $H_1(\Sigma_3(K))=0$. We then used Sage to compute~$\Arf(K)=1$ so that~Theorem~\ref{thm:Main}\eqref{item:1Main} holds. Finally, we used Sage to compute that in each case $\sigma_K (e^\frac{2\pi i}{3})=\sigma_K (e^\frac{4\pi i}{3})=-4$, from which it may be computed that~Theorem~\ref{thm:Main}\eqref{item:2Main} holds, confirming $K$ bounds the claimed locally flat disc.
\end{example}

\begin{remark}
Examples of the previous sort are difficult to find among low-crossing knots, as we now discuss. The knot invariants in Theorem~\ref{thm:Main} are the Arf invariant and Levine-Tristram signature, the latter of which achieves its maximum near the Murasugi signature $\sigma(K)=\sigma_K(-1)$, and computations with low-crossing knots show this is roughly where the quantity on the right of Theorem~\ref{thm:Main}\eqref{item:2Main} usually achieves its maximum. On the other hand, the current best techniques to obstruct smooth sliceness within a homology class use the $\tau$-invariant (see~\cite[Theorem 1.1]{MR2026543}) or~$s$-invariant (see~\cite{Qin}). Due to the well-known close connections between $\sigma(K)$, $\tau$, and~$s$, among low-crossing knots, there is a tension between trying to make $|s|$ or $|\tau|$ large relative to~$d$ to obstruct smooth sliceness, while desiring small $|\sigma(K)|$ relative to $d$ to apply~Theorem~\ref{thm:Main}.
\end{remark}

Next,  we consider when winding number 0 satellites of the negative torus knot~\(5_1=T(-2,5)\) bound a $\Z_d$-disc in~\(N=(\C P^2)^\circ\) and its stabilisations. For $d=3$, the knot $5_1$ is readily seen by \emph{ad hoc} methods to bound a \emph{smooth}~$\Z_d$-disc in~$(\C P^2)^\circ$; the purpose of taking satellites is that it is likely that a suitable choice of companion knot will preclude the satellite from being smoothly~$\Z_3$-slice in~$(\C P^2)^\circ$. As we shall see, the knot invariants used in~Theorem~\ref{thm:Main} are robust under a winding number $0$ satellite operation so these satellites will still bound locally flat $\Z_3$-discs.

\color{black}


\begin{example}
\label{ex:T25}
Use $P(K)$ to denote a satellite knot with pattern~$P=T(-2,5)$, winding number zero,  and companion $K$.
We claim~$P(K)$ bounds a~$\Z_d$-disc in~\(N=(\C P^2)^\circ\) if and only if~$d=3$. 


We first show $P(K)$ indeed bounds a $\Z_3$-disc.
Performing winding number zero satellite operations does not affect the Levine-Tristram signature,  the Arf invariant and the homology of the~$d$-fold branched cover, so it suffices to verify the conditions for Theorem~\ref{thm:Main} are satisfied for~$P$.
For~$d$,~$p$ and~$q$ pairwise coprime, the~$d$-fold branched cover of the~$(p,q)$-torus knot is an integer Brieskorn homology sphere~\cite{MilnorBrieskorn}, so $H_1(\Sigma_3(P))=0$.
The remaining conditions for Theorem~\ref{thm:Main} follow because $P$ is \emph{smoothly} $\Z_3$-slice in~\(N=(\C P^2)^\circ\), but we check them manually as we will use the computation later anyway.

 The knot has~$\Arf(P)=1$ and~$\sigma(P)=4$, so the characteristic class~$3 \in H_2((\C P^2)^\circ,S^3)$ satisfies~\eqref{item:1Main} from Theorem~\ref{thm:Main}.
