As explained above, the claim ensures we can perform ambient surgery on~$\gamma$.
It remains to argue that that the outcome stably represents~$x$.
We recall why ambient surgery is possible.
The bundle~$\nu(\gamma \subset F)$ is trivial.
Pick one of the two sections(=framings) for this bundle, call it~$s$, and identify~$\nu(\gamma \subset F)$ with~$\gamma \times [-1,1]$.
As~$W(\Delta_i)=0$,  the section~$s$ extends to a section of~$\nu(\Delta \subset N)$.
%because orientable
Since the manifolds are orientable, we obtain a framing of~$\Delta$ and can therefore perform ambient surgery.

Write~$\gamma^\pm:=\gamma \times \lbrace \pm 1\rbrace$.
Since the section~$s$ extends over~$D$,  we obtain disjoint discs~$\Delta^\pm$ with boundary~$\gamma^\pm$.
The ambient surgery removes~$\nu(\gamma \subset F)$ from~$F$,  and adds~$\Delta^\pm$.
Since the surgery is performed in the interior of~$F$ we have~$\partial F'=\partial F$.

We argue that~$[F']=[F]$.
It suffices to show~$F' \cdot z=F \cdot z$ for every~$z \in H_2(N)$.
By construction we have~$z \cdot F'=z \cdot F+z \cdot \Delta^++z \cdot \Delta^-$.
An intersection between~$z$ and~$\Delta$ introduces an intersection between~$z$ and~$\Delta^+$ and also an intersection between~$z$ and~$\Delta^-$, but these intersections have opposite signs because they come at either end of~$\Delta\times[0,1]$.
It follows that~$z \cdot F'=z \cdot F$ for every~$z \in H_2(N)$ and therefore~$[F]=[F'].$ \qedhere
%Alternatively, note that the trace of the surgery embeds in~$N$ (XXX: why?), providing a cobordism (and thus a homology) between~$F$ and~$F'$.
\end{proof}





\section{Sufficient conditions for the existence of a disc}
\label{sec:Sufficient}



Throughout this section, let $N$ be a simply-connected $4$-manifold with boundary~$S^3$, let~$K \subset \partial N \cong S^3$ be a knot with~$H_1(\Sigma_d(K))=0$, let $x \in H_2(N,\partial N)$ be a nonzero class of divisibility~$d$
and assume that a simple disc with boundary~$K$ exists in a stabilisation~$N_k:=N\#^k S^2 \times S^2$, representing $x\oplus0$.

The purpose of this section is to prove Proposition~\ref{prop:TopSplitting}, where we list three conditions that are sufficient to ensure the existence of a simple disc in $N$ representing $x \in H_2(N,\partial N)$. 
The conditions are distilled from an algebraic theorem due to Lee and Wilczy\'nski, applied to our setup.
After recalling the notion of a pointed hermitian form in Section~\ref{sub:PointedHermitian},
Section~\ref{sub:SplittingTheorem} recalls the Lee-Wilczy\'nski theorem;~in essence, their splitting theorem lists five conditions that are sufficient for a pointed hermitian form to split off a hyperbolic form.   
Section~\ref{sub:Fixed} notes that in our setting,  one of their conditions is automatic. 
Section~\ref{sub:Signature} reformulates another of the conditions using Levine-Tristram signature of $K$.
Section~\ref{sub:Sufficient} states the remaining conditions in a way amenable to verification in subsequent sections. We also provide the geometric argument confirming the conditions are sufficient to slice the knot~$K$ in $N$.


\subsection{Pointed hermitian forms}
\label{sub:PointedHermitian}



This section recalls the definition of a pointed hermitian form.

\begin{definition}
A \emph{pointed hermitian form} over a ring with involution $R$ is a triple~$(P,\lambda,z)$ where~$P$ is an $R$-module, $\lambda$ is a hermitian form on $P$, and $z \in P$.
\end{definition}

This notion played a prominent role in~\cite{LWCommentarii,LWKtheory,LWGenus}.



\begin{example}
\label{ex:pointed}
We describe two examples of pointed hermitian forms.
~
\begin{itemize}
\item The \emph{pointed hyperbolic form} over a ring with involution $R$ refers to 
\[
H(R)=\left(R\oplus R,\begin{pmatrix} 0 & 1 \\ 1 & 0 \end{pmatrix}, 0\oplus0\right ).
\]
\item 
Let~$N$,~$K$,~$x$ be as described at the start of the section, and let~$D \subset N \#^k S^2 \times S^2$ be a disc representing~$x \oplus 0$, with boundary~$K$. Consider the~$d$-fold branched cover~$\Sigma_d(D)$ of~$D \subset N_k$.
The branch set, namely the embedded disc \(\widetilde{D} \subset \Sigma_d(D)\), represents a 
%primitive homology 
class in~\(H_2(\Sigma_d(D), \partial\Sigma_d(D))\).
Since~\(H_1(\Sigma_d(K)) = 0\), the inclusion induces an isomorphism~$H_2(\Sigma_d(D)) \to H_2(\Sigma_d(D),\partial \Sigma_d(D)).$
Denote by \(z \in H_2(\Sigma_d(D)) \) the unique element which is sent to \([\widetilde{D}]\) under this isomorphism.
We also use~$Q_{\Sigma_d(D)}$ to denote the intersection form of~$\Sigma_d(D)$ and consider the hermitian form
\begin{align*}
\lambda_{\Sigma_d(D)} \colon H_2(\Sigma_d(D)) \times H_2(\Sigma_d(D)) &\to \Z[\Z_d] \\
(x,y) \mapsto &=\sum_{g\in \Z_d}Q_{\Sigma_d(D)}(x,gy)g^{-1}.
\end{align*}
The following is a pointed hermitian form over~$\Z[\Z_d]$:
\[
(P,\lambda,z)=(H_2(\Sigma_d(D)),\lambda_{\Sigma_d(D)},z).
\]
\end{itemize}
\end{example}



\subsection{Lee-Wilczy\'nski's splitting theorem}
\label{sub:SplittingTheorem}



We now recall an algebraic ``destabilisation'' result due to Lee-Wilczy\'nski. 
For this, we will need some definitions and notation.

\medbreak

Write $\Z_d=\{1,t,\dots,t^{d-1}\}$ the cyclic group of order $d$ and~$\Lambda:=\Z[\Z_d]$ for its group ring.
We denote by~\(\mathcal{N}:=1+t+\ldots+t^{d-1}\in \Lambda\) the \emph{norm element} and $I=\ker(\Lambda\xrightarrow{\varepsilon}\Z)$ the \emph{augmentation ideal}. Note the free resolution
\begin{equation}
\label{eq:FreeResolution}
\dots\xrightarrow{1-t}\Lambda\xrightarrow{\mathcal{N}}\Lambda\xrightarrow{1-t}\Lambda\xrightarrow{\varepsilon}\Z\to 0.
%AC: There was \cdot \mathcal{N} but I removed it because we don't do that for (1-t) and also don't do it elsewhere.
\end{equation}
Whence, we have $I=\{a\in\Lambda\,|\, \mathcal{N}a=0\}$ the $\mathcal{N}$-torsion elements.
%I=\im(1-t)=\ker(\mathcal{N}).
%Note as well that $\Z\mathcal{N}:=\{a\mathcal{N}\,|\,a\in\Z\}=\Lambda^{\Z_d}$, the fixed point set under multiplication by group elements.
The \emph{Rim square} is the following pullback square, where horizontal maps are the quotient by $(\mathcal{N})$ and vertical maps are the quotient by $I$:
\begin{equation}\label{eq:rim}
\begin{tikzcd}
\Lambda \ar[r] \ar[d]& \Lambda_1\ar[d] \\
\Lambda_0 \ar[r]& \Lambda_2.
\end{tikzcd}
:=
\begin{tikzcd}
\Lambda \ar[r] \ar[d]& \Lambda/(\mathcal{N})\ar[d] \\
\Lambda/I\cong\Z \ar[r]& \Z_d.
\end{tikzcd}
\end{equation}
The isomorphism~$\Lambda/I \cong \Z$ is induced by the augmentation homomorphism.
In what follows, the identification~$\Lambda_0\cong \Z$ will be made implicitly.







\begin{notation}
Let $(P,\lambda, z)$ be a pointed hermitian form over $\Lambda$. We denote by
\begin{itemize}
\item~$T_{\mathcal{N}}P$ the submodule of~$\mathcal{N}$-torsion elements, i.e.\@  those~$x \in P$ such that~$\mathcal{N}x=0$;
\item $(P_0,\lambda_0,z_0)$ the induced $\Z$-valued form on the abelian group~$P_0 :=P/T_{\mathcal{N}}P$;
%~$\Lambda_0$-module~$P_0 :=P/T_{\mathcal{N}}P$;
\item~$\pi_0 \colon P \to P_0$ the quotient map;
