Given a pointed hermitian form \((P,\lambda,z)\) over $\Lambda$ where it is known that the corresponding $\Z$-form splits off some number of hyperbolic summands,~$\beta_0\colon (P_0,\lambda_0,z_0)\cong (L, \lambda, x) \oplus H(\Z)^k$, we wish to know when the splitting can be ``lifted'' to the level of the $\Lambda$-form. This desired situation is summarised in the following diagram of quotient maps and isometries:
\[\begin{tikzcd}
	{(P,\lambda,z)} &&& {(P',\lambda',z')\oplus H(\Lambda)^k} \\
	\\
	&&& {(P_0',\lambda_0',z_0')\oplus H(\Z)^k} \\
	\\
	{(P_0,\lambda_0,z_0)} &&& {(L, \lambda, x) \oplus H(\Z)^k.}
	\arrow["\alpha", from=1-1, to=1-4]
	\arrow["\cong"', from=1-1, to=1-4]
	\arrow["{\pi_0}"', from=1-1, to=5-1]
	\arrow["{\pi_0}", from=1-4, to=3-4]
	\arrow["\cong"',"{\alpha_0}", from=5-1, to=3-4, bend left =18]
	\arrow["\cong"', from=5-1, to=5-4]
	\arrow["{\beta_0}", from=5-1, to=5-4]
	\arrow["{\beta_0' \oplus \text{Id}}", from=3-4, to=5-4]
	\arrow["\cong"', from=3-4, to=5-4]
\end{tikzcd}
\]

Lee-Wilczy\'nski's splitting theorem provides the conditions ensuring such a diagram exists and commutes.
For brevity, we say that the hermitian form~$\lambda$ is \emph{weakly even} on a subset $A \subset P$ if, for every~$a \in A$,  it satisfies $\lambda(a,a)=r+\overline{r}$ for some $r \in \Lambda.$

\begin{theorem}[The Splitting Theorem {\cite[Theorem 3.1]{LWGenus}}]\label{thm:splitting}
    Let \((P,\lambda,z)\) be a nonsingular pointed hermitian form over \(\Lambda\).
     Suppose the following conditions hold:
    \begin{enumerate}
            \item \(z\in P^{\Z_d}\);
        \item \(P\) is a projective module of rank \(b+2k\) over \(\Lambda\) with $b,k \geq 1$;
         \item   the $j$-signatures of $\lambda$ satisfy~\(b \geq \max_{0 \leq j<d} \vert \sigma_j(\lambda)\vert\);
         %%XXX: The sphere papers have \leq instead of <; also that's how it's stated in the topological application.
        \item there is a nonsingular pointed hermitian \(\Z\)-module \((L,\lambda,x)\) and a splitting \[\beta_0\colon (P_0,\lambda_0,z_0) \cong (L,\lambda,x) \oplus H(\Z)^k;\]
        \item the form $\lambda$ is weakly even on the kernel of
\[\begin{tikzcd}
%	{\eta \colon P} 
		{P} & {P_0} & {L\oplus \Z^{2k} } & L.
	\arrow["{\pi_0}", from=1-1, to=1-2]
	\arrow["{\beta_0}", from=1-2, to=1-3]
	\arrow["\proj_1",from=1-3, to=1-4]
\end{tikzcd}\]
    \end{enumerate}
    Then there is a pointed hermitian form \((P', \lambda', z')\) over $\Lambda$ and isometries of pointed hermitian~forms 
        \begin{align*}
            \alpha & \colon (P,\lambda,z) \cong (P',\lambda',z') \oplus H(\Lambda)^k, \\ 
        \beta_0' & \colon (P_0',\lambda_0',z_0') \cong (L, \lambda,x)
        \end{align*}
        such that \(\beta_0 = (\beta_0' \oplus \id)\circ \alpha_0\).

        \end{theorem}



\begin{remark}
Theorem~\ref{thm:splitting} is a modified version of the splitting theorem found in \cite[Theorem~3.1]{LWGenus}.
We are restricting to the case of genus zero, which corresponds to setting \(q=0\) in~\cite[Theorem 3.1]{LWGenus}. In this case, as in the other formulation of the splitting theorem from~\cite[Theorem 6.1]{LWKtheory}, there is no $2$-adic condition.
\end{remark}



\subsection{The fixed-point condition}
\label{sub:Fixed}

Let~$N$, $K$, $x$ be as described at the start of the section, and let~$D \subset N \#^k S^2 \times S^2$ be a disc representing $x \oplus 0$ with boundary~$K$.
 Recall from Example~\ref{ex:pointed} that this determines a pointed hermitian form
\[
(P,\lambda,z)=(H_2(\Sigma_d(D)),\lambda_{\Sigma_d(D)},z)
\]
over $\Lambda$, where $z$ corresponds to \([\widetilde{D}]\), the class of the branch set, under the inclusion induced isomorphism \( H_2(\Sigma_d(D))\cong H_2(\Sigma_d(D), \Sigma_d(K))\). 
We now verify $z$ is indeed in the fixed-point set of the $\Z_d$-action.

\begin{lemma}
\label{lem:FixedPointCondition}
Let~$N$ be a simply-connected~\(4\)-manifold with boundary \(S^3\), let~$x \in H_2(N, \partial N)$ be a nonzero homology of divisibility~$d$, and let $K \subset S^3$ be a knot with $H_1(\Sigma_d(K))=0$.
The class~$z$ lies in~\(H_2(\Sigma_d(D))^{\Z_d}\).
\end{lemma}
\begin{proof}
Since $\widetilde{D}$ is the branch set of $\Sigma_d(D)$, the element~$[\widetilde{D}]$ belongs to $H_2(\Sigma_d(D),\Sigma_d(K))^{\Z_d}$. 
Since the inclusion induced isomorphism~$i\colon H_2(\Sigma_d(D)) \to H_2(\Sigma_d(D),\Sigma_d(K))$ is an isomorphism of~\(\Lambda\)-modules, $z=i_*^{-1}([\widetilde{D}]) \in H_2(\Sigma_d(D))^{\Z_d}$, establishing the lemma.
\end{proof}



\subsection{The $j$-signature condition}
\label{sub:Signature}

Next we recast the signature condition of Theorem~\ref{thm:splitting}, in the case where $P=H_2(\Sigma_d(D))$, in terms of Levine-Tristram signatures of the knot $K$.

Let $M$ be a simply-connected $4$-manifold with boundary $S^3$.
Given a properly embedded surface~$F \subset M$ with $H_1(M \setminus F) \cong \Z_d$, the intersection form of~$\Sigma_d(F)$ restricts to a hermitian form on the $e^{2\pi ij/d}$-eigenspace of the $\Z_d$-action
$$\left\{ x \in H_2(\Sigma_d(F);\C) \mid tx=e^{\frac{2\pi ij}{d}} x \right\}.$$
We write~$\sigma_j(\Sigma_d(F))$ for the signature of this restricted form.
Also, we write~$\sigma_K(\omega)$ for the Levine-Tristram signature of a knot~$K$ at~$\omega \in S^1$.
The next lemma, which stems from the work of Rohlin~\cite{RoklinTwoDimensional}, recasts~$\sigma_j(\Sigma_d(D))$ in terms of~$\sigma_K(e^{2\pi ij/d})$ and the algebraic topology of~$M$. 



\begin{lemma}
\label{lem:PrelimLT}
Let~$M$ be a simply-connected~$4$-manifold with boundary~$S^3$,  let $K \subset \partial M \cong S^3$ be a knot,  and let $0 \leq j <d$.  If $\Sigma_d(F) \to M$ is a $d$-fold cover with branch set a surface $F \subset M$ with boundary $K$, then
$$\sigma_j(\Sigma_d(F))=\sigma(M)-\frac{2j(d-j)}{d^2} Q_M([F],[F])+\sigma_K(e^{2\pi ij/d}).$$ 
\end{lemma}
\begin{proof}
Consider the closed~$4$-manifold~$X:=M \cup D^4$. 
Let~$G \subset D^4$ be a properly embedded surface with boundary~$K$. A Mayer-Vietoris argument shows the surface~$S:=F \cup G\subset  X$ has~$H_1(X\sm S)\cong~\Z_{d}$. 
The abelianisation~$\pi_1(X\sm S)\to H_1(X\sm S)\cong  \Z_d$ extends~$\pi_1(M\sm F) \to\Z_d$. 
Denote the \(d\)-fold branched cover of~$X$ over \(S\) by \(\Sigma_d(S)\), noting this extends the branched cover of~$M$ over~$F$.
Since~$X$ is closed, a result of Rohlin~\cite{RoklinTwoDimensional} (see also~\cite[Lemma~2.1]{CassonGordonOnSliceKnots}), together with the definition of~$S$ as~$F \cup G$,  implies that
$$ \sigma_j(\Sigma_d(S)) 
 =\sigma(X)-\frac{2j(d-j)}{d^2} Q_X([S],[S])
  =\sigma(M)-\frac{2j(d-j)}{d^2} Q_M([F],[F]).$$ 
On the other hand,  combining Novikov additivity (for~$\Sigma_d(S)=\Sigma_d(F)\cup -\Sigma_d(G)$) with a four-dimensional interpretation of the Levine-Tristram signature~\cite{ViroBranched} (see also~\cite[Theorem~3.1]{ConwaySurvey}) yields
$$ \sigma_j(\Sigma_d(S)) 
=\sigma_j(\Sigma_d(F)) -\sigma_j(\Sigma_d(G)) 
=\sigma_j(\Sigma_d(F)) -\sigma_K(e^{2\pi i j/d}).  
$$ 
The lemma now follows by combining these two results.
\end{proof}





Finally,  we note that the signature condition in Theorem~\ref{thm:Main} is necessary.
\begin{proposition}
\label{prop:SignatureCondition}
For a simply-connected~$4$-manifold~$M$ with boundary~$S^3$,   a~$\Z_d$-surface~$F \subset M$ with boundary a knot~$K \subset S^3$,  and $0 \leq j<d$, we have
$$ b_1(F)+b_2(M) \geq \Bigg| \sigma(M)-\frac{2j(d-j)}{d^2} Q_M([F],[F]) +\sigma_K(e^{2\pi ij/d}) \Bigg|=\Bigg|\sigma_j(\Sigma_d(F))\Bigg|.$$ 
\end{proposition}
\begin{proof}
The first inequality is due (in much greater generality) to Gilmer~\cite[Remark following Corollary 4.2]{GilmerConfiguration}.
Gilmer's result is stated for $d$ a prime power dividing $x$ but without the assumption that $F$ is simple. 
A little work shows that the prime power assumption can be dropped if $F$ is a~$\Z_d$-surface (so, in particular, $d$ is the divisibility of $x$).
