	\arrow[from=1-4, to=1-5]
\end{tikzcd}\]
We now tensor this sequence over~$\Lambda_1$, yielding
\[\begin{tikzcd}
	{  \underbrace{H^1(\widetilde{D}\times S^1)}_{\cong \Lambda_0 \otimes_\Lambda \Lambda_1}  } & { H_2(\Sigma_d(D)) \otimes_{\Lambda} \Lambda_1} & {\underbrace{H^2(X_D^d) \otimes_{\Lambda} \Lambda_1}_{\cong_s I \otimes_{\Lambda} \Lambda_1}} & 0.
	\arrow["\iota", from=1-1, to=1-2]
	\arrow[from=1-2, to=1-3]
	\arrow[from=1-3, to=1-4]
\end{tikzcd}\]
We assert that the map labelled~$\iota$ is the zero map.
Note that~$\Lambda_0 \otimes_{\Lambda} \Lambda_1 \cong \Z_d$ is~$\Z$-torsion.
Since~$H_2(\Sigma_d(D))$ is projective, it follows that~$H_2(\Sigma_d(D)) \otimes_{\Lambda} \Lambda_1$ is also projective and therefore has no~$\Z$-torsion.
%%Don't delete.
%If it had $\Z$-torsion, it would have $\Lambda_1$-torsion as well, but projective modules are torsion-free.
Combining these two facts implies that~$\iota$ is the zero map.

Since~$I$ is free as a~$\Lambda_1$-module, 
%%Don't delete. See MP augmentation ideal is free as a Lambda1 Module.pdf.
it follows that~$H^2(X_D^d)$ is stably free as a~$\Lambda_1$-module.
Since~$\iota$ is the zero map, it follows that~$H_2(\Sigma_d(D)) \otimes_{\Lambda} \Lambda_1$ is also stably free.  
\end{proof}

In order to determine $H_2(\Sigma_d(D))$,  it remains to perform an Euler characteristic calculation.
\begin{lemma}
\label{lem:RankCalculation}
If $M$ is a simply-connected $4$-manifold with boundary $S^3$ and $D \subset M$ is a properly embedded $\Z_d$-disc with $d \neq 0$, then $b_2(\Sigma_d(D))=d \cdot b_2(M).$
\end{lemma}
\begin{proof}
Since $\pi_1(M\setminus D) \cong \Z_d$,  the branched cover~$\Sigma_d(D)$ is simply-connected.
We deduce that~$H_3(\Sigma_d(D)) \cong  H^1(\Sigma_d(D),\partial \Sigma_d(D))=0$.
It follows that $b_2(\Sigma_d(D))+1=\chi(\Sigma_d(D))$.
Next, observe that 
%%Don't delete.
%Use that the gluing is along D \times S^1 which is a 3-manifold with toroidal boundary and therefore has vanishing Euler characteristic.
$$ \chi(\Sigma_d(D))
=\chi(X_d(D))+1
=d \cdot \chi(X_D) +1
=d(\chi(X)-1)+1
=d\cdot b_2(X)+1.
$$
Combining these calculations yields $b_2(\Sigma_d(D))=d \cdot b_2(M)$.
\end{proof}

Finally,  we prove the main result of this section.

\begin{proposition}
\label{prop:H2Free}
Let $N$ be a simply-connected $4$-manifold with boundary $S^3$,  let $K \subset \partial N$ be a knot with $H_1(\Sigma_d(K))=0$,  and let~$x \in H_2(N,\partial N)$
be a nonzero class of divisibility $d$.
If~$D \subset N \#^k S^2 \times S^2$ is a disc representing~$x \oplus 0$ with boundary~$K$,  then
$$ H_2(\Sigma_d(D)) \cong \Lambda^{b_2(N)+2k}.$$
\end{proposition}
\begin{proof}
Proposition~\ref{prop:SphereStablyFree} ensures that $H_2(\Sigma_d(D))$ is stably free.
Theorem~\ref{thm:ModulesOverZZd} therefore ensures that it is free, say of rank $r$.
It follows that as an abelian group $H_2(\Sigma_d(D))$ is free of rank $dr$.
Lemma~\ref{lem:RankCalculation} then implies that $r=b_2(N)+2k.$
\end{proof}



\section{Splitting of the form over $\Z$.}
\label{sec:SplittingFormOverZ}

Continuing with Notation~\ref{not:TheUsual}, the goal of this section is to establish the second condition from Proposition~\ref{prop:TopSplitting}, which states that the $\Lambda_0$ version of the pointed hermitian form on $H_2(\Sigma_d(D))$ splits off $k$ hyperbolic summands.
Our overall strategy follows Lee and Wilczy\'nski's approach in the closed case~\cite{LWCommentarii,LWKtheory}.

\medbreak 
We recall some notation. 
We write~$\pi_0\colon \Lambda \to \Lambda_0 =\Lambda/T_{\mathcal{N}}\Lambda\cong\Z$ for the projection map.
We set~$H_2(\Sigma_d(D))_0:=H_2(\Sigma_d(D))/T_{\mathcal{N}}H_2(\Sigma_d(D))$ with the corresponding projection map also denoted~$\pi_0 \colon H_2(\Sigma_d(D)) \to H_2(\Sigma_d(D))_0$. 
Recall that $\lambda_{\Sigma_d(D)}$ descends to a~$\Z$-valued form on~$H_2(\Sigma_d(D))_0$, which we were previously denoting $(\lambda_{\Sigma_d(D)})_0$, but in this section will denote
\begin{align*}
\lambda_0 \colon H_2(\Sigma_d(D))_0 \times H_2(\Sigma_d(D))_0 &\to \Lambda/T_{\mathcal{N}}\Lambda \cong \Z \\
(\pi_0(x),\pi_0(y)) &\mapsto \pi_0(\lambda(x,y)),
\end{align*}
for brevity. Recall that $\lambda_0$ is nonsingular; see Remark~\ref{rem:NonSingular}. 
Here and in the sequel we denote $z_0:=\pi_0(z)$ and $i_* \colon H_2(N) \to H_2(N,\partial N)$ for inclusion induced map.





The next proposition, whose proof closely follows~\cite[Proposition \(2.6\)]{LWGenus} is the main result of this section: it proves the required splitting of~$(H_2(\Sigma_d(D))_0,\lambda_0,z_0)$. 

\begin{proposition}
\label{prop:SplitDownstairs}
The branched covering projection~$p \colon \Sigma_d(D) \to N_k$ induces an isometry
$$p_0 \colon  (H_2(\Sigma_d(D))_0,\lambda_0,z_0) \to (H_2(N_k),Q_{N_k},i_*^{-1}(x) \oplus 0)$$
that satisfies~\(p_0 \circ \pi_0 = p_*\).

In particular, there exists an orthogonal splitting of pointed hermitian modules 
    \[ p_0 \colon (H_2(\Sigma_d(D))_0,\lambda_0,z_0) \xrightarrow{\cong} (H_2(N), Q_N, x) \oplus H(\Z)^k\] which only depends on the branched cover \(p\) and the connected sum decomposition of \(N_k\). 
\end{proposition}
\begin{proof}
    The covering-induced map~$p_* \colon H_2(\Sigma_d(D)) \to H_2(N_k)$ vanishes on~$T_{\mathcal{N}} H_2(\Sigma_d(D))$. 
    Indeed if~$z \in T_{\mathcal{N}}$, then~$d \cdot p_*(z)=p_*(\mathcal{N}z)=0$, but since~$H_2(N_k)$ is torsion-free, we deduce that~$p_*(z)=0$, as asserted.
It follows that~$p_*$ induces a map 
$$ p_0 \colon H_2(\Sigma_d(D))_0 \to H_2(N_k).~$$
By definition, we have~$p_0 \circ \pi_0=p_*$.
Next, we argue that~$p_0$ induces a morphism 
$$ p_0 \colon (H_2(\Sigma_d(D))_0,\lambda_0,z_0) \to (H_2(N_k),Q_{N_k},i_*^{-1}(x) \oplus 0).$$
Clearly,  by definition of~$p_0$ we have~$p_0(z_0)=p_0(\pi_0(z))=p_*(z)=i_*^{-1}(x) \oplus 0.$
The crux is therefore to show that~$p_0$ preserves the intersection forms.
Using the surjectivity of $\pi_0$ and $p_0 \circ \pi_0=p_*$, this amounts to verifying that~$Q_{N_k}(p_*(y),p_*(y'))=\lambda_0(\pi_0(y),\pi_0(y'))$ for all~$y,y' \in H_2(\Sigma_d(D)).$



We use the augmentation-induced isomorphism~$\Lambda/T_{\mathcal{N}}\Lambda\cong\Z$ to identify~$\lambda_0(\pi_0(y),\pi_0(y')) \in \Lambda_0$ with~$\aug(\lambda_0(\pi_0(y),\pi_0(y'))) \in \Z$.
Proposition~\ref{prop:LWIntersectionEquality} now yields
$$\aug(\lambda_0(\pi_0(y),\pi_0(y')))
=\aug\left( \sum_{g \in G} Q_{\Sigma_d(D)}(y,gy')g^{-1} \right)
=\sum_{g \in G} Q_{\Sigma_d(D)}(y,gy')
=Q_{N_k}(p_*(y),p_*(y')).
$$
Thus~$p_0$ preserves the hermitian forms, as claimed.

Since $p_* \colon H_2(\Sigma_d(D)) \to H_2(N_k)$ is surjective (see Lemma~\ref{lem:Surjectivep*}, below), and~$p_0 \circ \pi_0=p_*$, it follows that $p_0$ is surjective.
Note that $Q_{N_k}$ and $\lambda_0$ are nonsingular; for the latter we use Remark~\ref{rem:NonSingular}.
Since~$p_0$ is a surjective morphism of nonsingular symmetric forms, it is necessarily injective.
Thus~$p_0$ is an isometry, as required.
\end{proof}

The following fact was needed in the proof above.
\begin{lemma}
\label{lem:Surjectivep*}
The following branched covering induced map is surjective:
$$ p_* \colon H_2(\Sigma_d(D)) \to H_2(N_k).$$
\end{lemma}

\begin{proof}
By excising \(\text{Int}(X_D^d)\cup X_K^d\), we obtain that $H_i(\Sigma_d(D),X_D^d) \cong H_i(\widetilde{D} \times D^2, \widetilde{D} \times S^1)$, and the latter is trivial except in degree~$2$, where it is infinite cyclic.
%%Don't delete
% {here during excision we used the identification~$(\overline{\nu}(\widetilde{D}),\partial \overline{\nu}(\widetilde{D}) \setminus  \nu(K)) \cong (\widetilde{D} \times D^2, \widetilde{D} \times S^1)$.
% in degrees~$0$ and~$2$, where it is infinite cyclic.
%AC: Degree 0 trivial as well.
The same holds for the pair $(N_k, X_D)$ and it follows that the branched covering map induces an isomorphism 
$$H_2(\Sigma_d(D),X_D^d) \xrightarrow{\cong} H_2(N_k,X_D).$$
Since $X_D^d, N_k$ and $\Sigma_d(D)$ are simply-connected, we obtain the following commutative diagram of projection induced maps:
\[\begin{tikzcd}
	0 & {H_2(X_D^d)} & {H_2(\Sigma_d(D))} & {H_2(\Sigma_d(D),X_D^d)} & 0 \\
	0 & {H_2(X_D)} & {H_2(N_k)} & {H_2(N_k,X_D)} & {H_1(X_D)} & 0.
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-2, to=1-3]
	\arrow["{\proj_*}", from=1-2, to=2-2]
	\arrow[from=1-3, to=1-4]
	\arrow["{p_*}", from=1-3, to=2-3]
	\arrow[from=1-4, to=1-5]
	\arrow["\cong", from=1-4, to=2-4]
	\arrow[from=2-1, to=2-2]
	\arrow[from=2-2, to=2-3]
	\arrow[from=2-3, to=2-4]
	\arrow[from=2-4, to=2-5]
	\arrow[from=2-5, to=2-6]
\end{tikzcd}\]
%%Don't delete.
%x goes to the right, lifts to t, which comes from a u
%thus u maps back down to p(u).
%Both x and p(u) map to t on the right.
%Thus x-p(u)=i(a).
%a=proj_*(b)
%Now p(u+j_*(b))=p(u)+pj(b)=p(u)+x-p(u)=x.
A diagram chase shows that if $\proj_* \colon H_2(X_D^d) \to H_2(X_D)$ is surjective, then so is $p_*$.
To establish the surjectivity of $\proj_*$,  we consider the following diagram which is commutative thanks to the naturality of the Hurewicz map:
\[\begin{tikzcd}
	{\pi_2(X_D^d)} && {\pi_2(X_D)} \\
	{H_2(X_D^d)} && {H_2(X_D).}
	\arrow["{\proj_*}", from=1-1, to=1-3]
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-3, to=2-3]
	\arrow["{\proj_*}", from=2-1, to=2-3]
