Since $H_2(\pi_1(X_D)) = H_2(\Z_d)=0$, the right map is surjective and since $X_D^d \to X_D$ is a covering space, the top map is an isomorphism.
It follows that the bottom $\proj_*$ is surjective, as required.
\end{proof}

\section{The evenness condition}
\label{sec:EvenessCondition}

Continuing with Notation~\ref{not:TheUsual}, the goal of this section is to establish the third and final condition from Proposition~\ref{prop:TopSplitting},  namely that~$\lambda_{\Sigma_d(D)}$ is weakly even on the kernel of
\[\begin{tikzcd}
	{\eta \colon H_2(\Sigma_d(D))} & {H_2(\Sigma_d(D))_0} & {H_2(N) \oplus \Z^{2k} } & H_2(N).
	\arrow["{\pi_0}", from=1-1, to=1-2]
	\arrow["{p_0}", from=1-2, to=1-3]
	\arrow["\proj_1",from=1-3, to=1-4]
\end{tikzcd}\]
Here, recall that a hermitian form $(H,\lambda)$ over $\Lambda$ is \emph{weakly even on a subset~$A \subset H$} if for every~$a \in A$,  it satisfies $\lambda(a,a)=r+\overline{r}$ for some~$r \in \Lambda$.
Furthermore, recall that 
$$\pi_0 \colon H_2(\Sigma_d(D)) \to H_2(\Sigma_d(D))_0=H_2(\Sigma_d(D))/T_{\mathcal{N}}H_2(\Sigma_d(D))$$ denotes the canonical projection.
Finally, note the map $p_0$, which was described in Proposition~\ref{prop:SplitDownstairs}, plays the role of the map $\beta_0$ in the splitting theorem (Theorem~\ref{thm:splitting}).

\medbreak

Proving this evenness condition requires several intermediate lemmas.


\begin{notation}
When $d$ is even, we write $T \in \Z_d$ for the unique nontrivial element of order $2$.
\end{notation}


In what follows, we say that an element $p \in \Lambda$ is \emph{even} if it can be written as~$p=r+\overline{r}$ for some~$r \in \Lambda$.
We begin with a criterion ensuring that $\lambda_{\Sigma_d(D)}(y,y)$ is even.

\begin{lemma}
\label{lem:EvenCriterion}
Given~\(y \in H_2(\Sigma_d(D))\), the group ring element~$\lambda_{\Sigma_d(D)}(y,y)$ is even if and only if~$Q_{\Sigma_d(D)}(y,y)$ is even and, in the case $d$ is even,~$Q_{\Sigma_d(D)}(y,Ty)$ is also even.
\end{lemma}
\begin{proof}
By definition of $\lambda_{\Sigma_d(D)}$ we have 
$$\lambda_{\Sigma_d(D)}(y,y)=\sum_{g \in \Z_d}Q_{\Sigma_d(D)}(y,g^{-1}y)g.$$
Since $Q_{\Sigma_d(D)}(y,h^{-1}y)=Q_{\Sigma_d(D)}(hy,y)=Q_{\Sigma_d(D)}(y,hy)$ for every $h\in \Z_d$, we deduce that~$\lambda_{\Sigma_d(D)}(y,y)$ is even if and only if~$Q_{\Sigma_d(D)}(y,gy)$ is even for every $g \in \Z_d$ of order~$2.$
\end{proof}

For the second lemma,  recall that~$\lambda_0$ denotes the form induced by~$\lambda_{\Sigma_d(D)}$ on~$H_2(\Sigma_d(D))_0$.

\begin{lemma}
\label{lem:SumIsEven}
For $x \in H_2(\Sigma_d(D))$,  the following congruences hold:
$$
\lambda_0(\pi_0(x),\pi_0(x))\equiv
\begin{cases}
Q_{\Sigma_d(D)}(x,x) & \quad \text{ if } d \text { is odd} \\
Q_{\Sigma_d(D)}(x,x)+Q_{\Sigma_d(D)}(x,Tx) & \quad \text{ if } d \text { is even}
\end{cases}
\quad \mod 2.
$$
\end{lemma}
\begin{proof}
Using that~$p_0$ is an isometry (Proposition~\ref{prop:SplitDownstairs}),  the equality~$p_0 \circ \pi_0=p_*$ (also from Proposition~\ref{prop:SplitDownstairs}) and Proposition~\ref{prop:LWIntersectionEquality}, we obtain
\begin{equation}
\label{eq:UsefulIntermediate}
\lambda_0(\pi_0(y),\pi_0(y'))
=Q_{N_k}(p_0(\pi_0(y)),p_0(\pi_0(y')))
=Q_{N_k}(p_*(y),p_*(y'))
= \sum_{g \in G} Q_{\Sigma_d(D)}(y,gy').
\end{equation}
The lemma now follows by taking $y=y'$,  reducing modulo $2$,  and recalling that~$Q_{\Sigma_d(D)}(y,h^{-1}y)=Q_{\Sigma_d(D)}(y,hy)$ for every~$h\in \Z_d$.
\end{proof}

Our final lemma is specific to the case where $d$ is even.

\begin{lemma}
\label{lem:Edmonds}
Assume that $d$ is even.
If there exists an~$x \in H_2(\Sigma_d(D);\Z_2)$ with $Q_{\Sigma_d(D)}(x,Tx) \neq 0$, then, for every $y \in H_2(\Sigma_d(D))$
$$ Q_{\Sigma_d(D)}(y,Ty) = Q_{\Sigma_d(D)}(y,z) \mod 2.$$
\end{lemma}
\begin{proof}
By hypothesis,  there is a class~$\alpha \in H^2(\Sigma_d(D),\partial \Sigma_d(D);\Z_2)$ with~$\alpha \cup T^*\alpha \neq 0$.
Writing~$k \colon (D^2,\partial D^2) \to (\Sigma_d(D),\partial \Sigma_d(D))$ for the embedding with image~$\widetilde{D}$, a relative version of~\cite[Proposition 5.1]{EdmondsAspects} (see Proposition~\ref{prop:BredonRel}) ensures that for every $\beta \in H^2(\Sigma_d(D),\partial \Sigma_d(D);\Z_2)$, we have
\begin{equation}
\label{eq:RelativeEdmonds}
\langle \beta \cup T^*\beta,[\Sigma_d(D)] \rangle =\langle k^*(\beta),[D^2]\rangle \mod 2.
\end{equation}
Since~$i_*(z)=[\widetilde{D}]=k_*([D^2]) \in H_2(\Sigma_d(D),\partial \Sigma_d(D))$,  using the definition of the intersection form, it follows that for all $y \in H_2(\Sigma_d(D))$ 
\begin{align*}
Q_{\Sigma_d(D)}(z,y)
&=\langle \PD_{\Sigma_d(D)}^{-1}(i_*(y)),z\rangle
=\langle i^*(\PD_{\Sigma_d(D)}^{-1}(y)),z\rangle
=\langle \PD_{\Sigma_d(D)}^{-1}(y),k_*([D^2])\rangle\\
&=\langle k^*(\PD_{\Sigma_d(D)}^{-1}(y)),[D^2]\rangle 
=\langle \PD_{\Sigma_d(D)}^{-1}(y)  \cup T^*\PD_{\Sigma_d(D)}^{-1}(y) ,[\Sigma_d(D)]\rangle  \\
&=Q_{\Sigma_d(D)}(y,Ty) \mod 2.
\end{align*}
Here we used~\eqref{eq:RelativeEdmonds} in the fifth equality.
%%Don't delete.
%%There is a bit of dance to make with the coefficients.
%%Apply with  \beta=red_2 (PD^{-1}(y)) etc.
%% it works out because reducing mod 2 is very natural, but it’s a little sneaky.
This concludes the proof of the lemma.
\end{proof}



We now prove the main result of this section, namely the evenness condition of Proposition~\ref{prop:TopSplitting}.

\begin{proposition}
\label{prop:EvenessCondition}
%x \neq 0 is in the set-up.
If~$D \subset N_{k}$ is a~$\Z_d$-surface representing~$x \oplus 0 \in H_2(N_k, \partial N)$, then~$\lambda_{\Sigma_d(D)}$ is weakly even on
$$\operatorname{Ker}:=\ker \Big( H_2(\Sigma_d(D)) \xrightarrow{\pi_0} H_2(\Sigma_d(D))_0 \xrightarrow{p_0,\cong}  H_2(N) \oplus H_2(S^2 \times S^2)^k \xrightarrow{\operatorname{proj}} H_2(N) \Big).$$
\end{proposition}
\begin{proof}
By Lemma~\ref{lem:EvenCriterion}, it suffices to prove that $Q_{\Sigma_d(D)}(y,y)$ (as well as $Q_{\Sigma_d(D)}(Ty,y)$ if $d$ is even) is even for every $y \in \operatorname{Ker}$.
Now given $y \in \operatorname{Ker}$, note that~$p_0(\pi_0(y))\in H_2(S^2\times S^2)$. 
%%Don't delete.
%an element in that kernel is basically in the kernel of pi_0 in which case it maps to zero by p_0 \circ pi_0, so ok, or in ker(prok) in which case it's by def in the $S^2 \times S^2$-summands.
But elements of~$H_2(\#^k S^2\times S^2)\subset  H_2(N_k)$ pair trivially with themselves and also trivially with all elements~$w\in H_2(N)$, under $Q_{N_k}$. 
In particular since $p_0$ is an isometry (Proposition~\ref{prop:SplitDownstairs}),
we have~$\lambda_0(\pi_0(y),\pi_0(y))=Q_{N_k}(p_0(\pi_0(y)),p_0(\pi_0(y')))=0$.
%The same reasoning shows that $Q_{N_k}(p_0(\pi_0(y)),w)=0$.
For $d$ odd,  we apply Lemma~\ref{lem:SumIsEven} to compute that $Q_{\Sigma_d(D)}(y,y) \equiv \lambda_0(\pi_0(y),\pi_0(y))=0$ is even for every $y \in \operatorname{Ker}$, establishing the proposition in this case.

Now assume that~$d$ is even and write $x=dx_0$ with $x_0 \in H_2(N,\partial N)$ primitive.
Since~$H_2(\Sigma_d(D))$ is $\Lambda$-free (recall Proposition~\ref{prop:H2Free}),  there is a $z_0 \in H_2(\Sigma_d(D))$ with $z=\mathcal{N}z_0.$
By definition of~$z$ we have~$p(z)=i_*^{-1}(x)$,  and thus~$dx_0=i_*^{-1}(x)=p(z)=d  (p_0 \circ \pi_0 (z_0))$.
%(p_* \otimes \id_\Z)(z \otimes 1)=d\cdot ( p_* \otimes \id_\Z)(z_0 \otimes 1).$
%%Don't delete. Around here we're using the commutativity of eq:DiagramP0.
Dividing by~$d$ we deduce that~$x_0=p_0(\pi_0(z_0))$.
Since $p_0$ is an isometry, the previous paragraph therefore ensures that $\lambda_0(\pi_0(y),\pi_0(z_0))
=Q_{N_k}(p_0(\pi_0(y)),p_0(\pi_0(z_0))=0.$
%%Don't delete.  Because: x_0 \in H_2(N)
It follows that~$Q_{\Sigma_d(D)}(y,Ty)$ is even for every~$y \in \operatorname{Ker}$; to see this, consider that if there existed~$y \in \operatorname{Ker}$ violating this parity requirement, combining Lemma~\ref{lem:Edmonds} with~\eqref{eq:UsefulIntermediate} would lead to the following contradiction:
\begin{align*}
1 
&= Q_{\Sigma_d(D)}(y,Ty)
=Q_{\Sigma_d(D)}(y,z)
=\sum_{g \in \Z_d} Q_{\Sigma_d(D)}(y,gz_0) 
=\lambda_0(\pi_0(y),\pi_0(z_0)) 
 = 0 \quad  \mod 2.
 \end{align*}
 Thus $\lambda_0(\pi_0(y),\pi_0(y))$ and~$Q_{\Sigma_d(D)}(Ty,y)$ are both even.
Applying Lemma~\ref{lem:SumIsEven}, we compute that~$Q_{\Sigma_d(D)}(y,y)$ is also even,  thus concluding the proof in the even case as well.
\end{proof}

\begin{remark}
In the case of spheres in closed $4$-manifolds,  Lee-Wilczy\'nski assert that Lemma~\ref{lem:Edmonds} holds without having to assume that there exists an~$x \in H_2(\Sigma_d(D);\Z_2)$ with $Q_{\Sigma_d(D)}(x,Tx) \neq 0$; see~\cite[Equation (4.4)]{LWKtheory}.
We have not been able to confirm this assertion. 
Working in the smooth category, one might attempt to improve the sketch above~\cite[Proposition 5.1]{EdmondsAspects} to a proof of their assertion. 
For this,  one might work in the base space of the branched cover in order to overcome issues of equivariant transversality present in Edmonds' sketch. 
As we have used an alternative argument to prove Proposition~\ref{prop:EvenessCondition}, we have not attempted to complete these details (which would moreover need to be performed in the topological category, using a locally linear involution).
Finally, we note that when $Q_{\Sigma_d(D)}(z,z) \neq 0$, Lemma~\ref{lem:Edmonds} does automatically hold: in this case,~$Q_{\Sigma_d(D)}(z,Tz) \neq 0$ and so the lemma follows from~\cite[Proposition 5.1]{EdmondsAspects}.
\end{remark}




\section{Proof of the main theorem}
\label{sec:ProofMain}

We recall the main theorem for the reader's convenience.
\begin{customthm}{\ref{thm:Main}}
\label{thm:MainProof}
Let \(N\) be a compact, oriented, simply-connected $4$-manifold with boundary \(S^3\). Let $x \in H_2(N, \partial N)$ be a nonzero class of divisibility $d$, and 
suppose \(K\subset S^3\) is a knot such that~\(H_1(\Sigma_d(K))=0\). 
The following are equivalent:
\begin{itemize}
\item The knot $K$ is sliced by a simple disc in $N$ representing $x$.
\item
\begin{enumerate}
\item \label{item:1Main} $\operatorname{Arf}(K)+\ks(N)+\frac{1}{8}(\sigma(N)-x \cdot x) \equiv 0 \ \text{ mod } 2$ \ if $x$ is characteristic, and
\item\label{item:2Main}  $b_2(N)\geq \max_{0\leq j<d}|\sigma (N)-\frac{2j(d-j)}{d^2}\, x\cdot x +\sigma_K (e^{\frac{2\pi i j}{d}})|$.
\end{enumerate}
\end{itemize}
\end{customthm}
\begin{proof}
The necessity of the conditions is a consequence of Theorem~\ref{thm:StableWithBoundaryIntro} and Proposition~\ref{prop:SignatureCondition}.
We turn to the converse.
Theorem~\ref{thm:StableWithBoundaryIntro} produces an embedded disc~$D \subset N\#^k S^2 \times S^2$ with boundary~$K$ that represents the class $x \oplus 0$. 
Proposition~\ref{prop:TopSplitting} (which applies thanks to Propositions~\ref{prop:H2Free}, \ref{prop:SplitDownstairs} and~\ref{prop:EvenessCondition}) then ensures that $D$ can be upgraded to a disc in~$N$ with boundary~$K$ and representing~$x$.
\end{proof}



