\section{Intersection forms and transfers}

The goal of this section is to prove an equality that is implicit in~\cite[Proposition~3.7]{LWCommentarii}.
As we will see,  this result (namely Proposition~\ref{prop:LWIntersectionEquality}) follows fairly readily from properties of transfer homomorphisms.
However, since the literature on transfers is difficult to navigate, we instead decided to do things by hand.
%{XXX: let's keep this in -- people enjoy seeing us in pain}


\begin{notation}
We fix the following notation.
Set $G:=\Z_d$ with $d \neq 0$,  let $X$ be a simply-connected $4$-manifold whose boundary is empty or $S^3$,  let $F \subset X$ be a properly embedded surface with knot group~$\pi_1(X_F) \cong G$, and let $p \colon \Sigma(F) \to X$ be the corresponding branched cover.
Here we assume that $F$ has a boundary if and only if $X$ has a boundary.
\end{notation}



\begin{lemma}
\label{lem:TransferFundamentalClass}
The following equality holds:
$$p_*([\Sigma(F)])=|G|\cdot[X] \in H_4(X,\partial X).$$
\end{lemma} 
\begin{proof}
We claim the lemma reduces to the closed case.
Double the pair~$(X,F)$ to obtain~$(V,S)$.
As~$X$ is simply-connected and~$\pi_1(X_F)\cong G$, we obtain that~$V$ is simply-connected and~$\pi_1(V_S)\cong G$.
In particular the branched cover~$\Sigma(S)$ is simply-connected, whence~$H_3(\Sigma(S))=0$.
Consider the following commutative diagram:
$$
\xymatrix@R0.4cm{
0 \ar[r]&H_4(\Sigma(S)) \ar[r]^-{\cong}\ar[d]^{p_*}_{\cdot |G|}& {\overbrace{H_4(\Sigma(S),\Sigma(F))}^{\cong H_4(\Sigma(F),\partial\Sigma(F))}}\ar[d]^{p_*}_{} \ar[r]&0 \\
%%%%%
0 \ar[r]&H_4(V) \ar[r]^-\cong& {\underbrace{H_4(V,X)}_{\cong H_4(X,\partial X)}} \ar[r]&0. \\
}
$$
The left map is multiplication by $|G|$ because we are assuming the lemma holds in the closed case.
This concludes the proof of the claim.

We prove the lemma when $F$ and $X$ are closed.
Consider the following commutative diagram:
$$
\xymatrix@R0.4cm{
0 \ar[r]&H_4(\Sigma(F)) \ar[r]^-{\cong}\ar[d]^{p_*}& {\overbrace{H_4(\Sigma(F),\overline{\nu}(F))}^{\cong H_4(\widetilde{X}_F,\partial \widetilde{X}_F)}}\ar[d]^{p_*}_{\cdot |G|} \ar[r]&0 \\
%%%%%
0 \ar[r]&H_4(X) \ar[r]^-\cong& {\underbrace{H_4(X,\overline{\nu}(F))}_{\cong H_4(X_F,\partial X_F)}} \ar[r]&0. \\
}
$$
The right hand side map is multiplication by $|G|$ because (unbranched) regular $G$-covering projections have degree $|G|$.
\end{proof}

For the next statement, recall that $\mathcal{N} \in \Z[G]$ denotes the norm element.

\begin{proposition}
\label{prop:McGyver}
For every $y \in H_2(\Sigma(F))$, the homomorphism~$\tr:=\PD_{\Sigma(F)} \circ p^* \circ \PD_{X}^{-1}$ satisfies
$$\tr \circ p_*(y)=\mathcal{N}y \in H_2(\Sigma(F)).$$
\end{proposition}
\begin{proof}
We use
Lemma~\ref{lem:TransferFundamentalClass} to verify that~$p_* \circ \tr(\sigma)=|G|\sigma$:
\begin{align*}
p_* \circ \tr(\sigma)
&=p_*(p^*(\PD_X^{-1}(\sigma)) \cap [\Sigma(F)]) 
=\PD_X^{-1}(\sigma) \cap p_*([\Sigma(F)]) 
=\PD_X^{-1}(\sigma) \cap |G|[X] 
=|G|\sigma.
\end{align*}
Next, we observe that given $\sigma \in H_2(X),$ every $g \in G$ fixes $\tr(\sigma)$.
Indeed since deck transformations are orientation-preserving homeomorphisms,
%%True if everything is oriented (Google it) which is the case here.
 they are degree one and so
\begin{align*}
g_* \circ \tr(\sigma)
&=g_*(g^*g^{-*}p^*(\PD_X^{-1}(\sigma)) \cap [\Sigma(F)]) 
=g^{-*}p^*(\PD_X^{-1}(\sigma)) \cap g_*([\Sigma(F)]) \\
&=p^*(\PD_X^{-1}(\sigma)) \cap [\Sigma(F)] 
=\tr(\sigma).
\end{align*}
Since $H_2(\Sigma(F))$ is free abelian, it suffices to prove that $\mathcal{N}y=\tr \circ p_*(y) \in H_2(\Sigma(F);\Q)$.
%{XXX: free abelian implies the tensor-induced map (a.k.a.~the tensor map because localisation is flat) $H_2(-;\Z)\to H_2(-;\Q)$ is injective. So if they are equal in the image they are equal in the domain.}
Both elements lie in $H_2(\Sigma(F);\Q)^G$.
With rational coefficients, the projection induces an isomorphism~$p_* \colon H_2(\Sigma(F);\Q)^G \to H_2(X;\Q)$~\cite[Chapter III Theorem 7.4]{BredonTopology}.
Since we calculated that~$p_*(\mathcal{N}y)=|G|p_*(y)=p_* \circ \tr \circ p_*(y)$, we obtain~$\mathcal{N}y=\tr \circ p_*(y)$, as claimed. 
\end{proof}



\begin{proposition}
\label{prop:LWIntersectionEquality}
The following equality holds for every~$x,y\in H_2(\Sigma(F))$:
$$\sum_{g \in G} Q_{\Sigma(F)}(x,gy)= Q_{X}(p_*(x),p_*(y)).$$
\end{proposition}
\begin{proof}
Consecutively use Proposition~\ref{prop:McGyver}, the definition of  the intersection form and the properties of Poincar\'e duality to obtain
\begin{align*}
\sum_{g \in G} Q_{\Sigma(F)}(x,gy)
&=Q_{\Sigma(F)}(x,\mathcal{N}y)
=Q_{\Sigma(F)}(x,\tr \circ p_*(y)) 
=Q_{\Sigma(F)}(x, \PD_{\Sigma(F)} \circ p^* \circ \PD_{X}^{-1} \circ p_*(y)) \\
&=\langle  \PD_{\Sigma(F)}^{-1} \circ j_*(\PD_{\Sigma(F)}  \circ p^* \circ \PD_{X}^{-1} \circ p_*(y)),x\rangle 
=\langle  j^* \circ p^* \circ \PD_{X}^{-1} \circ p_*(y),x\rangle \\
&=\langle  p^* \circ \PD_{X}^{-1} \circ j_* \circ p_*(y),x\rangle 
=\langle  \PD_{X}^{-1} \circ j_*\c(p_*(y)),p_*(x)\rangle 
=Q_X(p_*(x),p_*(y)).
\end{align*}
The sixth equality is best summarised by the commutativity of the following diagram:
$$
\xymatrix@R0.5cm{
H_2(X) \ar[r]^-{\PD_X^{-1}}\ar[d]^-{j_*}&H^2(X,\partial X) \ar[r]^-{p^*}\ar[d]^{j^*}& H^2(\Sigma,\partial \Sigma)\ar[d]^-{j^*} \\
%%%%
H_2(X,\partial X) \ar[r]^-{\PD_X^{-1}}&H^2(X) \ar[r]^-{p^*}& H^2(\Sigma).
}
$$
This concludes the proof of the proposition.
\end{proof}




\section{A relative version of Bredon-Edmonds' result}

In this section, we state and prove a version of Edmonds' result~\cite[Proposition 5.1]{EdmondsAspects}. Edmonds' argument is made in the absolute case and we need a version in the case of manifolds with boundary and properly embedded surfaces.

The Edmonds result crucially uses a result of Bredon~\cite[Theorem~VII.7.4]{BredonIntroduction}, which is also only stated in an absolute version. Bredon's result has the following relative variant. The lengthy, but ultimately formal, exercise of adjusting Bredon's proof to the relative case will not be included here, and is left to the reader.

\begin{theorem}[Bredon]
\label{thm:Bredonmainrelative}
Let~$T$ be an involution on a paracompact space~$X$ and write $F$ for the fixed point set. Let~$A\subset X$ be a subspace such that $T(A)\subset A$.
Suppose~$H^i(X,A;\Z_2)=0$ for~$i>2n$ and~$T^*$ is the identity on~$H^{2n}(X,A;\Z_2)$. 
If~$a\in H^n(X,A;\Z_2)$ is such that~$a\cup T^* a\in H^{2n}(X,A;\Z_2)$ is non-zero, then~$k^*(a)\in H^n(F,F\cap A;\Z_2)$ is non-zero,  where $k \colon F \to X$ denotes the inclusion.
\end{theorem}

We now recall Edmonds' argument, with the minor adjustments for the relative case.

\begin{proposition}[Edmonds]
\label{prop:BredonRel}
Let~$T$ be an orientation-preserving involution on a connected orientable~$2n$-manifold~$X$ with non-empty boundary $A$. Suppose the fixed-point set is a proper submanifold with boundary~$(F,\partial F)\subset (X,A)$. Suppose there exists~$a\in H^n(X,A;\Z_2)$ such that~$a\cup T^* a\in H^{2n}(X,A;\Z_2)$ is non-zero. Then
\[
\langle c\cup T^*c,[X]\rangle\equiv \langle k^*(c),[F]\rangle\mod 2
\]
for all~$c\in H^n(X,A;\Z_2)$, where~$k\colon F\to X$ denotes the inclusion of the fixed-point set of~$T$.
\end{proposition}
\begin{proof}
Define two functions
%{XXX: I couldn't follow how~$k^*(c) \in H^k(F,F \cap A;\Z_2)$ is evaluated on~$[F] \in H_k(F,\partial F;\Z_2)$.
%Is it automatic that~$F \cap A=\partial F$?
%Aha, it's probably because of the assumption that ``proper submanifold with boundary~$(F,\partial F)\subset (X,A)$"}
\[
\begin{array}{rcll}
\varphi\colon H^n(X,A;\Z_2)&\to&\Z_2; \qquad\qquad&\varphi(c)=\langle c\cup T^* c,[X]\rangle\\
\psi\colon H^n(X,A;\Z_2)&\to&\Z_2; &\psi(c)=\langle k^*(c),[F]\rangle.
\end{array}
\]
%Don't delete.
%{We should say why the action is trivial on~$H^{2n}(X,A;\Z_2)$ but that's probably fine because of fundamental class stuff. XXX: yes, it's the orientation preserving condition.}
As~$T$ is orientation-preserving, it acts trivially on~$H^{2n}(X,A;\Z_2)$ and we may apply Theorem~\ref{thm:Bredonmainrelative}: if~$\varphi(c)\neq0$, then~$\psi(c)\neq 0$. 
Now, by hypothesis,~$a\cup T^* a\neq 0$, and so by Poincar\'{e} duality~$\varphi$ is not the trivial map. 
%%Don't delete
%{XXX: I was trying to understand why it was by PD. I felt like one needs $H^{2n}(X,A) \to H_{2n}(X,A)^*$ to be injective i.e.\ for $H_{2n-1}(X,A;\Z_2) \cong H^1(X,A;\Z_2))$ to be torsion free. This is true if $A$ is nonempty, so ok. }
Hence~$\psi$ is not the trivial map. 
The kernel of a surjective map to~$\Z_2$ has index 2, hence both maps vanish on exactly half the elements of~$H^n(X,A;\Z_2)$. 
But we already know that the maps agree on at least half the elements (the ones where~$\varphi(c)=1$). 
%XXX: By the theorem.
Hence they must agree on all the elements.
\end{proof}





