\section{Generalized infinite logarithm integrals in terms of finite series}
%
In this section we derive definite infinite integrals involving the product of generalized logarithm and reciprocal pochhammer symbol functions for the first formula. The second infinite integral involves the product of generalized logarithm and reciprocal polynomial function. 
%
\begin{theorem}
For all $k,b,c,v\in\mathbb{C}$ then,
\begin{multline}\label{eq:thm1}
\int_0^{\infty } \frac{x^{-1+m} \log ^k(a x)}{\left(b+c x^v\right){}_{1+n}} \, dx\\
=\sum _{j=0}^n \frac{(-1)^j
   c^{-\frac{3}{2}-\frac{m-\frac{3 v}{2}}{v}} e^{\frac{i \pi  \left(m-\frac{3 v}{2}\right)}{v}}
   (b+j)^{\frac{1}{2}+\frac{m-\frac{3 v}{2}}{v}} (2 \pi )^{1+k} \left(\frac{i}{v}\right)^{2+k} v \binom{n}{j} }{n!}\\ \times
\Phi
   \left(-e^{\frac{2 i \pi  \left(m-\frac{3 v}{2}\right)}{v}},-k,\frac{\pi -i v \log \left(a c^{-1/v}
   (b+j)^{1/v}\right)}{2 \pi }\right)
\end{multline}
where $Re(m)>0,Re(v)>0$ and there exists a singularity at $x=i/a$. If $Re(b)<0, Re(a)>0$.
\end{theorem}
\begin{proof}
The right-hand sides of relations (\ref{eq:poch_1}) and (\ref{eq:poch_2}) are identical, relative to equation (\ref{eq:prelim_1}); hence, the left-hand sides of the same are identical too. Simplifying with the Pochhammer function in [Wolfram, \href{https://mathworld.wolfram.com/PochhammerSymbol.html}{1}] yields the desired conclusion.
\end{proof}
%
\begin{theorem}
For all $k,b,c,v\in\mathbb{C}$ then,
\begin{multline}\label{eq:thm2}
\int_0^{\infty } \frac{x^{-1+m} \log ^k(a x)}{\left(1+b x^v\right)^{n+1}} \, dx\\
=\sum _{j=0}^n \sum _{l=0}^j
   \frac{(1+k-l)_l (-1)^{-j} b^{-\frac{m}{v}} e^{\frac{i \pi  \left(m-\left(\frac{1}{2}+n\right) v\right)}{v}} (2 \pi
   )^{1+k-l} \left(1-\frac{m}{v}\right)^{j-l} \left(-\frac{1}{v}\right)^l \left(\frac{i}{v}\right)^{k-l} \binom{j}{l}
   }{v n!}\\ \times
\Phi \left(e^{\frac{2 i \pi  (m-n v)}{v}},-k+l,\frac{\pi -i v \log \left(a b^{-1/v}\right)}{2 \pi }\right)
   S_n^{(j)}
\end{multline}
when $Re(b)<0$, then there exists a singularity at $x=i/a$.
\end{theorem}
\begin{proof}
The right-hand sides of relations (\ref{eq:poly_1}) and (\ref{eq:poly_2}) are identical, relative to equation (\ref{eq:prelim_2}); hence, the left-hand sides of the same are identical too. Simplifying with the Pochhammer function in [Wolfram, \href{https://mathworld.wolfram.com/PochhammerSymbol.html}{1}] yields the desired conclusion.
\end{proof}
%
