            2(2n)!\left(\frac{2}{\alpha}\right)^{2n+1}\sum\limits_{v=0}^{\infty}\binom{-m}{v}\frac{1}{(m+2v)^{2n+1}}, & \text{otherwise}
		 \end{cases}
\end{multline}
where $Re(\alpha)>0,0 < m < 2n+2, n=0,1,2,..,$, and there exists a singularity at $x=1$.
\end{example}
