\section{Model}

\subsection{Single firm model}
In this section, we analyze the model of decarbonation in the situation where a single firm would control the 2 technologies $X^1$ and $X^2$, the dynamic of each technology $i=1,2$ is given by
\begin{align*}
    &dX_t^i=a_t^idt+\sigma_idW_t^i
\end{align*}
with two independent Brownian motion $W^1,W^2$. 
The cost for Firm is given by
\begin{align*}
    &c(a)=\frac{1}{2}\frac{a_1^2}{\gamma_1}+\frac{1}{2}\frac{a_2^2}{\gamma_2}
\end{align*}
The objective for the firm with is to maximize its expected utility by choosing its control strategy $a=(a^1,a^2)$
\begin{align*}
    &J_A=E[U_A(Y_T-\int_0^T (f(X_t)-c(a_t))dt)]\\
    &f(x)=(p_0-p_1x_1+p_2x_2)(x_1+x_2)
\end{align*}
The objective for the principal is to maximize its expected utility .
\begin{align*}
    &J_p=E[U_p(-Y_T-\int_0^T g(X_t)dt)]\\
    &dY_t=Z^1_tdX^1_t+Z^2_tdX^2_t+\frac{1}{2}\eta_A(\sigma_1^2(Z^1_t)^2+\sigma_2^2(Z^2_t)^2)dt-H_A(Z_t,X_t)dt\\
    &H_A(Z,X)=\hat{a}_1(Z_1)(Z_1)+\hat{a}_2(Z_2)Z_2-c(\hat{a}(Z))+f(X)\\
    &g(X)=\frac{1}{2}\kappa (X^1)^2+\lambda (X^1+X^2-\delta)^2\\
    &\hat{a}_1(z_1)=\gamma_1 z_1,\hat{a}_2(z_2)=\gamma_2 z_2
\end{align*}
We assume that there is no interaction between $a_1$ and $a_2$, so the Principal's optimal control problem becomes:
\begin{align*}
    &V(0,x,y)=\sup_Z E[U_p(-Y_T -\int_0^Tg(X_t)dt)]\\
    &dY_t=\sigma^1dW_t^1+\sigma^2dW_t^2+\frac{1}{2}\eta_A(\sigma_1^2(Z^1_t)^2+\sigma_2^2(Z^2_t)^2)dt+c(\hat{a}(Z_t))dt-f(X_t)dt\\
\end{align*}
\subsection{Two firms model}

\begin{align*}
&\dd X^i_t = a^i_t \dd t + \sigma_i \dd W^i_t, \quad 
J_i := \E\Big[ U_i \Big( Y^i_T  + \int_0^T f_i(X_t) - c_i(a^i_t) \big) \dd t \Big)\Big], \quad
f_i(x) := (p_0 - p_i x_i - p_j x_j), \quad c_i(a) := \frac1{2\gamma_i} a^2, \\
& J_{\rm P} := \E\Big[ U_i \Big( - Y_T  - \int_0^T g(X_t) \big) \dd t \Big)\Big], \quad
Y_T := Y^1_T + Y^2_T, \quad
g(x) := \frac12 \kappa x_2^2 + \frac12 \lambda (x_1+x_2-\delta)^2, \\
& \dd Y^i_t = Z^{i,i}_t \dd X^i_t + Z^{i,j}_t \dd X^j_t + \frac12 \eta_i\big[ \sigma_i^2 (Z^{i,i}_t)^2 + \sigma_j^2 (Z^{i,j}_t)^2\big] \dd t
- H_i(Z_t,X_t) \dd t, \\
& H_i(z,x) := \hat a_i(z_{ii}) z_{ii} - c_i(\hat a_i(z_{ii})) + \hat a_j(z_{jj}) z_{ij} + f_i(x)
\end{align*}
From which we can write
\begin{align*}
& \dd Y^i_t =  \big[c_i(\hat a_i(Z^{ii}_t)) - f_i(X_t) + \frac12 \eta_i\big( \sigma_i^2 (Z^{ii}_t)^2 + \sigma_j^2 (Z^{i,j}_t)^2\big)\big]
+ \sigma_i Z^{ii}_t  \dd W^i_t + \sigma_j Z^{i,j}_t \dd W^j_t
\end{align*}
And thus for the sum of the payments $Y$ we get
\begin{align*}
& \dd Y_t =  \big[c(\hat a(Z_t)) - f(X_t) +  R(Z_t) \big)\big] + \hat \sigma_1(Z_t)  \dd W^1_t + \hat \sigma_2(Z_t) \dd W^2_t, \\
& c(\hat a(z)) := c_1(\hat a_1(z_{11})) +  c_2(\hat a_2(z_{22})) = \frac12\big( \gamma_1 z_{11}^2 + \gamma_2 z_{22}^2\big), \\
& f(x) := f_1(x) + f_2(x) = (p_0 - p_1 x_1 - p_2 x_2) (x_1 + x_2), \\
& R(z) := \frac12 \big( \eta_1 \sigma_1^2 z_{11}^2 +\eta_1 \sigma_2^2 z_{12}^2 + \eta_2 \sigma_2^2 z_{22}^2 + \eta_2 \sigma_1^2 z_{21}^2\big), \\
& \hat \sigma_1(z) := (z_{11} + z_{21})\sigma_1, \quad 
\hat \sigma_2(z) := (z_{22} + z_{12})\sigma_2
\end{align*}
Hence, the problem of the regulator reads
\begin{align*}
&V(0,x,y) := \sup_{z} \E\Big[ U_{\rm P}\Big(-Y_T - \int_0^T g(X_t) \dd t\Big) \Big], \\
& \dd X^i_t = \hat a_i(Z^{ii}_t) \dd t + \sigma_i \dd W^i_t, \quad \hat a_i(z) := \gamma_i z_{ii}, \\
& \dd Y_t =  \big[c(\hat a(Z_t)) - f(X_t) +  R(Z_t) \big)\big] + \hat \sigma_1(Z_t)  \dd W^1_t + \hat \sigma_2(Z_t) \dd W^2_t, \\
\end{align*}

\subsection{Firms equilibrium without incentives}
In this section, we analyze the strategic interaction between two competing firms prior to any external intervention (e.g., by a regulator or principal). The goal is to determine the Nash equilibrium of the differential game modeling their behavior. We assume no external incentives are present, meaning each firm solely seeks to maximize its own expected utility based on its costs.\\

\noindent
Components of our model:
\begin{itemize}
    \item Players: Two firms, Firm 1 and Firm 2.
    \item State Variables:
        \begin{itemize}
            \item $X_t$: Represents the state of Firm 1 carbon emission rate at time $t$.
            \item $Y_t$: Represents the state of Firm 2 carbon emission rate at time $t$.
        \end{itemize}
    \item Strategies:
        \begin{itemize}
            \item $a^1_t$: Firm 1's abatement effort at time $t$.
            \item $a^2_t$: Firm 2's abatement effort at time $t$.
        \end{itemize}
    \item Dynamics:
        \begin{align*}
            \dd X_t &= a^1_t \, dt + \sigma_1 \, dW^1_t, \quad X_0 = x_0, \\
            \dd Y_t &= a^2_t \, dt + \sigma_2 \, dW^2_t, \quad Y_0 = y_0.
        \end{align*}
        $\sigma_i > 0$ are constant, $W^1_t, W^2_t$ independant Brownian motions.

    \item Cost of Action: The cost for Firm $i$ to exert effort $a^i_t$ is given by :
        \begin{itemize}
            \item Firm 1's cost: $c_1(a^1_t) = \frac{1}{2\gamma_1} (a^1_t)^2$
            \item Firm 2's cost: $c_2(a^2_t) = \frac{1}{2\gamma_2} (a^2_t)^2$
        \end{itemize}
        where $\gamma_1 > \gamma_2 > 0$.

    \item Payoff: The instantaneous net payoff for each firm at time $t$ depends on both firms' emission rates and the firm's own action cost. 
    \begin{itemize}
        \item Firm 1: $\pi_1(X_t, Y_t, a^1_t) = (p_0 - p_1 X_t - p_2 Y_t) X_t - \frac{1}{2\gamma_1} (a^1_t)^2$ 
        \item Firm 2: $\pi_2(X_t, Y_t, a^2_t) = (p_0 - p_1 X_t - p_2 Y_t) Y_t - \frac{1}{2\gamma_2} (a^2_t)^2$
    \end{itemize}

        where $p_0, p_1, p_2$ are positive constants.

    \item Utility Functions: Firms are assumed to have risk aversion utility functions over their total accumulated payoff:
        \begin{itemize}
            \item Firm 1: $U_1(Z) = -\exp(-\eta_1 Z)$
            \item Firm 2: $U_2(Z) = -\exp(-\eta_2 Z)$
        \end{itemize}
        where $Z = \int_0^T \pi_i(X_t, Y_t, a^i_t) dt$ is the total payoff over the horizon $[0, T]$, and $\eta_1, \eta_2 > 0$.
    \item Objective: Each firm aims to maximize its expected utility by choosing its control strategy $a^i = \{a^i_t\}_{t \in [0,T]}$. The value functions representing the maximum achievable expected utility are:
        \begin{align*}
            V_1(0,x,y) &:= \sup_{a^1} \mathbb{E}\left[ -\exp\left(-\eta_1 \int_0^T \left( \left(p_0 - p_1 X_t - p_2 Y_t\right) X_t - \frac{1}{2\gamma_1} (a^1_t)^2 \right) dt \right) \;\middle|\; X_0=x, Y_0=y \right], \\
            V_2(0,x,y) &:= \sup_{a^2} \mathbb{E}\left[ -\exp\left(-\eta_2 \int_0^T \left( \left(p_0 - p_1 X_t - p_2 Y_t\right) Y_t - \frac{1}{2\gamma_2} (a^2_t)^2 \right) dt \right) \;\middle|\; X_0=x, Y_0=y \right].
        \end{align*}

\end{itemize}



% Definition of Nash Equilibrium
We seek a Nash Equilibrium in feedback strategies, denoted by a pair $(\hat a^1, \hat a^2)$. This pair constitutes an equilibrium if neither firm can improve its expected utility by unilaterally deviating from its equilibrium strategy, given that the other firm adheres to its equilibrium strategy. Formally, if such a pair exists, it must satisfy the following conditions for all alternative admissible strategies $a^1, a^2$:
\begin{align*}
    % Condition for Firm 1
    &\mathbb{E}\left[ U_1 \left( \int_0^T \pi_1(X_t, \hat Y_t, a^1_t) dt \right) \right]
    \leq \mathbb{E}\left[ U_1 \left( \int_0^T \pi_1(\hat X_t, \hat Y_t, \hat a^1_t) dt \right) \right], \\
    % Condition for Firm 2
    &\mathbb{E}\left[ U_2 \left( \int_0^T \pi_2(\hat X_t, Y_t, a^2_t) dt \right) \right]
    \leq \mathbb{E}\left[ U_2 \left( \int_0^T \pi_2(\hat X_t, \hat Y_t, \hat a^2_t) dt \right) \right].
\end{align*}
These expectations are evaluated considering the relevant state dynamics:
\begin{align*}
    \dd X_t &= a^1_t \, dt + \sigma_1 \, dW^1_t, \quad &&X_0 = x_0, \\
    \dd \hat X_t &= \hat a^1_t \, dt + \sigma_1 \, dW^1_t, \quad &&\hat X_0 = x_0, \\
    \dd Y_t &= a^2_t \, dt + \sigma_2 \, dW^2_t, \quad &&Y_0 = y_0, \\
    \dd \hat Y_t &= \hat a^2_t \, dt + \sigma_2 \, dW^2_t, \quad &&\hat Y_0 = y_0.
\end{align*}








