\subsection{Firm equilibrium without incentives}


We begin by analyzing the optimal strategy for one firm when the other firm's strategy is assumed to be a known, deterministic function of time. This corresponds to solving a standard stochastic control problem for the optimizing firm.

\begin{Proposition}[Optimal Strategy against Deterministic Competitor] \label{prop:best_response}
~ % Adds a small vertical space
\begin{enumerate}
    \item Given a deterministic strategy $(a^2_t)_{t \in [0,T]}$ for Firm 2, the optimal strategy for Firm 1 is given by:
    \begin{align*}
        a^{1,\star}_t =  -\frac{\gamma_1\partial_x v_1}{\eta_1 v_1} 
    \end{align*}
    where the associated value function has the form:
    \begin{align*}
        v_1(t,x,y) = -\exp\left( \eta_1 W_1(t, x, y) \right)
    \end{align*}
    with $W_1(t,x,y)$ being the quadratic function:
    \[
        W_1(t, x, y) = \frac{1}{2} A(t) x^2 + \frac{1}{2} B(t) y^2 + C(t) xy + D(t) x + E(t) y + F(t)
    \]
    The coefficient functions $A(t), \dots, F(t)$ satisfy the following system of ODEs :
    \begin{equation}\label{eq:ode_system_best_response_1}
    \begin{cases}
        A' + \sigma_1^2 \eta_1 A^2 + \sigma_2^2 \eta_1 C^2 - 2p_1 - \gamma_1 A^2 = 0 \\%[1ex] % Removed coupling term
        B' + \sigma_1^2 \eta_1 C^2 + \sigma_2^2 \eta_1 B^2 - \gamma_1 C^2 = 0 \\%[1ex] % Removed coupling term
        C' + \sigma_1^2 \eta_1 AC + \sigma_2^2 \eta_1 BC - p_2 - \gamma_1 AC = 0 \\%[1ex] % Removed coupling term
        D' + \sigma_1^2 \eta_1 AD + \sigma_2^2 \eta_1 CE + a^2(t) C - \gamma_1 AD = 0 \\[1ex]
        E' + \sigma_1^2 \eta_1 CD + \sigma_2^2 \eta_1 BE + a^2(t) B - \gamma_1 CD = 0 \\[1ex]
        F' + \frac{1}{2} \sigma_1^2 (\eta_1 D^2 + A) + \frac{1}{2} \sigma_2^2 (\eta_1 E^2 + B) + a^2(t) E + p_0 - \frac{1}{2} \gamma_1 D^2 = 0
    \end{cases}
    \end{equation}
    subject to the terminal conditions $A(T) = B(T) = C(T) = D(T) = E(T) = F(T) = 0$.

    \item Similarly, given a deterministic strategy $(a^1_t)_{t \in [0,T]}$ for Firm 1, the optimal strategy for Firm 2 is given by:
    \begin{align*}
        a^{2,\star}_t = -\frac{\gamma_2\partial_y v_2}{\eta_2 v_2} 
    \end{align*}
    where the associated value function has the form:
    \begin{align*}
        v_2(t,x,y) = -\exp\left( \eta_2 W_2(t, x, y) \right)
    \end{align*}
    with $W_2(t,x,y)$ being the quadratic function:
    \[
        W_2(t, x, y) = \frac{1}{2} \tilde{A}(t) x^2 + \frac{1}{2} \tilde{B}(t) y^2 + \tilde{C}(t) xy + \tilde{D}(t) x + \tilde{E}(t) y + \tilde{F}(t)
    \]
    The coefficient functions $\tilde{A}(t), \dots, \tilde{F}(t)$ satisfy the following system of ODEs :
     \begin{equation}\label{eq:ode_system_best_response_2}
    \begin{cases}
        \tilde{A}' + \sigma_1^2 \eta_2 \tilde{A}^2 + \sigma_2^2 \eta_2 \tilde{C}^2 - \gamma_2 \tilde{C}^2 = 0 \\%[1ex] % Removed coupling term
        \tilde{B}' + \sigma_1^2 \eta_2 \tilde{C}^2 + \sigma_2^2 \eta_2 \tilde{B}^2 - 2p_2 - \gamma_2 \tilde{B}^2 = 0 \\%[1ex] % Removed coupling term
        \tilde{C}' + \sigma_1^2 \eta_2 \tilde{A}\tilde{C} + \sigma_2^2 \eta_2 \tilde{B}\tilde{C} - p_1 - \gamma_2 \tilde{B}\tilde{C} = 0 \\%[1ex] % Removed coupling term
        \tilde{D}' + \sigma_1^2 \eta_2 \tilde{A}\tilde{D} + \sigma_2^2 \eta_2 \tilde{C}\tilde{E} + a^1(t) \tilde{A} - \gamma_2 \tilde{C}\tilde{E} = 0 \\[1ex]
        \tilde{E}' + \sigma_1^2 \eta_2 \tilde{C}\tilde{D} + \sigma_2^2 \eta_2 \tilde{B}\tilde{E} + a^1(t) \tilde{C} - \gamma_2 \tilde{B}\tilde{E} = 0 \\[1ex]
        \tilde{F}' + \frac{1}{2} \sigma_1^2 (\eta_2 \tilde{D}^2 + \tilde{A}) + \frac{1}{2} \sigma_2^2 (\eta_2 \tilde{E}^2 + \tilde{B}) + a^1(t) \tilde{D} + p_0 - \frac{1}{2} \gamma_2 \tilde{E}^2 = 0
    \end{cases}
    \end{equation}
    subject to the terminal conditions $\tilde{A}(T) = \tilde{B}(T) = \tilde{C}(T) = \tilde{D}(T) = \tilde{E}(T) = \tilde{F}(T) = 0$.
\end{enumerate}
\end{Proposition}

