\paragraph{Nash Equilibrium Analysis}

The more complex scenario involves finding the Nash equilibrium, where both firms simultaneously choose their optimal strategies, taking the other's optimal strategy into account. This leads to a coupled system where each firm's optimization depends on the outcome of the other's.

\begin{Proposition}[Nash Equilibrium Characterization] \label{prop:nash_equilibrium}
If a Nash equilibrium $(\hat a^1, \hat a^2)$ exists then:
\begin{enumerate}
    \item The equilibrium strategies are given by:
    \begin{align*}
        \hat a^{1}_t = -\frac{\gamma_1\partial_x \hat v_1}{\eta_1 \hat v_1} \\
        \hat a^{2}_t = -\frac{\gamma_2\partial_y \hat v_2}{\eta_2 \hat v_2}
    \end{align*}
    \item The associated value functions are:
    \begin{align*}
        \hat v_1(t,x,y) &= -\exp\left( \eta_1 W_1(t, x, y) \right)\\
        \hat v_2(t,x,y) &= -\exp\left( \eta_2 W_2(t, x, y) \right)
    \end{align*}
    where $W_1$ and $W_2$ are the quadratic functions defined previously.
    \item The coefficients $(A(t), \dots, F(t))$ and $(\tilde{A}(t), \dots, \tilde{F}(t))$ satisfy the following coupled system of 12 ODEs:
\end{enumerate}
\end{Proposition}


\begin{equation}\label{eq:ode_system_nash_1}
\begin{cases}
A' + \sigma_1^2 \eta_1 A^2 + \sigma_2^2 \eta_1 C^2 - 2\gamma_2 \tilde{C} C - 2p_1 - \gamma_1 A^2 = 0 \\[1ex]
B' + \sigma_1^2 \eta_1 C^2 + \sigma_2^2 \eta_1 B^2 - 2\gamma_2 \tilde{B} B - \gamma_1 C^2 = 0 \\[1ex]
C' + \sigma_1^2 \eta_1 AC + \sigma_2^2 \eta_1 BC - \gamma_2 (\tilde{B}C + \tilde{C}B) - p_2 - \gamma_1 AC = 0 \\[1ex]
D' + \sigma_1^2 \eta_1 AD + \sigma_2^2 \eta_1 CE - \gamma_2 (\tilde{C}E + \tilde{E}C) - \gamma_1 AD = 0 \\[1ex]
E' + \sigma_1^2 \eta_1 CD + \sigma_2^2 \eta_1 BE - \gamma_2 (\tilde{B}E + \tilde{E}B) - \gamma_1 CD = 0 \\[1ex]
F' + \frac{1}{2} \sigma_1^2 (\eta_1 D^2 + A) + \frac{1}{2} \sigma_2^2 (\eta_1 E^2 + B) - \gamma_2 \tilde{E} E + p_0 - \frac{1}{2} \gamma_1 D^2 = 0
\end{cases}
\end{equation}


% System 2 (Tilde A..F)

\begin{equation}\label{eq:ode_system_nash_2}
\begin{cases}
\tilde{A}' + \sigma_1^2 \eta_2 \tilde{A}^2 + \sigma_2^2 \eta_2 \tilde{C}^2 - 2\gamma_1 A \tilde{A} - \gamma_2 \tilde{C}^2 = 0 \\[1ex]
\tilde{B}' + \sigma_1^2 \eta_2 \tilde{C}^2 + \sigma_2^2 \eta_2 \tilde{B}^2 - 2\gamma_1 C \tilde{C} - 2p_2 - \gamma_2 \tilde{B}^2 = 0 \\[1ex]
\tilde{C}' + \sigma_1^2 \eta_2 \tilde{A}\tilde{C} + \sigma_2^2 \eta_2 \tilde{B}\tilde{C} - \gamma_1 (A\tilde{C} + C\tilde{A}) - p_1 - \gamma_2 \tilde{B}\tilde{C} = 0 \\[1ex]
\tilde{D}' + \sigma_1^2 \eta_2 \tilde{A}\tilde{D} + \sigma_2^2 \eta_2 \tilde{C}\tilde{E} - \gamma_1 (A\tilde{D} + D\tilde{A}) - \gamma_2 \tilde{C}\tilde{E} = 0 \\[1ex]
\tilde{E}' + \sigma_1^2 \eta_2 \tilde{C}\tilde{D} + \sigma_2^2 \eta_2 \tilde{B}\tilde{E} - \gamma_1 (C\tilde{D} + D\tilde{C}) - \gamma_2 \tilde{B}\tilde{E} = 0 \\[1ex]
\tilde{F}' + \frac{1}{2} \sigma_1^2 (\eta_2 \tilde{D}^2 + \tilde{A}) + \frac{1}{2} \sigma_2^2 (\eta_2 \tilde{E}^2 + \tilde{B}) - \gamma_1 D\tilde{D} + p_0 - \frac{1}{2} \gamma_2 \tilde{E}^2 = 0
\end{cases}
\end{equation}


Both systems must be solved subject to the terminal conditions at $t=T$:
\begin{gather*}
A(T) = B(T) = C(T) = D(T) = E(T) = F(T) = 0 \\
\tilde{A}(T) = \tilde{B}(T) = \tilde{C}(T) = \tilde{D}(T) = \tilde{E}(T) = \tilde{F}(T) = 0
\end{gather*}

