Now, let's consider that $V(t,x,y)=U_p(v(t,x)-y)$, we obtain
\begin{align*}
    &\partial_t V =-\eta_p V\partial_t v, \, V_1 = -\eta_p V v_1, \, V_2 = -\eta_p V v_2, \, V_y = \eta_p V, \\
& V_{ii} = \eta_p^2 v_i^2V- \eta_p V v_{ii}, \, V_{yy} = \eta_p^2 V, \, V_{iy} = - \eta_p^2 V v_i,i=1,2.
\end{align*}
After that we get
\begin{align*}
    &0=\partial_t v+\frac{1}{2}\sigma_1^2(v_{11}-\eta_p v_1^2)+\frac{1}{2}\sigma_2^2(v_{22}-\eta_pv_2^2)+f(x)-g(x)+\sup_z h(z,x,Dv)\\
    &v(T,x)=0\\
&h(z,x,Dv)=\gamma_1 z_1v_1+\gamma_2z_2v_2 +\sigma_1^2z_1\eta_p v_1+\sigma_2^2z_2\eta_pv_2-\frac{1}{2}(\sigma_1^2z_1^2+\sigma_2^2z_2^2)\eta_p-c(\hat{a}(z))-\frac{1}{2}\eta_A(\sigma_1^2z_1^2+\sigma_2^2z_2^2)
\end{align*}
Then with $c(a)=\frac{1}{2}\frac{a_1^2}{\gamma_1}+\frac{1}{2}\frac{a_2^2}{\gamma_2}$, we have
\begin{align*}
    h(z,x,Dv)&=\gamma_1 z_1v_1+\gamma_2z_2v_2 +\sigma_1^2z_1\eta_p v_1+\sigma_2^2z_2\eta_pv_2-\frac{1}{2}(\sigma_1^2z_1^2+\sigma_2^2z_2^2)\eta_p-\frac{1}{2}\gamma_1 z_1^2-\frac{1}{2}\gamma_2 z_2^2-\frac{1}{2}\eta_A(\sigma_1^2z_1^2+\sigma_2^2z_2^2)\\
    &=(\gamma_1v_1+\sigma_1^2\eta_pv_1)z_1-\frac{1}{2}(\sigma_1^2\eta_p+\gamma_1+\eta_A\sigma_1^2)z_1^2\\
    &+(\gamma_2v_2+\sigma_2^2\eta_pv_2)z_2-\frac{1}{2}(\sigma_2^2\eta_p+\gamma_2+\eta_A\sigma_2^2)z_2^2
\end{align*}
Hence the optimal value of $z_1^*$ and $z_2^*$ are
\begin{align*}
    &z_1^*=\frac{\gamma_1v_1+\sigma_1^2\eta_pv_1}{\sigma_1^2\eta_p+\gamma_1+\eta_A\sigma_1^2}\\
    &z_2^*=\frac{\gamma_2v_2+\sigma_2^2\eta_pv_2}{\sigma_2^2\eta_p+\gamma_2+\eta_A\sigma_2^2}
\end{align*}
Finally the PDE of $v$ becomes
\begin{align*}
    &0=\partial_t v +f(x)-g(x) \\
    &+\frac{1}{2}\sigma_1^2v_{11}+(\frac{(\gamma_1+\sigma_1^2\eta_p)^2}{\sigma_1^2\eta_p+\gamma_1+\eta_A\sigma_1^2}-\frac{1}{2}\eta_p)v_1^2\\
    &+\frac{1}{2}\sigma_2^2v_{22}+(\frac{(\gamma_2+\sigma_2^2\eta_p)^2}{\sigma_2^2\eta_p+\gamma_2+\eta_A\sigma_2^2}-\frac{1}{2}\eta_p)v_2^2\\
    &0=v(T,x)
\end{align*}
As we have seen in class, this PDE has the following form
\begin{align*}
    &0=Lx+\frac{1}{2}x\cdot Qx +\partial_t v +\frac{1}{2}Tr(\Sigma\Sigma^TD^2v)+\frac{1}{2}Dv\cdot M Dv\\
    &0=v(T,x)
\end{align*}
Assume that $v(t,x)=\frac{1}{2}x\cdot Ax+Bx+C$. Where $A$ is symmetric and depends on time, $B$ and $C$ depends on time. Then, $Dv=Ax+B$ and $Dv\cdot M Dv=(Ax+B)\cdot (MAx+MB)$ and a system of ODE
\begin{align*}
    &0=Q+\frac{1}{2}\dot{A}+\frac{1}{2}AMA\\
    &0=A(T)\\
    &0=L+\dot{B}+AMB\\
    &0=B(T)
\end{align*}
\section{Two firms model}

The PDE satisfied by $V$ is given by
\begin{align*}
&0 = \partial_t V + \frac12 \sigma_1^2 V_{11} + \frac12 \sigma_2^2 V_{22} - f(x) V_y +\eta_p g(x) V
+  \sup_{z} \tilde h(z,x,Dv), \quad V(T,x,y) = U_{\rm P}(-y), \\
& \tilde h(z,x,Dv) := \gamma_1 z_{11} V_1 + \gamma_2 z_{22} V_2 + \big[c(\hat a(z)) + R(z)\big] V_y 
+ \frac12 \big(\hat\sigma_1^2(z) + \hat\sigma_2^2(z)\big) V_{yy}
+ \sigma_1 \hat\sigma_1(z) V_{1y} + \sigma_2 \hat\sigma_2(z) V_{2y} 
\end{align*}
Now, consider $V(t,x,y) := U_{\rm P}(v(t,x)- y)$, we have
\begin{align*}
&\partial_t V = -\eta_p V  \partial_t v, \, V_1 = -\eta_p V v_1, \, V_2 = -\eta_p V v_2, \, V_y = \eta_p V, \\
& V_{ii} = -\eta_p V(v_{ii} - \eta_p v_i^2), \, V_{yy} = \eta_p^2 V, \, V_{iy} = - \eta_p^2 V v_i.
\end{align*}
Noting that $-\eta_p V>0$, we have
\begin{align*}
&0 = \partial_t v + \frac12 \sigma_1^2 (v_{11}-\eta_p v_1^2) + \frac12 \sigma_2^2 (v_{22}-\eta_p v_2^2) + f(x) -  g(x) +  \sup_{z} h(z,x,Dv), \quad v(T,x) = 0, \\
& h(z,x,Dv) := \gamma_1 z_{11} v_1 + \gamma_2 z_{22} v_2 - \big[c(\hat a(z)) + R(z)\big]  
- \frac12 \eta_p \big(\hat\sigma_1^2(z) + \hat\sigma_2^2(z)\big)  
+ \sigma_1 \eta_p \hat\sigma_1(z) v_1 
+ \sigma_2 \eta_p \hat\sigma_2(z) v_2 
\end{align*}
Now focus on $h$
\begin{align*}
 h(z,x,Dv) & = \gamma_1 z_{11} v_1 + \gamma_2 z_{22} v_2 
 - \frac12 \big[ \gamma_1 z_{11}^2 + \gamma_2 z_{22}^2  + 
  \eta_1 \sigma_1^2 z_{11}^2 + \eta_1 \sigma_2^2 z_{12}^2 + \eta_2 \sigma_2^2 z_{22}^2 + \eta_2 \sigma_1^2 z_{21}^2\big]  \\
& - \frac12 \eta_p \big(\sigma_1^2(z_{11}+z_{21})^2 + \sigma_2^2(z_{22}+z_{12})^2\big)  
+  \eta_p \sigma_1^2(z_{11}+z_{21}) v_1 
+  \eta_p  \sigma_2^2(z_{22}+z_{12}) v_2, \\
& = 
(\gamma_1+\eta_p\sigma_1^2) v_1 z_{11} 
+ (\gamma_2+\eta_p\sigma_2^2) v_2 z_{22} 
- \frac12\big[ (\gamma_1+(\eta_p+\eta_1)\sigma_1^2) z_{11}^2  + (\gamma_2+(\eta_p + \eta_2)\sigma_2^2) z_{22}^2\big] \\
& -\frac12 (\eta_1+\eta_p) \sigma_2^2 z_{12}^2 -\frac12 (\eta_2+\eta_p) \sigma_1^2 z_{21}^2 
- \eta_p \sigma_1^2 z_{11} z_{21} - \eta_p \sigma_2^2 z_{22} z_{12}
+ \eta_p \sigma_2^2 v_2 z_{12}
+ \eta_p \sigma_1^2 v_1 z_{21}, \\
& =
(\gamma_1+\eta_p\sigma_1^2) v_1 z_{11} 
+ (\gamma_2+\eta_p\sigma_2^2) v_2 z_{22} 
- \frac12\big[ (\gamma_1+(\eta_p+\eta_1)\sigma_1^2) z_{11}^2  + (\gamma_2+(\eta_p + \eta_2)\sigma_2^2) z_{22}^2\big] \\
& -\frac12 (\eta_1+\eta_p) \sigma_2^2 \Big[ z_{12}
+ \frac{\eta_p}{\eta_1+\eta_p}(z_{22}-v_2)\Big]^2 
+ \frac12 \frac{\eta_p^2  \sigma_2^2}{\eta_1+\eta_p} (z_{22}-v_2)^2 \\
& -\frac12 (\eta_2+\eta_p) \sigma_1^2 \Big[z_{21}
+ \frac{\eta_p}{\eta_2+\eta_p}(z_{11}-v_1)\Big]^2 
+ \frac12 \frac{\eta_p^2\sigma_1^2 }{\eta_2+\eta_p}  (z_{11}-v_1)^2, \\
\end{align*}
Hence $z_{12} = \eta_{1p} (v_2 - z_{22})$ and $z_{21} = \eta_{2p}(v_1 - z_{11})$, with $\eta_{ip} := \frac{\eta_p}{\eta_i+\eta_p}$, and we are left with
\begin{align*}
 h(z,x,Dv) & = 
 \Big[ \gamma_1 + \Big(1  - \frac{\eta_p}{\eta_2+\eta_p}\Big) \eta_p \sigma_1^2 \Big] v_1 z_{11}
- \frac12 \Big[ \gamma_1+\Big\{ (\eta_p+\eta_1) - \frac{\eta_p^2}{\eta_2+\eta_p}\Big\} \sigma_1^2 \Big] z_{11}^2\\
 & 
+ 
 \Big[ \gamma_2 + \Big(1  - \frac{\eta_p}{\eta_1+\eta_p}\Big) \eta_p \sigma_2^2 \Big] v_2 z_{22} 
- \frac12 \Big[ \gamma_2+\Big\{ (\eta_p+\eta_2) - \frac{\eta_p^2}{\eta_1+\eta_p}\Big\} \sigma_2^2 \Big] z_{22}^2\\
& 
+ \frac12 \frac{\eta_p^2  \sigma_1^2}{\eta_2+\eta_p} v_1^2
+  \frac12 \frac{\eta_p^2  \sigma_2^2}{\eta_1+\eta_p} v_2^2 
\end{align*}
Hence with $\bar\eta_i := \frac{\eta_p\eta_i}{\eta_p+\eta_i}$, 
\begin{align*}
 h(z,x,Dv) & = 
 \Big[ \gamma_1 +  \bar\eta_2 \sigma_1^2 \Big] v_1 z_{11}
- \frac12 \Big[ \gamma_1+ (\bar\eta_2+\eta_1)\sigma_1^2 \Big] z_{11}^2
 + 
 \Big[ \gamma_2 +  \bar\eta_1 \sigma_2^2 \Big] v_2 z_{22} 
- \frac12 \Big[ \gamma_2+ (\bar\eta_1+\eta_2)\sigma_2^2 \Big] z_{22}^2\\
& 
+ \frac12 \frac{\eta_p^2  \sigma_1^2}{\eta_2+\eta_p} v_1^2
+ \frac12 \frac{\eta_p^2  \sigma_2^2}{\eta_1+\eta_p} v_2^2 \\
 = &
- \frac12 \Big[ \gamma_1+ (\bar\eta_2+\eta_1)\sigma_1^2 \Big]
 \Big( z_{11} - \frac{\gamma_1 + \bar\eta_2\sigma_1^2}{\gamma_1 + (\eta_1+\bar\eta_2)\sigma_1 ^2} v_1\Big)^2 
 + \frac12 \Big[\frac{(\gamma_1 + \bar\eta_2\sigma_1^2)^2}{\gamma_1 + (\eta_1+\bar\eta_2)\sigma_1 ^2} + \frac{\eta_p^2  \sigma_1^2}{\eta_2+\eta_p} \Big]v_1^2 \\
&- \frac12 \Big[ \gamma_2 + (\bar\eta_1+\eta_2)\sigma_2^2 \Big]
 \Big( z_{22} - \frac{\gamma_2 + \bar\eta_1\sigma_2^2}{\gamma_2 + (\eta_2+\bar\eta_1)\sigma_2^2} v_2\Big)^2 
 + \frac12 \Big[\frac{(\gamma_2 + \bar\eta_1\sigma_2^2)^2}{\gamma_2 + (\eta_2+\bar\eta_1)\sigma_2^2} + \frac{\eta_p^2  \sigma_2^2}{\eta_1+\eta_p} \Big]v_2^2
\end{align*}
Hence, we have
\begin{align*}
&z_{11}^\ast = \Lambda_{12} v_1, \quad 
z_{12}^\ast = \frac{\eta_p}{\eta_1+\eta_p}(1 - \Lambda_{21}) v_2 = \frac{\eta_2\eta_p \sigma_2^2}{(\eta_1+\eta_p)(\gamma_2+(\eta_2+\bar\eta_1)\sigma_2^2)} v_2, \\
& 
\Lambda_{12} := \frac{\gamma_1 + \bar\eta_2\sigma_1^2}{\gamma_1 + (\eta_1+\bar\eta_2)\sigma_1^2}, \quad
\Lambda_{21} := \frac{\gamma_2 + \bar\eta_1\sigma_2^2}{\gamma_2 + (\eta_2+\bar\eta_1)\sigma_2^2}
\end{align*}
And the PDE for $v$ becomes
\begin{align*}
&0 =  f(x) -  g(x) + \partial_t v + \frac12 \sigma_1^2 v_{11}  + \frac12 \sigma_2^2 v_{22} 
+  \frac12\Big[\frac{(\gamma_1 + \bar\eta_2\sigma_1^2)^2}{\gamma_1 + (\eta_1+\bar\eta_2)\sigma_1^2} + \bar\eta_2\sigma_1^2\Big] v_1^2 
+  \frac12\Big[\frac{(\gamma_2 + \bar\eta_1\sigma_2^2)^2}{\gamma_2 + (\eta_2+\bar\eta_1)\sigma_2^2} + \bar\eta_1\sigma_2^2\Big] v_2^2 
  , \quad v(T,x) = 0.
\end{align*}
This PDE takes the form 
\begin{align*}
&0 =   L x + \frac12 x \cdot Q x + \partial_t v +  \frac12 {\rm Tr}[\Sigma\Sigma^\intercal D ^2v] + \frac12 Dv \cdot M Dv
  , \quad v(T,x) = 0, 
\end{align*}
Assume $v(t,x) = \frac12 x\cdot Ax + Bx + C$ with $A, B$ and $C$ functions of time and $A$ symmetric, we get the ODEs for $A$ and $B$ as
\begin{align*}
0 = Q + \dot A + AMA, \quad A(T) = 0, \quad 0 = L + \dot B + AM B, \quad B(T) = 0. 
\end{align*}

\section{Firm without incentives}

\paragraph{Proof}
To characterize the optimal strategy $\hat a^1$ for Firm 1, given Firm 2's equilibrium strategy $\hat a^2$, we solve the value function with a Hamilton-Jacobi-Bellman equation. As done in class, we will admit this equation :
\begin{align*}
\begin{cases}
    0 = \partial_t V_1 + \frac{1}{2} \sigma_1^2 \partial_{xx}V_1 + \frac{1}{2} \sigma_2^2 \partial_{yy}V_1 
    + \hat a^2_t \partial_y V_1 
    + \eta_1 \left( p_0 - p_1 x^2 - p_2 y x \right) V_1 
 + \inf_{a^1 \in \mathbb{R}} \left\{ \partial_x V_1 a^1 + \frac{\eta_1 V_1}{2\gamma_1} (a^1)^2 \right\} \quad &\forall (t,x,y), \\
    V_1(T,x,y) = -1 \quad &\forall (x,y).
\end{cases}
\end{align*}

Solving the minimum : $\hat a^1 =  - \frac{\gamma_1}{\eta_1 V_1} \partial_x V_1$ and we obtain the PDE :

\begin{align*}
\begin{cases}
0 = \partial_t V_1 + \frac{1}{2} \sigma_1^2 \partial_{xx}V_1 + \frac{1}{2} \sigma_2^2 \partial_{yy}V_1 + \hat a^2_t \partial_y V_1 + \eta_1 \left( p_0 - p_1 x^2 - p_2 y x \right) V_1 -  \frac{\gamma_1}{2\eta_1 V_1} (\partial_x V_1)^2 &\forall (t,x,y), \\
    V_1(T,x,y) = -1 \quad &\forall (x,y).
\end{cases}
\end{align*} \\

\noindent
We propose the following ansatz for $V_1$:
\begin{align*}
V_1(t, x, y) = -\exp \left( \eta_1 W_1(t, x, y) \right) 
\end{align*}
where $W_1(t, x, y)$ is a quadratic function of the state variables:
\begin{align*}
    W_1(t, x, y) = \frac{1}{2} A(t) x^2 + \frac{1}{2} B(t) y^2 + C(t) xy + D(t) x + E(t) y + F(t) 
\end{align*}
\noindent
$A(t), B(t), C(t), D(t), E(t), F(t)$ are deterministic functions of time, satisfying the terminal conditions $A(T)=B(T)=C(T)=D(T)=E(T)=F(T)=0$.\\

\noindent
Partial derivatives of $V_1$ :
\begin{align*}
\partial_t V_1 &= V_1 \eta_1 \partial_t W_1 = V_1\eta_1\left[ \frac{1}{2} A' x^2 + \frac{1}{2} B' y^2 + C' xy + D' x + E' y + F' \right]\\
\partial_x V_1 &= V_1 \eta_1 \partial_x W_1 = V_1 \eta_1 [A(t) x + C(t) y + D(t)] \\
-\frac{\gamma_1}{2\eta_1 V_1} (\partial_x V_1)^2 &=  - \frac{1}{2} \gamma_1 \eta_1 V_1 [A(t) x + C(t) y + D(t)]^2\\
\partial_y V_1 &= V_1 \eta_1 \partial_y W_1 = V_1 \eta_1 [B(t) y + C(t) x + E(t)] \\
\partial_{xx} V_1
&= V_1 \eta_1\left( \eta_1 [A(t) x + C(t) y + D(t)]^2 +  A(t) \right) \\
\partial_{yy} V_1 
&= V_1 \eta_1\left( \eta_1 [B(t) y + C(t) x + E(t)]^2 +  B(t) \right)\\
\end{align*}

\noindent
By replacing and dividing by $V_1\eta_1$ we obtain the following PDE : 

\begin{align*}
0 = \; &  \frac{1}{2} A' x^2 + \frac{1}{2} B' y^2 + C' xy + D' x + E' y + F'  \\
& + \frac{1}{2} \sigma_1^2 \left( \eta_1 [A x + C y + D]^2 + A \right) \\
& + \frac{1}{2} \sigma_2^2 \left( \eta_1 [B y + C x + E]^2 + B \right) \\
& + \hat a^2 (B y + C x + E) \\
& + \left( p_0 - p_1 x^2 - p_2 y x \right) \\
& - \frac{1}{2} \gamma_1 [A x + C y + D]^2\\
\end{align*}

\noindent
Following a similar method for Firm 2, we have : 

\begin{align*}
\begin{cases}
0 = \partial_t V_2 + \frac{1}{2} \sigma_1^2 \partial_{xx}V_2 + \frac{1}{2} \sigma_2^2 \partial_{yy}V_2 + \hat{a}^1_t \partial_x V_2 + \eta_2 \left( p_0 - p_2 y^2 - p_1 y x \right) V_2 -  \frac{\gamma_2}{2\eta_2 V_2} (\partial_y V_2)^2 &\forall (t,x,y), \\
    V_2(T,x,y) = 1 \quad &\forall (x,y).\\
\end{cases}
\end{align*}

\noindent
Using the ansatz $V_2(t, x, y) = \exp(\eta_2 W_2(t, x, y))$, where
\[
W_2(t, x, y) = \frac{1}{2} \tilde{A}(t) x^2 + \frac{1}{2} \tilde{B}(t) y^2 + \tilde{C}(t) xy + \tilde{D}(t) x + \tilde{E}(t) y + \tilde{F}(t)
\]
and substituting into the optimized HJB equation for $V_2$, we obtain the following PDE for $W_2(t, x, y)$:

\begin{align*}
0 = \; & \frac{1}{2} \tilde{A}' x^2 + \frac{1}{2} \tilde{B}' y^2 + \tilde{C}' xy + \tilde{D}' x + \tilde{E}' y + \tilde{F}'  \\
& + \frac{1}{2} \sigma_1^2 \left( \eta_2 [\tilde{A} x + \tilde{C} y + \tilde{D}]^2 + \tilde{A} \right) \\
& + \frac{1}{2} \sigma_2^2 \left( \eta_2 [\tilde{B} y + \tilde{C} x + \tilde{E}]^2 + \tilde{B} \right) \\
& +\hat{a}^1 (\tilde{A} x + \tilde{C} y + \tilde{D}) \\
& + \left( p_0 - p_2 y^2 - p_1 y x \right) \\
& - \frac{1}{2} \gamma_2 [\tilde{B} y + \tilde{C} x + \tilde{E}]^2\\
\end{align*}

\noindent
Now, by writing : 
\begin{align*}
\hat{a}^1_t &= - \gamma_1 (A(t) x + C(t) y + D(t))  \\
\hat{a}^2_t &= - \gamma_2 (\tilde{B}(t) y + \tilde{C}(t) x + \tilde{E}(t)) \\
\end{align*}

\noindent
We obtain :

\begin{align*}
\begin{cases}
0 =& \frac{1}{2} A' x^2 + \frac{1}{2} B' y^2 + C' xy + D' x + E' y + F' + \frac{1}{2} \sigma_1^2 \left( \eta_1 [A x + C y + D]^2 + A \right) + \frac{1}{2} \sigma_2^2 \left( \eta_1 [B y + C x + E]^2 + B \right) \\
& - \gamma_2 (\tilde{B} y + \tilde{C} x + \tilde{E}) (B y + C x + E)  + \left( p_0 - p_1 x^2 - p_2 y x \right)  - \frac{1}{2} \gamma_1 [A x + C y + D]^2\\
0 =& \frac{1}{2} \tilde{A}' x^2 + \frac{1}{2} \tilde{B}' y^2 + \tilde{C}' xy + \tilde{D}' x + \tilde{E}' y + \tilde{F}'+ \frac{1}{2} \sigma_1^2 \left( \eta_2 [\tilde{A} x + \tilde{C} y + \tilde{D}]^2 + \tilde{A} \right) + \frac{1}{2} \sigma_2^2 \left( \eta_2 [\tilde{B} y + \tilde{C} x + \tilde{E}]^2 + \tilde{B} \right) \\
& - \gamma_1 (Ax + Cy + D) (\tilde{A} x + \tilde{C} y + \tilde{D})  + \left( p_0 - p_2 y^2 - p_1 y x \right) - \frac{1}{2} \gamma_2 [\tilde{B} y + \tilde{C} x + \tilde{E}]^2\\ \end{cases}
\end{align*}


\noindent
Equating the coefficients of $x^2, y^2, xy, x, y,$ and the constant term to zero in the PDE gives the following 2 system of ODEs :


\begin{align*}
\begin{cases}
A' + \sigma_1^2 \eta_1 A^2 + \sigma_2^2 \eta_1 C^2 - 2\gamma_2 \tilde{C} C - 2p_1 - \gamma_1 A^2 = 0 \\[1ex]
