\begin{proposition}
{\cite[Proposition 3.2]{Lan14}}\label{Lan locally linear type}
Let $I$ and $\varphi$ be as in 
 the above setting. If $\p \in V(I) \backslash V(I_{n-2}(\varphi))$ then $I_\p$ is of linear type.    
\end{proposition}

\begin{proposition}\label{minimal prime is unique}
 With the assumption of above setting, the set $\Min(I_{n-2}(\varphi))$ has only one prime.   
\end{proposition}
\begin{proof}
Since $I$ satisfies $\Gs{2}$ but does not satisfy $\Gs{3}$, $\hgt I_{n-1}(\varphi)=\hgt I_{n-2}(\varphi)=2$ by \Cref{Gs and Fitting ideals}.
Let $\widetilde{\varphi}$ be the submatrix of $\varphi$ containing the first $n-2$ columns. From the presentation matrix $\varphi$ in \Cref{case i and ii presentation matrix}, it is clear that $I_{n-1}(\varphi) \subseteq I_{n-2}(\widetilde{\varphi}) \subseteq (x,y)$ and hence $\hgt I_{n-2}(\widetilde{\varphi}) =2$ since $\hgt I_{n-1}(\varphi)=2$. Therefore, $\Min(I_{n-2}(\widetilde{\varphi}))=\{(x,y)\}$. But $I_{n-2}(\widetilde{\varphi}) \subseteq I_{n-2}(\varphi) \subseteq (x,y)$, hence we get $\Min(I_{n-2}(\varphi))=\{(x,y)\}$.    
\end{proof}

The following theorem gives the structure of the defining ideal of the Rees algbera under the action of $\Gs{{2}}$  condition. Although there is general version of this description \cite[Proposition 3.9]{SurajMukundan24}. 
\begin{proposition}\label{colon ideal related to defining ideal of Rees algebra}\cite{SurajMukundan24}
With assumption in above setting,  then $\mathcal{A}= \mathcal{L} : (x,y)^{\infty}$.    
\end{proposition}
\begin{proof}
    Let $f \in \mathcal{L} : (x,y)^{\infty}$ then $f \in \mathcal{L} : (x,y)^t ; t \in \mathbb{N}$. Thus $x^tf, y^tf \in \mathcal{L} \subseteq \mathcal{A}$. But $\mathcal{A}$ is prime so $f \in  \mathcal{A}$. Thus $\mathcal{L} : (x,y)^{\infty} \subseteq \mathcal{A}$. Now \Cref{Lan locally linear type} implies that 
 $\Supp(\mathcal{A}/ \mathcal{L})\supset  V(I_{n-2}(\varphi))$. Since $\Supp(\mathcal{A}/ \mathcal{L})=V(\ann(\mathcal{A}/ \mathcal{L}))$ so we have $V(\ann(\mathcal{A}/ \mathcal{L})) \supset V(I_{n-2}(\varphi))$. Using \Cref{minimal prime is unique}, we know that $\p=(x,y)\in\Min(I_{n-2}(\varphi))$ is unique. Since $\mathcal{L} : (x,y)^{\infty} \subseteq \mathcal{A}$, we have $\p\in \Supp(\mathcal{A}/\mathcal{L})$. Thus, $\Supp(\mathcal{A}/\mathcal{L})=V(\ann(\mathcal{A}/\mathcal{L}))=V(I_{n-2}(\varphi))$. Again, $\sqrt{I_{n-2}(\varphi)}= \p = (x,y)$. Thus, $\p = (x,y)= \sqrt{\ann(\mathcal{A}/ \mathcal{L})}$. Now, $x,y \in \sqrt{\ann(\mathcal{A}/ \mathcal{L})}$ implies that there exists $t_1,t_2 \in \mathbb{N}$ such that $x^{t_1},y^{t_2} \in \ann(\mathcal{A}/ \mathcal{L})$. Fix $t = \max\{t_1,t_2\}$ then $(x,y)^t \subseteq \ann(\mathcal{A}/ \mathcal{L})$. Therefore, $(x,y)^t \mathcal{A}  \subseteq \mathcal{L}$. Hence $\mathcal{A}= \mathcal{L} : (x,y)^{\infty}$
\end{proof}


\section{Description of Defining ideal of Rees algebra when presentation matrix is in Case I}\label{section 4 and rees algebra in case i}

With the assumption of \Cref{Main Setting}, and that the presentation matrix $\varphi$ is of Case I (see \Cref{case i and ii presentation matrix}). In this section we will first give a better description of the Rees algebra which is comparable to \Cref{colon ideal related to defining ideal of Rees algebra} which is proved in \Cref{another characterization of defining ideal of Rees algebra}. Then we compute this colon ideal using methods in \cite{BoswellMukundan16, KPU11}, where we identify the the defining equations of the Rees algebra to the symbolic power of a height one unmixed ideal in a Cohen-Macaulay ring. Using Grobner basis technique, we give complete characterization of symbolic power of this height one unmixed ideal.

\begin{notation}\label{notation for case I}
Consider the $S$-ideal, $(x,y,zw_0)$ then $[w_0~\cdots~w_{n-1}] \cdot \varphi = [x~y~zw_0] \cdot B(\varphi)$. Here, $B(\varphi)$ is the Jacobian dual of the presentation matrix $\varphi$ with respect to ideal $(x,y,zw_0)$. Now onward, we will follow this definition of Jacobian dual. 

Recall that the ideal defining the symmetric algebra is $\mathcal{L} =(l_1,\dots,l_{n-1})$.  Since $l_{n-2} \in \mathcal{L}$, from the presentation matrix $\varphi$ (see \Cref{case i and ii presentation matrix}) of $I$ we have $l_{n-2}=zw_0 + xg_1 + yg_2$ where $g_i$'s are linear polynomial in $w_j; 1 \leq j \leq n-1$.
\end{notation}


\begin{lemma}\label{ second colon ideal related to defining ideal of Rees algebra}\cite[Lemma 5.1]{SurajMukundan24}
 With the assumption of \cref{Main Setting}, $\mathcal{A}=\mathcal{L}:(x,y,zw_0)^{\infty}$.   
\end{lemma}

\begin{observation}\label{colon ideal in second case}
 Assume the \Cref{Main Setting}, then $$\mathcal{L} : (x,y,zw_0) =\mathcal{L} + I_3(B(\varphi)).$$    
\end{observation}

\begin{proof}
Let $\mathcal{U}=(x,y,zw_0)$, then $\mathcal{U}$ is a complete intersection. We show that $\mathcal{L}: \mathcal{U}$ is the $(n-1)$-residual intersection of $\mathcal{U}$ then \Cref{deformation}, \Cref{computation of generic residual intersection} and \Cref{generic residual intersection is Cohen Macaulay} imply $\mathcal{L}:\mathcal{U}=\mathcal{L}+I_3(B(\varphi))$. It suffices to show that $\hgt (\mathcal{L}:\mathcal{U}) \geq n-1$. 

Let $P$ be a minimal prime of $\mathcal{L}: \mathcal{U}$. Suppose $p=P \bigcap R$. Now, $(x,y) \subseteq p$ or $(x,y) \nsubseteq p$. If $(x,y) \subseteq p$ then $(x,y)+I_3(B(\varphi)) \subseteq P$. Since, $I_3(B(\varphi))$ is prime ideal of height $n-3$, therefore $\hgt((x,y)+I_3(B(\varphi))) \geq n-1$. Thus, $\hgt P \geq n-1$. If $(x,y) \nsubseteq p$, then $(\mathcal{L}:\mathcal{U})_p \subseteq \mathcal{A}_p$. But \Cref{Lan locally linear type}, \Cref{minimal prime is unique} implies  $\mathcal{L}_p=\mathcal{A}_p$. Thus, $(\mathcal{L}:\mathcal{U})_p=\mathcal{A}_p$. This implies $\mathcal{A} \subseteq P$ and hence $\hgt P \geq n-1$. 
\end{proof}

