\begin{lemma}\label{colon ideal of K}
    The ring $B$ is a Cohen-Macaulay domain of dimension $5$. And the $B$-ideal, $\overline{\mathcal{K}}$ is Cohen-Macaulay ideal of height one. We also have the equalities of $B$-ideals,
    \begin{align*}
\overline{\mathcal{K}}^{(j)} = \overline{(zw_0)}^{(j)} : \overline{(x,y,zw_0)}^{(j)} \\ \overline{(x,y,zw_0)}^{(j)} = \overline{(zw_0)}^{(j)} : \overline{\mathcal{K}}^{(j)} ; 1 \leq j \leq 2.
    \end{align*}
\end{lemma}
\begin{proof}
   Proof is similar to the proof \cite[Observation 5.6, Observation 5.7, Lemma 5.10]{SurajMukundan24}.
