\subsection{When $\varphi'$ is strictly equivalent to $[L'_{n-2}]$}
Define the $B$-ideals,

$$N_1=(\{\overline{-w_{n-2}\a_{i+1}+w_{n-1}\a_i} ; 1\leq i \leq {n-4}\})$$ and \begin{align*}
    N_2=\overline{\mathcal{K}}^2+(\{\overline{-zw_{n-2}\a_{i+1}+zw_{n-1}\a_i} ; 1\leq i \leq {n-4}\})\\+(\{{\overline{w_{n-1}(\a_{i+1}-\a_i)-w_{n-2}(\a_{i+2}-\a_{i+1})}} ; 1 \leq i \leq n-5\}).
\end{align*} Clearly, $N_i \neq \overline{\mathcal{K}}^2$ for $i=1,2$.


\begin{lemma}\label{x.N_1 is subset of K^2}
    With the assumption of \Cref{Main Setting}. In the ring $B$, we have $\overline{x} \cdot N_i \subseteq \overline{\mathcal{K}}^2$, for $i=1,2$.
\end{lemma}
\begin{proof}
     For $1 \leq j \leq n-3$, consider the $S$-ideal, $(l_j,l_{n-2})$. Then $[l_j,l_{n-2}]=[x~y~zw_0] \cdot B_j$, where $B_j$ is $2 \times 3$ submatrix of $B(\varphi'')$, such that first column of $B_j$ is $j$-th column and second column be the last column of $B(\varphi'')$. Now,  \cite[Lemma 4.3]{BoswellMukundan16}, implies $x\a_i=zw_0 \a_{i_x}$. Similarly, $x \a_{i+1}=zw_0 \a_{{i+1}_x}$. Therefore,
     \begin{align*}
    \overline{x} \cdot (-\overline{w_{n-2}\a_{i+1}}+\overline{w_{n-1} \a_i})&=-\overline{w_{n-2}}\{\overline{x \a_{i+1}}\}+ \overline{w_{n-1}}\{\overline{x \a_i}\} \\&=\overline{w_{n-2}}\{\overline{zw_0 \a_{{i+1}_x}}\}- \overline{w_{n-1}}\{zw_0 \a_{i_{x}}\}
    \\&= \overline{w_{n-2}}\{\overline{zw_0 \a_{{i+1}_x}}\} - \overline{w_{n-1}}\{\overline{zw_0 \a_{{i_x}}}\} \\&=\overline{zw_0}\{\overline{w_{n-2} \a_{{i+1}_x}}-\overline{w_{n-1} \a_{i_x}}\} \in \overline{\mathcal{K}}^2.
\end{align*}
Thus, $\overline{x}\cdot N_1 \subseteq \overline{\mathcal{K}}^2$. That is, ${N_1} \subseteq \overline{\mathcal{K}}^{(2)}$. Similarly, $\overline{x} \cdot N_2 \subseteq \overline{\mathcal{K}}^2$ and hence $N_2 \subseteq \overline{\mathcal{K}}^{(2)}.$
\end{proof}


