\begin{theorem}\label{w_0 is regular over ideal}
    Assume the assumption of \Cref{Main Setting}. Let $\varphi'$ is strictly equivalent to $[L'_{n-2}]$.
    \begin{enumerate}
        \item If $w_0 \notin I_2(B(\varphi''))$, then we have $\overline{\mathcal{K}}^{(2)}=(\overline{z^2w_0^2})+{N_1}$.
        \item If $w_0 \in I_2(B(\varphi''))$, then we have $\overline{\mathcal{K}}^{(2)}=\overline{\mathcal{K}}^2+ N_2$.
    \end{enumerate}
    \end{theorem}
\begin{proof}
Let the first $n-3$ entries in the first row of the presentation matrix $\varphi$ be $a_1x+b_1y, a_2x+b_2y,\cdots, a_{n-3}x+b_{n-3}y$ where $a_i,b_i \in \k$. Since $\varphi'$ is strictly equivalent to $[L_{n-2}']$. Then Jacobian Dual of $\varphi''$ is 
\begin{align*}
    B(\varphi'')=\begin{pmatrix}
        a_1w_0+w_1&a_2w_0+w_2&\cdots&a_{n-3}w_0+w_{n-3}&w_{n-2}\\
        b_1w_0+w_2&b_2w_0+w_3&\cdots&b_{n-3}w_0+w_{n-2}&w_{n-1}\\
        0&0&\cdots&0&1\\
    \end{pmatrix}
\end{align*}
For $2 \leq i \leq n-3$, $a_iw_0+w_i,b_{i-1}w_0+w_i \in I_2(B(\varphi''))$. Thus, $(a_{i}-b_{i-1})w_0 \in I_2(B(\varphi''))$. But $w_0 \notin I_2(B(\varphi''))$, this will imply $a_i=b_{i-1}$ for $2 \leq i \leq n-3$. Without loss of generality, take $a_i=b_{i-1}=0$ for $2\leq i \leq n-3$ and $a_1=1,b_{n-3}=1$. Thus, the symmetric equations $l_i=xw_i+yw_{i+1}$ for $2 \leq i \leq n-4$, $l_1=x(w_0+w_1)+yw_2, l_{n-3}=xw_{n-3}+y(w_0+w_{n-2})$ and $l_{n-2}=xw_{n-2}+yw_{n-1}+zw_0$.

We have $\overline{x}$ is regular over $\overline{\mathcal{K}}$ and $(\overline{z^2w_0^2})+N_1 \subseteq \overline{\mathcal{K}}^{(2)}$. If $\overline{x}$ is regular over $(\overline{z^2w_0^2})+N_1$ then for all $P \in \Ass{((\overline{z^2w_0^2})+N_1)}$, $\overline{x} \notin P$. Thus, for all $P \in \Ass{((\overline{z^2w_0^2})+N_1)}$,
\begin{align*}
    \{(\overline{z^2w_0^2})+{N_1} \}_P \subseteq (\overline{z^2w_0^2})_P :\overline{(x,y,zw_0)}^{(2)}_P=(\overline{z^2w_0^2})_P:B_P=(\overline{z^2w_0^2})_P.
\end{align*}
Thus, it suffices to show that $\overline{x}$ is regular over $(\overline{z^2w_0^2})+N_1$. Equivalently, to show in the ring $S$,$x$ is regular over $\mathcal{J}+(z^2w_0^2)+N_1$. We will use the Grobner basis technique to prove this.

Let $<$ be the reverse lexicographical monomial order on the ring $S=\k[\underline{x},\underline{w}]$ and 
\begin{align*}
    x<y<z<w_0<\cdots<w_{n-1}.
\end{align*}
Suppose $G=\{h_1,h_2,\dots,h_m\}$ is the Grobner basis of $\mathcal{J}+(z^2w_0^2)+N_1$ then $\mathcal{J}+(z^2w_0^2)+N_1=(h_1,h_2,\dots,h_m)$. Now $x$ will be regular over $\mathcal{J}+(z^2w_0^2)+N_1$ if and only if $\{ \mathcal{J}+(z^2w_0^2)+N_1 \}:(x)=\mathcal{J}+(z^2w_0^2)+N_1$ and to compute the Grobner basis of $\mathcal{J}+\{(z^2w_0^2)+N_1 \} : (x)$ we need to compute the Grobner basis of $\{ \mathcal{J}+(z^2w_0^2)+N_1 \} \bigcap (x)$.

Consider the ring $S[t]$, where $t$ is indeterminate such that $x<y<z<w_0<\cdots<w_{n-1}<t$. Then, we have to compute the Grobner basis of $t{\mathcal{J}}+(tz^2w_0^2)+tN_1+(1-t)x$. For polynomials $f,g$,  $S(f,g)$ be the $S$-pair of polynomials, then we have to compute following $S$-pair of polynomials, $S(th_i,th_j)$ and $S(th_i,(1-t)x)$, $1\leq i <j \leq m$. Observe that, $S(th_i,th_j)=tS(h_i,h_j)=0$ for $1 \leq i < j \leq m$, as $\{h_1,\dots,h_m \}$ is Grobner basis. 

If $x$ does not divide $\inn_{<}h_i$, for all $i$, then $S(th_i,(1-t)x)=xh_i$. Thus the Grobner basis of $\{ \mathcal{J}+(z^2w_0^2)+N_1 \} \bigcap (x)$ will be $\{xh_1,xh_1,\dots,xh_m \}$ and hence, the Grobner basis of $\{ \mathcal{J}+(z^2w_0^2)+N_1 \} :(x)$ will be $G=\{h_1,h_2,\dots,h_m \}$. So, we need to prove that for all $i$, $x$ does not divide $in_{<}h_i$. That is, we have to compute the Grobner basis of $\mathcal{J}+(z^2w_0^2)+N_1$.

Let $G_0=\{l_1,l_2,\dots,l_{n-2} \} \bigcup \{c_{jk} ; 1 \leq j <k \leq n-3 \} \bigcup \{z^2w_0^2, \eta_{i} ; 1 \leq i \leq n-4 \}$ where 
\begin{align*}
    c_{jk}=w_jw_{k+1}-w_{j+1}w_k ; j \neq 1,n-3, k \neq n-3 && in_{<}c_{jk}=w_{j+1}w_{k} \\c_{1k}=w_0w_{k+1}+w_1w_{k+1}-w_2w_k && in_{<}c_{1k}=w_2w_k \\c_{j,n-3}=w_0w_j+w_jw_{n-2}-w_{j+1}w_{n-3} && in_{<}c_{j,n-3}=w_{j+1}w_{n-3} \\ c_{1,n-3}=w_0^2+w_0w_{n-2}+w_0w_1+w_1w_{n-3}-w_2w_{n-3}&& in_{<}c_{1,n-3}=w_2w_{n-3}.
\end{align*}
 And, 
 \begin{align*}
 \eta_i= w_iw_{n-1}^2-2w_{i+1}w_{n-2}w_{n-1}+w_{i+2}w_{n-2}^2 ; 2 \leq i \leq n-5 && in_{<} \eta_i=w_{i+1}w_{n-2}^2 \\ \eta_1=w_0w_{n-1}^2+w_1w_{n-1}^2-2w_2w_{n-2}w_{n-1}+w_3w_{n-2}^2 && in_{1}=w_3w_{n-2}^2
 \\ \eta_{n-4}=w_{n-4}w_{n-1}^2-2w_{n-3}w_{n-2}w_{n-1}+w_0w_{n-2}^2+w_{n-2}^3 && in_{<} \eta_{n-4}=w_{n-2}^3.
\end{align*}
Now, $\mathcal{J}$ is prime ideal, so in stage one iteration of $S$-polynomials, we have to compute following $S$-pair
of polynomials
\begin{align*}
    S(l_{i'},z^2w_0^2) && S(l_{i'},\eta_i) \\ S(c_{jk},z^2w_0^2) &&
    S(c_{jk}, \eta_i) && S(z^2w_0^2,\eta_i).
\end{align*}
For $1 \leq i' \leq n-3$, $S(l_{i'},z^2w_0^2)$ reduces to zero. We have  $in_{<}l_{i'}=yw_{i'+1}$ for $1 \leq i' \leq n-3$ so $2 \leq i'+1 \leq n-2$. Thus, $\gcd(in_{<}l_{i'},z^2w_0^2)=1$. Hence, $S(l_{i'},z^2w_0^2)$ reduces to zero with respect to $l_{i'},z^2w_0^2$ for $1 \leq i' \leq n-3$. Also, $\lcm(in_{<}l_{n-2},z^2w_0^2)=z^2w_0^2$. Thus, $S(l_{n-2},z^2w_0^2)=zxw_0w_{n-2}+yzw_0w_{n-1}$. Applying, division algorithm with respect to $l_{n-2}$, we get $S(l_{n-2},z^2w_0^2)=-x^2w_{n-2}^2-2xyw_{n-2}w_{n-1}-y^2w_{n-1}^2$. Further, reducing with respect to $l_{n-3}$, we get 
\begin{align*}
    S(l_{n-2},z^2w_0^2)=x^2w_{n-2}^2-2x^2w_{n-3}w_{n-1}-2xyw_0w_{n-1}+y^2w_{n-1}^2.
\end{align*}
We have $\mathcal{J}$ a prime ideal and $c_{jk} \in \mathcal{J}$. So, $c_{jk}; 1 \leq j < k \leq n-3$, is irreducible polynomials in $\k[\underline{w}]$, this implies  $\gcd(in_{<}c_{jk},z^2w_0^2)=1$ and thus $S(c_{jk},z^2w_0^2)$ reduces to zero with respect to $c_{jk}, z^2w_0^2$ for $1 \leq j < k \leq n-3$. Also, $w_0$ regular over $I_2(B(\varphi''))$ and $\eta_i \in \k[\underline{w}]$ implies $\gcd(in_{<} \eta_i, z^2w_0^2)=1$. Hence $S(z^2w_0^2, \eta_i)$ reduces to zero with respect to $z^2w_0^2, \eta_i$ for $1 \leq i \leq n-4$.

Now, we investigate $S(l_{i'}, \eta_i); 1 \leq i' \leq n-2, 1 \leq i \leq n-4$. Clearly, for $1 \leq i \leq n-4$, $\gcd(in_{<}l_{n-2}, in_{<} \eta_i)=\gcd(zw_0,w_{i+2}w_{n-2}^2)=1$. Thus, $S(l_{n-2},\eta_i)$ reduces to zero with respect to $l_{n-2}, \eta_i$ for $1 \leq i \leq n-4$. Also, let $2 \leq i \leq n-4$ then $i'=i$ or $i'=i+1$ or $i' \neq i,i+1$. If $i'=i$, then $in_{<} l_i=yw_{n+1}$ and $in_{<} \eta_i=w_{i+2}w_{n-2}^2$. Thus $\gcd(in_{<}l_i, \eta_i)=1$ and hence $S(l_i,\eta_i)$ reduces to zero with respect to $l_i, \eta_i$. If $i'=i+1$ then $\lcm(in_{<} l_{i+1}, in_{<} \eta_i)=\lcm(yw_{i+2}, w_{i+2}w_{n-2}^2)=yw_{i+2}w_{n-2}^2$. Therefore, $S(l_{i+1},\eta_i)=xw_{i+1}w_{n-2}^2-yw_{i}w_{n-1}^2+2yw_{i+1}w_{n-2}w_{n-1}$. Applying the division algorithm with respect to $l_{i-1}, l_{i}$, we get $S(l_{i+1}, \eta_i)=xw_{i+1}w_{n-2}^2+xw_{i-1}w_{n-1}^2-2xw_iw_{n-2}w_{n-1}=x \eta_{i-1}$. Thus, $S(l_{i+1}, \eta_{i})$ reduces to zero. If $i' \neq i, i+1$ then either $i' < i$ or $i'> i+1$, suppose $i' \leq i-1$ then $\gcd(in_{<}l_{i'}, in_{<} \eta_i)= \gcd(yw_{i'+1},w_{i+2}w_{n-2}^2)=1$, as $i'+1 \leq i$ and this implies $S(l_{i'},\eta_{i})$ reduces to zero for $i' \leq i-1$. Similarly, $S(l_{i'}, \eta_i)$ reduces to zero for $i \geq i+1$. Thus, the only case remaining to investigate is $S(l_{i'}, \eta_1)$. Although, for $ 1\leq i' \leq n-2$ but $i' \neq 2$, $S(l_{i'}, \eta_1)$ reduces to zero because $\gcd(in_{<}l_{i'}, \eta_{i})=1$. For $i'=2$, $\gcd(in_{<}l_2, \eta_1) \neq 1$ and hence
\begin{align*}
    S(l_{2}, \eta_1)=xw_2w_{n-2}^2-yw_0w_{n-1}^2-yw_1w_{n-1}^2+2yw_2w_{n-2}w_{n-3}.
\end{align*}
Thus, applying division algorithm with respect to $l_1$, the reduced polynomial is 
\begin{align*}
    S(l_2,\eta_1)=xw_2w_{n-2}^2-2xw_0w_{n-2}w_{n-1}-2xw_1w_{n-2}w_{n-1}-yw_0w_{n-1}^2-yw_1w_{n-1}^2.
\end{align*}
Finally, we have to compute $S(c_{jk}, \eta_i)$. From definition of $\eta_i=w_{n-1} \a_i-w_{n-2} \a_{i+1} ; 1 \leq i \leq n-4$, we have following possibilities $j=i, k=i+1$ (vice-versa) or $j=i,k\neq i+1$ (vice-versa) or $j\neq i, k=i+1$ (vice-versa) or $j \neq i, k \neq i+1$ (vice-versa). If $j=i, k=i+1$, then $in_{<}c_{i,i+1}=w_{i+1}^2$ and $in_{<} \eta_i=w_{i+2}w_{n-2}^2$. Thus $\gcd(in_{<}c_{i,i+1},in_{<} \eta_i)=1$ and this implies $S(c_{i,i+1}, \eta_i)$ reduces to zero with respect to $c_{i,i+1}, \eta_i$. If $j=i,k\neq i+1$, then $k \geq i+2$. This implies $i+2 \leq n-3$, as $k \leq n-3$. So, $in_{<}c_{ik}=w_{i+1}w_k$. If $k>i+2$, $\gcd(in_{<}c_{ik},\eta_i)=1$. And, thus $S(c_{ik},\eta_i)$ reduces to zero. If $k=i+2$, then $\lcm(in_{<}c_{i,i+2}, in_{<} \eta_i)=w_{i+1}w_{i+2}w_{n-2}^2$, $S(c_{i,i+2}, \eta_i)=2w_{i+1}^2w_{n-2}w_{n-1}-w_iw_{i+3}w_{n-2}^2-w_iw_{i+1}w_{n-1}^2$. Applying division algorithm with respect to $\eta_{i+1}, c_{i,i+1}$, $S(c_{i,i+2}, \eta_i)$ reduces to zero. Similarly, if $j\neq i, k=i+1$, then $S(c_{j,i+1},\eta_i)$
reduces to zero. If $j \neq i,k \neq i+1$, then either $j\geq i+1, k\geq i+2$ or $j \leq i-1, k\leq i$. Let $j\geq i+2$ then $k \geq i+3$, which implies that $S(c_{j,k}, \eta_i)$ reduces to zero, as $\gcd(in_{<}c_{jk},in_{<} \eta_i)=1$. If $j=i+1$, then $k \geq i+2$, $\lcm(in_{<}c_{i+1,k},in_{<}\eta_i)=\lcm(w_{i+2}w_k,w_{i+2}w_{n-2}^2)=w_{i+2}w_kw_{n-2}^2$. Thus, $S(c_{i+1,k},\eta_i)=2w_kw_{i+1}w_{n-2}w_{n-1}-w_{i+1}w_{k+1}w_{n-2}^2-w_kw_iw_{n-1}^2=-\eta_{i-1}$, reduces to zero. Similarly, $S(c_{jk},\eta_i)$ reduces to zero for $j \leq i-1, k\leq i$. Hence, $S(c_{jk},\eta_i)$ reduces to zero for $1 \leq j< k \leq n-3, 1 \leq i \leq n-4$.

Therefore, in stage one iteration of Buchberger's algorithm, there are two non-zero $S$-polynomials. That is, 
\begin{align*}
    S(l_{n-2},z^2w_0^2)=x^2w_{n-2}^2-2x^2w_{n-3}w_{n-1}-2xyw_0w_{n-1}+y^2w_{n-1}^2,\\
    S(l_2,\eta_1)=xw_2w_{n-2}^2-2xw_0w_{n-2}w_{n-1}-2xw_1w_{n-2}w_{n-1}-yw_0w_{n-1}^2-yw_1w_{n-1}^2.
\end{align*}
Let $G_1=G_0 \bigcup \{h_{m+1},h_{m+2} \}$ where $h_{m+1}=S(l_{n-2},z^2w_0^2), h_{m+2}=S(l_2,n_1)$ and $in_{<}h_{m+1}=y^2w_{n-1}^2, in_{<}h_{m+2}=yw_1w_{n-1}^2$. Now in stage two iteration of Buchberger's algorithm, we have to compute the following $S$-polynomials
\begin{align*}
    S(l_i',h_{m+1}) && S(c_{jk},h_{m_+1}) && S(z^2w_0^2, h_{m+1})\\ S(\eta_i, h_{m+1})&&
    S(l_i',h_{m+2}) && S(c_{jk},h_{m_+2}) \\ S(z^2w_0^2, h_{m+2}) && S(\eta_i, h_{m+2})&&
    S(h_{m+1},h_{m+2}).
\end{align*}
We show that every $S$-polynomials in stage two will reduces to zero and thus $G_1$ will be required Grobner basis of $\mathcal{J}+(z^2w_0^2)+N_1$. Enough to show $S(l_{i'},h_{m+1}), S(c_{jk},h_{m+1}),\\ S(z^2w_0^2,h_{m+1}), S(\eta_i, h_{m+1}), S(h_{m+1},h_{m+2})$ reduces to zero. And using similar line of argument, one can show $S(l_{i'},h_{m+2}), S(c_{jk},h_{m+2}), S(z^2w_0^2,h_{m+2}), S(\eta_i, h_{m+2})$ also reduces to zero.

We have $in_{<}h_{m+1}=y^2w_{n-1}^2$ and we have already seen that $in_{<}c_{jk}=w_{j+1}w_{k}; 1 \leq j <k \leq n-3$, $in_{<}\eta_i=w_{i+2}w_{n-2}^2; 1 \leq i \leq n-4$. So, $\gcd(in_{<}c_{jk},in_{<}h_{m+1})=\gcd(in_{<}z^2w_0^2,in_{<}h_{m+1})=\gcd(in_{<}\eta_i, in_{<}h_{m+1})=1$. Thus, $S(c_{jk},h_{m+1}),S(z^2w_0^2,h_{m+1}),S(\eta_i,h_{m+1})$ reduces to zero, for $1 \leq i \leq n-4, 1 \leq j<k \leq n-3$.

For $2 \leq i' \leq n-4$, $\lcm(in_{<}l_{i'},  in_{<}h_{m+1})=\lcm(yw_{i'+1}, y^2w_{n-1}^2)=y^2w_{i'+1}w_{n-1}^2$. Therefore,
$S(l_{i'},h_{m+1})=2x^2w_{i'+1}w_{n-3}w_{n-1}-x^2w_{i'+1}w_{n-2}^2-xyw_{i'}w_{n-1}^2+2xyw_0w_{i'+1}w_{n-1}$. Applying the division algorithm with respect to $l_{i'-1}, l_{i'}$, we get $S(l_{i'},h_{m+1})=2x^2w_{i'+1}w_{n-3}w_{n-1}-x^2w_{i'+1}w_{n-2}^2-x^2w_{i'-1}w_{n-1}^2-2x^2w_0w_{i'}w_{n-1}$. Further, reducing it with respect to $c_{i',n-3}$, we get $S(l_{i'},h_{m+1})=2x^2w_{i'}w_{n-2}w_{n-1}-x^2w_{i'+1}w_{n-2}^2-x^2w_{i'-1}w_{n-1}^2=-x^2 \eta_{i'-1}$. Thus, $S(l_{i'},h_{m+1})$ reduces to zero. Similarly, $S(l_1,h_{m+1}), S(l_{n-3},h_{m+1})$ reduces to zero. Also, $\gcd(in_{<}l_{n-2},in_{<}h_{m+1})=\gcd(zw_0,y^2w_{n-1}^2)=1$, so $S(l_{n-2},h_{m+1})$ reduces to zero. Hence, $S(l_{i'},h_{m+1})$ reduces to zero, for $1 \leq i' \leq n-2$.

Now, we will show that $S(h_{m+1},h_{m+2})$ reduces to zero. Since $\lcm(in_{<}h_{m+1},in_{<}h_{m+2})=y^2w_1w_{n-1}^2$ therefore $S(h_{m+1},h_{m+2})=x^2w_1w_{n-2}^2-2x^2w_1w_{n-3}w_{n-1}-2xyw_0w_1w_{n-1}+xyw_2w_{n-2}^2-2xyw_0w_{n-2}w_{n-1}-2xyw_1w_{n-2}w_{n-1}-y^2w_0w_{n-1}$. Applying, division algorithm with respect to $l_1$, we get $S(h_{m+1},h_{m+2})=-2x^2w_1w_{n-3}w_{n-1}-2xyw_0w_1w_{n-1}-2xyw_0w_{n-2}w_{n-1}-2xyw_1w_{n-2}w_{n-1}\\-y^2w_0w_{n-1}-x^2w_0w_{n-2}^2$. Further, reducing it with respect to $l_{n-3}$, $S(h_{m+1},h_{m+2})=-x^2w_0w_{n-2}^2+2x^2w_0w_{n-3}w_{n-1}+2xyw_0^2w_{n-1}-y^2w_0w_{n-1}^2=-w_0h_{m+1}$. Thus, $S(h_{m+1},h_{m+2})$ reduces to zero.

Hence, $G_1=\{ l_1,l_2,\dots,l_{n-2},z^2w_0^2,h_{m+1},h_{m+2}\} \bigcup \{c_{jk}; 1 \leq j < k \leq n-3 \} \bigcup \{ 
\eta_i ; 1 \leq i \leq n-4 \}$ is the Grobner basis of $\mathcal{J}+(z^2w_0^2)+N_1$ and for any $h \in G_1$, $x$ does not divide $in_{<}h$.

$(2)$ Now we suppose $w_0 \in I_2(B(\varphi''))$. Let the first $n-3$ entries in the first row of the presentation matrix $\varphi$ be $a_1x+b_1y, a_2x+b_2y,\cdots, a_{n-3}x+b_{n-3}y$ where $a_i,b_i \in \k$. Since $\varphi'$ is strictly equivalent to $[L_{n-2}']$. Then the Jacobian dual of $\varphi''$ is 
\begin{align*}
   B(\varphi'')= \begin{pmatrix}
        a_1w_0+w_1&a_2w_0+w_2&\cdots&a_{n-3}w_0+w_{n-3}&w_{n-2}\\
        b_1w_0+w_2&b_2w_0+w_3&\cdots&b_{n-3}w_0+w_{n-2}&w_{n-1}\\
        0&0&\cdots&0&1\\
    \end{pmatrix}
\end{align*}
For $2 \leq i \leq n-3$, $a_iw_0+w_i,b_{i-1}w_0+w_i \in I_2(B(\varphi''))$. Thus, $(a_{i}-b_{i-1})w_0 \in I_2(B(\varphi''))$. Since $w_0 \in I_2(B(\varphi''))$, implies $a_i \neq b_{i-1}$ for at least one $i$, where $2 \leq i \leq n-3$. Without loss of generality, take $a_2=0, b_1=1$ and $a_i=b_{i-1}=0$ for $3 \leq i \leq n-3$.


Using the Grobner basis technique and tracing the above proof, we get $\overline{x}$ regular over $\overline{\mathcal{K}}^2+N_2$. Thus, $\overline{x} \notin P$ for all $P \in \Ass{(\overline{\mathcal{K}}^2+N_2)}$. So,
\begin{align*}
    (\overline{\mathcal{K}}^2+N_2)_P \subseteq (\overline{z^2w_0^2})_P: \overline{(x,y,zw_0)}^{(2)}_P=(\overline{z^2w_0^2})_P:B_P=(\overline{z^2w_0^2})_P.
\end{align*}
But, $(\overline{z^2w_0^2})_P \subseteq (\overline{\mathcal{K}}^2+N_2)_P$. Thus, $(\overline{\mathcal{K}}^2+N_2)_P=\overline{\mathcal{K}}^{(2)}_P$. Hence, $\overline{\mathcal{K}}^2+N_2=\overline{\mathcal{K}}^{(2)}$.
\end{proof}

Now, we discuss the case where $\varphi'$ is strictly equivalent to $[L'_{r}~M_{r_1}~\cdots~M_{r_k}]$. It suffices to consider only one sub-block of type $M_{r_i}$, the results will be the same if there is more than one sub-block of type $M_{r_i}$. That is, the description of $\overline{\mathcal{K}}^{(2)}$ in both cases, $\varphi'$ strictly equivalent to $[L'_r~M_{r_1}~\cdots~M_{r_k}]$ and $\varphi'$ strictly equivalent to $[L'_r~M_{r'}]$ are the same.

Since $M_{r'}$ is a square matrix of order $r'$, we can have $r' \geq 2$ or $r'=1$. Depending on $r'$, we will give the complete description of $\overline{\mathcal{K}}^{(2)}$.

\subsection{When $r' \geq 2$} Suppose that the entries in first row of the presentation matrix $\varphi$ are $a_1x+b_1y, a_2x+b_2y, \dots,a_rx+b_ry, a_{r+1}x+b_{r+1}y,\dots,a_{n-3}x+b_{n-3}y$, therefore 
\begin{align*}
    \varphi=\begin{pmatrix}
    a_1x+b_1y & a_2x+b_2y & \cdots & a_rx+b_ry & a_{r+1}x+b_{r+1}y & \cdots a_{n-3}x+b_{n-3}y & z & *'' \\
    & & & & & & &*'\\
& & \varphi' & & & & &\vdots\\
& & & & & & &*'\\
\end{pmatrix},
\end{align*}
where $\varphi$ is strictly equivalent to $[L'_r~M_{r'}]$.

\begin{lemma}\label{the case where w_0 is always zd}
    Assume the assumption of \Cref{Main Setting}. If $\varphi'$ is strictly equivalent to $[L'_r~M_{r'}]$ and $r' \geq 2$, then $w_0 \in I_2(B(\varphi''))$.
\end{lemma}
\begin{proof}
    Suppose $w_0 \notin I_2(B(\varphi''))$ then the Jacobian dual is,
    \begin{align*}
    B(\varphi'')=\begin{pmatrix}
            a_1w_0+w_1 & a_2w_0+w_2 & \cdots & a_rw_0+w_r & a_{r+1}w_0+a^{r_1}w_{r+2} & \cdots & *\\
            b_1w_0+w_2 & b_2w_0+w_3 & \cdots & a_rw_0+w_{r+1} & b_{r+1}w_0+b^{r_1}w_{r+2} &\cdots & *\\
            0 & 0 & \cdots & 0 & 0 & \cdots & *
        \end{pmatrix}.
    \end{align*}
    Now, for $ 2 \leq j \leq r$, $a_jw_0+w_j, b_{j-1}w_0+w_j \in I_2(B(\varphi''))$, thus $(a_j-b_{j-1})w_0 \in I_2(B(\varphi''))$. But $w_0 \notin I_2(B(\varphi''))$, therefore $a_j=b_{j-1}$. From the $(r+1)$-th column of $B(\varphi'')$, we have $a_{r+1}w_0+a^{r_1}w_{r+2}, b_{r+1}w_0+b^{r_1}w_{r+2} \in I_2(B(\varphi''))$. Thus, $a'w_0+w_{r+2}, b'w_0+w_{r+2} \in I_2(B(\varphi''))$, where $a'=a_{r+1}/a^{r_1}$ and $b'=b_{r+1}/b^{r_1}$. Hence, $a'w_0-b'w_0 \in I_2(B(\varphi''))$. Again, $w_0 \notin I_2(B(\varphi''))$ will imply $a'=b'$, that is, $a_{r+1}=a^{r_1}c$ and $b_{r+1}=b^{r_1}c$, for some $c \in \k$ which would imply $r$-th symmetric equation, $l_r=(a^{r_1}x+b^{r_1}y)(cw_0+w_{r+2})$. Now, calculating the $I_{n-1}(\varphi)$ along the $r$-th column, we get $I_{n-1}(\varphi) \subseteq (a^{r_1}x+b^{r_1}y)$, that is, $\hgt I_{n-1}(\varphi) =1$, which is a contradiction as $I_{n-1}(\varphi)=I$, is of height two. Thus, $w_0 \in I_2(B(\varphi''))$. 
\end{proof}

\begin{theorem}\label{subcase two}
    With the assumption of \Cref{Main Setting}. If $\varphi'$ is strictly equivalent to $[L'_r~M_{r'}]$ and $r' \geq 2$, then
        \begin{align*}
        \overline{\mathcal{K}}^{(2)}=\overline{\mathcal{K}}^2 + \overline{(zw_{n-2}\a_{n-3})} \\  +\overline{(dw_{n-2}+bw_{n-1})\a_1-(cw_{n-2}+aw_{n-1})\a_2)} \\ + \overline{(cw_{n-2}+aw_{n-1})\a_3-(dw_{n-2}+bw_{n-1})\a_2+(cw_{n-2}+aw_{n-1})\a_1)} \\ + \overline{(dw_{n-2}+bw_{n-1})\a_{i+1}-(cw_{n-2}+aw_{n-1})\a_i ; 3 \leq i \leq n-5)},
        \end{align*}
        where $a,b,c,d \in \k$ such that the $(n-3)$ symmetric equation $l_{n-3}=zw_0+(aw_{n-1}+cw_{n-2})x+(bw_{n-1}+dw_{n-2}y)$
\end{theorem}
\begin{proof}
The proof is similar to the proof of \Cref{w_0 is regular over ideal}.    
\end{proof}



\subsection{When $r'=1$} 
