\section{Description of Defining ideal of Rees algebra when presentation matrix is in Case II}\label{section 5 and rees algebra in Case ii}

Assume the assumption of \Cref{Main Setting}, and throughout this section, the presentation matrix $\varphi$ is of Case II (see \Cref{case i and ii presentation matrix}). Although the description of the Rees algebra in this case is similar to \Cref{another characterization of defining ideal of Rees algebra} and comparable to \Cref{colon ideal related to defining ideal of Rees algebra}. Again we compute this colon ideal using methods in \cite{SurajMukundan24}, where we identify the the defining equations of the Rees algebra to  a height one unmixed ideal in a Cohen-Macaulay ring.

\begin{notation}
Assume the \Cref{notation for case I}.  
Recall that the defining ideal of symmetric algebra is $\mathcal{L} =(l_1,\dots,l_{n-1})$.  Since $l_{n-1},l_{n-2} \in \mathcal{L}$, then from the presentation matrix $\varphi$ (see \Cref{case i and ii presentation matrix}) of $I$ we have $l_{n-2}=zw_0 + xg_1 + yg_2$ where $g_i$'s are linear polynomial in $w_j; 1 \leq j \leq n-1$ and $l_{n-1}=x^2h_1+y^2h_2+xyh_3+xzh_4+yzh_5$ where $h_i's$ are linear polynomial in $\k[\underline{w}]$ with $h_4,h_5 \notin \k[w_0]$.
\end{notation}

We will collect some of the results of the previous section, which also holds for the presentation matrix $\varphi$ in Case II.

\begin{theorem}\label{ second colon ideal related to defining ideal of Rees algebra}\cite[Lemma 5.1]{SurajMukundan24}
 With the assumption of \cref{Main Setting}, and $\varphi$ in Case II. Then,
 \begin{enumerate}
     \item $\mathcal{A}=\mathcal{L}:(x,y,zw_0)^{\infty}$.
     \item $\mathcal{L} : (x,y,zw_0) =\mathcal{L} + I_3(B(\varphi)).$
     \item $\mathcal{A}=\mathcal{L}:(x,y,zw_0)^2$.
 \end{enumerate}   
\end{theorem}


\begin{notation}
Recall the \Cref{notation 5.1}, $\mathcal{J}=(l_1,\dots,l_{n-2}):(x,y,zw_0)$ and  $B=S/{\mathcal{J}}$ is Cohen-Macaulay domain of dimension 5. Define the $B$-ideal, $\mathcal{K'}$ such that
\begin{align*}
\mathcal{K'}=\overline{(z^2w_0)}:\overline{(x,y,zw_0)}^{2}.
\end{align*}
\end{notation}

From the previous section, $\varphi'$ is strictly equivalent to block diagonal matrix $[L_{n-2}']$ or $[L_r'~M_{r'}]$. Depending on wether $w_0 \in I_2(B(\varphi''))$ or $w_0 \notin I_2(B(\varphi''))$,
we give the complete characterization of the $B$-ideal,
${\mathcal{K}}'$.

\begin{theorem}\label{subcase five}
    With the assumption of \Cref{Main Setting}.
    \begin{enumerate}
        \item Let $\varphi'$ is strictly equivalent to $[L'_{n-2}]$.
        \begin{enumerate}
            \item If $w_0 \notin I_2(B(\varphi''))$, then the $B$-ideal,
            \begin{align*}\mathcal{K'}=(\overline{z^2w_0})+(\{ \overline{z\a_i} ; 1 \leq i \leq n-3 \}) \\ +(\{\overline{-w_{n-2}\a_{j+1}+w_{n-1}\a_j} ; 1\leq j \leq {n-4}\}).\end{align*}
            \item If $w_0 \in I_2(B(\varphi''))$, then the $B$-ideal,
            \begin{align*}
            \mathcal{K'}=(\overline{z^2w_0})+(\{\overline{z\a_i} ; 1 \leq i \leq n-3\})+(\{ \overline{\a_i \a_{i'}} ; 1 \leq i,i' \leq n-3 \}) \\+(\{{\overline{w_{n-1}(\a_{i+1}-\a_i)-w_{n-2}(\a_{i+2}-\a_{i+1})}} ; 1 \leq i \leq n-5\}).\end{align*}
        \end{enumerate}
        \item Let $\varphi'$ be strictly equivalent to $[L'_r~M_{r'}]$ and $r' \geq 2$.
        \begin{enumerate}
            \item Then $w_0$ is always a zero divisor over $I_2(B(\varphi''))$.
            \item The $B$-ideal,
            \begin{align*}
                \mathcal{K'}=(\overline{z^2w_0}) + (\{ \overline{z\a_i} ; 1 \leq i \leq n-3\}) + (\{ \overline{\a_i \a_j} ; 1 \leq i,j \leq n-3\}) \\ +((\overline{dw_{n-2}+bw_{n-1})\a_1-(cw_{n-2}+aw_{n-1})\a_2}) \\ + (\overline{(cw_{n-2}+aw_{n-1})\a_3-(dw_{n-2}+bw_{n-1})\a_2+(cw_{n-2}+aw_{n-1})\a_1}) \\ + (\overline{(dw_{n-2}+bw_{n-1})\a_{i+1}-(cw_{n-2}+aw_{n-1})\a_i ; 3 \leq i \leq n-5}), \end{align*}
         where $a,b,c,d \in \k$ such that the $(n-3)$ symmetric equation $l_{n-3}=zw_0+(aw_{n-1}+cw_{n-2})x+(bw_{n-1}+dw_{n-2}y)$.   
        \end{enumerate}
        \item Let $\varphi'$ be strictly equivalent to $[L'_{n-3}~M_1]$, where $M_1=[ax+by]; a,b \in \k$.
        \begin{enumerate}
            \item If $w_0 \notin I_2(B(\varphi'')$, then the $B$-ideal,
            \begin{align*}
                \mathcal{K'}=(\overline{z^2w_0})+(\{\overline{z \a_i} ; 1 \leq i \leq n-3\})+(\{\overline{-aw_{n-1}\a_{j+1}+bw_{n-1}\a_j} ; 1\leq j \leq {n-4}\}).
            \end{align*}
            \item If $w_0 \in I_2(B(\varphi''))$, then the $B$-ideal,
            \begin{align*}
                \mathcal{K'}=(\overline{z^2w_0})+(\{ \overline{z \a_i} ; 1 \leq i \leq n-3 \})+(\{ \overline{\a_i \a_{i'}} ; 1 \leq i,i' \leq n-3\})\\+(\{{\overline{bw_{n-1}(\a_{i+1}-\a_i)-aw_{n-1}(\a_{i+2}-\a_{i+1})}} ; 1 \leq i \leq n-5\}).
            \end{align*}
        \end{enumerate}
    \end{enumerate}
\end{theorem}
\begin{proof}
    Using the Grobner basis technique and tracing the proof of \Cref{w_0 is regular over ideal}, we have $\overline{x}$  regular over the candidate (say $N$) for $\mathcal{K'}$ in each case. Thus, we have $N_p=\mathcal{K'}_p$ for all $p \in \Ass(N)$. Hence $N=\mathcal{K'}$.
\end{proof}

Define  $\mathcal{D}'= \frac {\overline{l_{n-1}}\overline{\mathcal{K'}}}{\overline{z^2w_0}}$, then 
$\mathcal{D}'$ is well defined $B$-ideal (See for example \cite[Proposition 6.5]{SurajMukundan24}). Also $\overline{\mathcal{A}}$ is prime ideal and $\overline{l_{n-1}}\in \overline{\mathcal{A}}$ but $\overline{z},\overline{w_0}\notin \overline{\mathcal{A}}$ therefore $\mathcal{D}' \subseteq \overline{\mathcal{A}}$.


\begin{theorem}\label{equality of D' and A in case iii}
Assume the \Cref{Main Setting}, the $B$-ideals $\mathcal{D}'$ and $\mathcal{\overline{A}}$ are equal.    
\end{theorem}
\begin{proof}
Proof is similar to the proof of \Cref{another characterization of defining ideal of Rees algebra}.    
\end{proof}


\section{Description of Defining ideal of Rees algebra when presentation matrix is in Case III}\label{section 6 and rees algebra in case iii}
Assume the \Cref{Main Setting}, and that the presentation matrix $\varphi$ is of Case III (see \Cref{case i and ii presentation matrix}).  %{In this section we will prove $I$ is not of linear type.}
In this section we will show there exist some non-zero element in $\mathcal{A}$ which does not belongs to $\mathcal{L}$ and that this element can be computed from the Jacobian dual matrix. Also we will compute the defining ideal $\mathcal{A}$ of Rees algebra $\rees(I)$ explicitly and prove that it is Cohen-Macaulay.

\begin{notation}
Consider the $S$-ideal, $(x,y,z^2w_0)$ then $\underline{w} \cdot \varphi = (x,y,z^2w_0) \cdot B(\varphi)$. Here $B(\varphi)$ is Jacobian dual of presentation matrix $\varphi$ with respect to ideal $(x,y,z^2w_0)$. Throughout this section we will follow this definition of Jacobian dual.

Let $J=(l_1,\dots,l_{n-2}) \subseteq \mathcal{L}$ and $\varphi''$ be $n \times (n-2)$ submatrix of $\varphi$, obtained after deleting the last column of $\varphi$. From presentation matrix $\varphi$ (Case III of \Cref{case i and ii presentation matrix}), we have $J \subseteq (x,y)$ thus $[l_1~\cdots~l_{n-2}]=[x~y] \cdot B(\varphi'')$. Define the $S$-ideal, $\mathcal{J}=J:(x,y)$ and consider the quotient ring $B=S/{\mathcal{J}}$. Let $f \in S$ and  $\overline{f}$ be image of $f$ in the ring $B$. Define the $B$-ideal,
\begin{align*}
    \overline{\mathcal{K}}'=(\overline{z^2w_0}) : (\overline{x,y,z^2w_0}).
\end{align*}
\end{notation}

\begin{observation}
    With the assumption of \Cref{Main Setting}, the $S$-ideal, $\mathcal{J}$ is Cohen-Macaulay prime ideal of height $n-2$ and 
    \begin{align*}
        \mathcal{J}=J:(x,y)^{\infty}=J+I_2(B(\phi'')).
    \end{align*}
    Furthermore, the ideal $I_2(B(\phi''))$ is prime ideal of height $n-3$.
\end{observation}
\begin{proof}
 From \Cref{colon ideal related to defining ideal of Rees algebra}, we have $\mathcal{A}=\mathcal{L}:(x,y)^{\infty}$. Thus \cite[Proposition 2.2, Theorem 2.3] {BoswellMukundan16} imply 
 \begin{align*}
     \mathcal{J}=J:(x,y)^{\infty}=J:(x,y)=J+I_2(B(\varphi'')),
 \end{align*}
is Cohen-Macaulay prime ideal of height $n-2$. And, hence $I_2(B(\varphi''))$ is prime ideal of height $n-3$.
\end{proof}

\begin{observation}
    The ring $B$ is Cohen-Macaulay domain of dimension $5$.
\end{observation}
\begin{proof}
    Since $\mathcal{J}$ is Cohen-Macaulay prime ideal of the height $n-2$, therefore $B$ is Cohen-Macaulay domain of dimension 5.
\end{proof}

\begin{theorem}\label{K in case III}
    With the assumption of \Cref{Main Setting}. The $B$-ideal,
    \begin{align*}
        \overline{\mathcal{K}}''=(\overline{z^2w_0})
        :(\overline{x,y,z^2w_0})=(\overline{z^2w_0}).
    \end{align*}
    Also, $\overline{\mathcal{K}}''$ is Cohen-Macaulay ideal of height one.
\end{theorem}
\begin{proof}
    The ring $B$ is Cohen-Macaulay domain. Thus the $B$-ideal, $(\overline{z^2w_0})$ is Cohen-Macaulay ideal of height one.
    Now we will prove that the $B$-ideal, $(\overline{x,y,z^2w_0})$ is of height two, that is the $S$-ideal, $\mathcal{J}+(x,y,z^2w_0)$ is of height $n$. Let $Q$ be a minimal prime of $\mathcal{J}+(x,y,z^2w_0)$ then $\mathcal{J}+(x,y,z^2w_0) \subseteq Q$, that is, $(x,y,z^2w_0) +I_2(B(\varphi'')) \subseteq Q$. Thus either $(x,y,z)+I_2(B(\varphi'')) \subseteq Q$ or $(x,y,w_0)+I_2(B(\varphi'')) \subseteq Q$. Since $I_2(B(\varphi'')) \subseteq \k[\underline{w}]$ is prime ideal of of height $n-3$ therefore $(x,y,z)+I_2(B(\varphi''))$ and $(x,y,w_0)+I_2(B(\varphi''))$ is of height $n$. Thus $\mathcal{J}+(x,y,z^2w_0)$ is of height $n$ and hence $(\overline{x,y,z^2w_0})$ is of height two.

    Now for any $P \in \Ass{(\overline{z^2w_0})}$, $\hgt P=1$ and this implies $P \notin \Ass{(\overline{x,y,z^2w_0})}$. Thus $(\overline{x,y,z^2w_0})_P=B_P$, for all $P \in \Ass{(\overline{z^2w_0})}$. So, for all $P \in \Ass{(\overline{z^2w_0})}$ we have,
    \begin{align*}
        (\overline{z^2w_0})_P \subseteq (\overline{z^2w_0})_P : (\overline{x,y,z^2w_0})_P=(\overline{z^2w_0})_P:B_P=(\overline{z^2w_0})_P.
    \end{align*}
    Hence, $\overline{\mathcal{K}}''=(\overline{z^2w_0})$ is Cohen-Macaulay ideal of height one.
\end{proof}
    Consider $\mathcal{D}=\frac{\overline{l_{n-1}}{\overline{\mathcal{K}}''}}{\overline{z^2w_0}}$, \Cref{K in case III} implies, $\mathcal{D}$ is well defined $B$-ideal. Also $\overline{l_{n-1}} \in \overline{\mathcal{A}}$, so $\overline{l_{n-1}{\mathcal{K}}}'' \subseteq \overline{\mathcal{A}}$. That is, $\overline{z^2w_0}{\mathcal{D}} \subseteq \overline{\mathcal{A}}$. Since $\overline{\mathcal{A}}$ is the prime ideal and $\overline{z^2w_0} \notin \overline{\mathcal{A}}$ therefore, $\mathcal{D} \subseteq \overline{\mathcal{A}}$.

 \begin{theorem}\label{equality of D and A in case iii}
     With the assumption of \Cref{Main Setting}. The $B$-ideal, $\mathcal{D}$ and $\overline{\mathcal{A}}$ are equal.
 \end{theorem}
\begin{proof}
 Proof is similar to the proof of \Cref{another characterization of defining ideal of Rees algebra}.   
\end{proof}


\begin{theorem}\label{explicit expression for defining ideal of Rees algebra}
 Assume the \Cref{Main Setting}, then the defining ideal of the Rees algebra, $$\mathcal{A}= \mathcal{L}+ I_3(B(\varphi)).$$
\end{theorem}
\begin{proof}
Follows from \Cref{K in case III}, \Cref{equality of D and A in case iii} and the fact that $I_2(B(\varphi''))=I_3(B(\varphi))$.
\end{proof}


\begin{cor}
    The Rees algebra $\mathcal{R}(I)$ is Cohen-Macaulay.
\end{cor}

