%-------------------------------------------------------------------------------
\subsection{Preliminaries and Notation}

Throughout, we set the primary costate
\[
  \lambda := \nabla_x V^{\pi,c}.
\]
For any admissible control~$(\pi,c)$ the sub‑value function~$V^{\pi,c}$ solves
\[
  -\partial_t V^{\pi,c}
  = \cL_{\pi,c}[V^{\pi,c}] + f_{\pi,c},
  \qquad
  V^{\pi,c}(T,\cdot)=g,
\]
with oblique‑derivative boundary $\partial_{\mathbf n}V=0$ on~$\partial\Omega$ to match the Skorokhod reflection \citep{lieberman1996second}. Error quantities on~$Q_T:=(0,T)\times\Omega$:
\[
  \begin{aligned}
    h &:= (a_{\pi,c}-a_*,\,b_{\pi,c}-b_*),
    &\quad E_h &:= \|h\|_{L^{q,p}},\\
    E_f &:= \bigl\|e^{-\delta t}(U(c^*)-U(c))\bigr\|_{L^{q,p}},
    &\quad E_v &:= \|\nabla V^{\pi,c}-\nabla V^*\|_{L^{q,p}},\\
    \varepsilon &:= \|\mathcal R_{\mathrm{FOC}}\|_{L^{q,p}}.&&
  \end{aligned}
\]

%-------------------------------------------------------------------------------
\subsection{Minimal Assumptions}\label{subsec:assumption_publishable}

\begin{assumption}[Baseline Well‑Posedness]\label{ass:baseline}
Fix $T>0$, a $C^{1,1}$ domain~$\Omega$, mixed‑norm exponents $p>d+2,\;q\ge2$ and a compact cylinder
\[
  \mathcal D
  := [0,T]\times[\underline x,\bar x]\times\{\|y\|\le R_Y\}.
\]
There exist positive constants $\underline\nu,\overline\nu,L_{\mathrm{coef}},C_{\mathrm{MR}},\eta_0$ such that
\begin{enumerate}[leftmargin=1.8em,itemsep=4pt]
\item\textbf{Reflected SDE.}
  The Skorokhod‑reflected SDE with inward normal~$\mathbf n\in C^{1,\alpha}$
  is well posed.

\item\textbf{Uniform ellipticity \& VMO coefficients.}
  $\underline\nu|\xi|^2\!\le\!\xi^\top a_{\pi,c}\xi\!\le\!\overline\nu|\xi|^2$
  and $(a_{\pi,c},b_{\pi,c})$ have VMO/BMO bounds.

\item\textbf{VMO‑smallness.}
  On every cylinder $Q_r\subset\mathcal D$ with $r\le R_0$ the VMO modulus
  is $\le\eta_0<\bar\eta(d,p,q)$ of \citet{dong2009parabolic}.

\item\textbf{Costate band \& utility.}
  $\underline\lambda\le\lambda\le\bar\lambda$ on~$\mathcal D$ and
  $U(c)=c^{1-\gamma}/(1-\gamma)$, $\gamma>0,\gamma\neq1$.
\end{enumerate}
\end{assumption}

%-------------------------------------------------------------------------------
\subsection{Automatic Properties of the Model}

\begin{lemma}[Strong concavity of the Hamiltonian]\label{lem:strong_concavity}
Under Assumption~\ref{ass:baseline} with HARA utility parameters $(a,b,\gamma)$ and bounded controls $\|\pi_t\|\le\Pi_{\max},\;0\le c_t\le\xi\bar x$, the Hamiltonian satisfies
\[
  -\nabla^2_{(\pi,c)}H(t,x,y,\lambda,\eta,\pi,c)
  \;\succeq\;\underline\Lambda I_{n+1},
\]
where $\underline\Lambda>0$ depends only on $(a,b,\gamma,\Pi_{\max},\underline\lambda,\bar\lambda)$.
\end{lemma}
\begin{proof}
HARA implies $U''(c)\le -\kappa_0<0$ on the compact $c$‑interval, while the quadratic portfolio term contributes $-x^2\lambda\,\sigma^\top\Sigma\sigma\preceq-\kappa_1 I_n$ since $x\in[\underline x,\bar x]$ and $\Sigma\succ0$. Summing gives the claim.
\end{proof}

\begin{lemma}[Maximal regularity for $V^{\pi,c}$]\label{lem:max_regularity}
Under Assumption~\ref{ass:baseline} and the VMO‑smallness $\eta_0<\bar\eta(d,p,q)$, both $V^{\pi,c}$ and $V^*$ lie in $W^{2,1}_{q,p}(Q_T)$ with
\[
  \|D^2V^{\pi,c}\|_{L^{q,p}}+\|\partial_tV^{\pi,c}\|_{L^{q,p}}
  \;\le\;
  C_{\mathrm{MR}}\bigl(\|f_{\pi,c}\|_{L^{q,p}}
        +\|g\|_{W^{2-2/p}_q}\bigr).
\]
\end{lemma}
\begin{proof}
Apply \citet{dong2009parabolic} to the non‑divergence PDE for $V^{\pi,c}$ using the VMO modulus bound, uniform ellipticity and bounded coefficients. The same argument holds for $V^*$.
\end{proof}

%-------------------------------------------------------------------------------
\subsection{Foundational Lemmata}

\begin{lemma}[FOC‑Reduction: Coefficient Gap]\label{lem:foc_reduction_publishable}
Under Assumption~\ref{ass:baseline} and Lemma~\ref{lem:strong_concavity},
\[
  E_h \;\le\; L_H\,E_v \;+\; C_{\mathrm{FOC}}\,\varepsilon.
\]
\end{lemma}
\begin{proof}
The strong concavity of the Hamiltonian (Lemma~\ref{lem:strong_concavity}) implies that its gradient with respect to the control, $G(u;\lambda) := \nabla_u H(u, \lambda)$, is a strongly monotone operator in $u$ for a fixed state $\lambda$. By the Minty–Browder theorem \citep{minty1962monotone, browder1965nonlinear}, such an operator has a Lipschitz-continuous inverse. This allows us to bound the gap in controls by the gap in costates ($E_v$) and the FOC residual ($\varepsilon$), which after applying the control-to-coefficient Lipschitz bound, yields the stated inequality.
\end{proof}

\begin{lemma}[Source‑Gap]\label{lem:source_gap_publishable}
Under Assumption~\ref{ass:baseline},
\[
  E_f \;\le\; C_f' E_v + C_f \varepsilon.
\]
\end{lemma}
\begin{proof}
Compactness of the costate band and the properties of HARA utility imply that both $U$ and $(U')^{-1}$ are Lipschitz continuous on the relevant compact intervals. The result follows from a standard mean-value argument on the first-order conditions for consumption.
\end{proof}

\begin{lemma}[Gradient Stability]\label{lem:gradient_stab_publishable}
With Lemma~\ref{lem:max_regularity} in force,
\[
  E_v \;\le\; C_S(E_h+E_f).
\]
\end{lemma}
\begin{proof}
Let $W:=V^{\pi,c}-V^*$. The function $W$ solves a linear parabolic PDE whose source term is determined by the coefficient and source gaps ($h$ and $f$). By the Dong–Kim gradient estimate for PDEs with VMO coefficients, a core result of maximal regularity theory, the gradient of the solution is bounded by the norm of the source term, which gives $\|\nabla W\|_{L^{q,p}}\le C_S(E_h+E_f)$.
\end{proof}

\begin{proposition}[Coupled Error Resolution]\label{prop:coupled_publishable}
There exists $C_v''$ such that $E_v\le C_v''\,\varepsilon$.
\end{proposition}
\begin{proof}
Combining the three preceding lemmas yields the recursive inequality $E_v\le\alpha E_v+\beta\varepsilon$, where $\alpha=C_S(L_H+C_f')$. For a sufficiently small time interval $\Delta t \le \Delta_\star$, PDE theory ensures that the constant $\alpha < 1$. This turns the mapping $T(E_v) = \alpha E_v + \beta\varepsilon$ into a contraction. By the contraction mapping principle, this recursion converges. Iterating this argument over the $\lceil T/\Delta_\star\rceil$ time slabs that cover the full horizon $[0,T]$ yields a final bound for $E_v$ that depends only on $\varepsilon$.
\end{proof}

%-------------------------------------------------------------------------------
\subsection{Final Policy‑Gap Theorem}

\begin{definition}[BPTT Error]\label{def:bptt_error_publishable}
$\displaystyle
  \delta_{\mathrm{BPTT}}
  :=\|\widehat\lambda-\nabla V^{\pi,c}\|_{L^{q,p}}
  \le \kappa_1\Delta t+\kappa_2/\sqrt M,$ with constants depending on the value function regularity established in Lemma~\ref{lem:max_regularity}.
\end{definition}

\begin{theoremrestate}
\textbf{Theorem \ref{thm:policy_gap_formal} (Policy Gap Bound).} 
\itshape
Let $\pi^*$ be the true optimal policy and $\widehat\pi$ be the policy generated by the P-PGDPO algorithm using a time step $\Delta t$ and batch size $M$. Under the regularity conditions specified in Assumption~\ref{ass:baseline} in the Appendix, the gap between the P-PGDPO policy and the true optimum is bounded as follows:
\[
     \|\widehat\pi-\pi^*\|_{L^{q,p}}
     \;\le\;
     C_{\text{tot}} \left( \varepsilon + \kappa_1 \Delta t + \frac{\kappa_2}{\sqrt{M}} \right)
\]
where:
\begin{itemize}[leftmargin=*,labelindent=5pt,itemsep=2pt]
    \item \(\varepsilon\) is the $L^{q,p}$-norm of the Pontryagin FOC residual from the warm-up policy.
    \item \(\kappa_1, \kappa_2\) are positive constants governing the BPTT estimation error, which arises from time discretization (error proportional to \(\Delta t\)) and Monte Carlo sampling (error proportional to \(1/\sqrt{M}\)).
    \item \(C_{\text{tot}}\) is a positive constant that depends on the model parameters but not on $\varepsilon$, $\Delta t$, or $M$.
\end{itemize}
\end{theoremrestate}

\begin{proof}
The proof follows from the triangle inequality:
$
  \|\widehat\pi-\pi^*\|
  \le L_F\bigl(\|\widehat\lambda-\nabla V^{\pi,c}\|+\|\nabla V^{\pi,c}-\nabla V^*\|\bigr)
  \le L_F(\delta_{\mathrm{BPTT}}+E_v).
$
Substituting the bounds for $\delta_{\mathrm{BPTT}}$ from Definition~\ref{def:bptt_error_publishable} and for $E_v$ from Proposition~\ref{prop:coupled_publishable} yields the final result.
\end{proof}


\section{Detailed Experimental Setup}
\label{app:experimental_setup_details}

This appendix provides the detailed setup for the numerical experiments presented in Section~\ref{sec:numerical_experiments}.

\subsection{Parameter Values}
\label{app:param_values} % Renamed label slightly for appendix context

The experiments consider the objective of maximizing the expected utility of terminal wealth \(X_T\), \(J = \mathbb{E}[U(X_T)]\), using a CRRA utility function \(U(x) = x^{1-\gamma}/(1-\gamma)\) with a relative risk aversion coefficient \(\gamma = 2.0\). The fixed time horizon is \(T = 1.5\).

Unless otherwise specified, the model parameters (for the model described in Section~\ref{sec:multiasset_multifactor_KO}) are generated based on the asset dimension \(n\) and factor dimension \(k\) using the following process (seeded for reproducibility, e.g., `seed=42'):
\begin{itemize}
    \item Risk-free rate: \(r = 0.03\).
    \item State process parameters (for the \(k\)-dimensional OU process \(\mathbf{Y}_t\)):
        \begin{itemize}
            \item Mean-reversion speeds: \(\boldsymbol{\kappa}_Y = \mathrm{diag}(2.0, 2.5, \dots, 2.0 + (k-1)0.5)\).
            \item Long-term means: \(\boldsymbol{\theta}_Y\) components drawn uniformly from \(U(0.2, 0.4)\).
            \item Factor volatilities: \(\boldsymbol{\sigma}_Y\) diagonal elements drawn uniformly from \(U(0.3, 0.5)\).
        \end{itemize}
    \item Asset parameters (for the \(n\) risky assets):
        \begin{itemize}
            \item Volatilities: \(\boldsymbol{\sigma} \in \mathbb{R}^n\) components drawn uniformly from \(U(0.1, 0.5)\).
            \item Factor loadings (\(\boldsymbol{\alpha} \in \mathbb{R}^{n \times k}\)): For each asset \(i = 1, \dots, n\), the \(k\)-dimensional row vector of factor loadings \(\boldsymbol{\alpha}_i^\top = (\alpha_{i1}, \dots, \alpha_{ik})\) is drawn independently from a Dirichlet distribution. This is done using `scipy.stats.dirichlet` with a concentration parameter vector consisting of \(k\) ones (\(\mathbf{1}_k = [1.0, \dots, 1.0]\)). Consequently, for each asset \(i\), all loadings are non-negative (\(\alpha_{ij} \ge 0\)) and they sum to unity (\(\sum_{j=1}^k \alpha_{ij} = 1\)). (Note: These loadings define the risk premium structure \(\boldsymbol{\mu}(t, \mathbf{Y}_t) = r\mathbf{1} + \mathrm{diag}(\boldsymbol{\sigma}) \boldsymbol{\alpha} \mathbf{Y}_t\)).
        \end{itemize}
    \item Correlation structure: The generation process aims to produce realistic correlation parameters while ensuring the overall block correlation matrix remains positive definite, which is crucial for stable simulations. This involves: % Added Rationale
        \begin{itemize}
            \item Asset correlation \(\Psi\) (\(n \times n\)) generated based on a latent factor structure ensuring validity.
            \item Factor correlation \(\Phi_Y\) (\(k \times k\)) generated as a random correlation matrix.
            \item Cross-correlation \(\boldsymbol{\rho}_Y\) (\(n \times k\)) components drawn uniformly from \(U(-0.2, 0.2)\).
            \item The full \((n+k) \times (n+k)\) block correlation matrix \(\begin{pmatrix} \Psi & \rho_Y \\ \rho_Y^\top & \Phi_Y \end{pmatrix}\) is constructed and numerically adjusted (e.g., via minimal diagonal loading) if necessary to ensure positive definiteness (tolerance \(10^{-6}\)).
        \end{itemize}
\end{itemize}
The specific values generated by the seed are used consistently across experiments for given \(n\) and \(k\).

\subsection{PG-DPO Implementation Details}
\label{app:pgdpo_impl} % Renamed label slightly

We implement the Baseline PG-DPO algorithm using PyTorch.
\begin{itemize}
    \item \textbf{Policy Network (\(\boldsymbol{\pi}_\theta\)):} The policy network  consists of an input layer taking the current wealth \(W_t\), current time \(t\), and state vector \(\mathbf{Y}_t\) (total \(2+k\) inputs), followed by three hidden layers with 200 units each and LeakyReLU activation, and an output layer producing the \(n\)-dimensional portfolio weight vector \(\boldsymbol{\pi}_\theta\).
    \item \textbf{Optimizer:} Adam optimizer with a learning rate of \(1 \times 10^{-5}\).
    \item \textbf{Training:}
        \begin{itemize}
            \item Total epochs: \(10,000\).
            \item Batch size (\(M\)): \(1,000\).
            \item Time discretization steps (\(N\)): \(20\).
            % --- Revised Initial State Sampling for Y_0 (min of lower bounds, max of upper bounds) ---
            \item Initial state sampling (\(\eta\)): For each trajectory in a batch, the initial time \(t_0\) is drawn uniformly from \([0, T)\), initial wealth \(W_0\) from \(U(0.1, 3.0)\). The initial state variables \(\mathbf{Y}_0 = (Y_{0,1}, \dots, Y_{0,k})^\top\) are sampled such that each component \(Y_{0,i}\) is drawn independently and uniformly from a single common range \([Y_{\min}, Y_{\max}]\). This range is determined by the minimum lower bound and the maximum upper bound observed across all individual factors' typical \( \pm 3\sigma \) intervals:
            \[ Y_{\min} = \min_{i=1,\dots,k}(\theta_{Y,i} - 3\sigma_{Y,ii}), \quad Y_{\max} = \max_{i=1,\dots,k}(\theta_{Y,i} + 3\sigma_{Y,ii}), \]
            where \(\theta_{Y,i}\) is the long-term mean and \(\sigma_{Y,ii}\) is the instantaneous volatility parameter for the \(i\)-th factor. The simulation then runs forward from \(t_0\) to the fixed horizon \(T\) using \(N=20\) time steps, with step size \(\Delta t = (T - t_0) / N\). This approach ensures the policy is trained effectively across the entire time interval \([0, T]\) and a relevant hypercube in the state space defined by the collective factor dynamics.
            % --- End Revised ---
            \item Variance Reduction: Antithetic variates used.
            \item Wealth constraint: Simulated wealth \(W_t\) clamped at lower bound \(0.1\).
        \end{itemize}
    \item \textbf{Costate Estimation (for Two-Stage Evaluation):} During periodic evaluation, costate \(\lambda\) and derivatives \(\partial_x \lambda, \partial_{\mathbf{Y}} \lambda\) are computed via BPTT (`torch.autograd.grad') applied to Monte Carlo estimates of the expected terminal utility starting from evaluation points \((t_k, W_k, \mathbf{Y}_k)\).
\end{itemize}


\subsection{Benchmark Solution and Evaluation}
\label{app:benchmark_eval} % Renamed label slightly

As mentioned, the chosen multi-factor OU model allows for a semi-analytical benchmark solution. It is important to note that these experiments focus solely on the terminal wealth objective (\(J = \mathbb{E}[U(X_T)]\)), and thus do not include optimization or a neural network for the consumption policy \(C_\phi\). This simplification is made specifically to enable direct comparison with the semi-analytical benchmark solution derived from the HJB equation, which is readily available for the terminal wealth problem in this affine setting. % Added explanation for no C_phi
\begin{itemize}
    \item \textbf{Benchmark Computation:} The system of ODEs (including a matrix Riccati equation) associated with the HJB equation for this terminal wealth problem (Appendix~\ref{app:analytic_MF}) is solved numerically backwards from the fixed horizon \(T\) using `scipy.integrate.solve\_ivp' (`Radau' method) to obtain the coefficients determining the value function and the optimal policy \(\boldsymbol{\pi}^*(t, W_t, \mathbf{Y}_t)\).
    \item \textbf{Interpolation:} The benchmark policy (total, myopic, and hedging components) is pre-computed on a grid over \((t, W_t, \mathbf{Y}_t)\) space and stored using `scipy.interpolate.RegularGrid Interpolator' for efficient lookup.
    \item \textbf{Evaluation Metrics:} Performance is evaluated via the Root Mean Squared Error (RMSE) between the policies generated by (i) Baseline PG-DPO (\(\boldsymbol{\pi}_\theta\)) and the benchmark (\(\boldsymbol{\pi}^*\)), and (ii) Two-Stage PG-DPO (using Eq.~\eqref{eq:pi_star} with BPTT-estimated costates) and the benchmark (\(\boldsymbol{\pi}^*\)). RMSEs are computed for total, myopic, and hedging components.
    \item \textbf{Visualization:} Contour plots compare the learned policies and the benchmark over the state space (typically time \(t\) vs. one state variable \(Y_k\)), alongside error plots and costate visualizations.
\end{itemize}
All computations are performed using PyTorch on an NVIDIA A6000 GPU. % Added specific GPU

\subsection{Deep BSDE Implementation Details}
\label{app:deep_bsde_impl}

The Deep BSDE method, serving as a benchmark, was implemented based on the standard framework by \citet{Han2018Solving} and \citet{E2017Deep}. This approach reformulates the problem's PDE as a backward stochastic differential equation (BSDE) and approximates its solution components using neural networks. Our PyTorch implementation addresses the multi-asset, multi-factor portfolio optimization problem from Section~\ref{sec:multiasset_multifactor_KO}.

\begin{itemize}
\item \textbf{Network Architectures:} Two main feedforward neural networks with Tanh activations are utilized:
\begin{itemize}
\item \textbf{V0Net:} Approximates the value function at the initial time of a path. Its output, denoted \(\hat{V}_{t_0}\), is an approximation of the true value, \(V(t_0, X_{t_0}, \mathbf{Y}_{t_0})\). It takes the initial state \((t_0, \log X_{t_0}, \mathbf{Y}_{t_0})\) as input and produces a scalar output (with a final negative softplus transformation). It typically uses 2 hidden layers of 64 units.
\item \textbf{ZNet:} Approximates \(\boldsymbol{Z}_t\), which relates to the scaled gradient of the value function concerning the underlying Brownian motions, at each time step \(t\). It takes the current state \((t, \log X_t, \mathbf{Y}_t)\) as input and outputs an \((n+k)\)-dimensional vector, representing \(\boldsymbol{Z}^X_t \in \mathbb{R}^n\) and \(\boldsymbol{Z}^Y_t \in \mathbb{R}^k\). It typically uses 3 hidden layers of 128 units.
\end{itemize}

\item \textbf{Policy Derivation:} The optimal portfolio \(\boldsymbol{\pi}_t\) is not a direct network output but is dynamically constructed at each step. For CRRA utility, the FOC-derived policy simplifies significantly. The simplification stems from the value function's known separable form in wealth (i.e., \(V \propto X_t^{1-\gamma}\)). This property allows the general intertemporal hedging demand term, \(-\frac{1}{X_t V_{xx}}\Sigma^{-1}(\boldsymbol{\sigma\rho\sigma_Y})V_{x\mathbf{y}}\), to be analytically transformed into the more tractable expression \(\frac{1}{\gamma} \Sigma^{-1} \left( \boldsymbol{\sigma} \boldsymbol{\rho} \right) \left(\boldsymbol{\sigma}_Y \frac{\nabla_{\mathbf{y}}V}{V}\right)\).

The Deep BSDE implementation then creates a policy by combining an analytical myopic demand with a network-based approximation of this tractable hedging term. Specifically, the core theoretical component \(\boldsymbol{\sigma}_Y \frac{\nabla_{\mathbf{y}}V}{V}\) is approximated by the ratio of neural network outputs, \(\frac{\boldsymbol{Z}^Y_t}{\hat{V}_t}\).\footnote{In our BSDE parameterization, the network \texttt{ZNet} learns \(\boldsymbol{Z}^Y_t \approx \nabla_{\mathbf{y}}V \cdot \boldsymbol{\sigma}_Y\), where \(\boldsymbol{\sigma}_Y\) is the diagonal matrix of factor volatilities. The ratio in the policy formula thus correctly approximates the required theoretical term \(\frac{\nabla_{\mathbf{y}}V \cdot \boldsymbol{\sigma}_Y}{V}\).} This leads to the final implemented formula:
\begin{equation}
\boldsymbol{\pi}_t = \underbrace{\frac{1}{\gamma} \Sigma^{-1} \left( \boldsymbol{\sigma} \mathbf{A} \mathbf{Y}_t \right)}_{\text{Myopic Demand}} \quad+ \underbrace{\frac{1}{\gamma} \Sigma^{-1} \left( \boldsymbol{\sigma} \boldsymbol{\rho} \frac{\boldsymbol{Z}^Y_t}{\hat{V}_t} \right)}_{\text{Intertemporal Hedging Demand}}.
\end{equation}
This structure is explicitly designed to capture both demand components, but as shown in our numerical results, the accuracy of this network-based approximation can be a practical point of failure.

\item \textbf{Loss Function:} The training objective is to accurately match the BSDE's terminal condition. For each sample path starting at state \((t_0, X_{t_0}, \mathbf{Y}_{t_0})\), the `V0Net' provides an initial value estimate, \(\hat{V}_{t_0}\). This single initial estimate is then \textbf{evolved forward to the terminal time \(T\) using the discrete-time BSDE formula}, which incorporates the outputs of the `ZNet' at each intermediate time step. This process yields a \textbf{simulated terminal value} for that specific path, which we denote \(\hat{V}_T^{\text{sim}}\). The loss is then calculated as the mean squared error between this simulated terminal value and the \textbf{true terminal condition}—the utility of the wealth \(U(X_T)\) realized at the end of that same path:
$$ \mathcal{L} = \mathbb{E}\left[ \left( \hat{V}_T^{\text{sim}} - U(X_T) \right)^2 \right]. $$
The parameters of both `V0Net' and `ZNet' are optimized to minimize this terminal loss, effectively forcing the initial prediction \(\hat{V}_{t_0}\) to be consistent with the terminal utility value through the lens of the BSDE dynamics.

\item \textbf{Training Details:} The networks are trained for \(10,000\) epochs using the Adam optimizer (initial learning rate \(3 \times 10^{-5}\), with a multi-step decay scheduler) and a batch size of \(1,024\). Each BSDE path is discretized into \(N_{\text{BSDE}}=80\) time steps. Gradient clipping (norm 2.0) and bounding of portfolio weights are applied to enhance training stability.

\item \textbf{Initial State Sampling:} For each training path, the initial time \(t_0\) is sampled uniformly from the discrete time steps over \([0, T-\Delta t]\). The initial wealth \(X_0\) is drawn uniformly from \([0.1, 3.0]\), and initial factor states \(\mathbf{Y}_0\) are sampled uniformly from a hyperrectangle representing their typical dynamic range (e.g., based on \(\pm 3\) stationary standard deviations around their long-term means).

\end{itemize}
The implementation uses PyTorch and is executed on the same NVIDIA A6000 GPU hardware as the PG-DPO experiments to ensure a fair comparison.

