\section{The weighted conditional type operators }%=======================================================================================
In this section, we focus our investigation on the class of $k$-quasi $n$-power posinormal operators within the specific context of weighted conditional type operators. These operators, defined on $L^2(\Sigma)$ spaces, play a significant role in various areas of functional analysis and probability theory.

The weighted conditional type operator $\tTwu = M_wEM_u$, where $w,u$ are measurable weight functions and $E$ represents the conditional expectation operator, has been extensively studied in recent literature \cite{Azimi, Estaremi1, Estaremi2}. Our primary objective is to establish necessary and sufficient conditions under which these operators belong to the $k$-quasi $n$-power posinormal class.

We begin by recalling several key results from \cite{EJ} that will be fundamental to our analysis. These include important properties of the polar decomposition and norm characterizations of $\tTwu$. Building upon these foundations, we will:

\begin{itemize}
    \item Establish precise conditions for the posinormality of $\tTwu$ operators
    \item Extend these results to the $n$-power posinormal case
    \item Derive complete characterizations for the $k$-quasi $n$-power posinormal case
\end{itemize}

Our approach combines techniques from operator theory with measure-theoretic considerations, allowing us to obtain concrete criteria expressed in terms of the weight functions $w,u$ and their conditional expectations. The results in this section not only contribute to the abstract theory of posinormal operators but also have potential applications in the study of stochastic processes and functional calculus.

\begin{lemma}\label{Weighted1}\cite{EJ}.
  Let $T_{w,u}= M_{w}EM_{u}$ be a bounded operator on $L^2(\Sigma)$ and $m\in (0, \infty)$. Then
   $(\tTwu^*\tTwu)^m=M_{\bar{u}(E(|u|^2))^{m-1}\chi_{S}(E(|w|^2))^m}EM_{u}$ and
   $(\tTwu\tTwu^*)^m=M_{w(E(|w|^2))^{m-1}\chi_{G}(E(|u|^2))^m}EM_{\bar{w}}$,
where $S=S(E(|u|^2))$ and $G=S(E(|w|^2))$.
\end{lemma}
%===================================================================
\begin{theorem}\cite{EJ}.
  The unique polar decomposition of bounded operator $T_{w,u}= M_{w}EM_{u}$ is $U|T_{w,u}|$,
   where $|T_{w,u}|(f)=\bra{\frac{E(|w|^2)}{E(|u|^2)}}^{\frac{1}{2}}\chi_S\bar{u}E(uf)$
  and $$U(f)=\bra{\frac{\chi_{S\cap G}}{E(|w|^2)E(|u|^2)}}^{\frac{1}{2}}wE(uf),$$
for all $f\in L^2(\Sigma)$.
\end{theorem}
%============================================================================
\begin{theorem} Let operator $T_{w,u}$  be a bounded on $L^2(\Sigma)$ and $\lambda>0$. Then
\begin{enumerate}
  \item [(i)] If for each $f\in L^2(\Sigma)$
  $$\lambda^2 E(|u|^2)E(|w|^2)\geq \overline{w}\bra{E(|u|^2)}^{\frac{1}{2}},$$
  then $T_{w,u}$ is a posinormal operator.
  \item [(ii)] If $T_{w,u}$ is a posinormal operator, then
   $$\lambda^2E(|w|^2)|E(u)|^2\geq E(|u|^2)|E(w)|^2$$
   on $S'=S(E(u)$.
   \item [(iii)] If $S=S'$, then $T$ is a posinormal if and only if $\lambda^2E(|w|^2)|E(u)|^2\geq E(|u|^2)|E(w)|^2$.
\end{enumerate}
\end{theorem}
\begin{proof}(i) For each $f\in L^2(\Sigma)$, a simple calculation and Lemma \ref{Weighted1} shows that
$$|\tTwu|^2(f)=E(|w|^2)\chi_S\bar{u}E(uf), \,\,\, |\tTwu^*|^2(f)=E(|u|^2)wE(\bar{w}f).$$
So for every $f\in L^2(\Sigma)$ and $\lambda>0$ we have,
\begin{eqnarray*}
% \nonumber to remove numbering (before each equation)
  \seq{\lambda^2|\tTwu|^2(f)-|\tTwu^*|^2(f),f} &=&\int_{X}\bra{\lambda^2E(|w|^2)\chi_S\bar{u}fE(uf)-E(|u|^2)wfE(\bar{w}f)}\,d\mu \\
   &=&\int_{X}\bra{\lambda^2E(|w|^2)|E(uf)|^2-E(|u|^2)|E(\bar{w}f)|^2}\,d\mu.
\end{eqnarray*}
If $\lambda^2 E(|u|^2)E(|w|^2)\geq \overline{w}\bra{E(|u|^2)}^{\frac{1}{2}},$ then $\seq{\lambda^2|\tTwu|^2(f)-|\tTwu^*|^2(f),f}\geq 0$
for all $f\in L^2(\Sigma)$. So $\tTwu$ is a posinormal operator.\\
(ii) If $\tTwu$ is a posinormal operator, for all $f\in L^2(\Sigma)$, we have
$$\int_{X}\bra{\lambda^2E(|w|^2)|E(uf)|^2-E(|u|^2)|E(\bar{w}f)|^2}\,d\mu\geq 0.$$
Let $A\in\A$, with $0<\mu(A)<\infty$. By replacing $f$ to $\chi_A$, we have
$$\int_A\lambda^2 E(|w|^2)|E(uf)|^2-E(|u|^2)|E(\bar{w}f)|^2\,d\mu\geq 0.$$
Since $A\in\A$ is arbitrary, then $\lambda^2E(|w|^2)|E(u)|^2\geq E(|u|^2)|E(w)|^2$ on $S'=S(E(u)$.\\
(iii) It follows from (i) and (ii).
\end{proof}
%=================================================================================
\begin{theorem} Let operator $T_{w,u}$  be a bounded on $L^2(\Sigma)$ and $\lambda>0$. Then
  \begin{enumerate}
    \item [(i)] If for each $f\in L^2(\Sigma)$
    $$\lambda^2 E(|w|^2)|E(\overline{u}f)|^2\geq |E(wf)|^2|E(uw)|^{2n}\bra{\frac{E(|u|^2)}{(E(|w|^2))^n}}\chi_S(E(|w|^2)),$$
    then $\tTwu$ is an $n$-power posinormal operator.
    \item [(ii)] If $\tTwu$ is an  $n$-power posinormal operator, then
    $$\lambda^2 E(|w|^2)|E(u)|^2\geq |E(uw)|^{2n}\bra{\frac{E(|u|^2)}{\bra{E(|w|^2)}^{n}}}|E(w)|^2.$$
  \end{enumerate}
\end{theorem}
\begin{proof}(i) For each $f\in L^2(\Sigma)$, a simple calculation and Lemma \ref{Weighted1} shows that
\begin{eqnarray*}
% \nonumber to remove numbering (before each equation)
  |\tTwu|^2(f)&=&E(|w|^2)\chi_S\bar{u}E(uf), \,\,\mbox{and}\\
  (T_{w,u}^nT_{w,u}^{*n})(f) &=&|E(uw)|^{2n}\bra{\frac{E(|u|^2)}{\bra{E(|w|^2)}^{n}}}\chi_{S(E(|w|^2))}
\bar{w}E(wf).
\end{eqnarray*}
So for every $f\in L^2(\Sigma)$ and $\lambda>0$ we have,
\begin{eqnarray*}
% \nonumber to remove numbering (before each equation)
 && \seq{\lambda^2|\tTwu|^2(f)-(T_{w,u}^nT_{w,u}^{*n})(f),f}= \\
  &&\int_{X}\bra{\lambda^2E(|w|^2)\chi_S\bar{u}E(uf)-|E(uw)|^{2n}\bra{\frac{E(|u|^2)}{\bra{E(|w|^2)}^{n}}}\chi_{S(E(|w|^2))}
\bar{w}E(wf)}\,d\mu\\
&&\int_{X}\bra{\lambda^2E(|w|^2)\chi_S|E(uf)|^2-|E(uw)|^{2n}\bra{\frac{E(|u|^2)}{\bra{E(|w|^2)}^{n}}}\chi_{S(E(|w|^2))}
|E(wf)|^2}\,d\mu.
\end{eqnarray*}
Now, if for each $f\in L^2(\Omega)$ we assume that
$$\lambda^2E(|w|^2)\chi_S|E(uf)|^2\geq |E(uw)|^{2n}\bra{\frac{E(|u|^2)}{\bra{E(|w|^2)}^{n}}}\chi_{S(E(|w|^2))},$$
then $\tTwu$ is an $n$-power posinormal operator.\\
(ii) Assume that $\tTwu$ is an $n$-power posinormal operator. Then for each $f\in L^2(\Omega)$ and $\lambda>0$,
$$\int_{X}\bra{\lambda^2E(|w|^2)\chi_S|E(uf)|^2-|E(uw)|^{2n}\bra{\frac{E(|u|^2)}{\bra{E(|w|^2)}^{n}}}\chi_{S(E(|w|^2))}
|E(wf)|^2}\,d\mu.$$
Pick $A \in \A$, with $0 < \mu(A) <\infty$. By replacing $f$ to $\chi_A$, we have
$$\int_{X}\bra{\lambda^2E(|w|^2)\chi_S|E(u)|^2-|E(uw)|^{2n}\bra{\frac{E(|u|^2)}{\bra{E(|w|^2)}^{n}}}\chi_{S(E(|w|^2))}
|E(w)|^2}\,d\mu\geq 0.$$
Since $A\in \A$ is arbitrarily chosen, we get that
$$\lambda^2 E(|w|^2)|E(u)|^2\geq |E(uw)|^{2n}\bra{\frac{E(|u|^2)}{\bra{E(|w|^2)}^{n}}}|E(w)|^2.$$
\end{proof}
