\begin{theorem} A bounded operator $\tTwu$ on $L^2(\Sigma)$  is a $k$-quasi $n$-power posinormal operator if and only if
$$ |E(uw)|^{2k+2}\leq \lambda^2(E(|u|^2))^{2n-1}(E(|w|^2)^{2kn-1}.$$
\end{theorem}
\begin{proof} For each $f\in L^2(\Omega)$ , by calculation we have
$$\tTwu^{*k}|T_{w,u}^{*n}|\tTwu^{k}(f)=|E(uw)|^{2k+n-1}\bra{\frac{E(|u|^2)}{(E(|w|^2))^{n-1}}}^{\frac{1}{2}}\chi_{S(E(|w|^2))}\bar{w}E(wf)$$
and
$$\tTwu^{*k}|\tTwus|^2\tTwu^{k}(f)=\bra{E(|u|^2)}\bra{E(|w|^2)}^{2k}\bar{u}E(uf).$$
So, for all $f\in L^2(\Sigma)$ and $\lambda>0$ we obtain that,
\begin{eqnarray*}
% \nonumber to remove numbering (before each equation)
&&\seq{\lambda^2\tTwu^{*k}|\tTwus|^2\tTwu^{k}(f)-\tTwu^{*k}|T_{w,u}^{*n}|^2\tTwu^{k}(f),f}=\\
&&\int_{X}\left(\lambda^2\bra{E(|u|^2)}\bra{E(|w|^2)}^{2k}\bar{u}fE(uf)-|E(uw)|^{2k+n-1}\bra{\frac{E(|u|^2)}{(E(|w|^2))^{n-1}}}^{\frac{1}{2}}\right.\\
&&\left. \chi_{S(E(|w|^2))}\bar{w}fE(wf)\right)\,d\mu\\
&&\int_{X}\left(\lambda^2\bra{E(|u|^2)}\bra{E(|w|^2)}^{2k}|E(uf)|^2-|E(uw)|^{2k+n-1}\bra{\frac{E(|u|^2)}{(E(|w|^2))^{n-1}}}^{\frac{1}{2}}\right.\\
&&\left. \chi_{S(E(|w|^2))}|E(wf)|^2\right)\,d\mu.
\end{eqnarray*}
Hence, if we assume that
$$|E(uw)|^{2k+2}\leq \lambda^2(E(|u|^2))^{2n-1}(E(|w|^2)^{2kn-1},$$
then it follows that $\tTwu$ is a $k$-quasi $n$-power posinormal operator.\\
Conversely, suppose that $\tTwu$ is a $k$-quasi $n$-power posinormal operator. Then for each $f\in L^2(\Sigma)$ and $\lambda>0$,
we have
\begin{equation*}
  \left.
    \begin{array}{ll}
      \int_{X}\bra{\lambda^2\left(E(|u|^2)}\bra{E(|w|^2)}^{2k}\bar{u}fE(uf)-\right.\\
     \left. |E(uw)|^{2k+n-1}\bra{\frac{E(|u|^2)}{(E(|w|^2))^{n-1}}}^{\frac{1}{2}}\chi_{S(E(|w|^2))}\bar{w}fE(wf)\right)\,d\mu\geq 0.
    \end{array}
  \right.
\end{equation*}
Pick $A\in \A$, with $0 < \mu(A) <\infty$. By replacing $f$ to $\chi_A$, we have
\begin{equation*}
  \left.
    \begin{array}{ll}
      \int_{X}\bra{\lambda^2\left(E(|u|^2)}\bra{E(|w|^2)}^{2k}|E(uf)|^2-\right.\\
     \left. |E(uw)|^{2k+n-1}\bra{\frac{E(|u|^2)}{(E(|w|^2))^{n-1}}}^{\frac{1}{2}}\chi_{S(E(|w|^2))}|E(wf)|^2\right)\,d\mu\geq 0.
    \end{array}
  \right.
\end{equation*}
Since $A\in \A$ is arbitrarily chosen, we get that
$$\lambda^2\bra{E(|u|^2)}\bra{E(|w|^2)}^{2k}|E(uf)|^2\geq
|E(uw)|^{2k+n-1}\bra{\frac{E(|u|^2)}{(E(|w|^2))^{n-1}}}^{\frac{1}{2}}\chi_{S(E(|w|^2))}|E(wf)|^2.$$
\end{proof}
