\begin{equation}
\label{eq:selm_optika_refractivity}
R\textsubscript{M} = \left( \frac{n\textsuperscript{2}-1}{n\textsuperscript{2}+2}\right) \times V\textsubscript{M}
\end{equation}

\begin{equation}
\label{eq:selm_optika_polarizability}
\alpha = \left( \frac{3}{4 \pi N\textsubscript{A}}\right) \times R\textsubscript{M}
\end{equation}

