\title{Biting the CHERI bullet:  Blockers, Enablers and Security Implications of CHERI in Defence}

\author{\IEEEauthorblockN{Shamal Faily}
\IEEEauthorblockA{\textit{Defence Science \& Technology Laboratory} \\
Portsdown West, UK \\
sfaily@dstl.gov.uk}
