	\end{figure}



\paragraph{Первый вариант раскраски.}

Первый вариант проще, ведь матрица Гёрица состоит из одного числа $p$ --- числа пересечений областей 0 и 1: 
\begin{equation}\label{Goeritz1Tor2n}
\widetilde{G}^{T[2,p]}_I  =
\begin{pmatrix}
 \begin{array}{cc}  -p & p \\  p & -p       
 \end{array}
 \end{pmatrix}\quad \mapsto \quad G^{T[2,p]}_I  = -p\,.
\end{equation}
Тогда скобку Кауффмана сразу находим  из \eqref{Step2}\,:
% \begin{equation}
%     \mu[-p] \,,
% \end{equation}

\begin{equation}\label{GoeritzFunctionForT2p}
   \mu[G^{T[2,p]}_I ] = \mu[-p]=(-q)^{p/2}D_2^2 + P_p(q)D_2 = (-q)^{p/2}(q^{-2}+1+q^2+(-1)^pq^{-2p})\,.
\end{equation}
Известный ответ для полиномов Джонса двухнитевых узлов легко получаем с помощью нормировки \eqref{Jones}:

\begin{equation}\label{JonesT2pTrue}
    J^{T[2,p]}(q) = (-(-q)^{3/2})^{-p}\mu [G_{I}^{T[2,p]}]  =q^{-p} (q^{-2}+1+(-1)^pq^{-2p}+q^2)\,.
\end{equation}


%Легко заметить, что ответ получается верным для узлов (нечётное n) и верным с точностью до домножения на $-1$ для зацеплений (чётное n). Эта проблема кроется в отрицательной квантовой двойке соответствующей тривиальному узлу, решается выбором другого фрейминга, например Бар-Натана ~\cite{bar2002khovanov}.

\paragraph{Второй вариант раскраски.}

В этом варианте раскраски количество белых областей совпадает с числом пересечений $p$ в торическом узле, соответственно, сама матрица Гёрица $G_{II}^{T[2,p]}$ имеет размер $(p-1)\times(p-1)\,$: 

\begin{equation}\label{GoeritzMatrixTorKont2}
\widetilde{G}_{II}^{T[2,p]}  =
\begin{pmatrix}
2 & -1 & 0 & \dots  & 0 &-1\\
-1 & 2 & -1 & \ddots &\dots & 0 \\
0 & -1 & \ddots & \ddots &\ddots &\vdots\\

\vdots  & \ddots & \ddots&\ddots & -1 & 0 \\

0  &\dots &\ddots & -1 & 2 & -1 \\
-1 & 0 & \dots & 0 &-1 & 2  \\

\end{pmatrix}\quad  \mapsto \quad G_{II}^{T[2,p]}=\begin{pmatrix}
2 & -1 & 0 & \dots  & 0 \\
-1 & 2 & -1 & \ddots &\vdots  \\
0 & -1 & \ddots & \ddots &0 \\

\vdots  & \ddots & \ddots&\ddots & -1  \\

 0 & \dots & 0 &-1 & 2  \\
\end{pmatrix}. 
\end{equation}
Из совпадения недиагональных элементов и их расположения относительно главной диагонали все преобразования функции $\mu[G_{II}^{T[2,p]}]$ в первом шаге алгоритма Бонингера идентичны между собой.

\begin{equation}\label{GoeritzCalculatingTor2p}
\mu [G_{II}^{T[2,p]}] = (-q)^{-1/2} \mu \begin{bmatrix}\begin{pmatrix}
    \begin{array}{c|cc|c}
\multirow{2}{*}{\begin{tabular}{c}$G_{II}^{T[2,k]}$\end{tabular}} & \cdots  & \cdots & \multirow{2}{*}{\textbf{\Large{0}}} \\
 & -1  & \cdots &  \\
\hline
0 \ \ \cdots -1 & 1 & 0 & \cdots \\
\cdots  & 0 & 1 & -1 \ \cdots \ \ \ 0 \\
\hline
\multirow{2}{*}{\textbf{\Large{0}}} & \cdots  & -1 & \multirow{2}{*}{\begin{tabular}{c}$G_{II}^{T[2,p-k-2]}$\end{tabular}} \\
 & \cdots  & \cdots & \\
\end{array}\end{pmatrix} \end{bmatrix} + P_{-1}(q)\mu [G_{II}^{T[2,p-1]}]\,.
\end{equation}
А значит, комбинаторика 1 шага алгоритма Бонингера будет биномиальной. Учтя, что нули на диагоналях тождественны умножению функции $\mu[G]$ на квантовую двойку $D_2 = q + q^{-1}$, получим следующее выражение для $\mu [G_{II}^{T[2,p]}]$\footnote{Функцию мы приводим в общем виде, чтобы воспроизводился ответ для зеркальных зацеплений $\overline{L}$. Очевидно, матрица Гёрица для них будет равна отрицательной матрице \eqref{GoeritzMatrixTorKont2}: $G_{II}^{\overline{T[2,p]}} = - G_{II}^{T[2,p]}.$}:

\begin{equation}\label{ExampleTorKnot2}
    \mu [G_{II}^{T[2,p]}] = \sum_{k=0}^{|p|-3}\left\{\begin{pmatrix}
 \begin{array}{c}  |p|-2  \\  k     
 \end{array}
 \end{pmatrix}(-q)^{-{\rm sgn}(p)(|p|-2-k)/2}P_{-{\rm sgn}(p)}^{k}D_2^{|p|-3-k}\right\}\mu\begin{bmatrix}\begin{pmatrix}  1 & 0\\0 & 1     
 \end{pmatrix}

 \end{bmatrix} + P_{-{\rm sgn}(p)}^{|p|-2}\mu[2]\,.
\end{equation}
Данное выражение воспроизводит значения \eqref{GoeritzFunctionForT2p} для $|p| \ge 3$, поскольку матрицы вида \eqref{GoeritzMatrixTorKont2} появляются для двухнитевых узлов, начиная с 3 пересечений. Таким образом, несколько более длинным путём мы снова воспроизвели значение полинома Джонса для двухнитевых узлов: \begin{equation}\label{JonesT2p2}
    J^{T[2,p]}(q)  = (-(-q)^{3/2})^{-p}\mu [G_{II}^{T[2,p]}]\,.
\end{equation}




\subsection{Твистованные узлы Tw$_{m}$}

Другой удобный для демонстрации метода Гёрица пример --- однопараметрическое семейство твистованных узлов ${\rm Tw}_{m}$\footnote{По умолчанию мы считаем $m$ положительным. Для первой раскраски нам это не важно, поскольку $m$ явно входит в матрицу Гёрица для неё \eqref{Goeritz1Twist2m}, при этом вторая раскраска претерпит изменения --- из всех недиагональных элементов только $\Tilde g_{0m}$ не поменяет знак. Соответственно, и в вычислении полинома Джонса будут небольшие изменения, но все действия алгоритма полностью аналогичны \eqref{ExampleTwist2}. Заметим также, что отрицательное $m$ не соответствует зеркальному зацеплению.} (см. раздел \,\ref{sec:TwistKnots}). Аналогично примеру с торическими узлами, в первом варианте раскраски внешнюю область выберем белой, а во втором чёрной.
%--- это будет другой объект.

\begin{figure}[h!]
		\centering	
		\includegraphics[width =0.75\linewidth]{TwistKnot.png}
		\label{fig:TwistKnot}
        \caption{\footnotesize Две раскраски для твистованных узлов $\rm Tw_m$, с положительным $m$.}
	\end{figure}

\paragraph{Первый вариант раскраски.}

При данной раскраске имеем 3 белых области, а значит, матрица Гёрица будет размера $2\times2$:
\begin{equation}\label{Goeritz1Twist2m}
\widetilde{G}^{{\rm Tw}_{m}}_I  =
\begin{pmatrix}
 \begin{array}{ccc}  -m-1 & m & 1 \\ 
 m & -m-1 & 1 \\ 
 1 & 1 & -2      
 \end{array}
 \end{pmatrix} \quad \mapsto \quad G^{{\rm Tw}_{m}}_I  = \begin{pmatrix}
 \begin{array}{cc}  -m-1 & 1 \\  1 & -2       
 \end{array}
 \end{pmatrix}.
\end{equation}
Рассмотрев единственный недиагональный элемент, мы получим:

\begin{equation}\label{Twist1Step1}
\mu\left[G^{{\rm Tw}_{m}}_I\right] = (-q)^{\frac{1}{2}} \mu \begin{bmatrix}
 \begin{pmatrix}
     -m  & 0 \\  0 & -1  
 \end{pmatrix}     
 \end{bmatrix} + P_1(q)\,\mu [-m-1]\,,
\end{equation}

\begin{equation}\label{Twist1Step2}
\mu\left[G^{{\rm Tw}_{m}}_I\right] = (-q)^{\frac{1}{2}}D_2 \left((-q)^{-\frac{m}{2}}D_2 + P_{-m}(q)\right)\left((-q)^{-\frac{1}{2}}D_2 + P_{-1}(q)\right) + P_1(q)D_2\left((-q)^{-\frac{m+1}{2}}D_2 + P_{-m-1}(q)\right)\,,
\end{equation}


\begin{equation}\label{Twist1Step3}
\mu\left[G^{{\rm Tw}_{m}}_I\right] = (-q)^{m/2} (q^{-2}-(-q^2)^{-m}(q^{-2}+q^2)-q^4)\,.
\end{equation}
Заметим, что в зависимости от чётности $m$ будет отличаться знак пересечений в нижнем тэнгле. А значит, и вклад в нормировку будет отличаться на соответствующий множитель. Поэтому значения полиномов Джонса для чётных $(W = -m+2)$  и нечётных $(W = -m - 2)$  $m$ в общем случае различаются:




\begin{equation}\label{JonesTwist} 
\left\{\begin{split} 
J^{{\rm Tw}_{m}}(q)  = q^{2m-3}(q^4+q^{-2m}(q^{-2}+q^2)-q^{-2})\,,\quad \text{ чётное } m, \ \ \ \\
J^{{\rm Tw}_{m}}(q)  = q^{2m+3}(q^{-2}+q^{-2m}(q^{-2}+q^2)-q^{4})\,,\quad \text{ нечётное } m. 
\end{split}\right.
\end{equation}




\paragraph{Второй вариант раскраски.}

В данном случае имеется $m+1$ белая область. При этом относительное расположение областей схоже со второй раскраской для двухнитевого узла, за тем исключением, что область 0 разбивается на две области (0 и $m$), а число пересечений у двух новых областей 2:

\begin{equation}\label{GoeritzMatrixTwist}
\widetilde{G}^{{\rm Tw}_{m}}_{II}  =
\begin{pmatrix}
3 & -1 & 0 & \dots  & 0 &-2\\
-1 & 2 & 1 & \dots & & 0 \\
0 & -1 & \ddots &  & &\vdots\\

\vdots  & \vdots & &\ddots & -1 & 0 \\

0  & & & -1 & 2 & -1 \\
-2 & 0 & \dots & 0 & -1 & 3  \\

\end{pmatrix} \quad \mapsto \quad G^{{\rm Tw}_{m}}_{II} =\begin{pmatrix}
2 & -1 & 0 & \dots  & 0\\
-1 & 2 & -1 & \dots  \\
0 & -1 & \ddots &  &\vdots\\

\vdots  & \vdots & & \ddots & -1 \\
0 & & \dots & -1 & 3  \\

\end{pmatrix}. 
\end{equation}
Крайне удобно, что матрица \eqref{GoeritzMatrixTwist} имеет схожую структуру с \eqref{ExampleTorKnot2}, что делает выражение для скрученных узлов аналогичным выражению для двухнитевых узлов:


\begin{equation}\label{ExampleTwist2}
    \mu [G^{{\rm Tw}_{m}}_{II}] = \sum_{k=0}^{m-2}\left\{\begin{pmatrix}
 \begin{array}{c}  m-1  \\  k     
 \end{array}
 \end{pmatrix}(-q)^{-\delta\frac{m-1-k}{2}}P_{-\delta}^{k}D_2^{m-2-k}\right\}\mu\begin{bmatrix}\begin{array}{cc}  \delta & 0\\0 & 2\delta     
 \end{array}

 \end{bmatrix} + P_{-\delta}^{m-1}\mu[3\delta]\,.
\end{equation}
Несложно убедиться в эквивалентности этой формулы и \eqref{Twist1Step3}, значит, и ответы для твистованных полиномов Джонса \eqref{JonesTwist} воспроизводятся. Здесь $\delta = 1$ для обычных узлов Tw$_m$, $\delta = -1$ для зеркальных $\overline{{\rm Tw}}_m$.






\section{Бипартитные полиномы ХОМФЛИ--ПТ из четверной \\ матрицы Гёрица}
\label{sec:HOMFLYfromGoeritz}

\setcounter{equation}{0}

В работах ~\cite{anokhina2024planar,anokhina2025planar,anokhina2025bipartite} была обобщена скобка Кауффмана, как метод вычисления полинома Джонса, на метод вычисления полиномов ХОМФЛИ--ПТ для определённого класса бипартитных узлов, то есть для таких узлов, которые можно представлять как узлы из удвоенных пересечений с антипараллельной ориентацией (см. рис.\,\ref{fig:pladeco}). Это позволяет думать, что метод Гёрица можно обобщить для полиномов ХОМФЛИ--ПТ как минимум для класса бипартитных узлов. Данный вопрос и послужил основной целью нашего исследования. Для подобного обобщения необходимо изменить как матрицу Гёрица, так и алгоритм Бонингера. Учитывая увеличение числа различающихся пересечений в бипартитной диаграмме (их становится 4) и соотношения на них (см. приложение \ref{sec:App1}) мы получим правила для шахматной раскраски и заполнения элементов аналога матрицы Гёрица --- четверной матрицы Гёрица $\mathcal{G}$ и вид преобразований для этих матриц в подразделе \ref{sec:TransformationTripleMatrix}. Пользуясь интуицией, наработанной при разборе алгоритма Бонингера для вычисления полиномов Джонса в разделах \ref{sec:muInv} и \ref{sec:ExceptionalCases}, мы вводим инвариант $\mathcal{M}[\mathcal{G}]$ для четверных матриц Гёрица, который с учётом нормировки \eqref{HOMFLYNorm} даёт полином ХОМФЛИ--ПТ (см. разд. \ref{sec:HOMFLYfromTripleGoeritz}). 

\subsection{Четверная матрица Гёрица}
\label{sec:quadruple-Goeritz}

Для обобщения матрицы Гёрица на бипартитный случай необходимо определиться, как именно новая матрица будет пересчитывать бипартитные пересечения в двухнитевых косах, которые состоят из 4 различных типов <<замков>> (см. рис. \ref{fig:pladeco}). Несложно заметить, что все бипартитные пересечения, собранные в одной двухнитевой косе, коммутируют друг с другом относительно разрешения скобкой Кауффмана. То есть зацепление, диаграмма которого включает в себя двухнитевые тэнглы из последовательно соединённых  <<замковых>> элементов, имеет такой же полином ХОМФЛИ--ПТ, как зацепления, диаграммы которых отличаются от рассматриваемой диаграммы только произвольными перестановками <<замковых>> элементов в двухнитевых тэнглах. Поэтому мы могли бы, без потери общности, рассматривать только диаграммы из двухнитевых тэнглов, в которых соединяются последовательно $x$ положительных вертикальных пересечений, $\widetilde{y}$ --- положительных горизонтальных, $\overline{z}$ --- отрицательных вертикальных и $\widehat{t}$ --- отрицательных горизонтальных (см. рис. \ref{fig:SignHOMFLYPT}). Для аналога матрицы Гёрица $\mathcal{G}$ это означает, что необходимо по отдельности считывать количество различных типов <<замков>> в двухнитевых косах, на которые разбита диаграмма зацепления. 

\subsubsection{Определение и примеры}\label{sec:QuadrupleGoeritzParametrs}




Исходя из вышеизложенного, введём новый объект --- четверную матрицу Гёрица, зависящую от четырёх независимых параметров (числа $x,\widetilde{y}, \overline{z}, \widehat{t} $ ). Задавать её будем по следующему алгоритму, схожему с алгоритмом из раздела \ref{sec:Goeritz-mat}.


\begin{enumerate}

\item Сопоставляем бипартитной диаграмме узла шахматную раскраску по обычным правилам, но с бипартитными вершинами. Пронумеруем все белые области целыми числами.
%, начиная с 0

\item Нередуцированная четверная матрица Гёрица $\widetilde{\mathcal{G}} = (\widetilde{\mathfrak{g}}_{ij}) $  определяется идентично обычной матрице Гёрица \eqref{IrGoerMatr}, меняется только вклад, который даёт одно пересечение $c$, теперь этот вклад является одним из четырёх значений $\sigma(c) = \{ -1,\widehat{1},-\widetilde{1}, \overline{1}\}$\footnote{Обратим внимание, что два положительных бипартитных <<замка>> имеют отрицательные значения функции $\sigma(c)$: $(-1,-\widetilde{1})$, в то время как два отрицательных --- положительные значения $(\overline{1},\widehat{1})$. Как будет видно далее, с точки зрения вычисления полинома ХОМФЛИ--ПТ информация о знаках не так ценна, поскольку наш алгоритм  подсчитывает каждый тип бипартитных пересечений отдельно. Смысл наличия данных знаков состоит в том, чтобы мы могли перейти от бипартитных диаграмм к диаграммам-предшественникам (см. раздел~\ref{sec:BonNorm}) и получить полином Джонса для этих предшественников из-за редукции метода Гёрица для бипартитных ХОМФЛИ--ПТ $\Big(\phi \rightarrow -q$, $\bphi \rightarrow -q^{-1}$, $D_N \rightarrow D_2\Big)$ и соглашения о знаках шахматной раскраски  $(-1 \to -1;\widehat{1}\to 1;-\widetilde{1}\to -1; \overline{1}\to 1)$.} (см. рис.\,\ref{fig:SignHOMFLYPT}). 

\begin{equation}\label{FirstGoeritzHOMFLYMatrix}
\centering
\widetilde{\mathfrak{g}}_{ij} = \left\{\begin{split}
&-\sum_{c_{ij}}\sigma(c_{ij}),  \ \  &i\ne j\,,  \ \\
&-\sum_{k \ne i} \widetilde{\mathfrak{g}}_{kj},  & i = j\,, \\ 
\end{split}\right.
\end{equation}
где $c_{ij}$ -- множество всех пересечений между областями $i$ и $j$, $x_{ij},  \widetilde{y}_{ij}, \overline{z}_{ij}, \widehat{t}_{ij}$ --- число бипартитных пересечений каждого типа между областями $i$ и $j$, а $\sigma(c_{ij}) = x_{ij} +\widetilde{y}_{ij}+\overline{z}_{ij}+\widehat{t}_{ij}$.




\begin{figure}[h!]
		\centering	
		\includegraphics[width =0.65\linewidth]{CheckerboardHOMFLYPT.png}
        \caption{\footnotesize Соглашение о знаках в шахматной раскраске для бипартитных диаграмм. Слева направо: положительный вертикальный, отрицательный горизонтальный, отрицательный вертикальный, положительный горизонтальный <<замки>>. Все тэнглы нарисованы в наших обозначениях, см. рис.\,\ref{fig:pladeco}. В частности, двойной линией на третьей и четвертой диаграммах мы обозначаем тэнглы, полученные из первой и второй диаграмм, соответственно, заменой пересечений на обратные.}
        \label{fig:SignHOMFLYPT}
	\end{figure}


\item Четверная матрица Гёрица (редуцированная) $\mathcal{G} = (\mathfrak{g}_{ij})$ снова получается из нередуцированной матрицы 
вычёркиванием $k$-ых столбца и строки $(\forall k)$, тогда искомая матрица будет состоять из оставшихся элементов $\mathfrak{g}_{ij} = \widetilde{\mathfrak{g}}_{ij},\; \forall i\ne k,\; j\ne k$. 



\end{enumerate}

Полученную четверную матрицу с очевидностью можно разложить в сумму четырёх симметричных матриц, каждая из которых будет зависеть только от одного параметра из $(x,\widetilde{y}, \overline{z}, \widehat{t} \ )$.

\begin{equation}
    \mathcal{G}(x,\widetilde{y}, \overline{z}, \widehat{t} \ ) = \mathcal{G}(x)+\mathcal{G}(\widetilde{y} ) + \mathcal{G}(\overline{z}) + \mathcal{G}( \widehat{t} \ )\,.
\end{equation}

\subsubsection{Преобразования четверных матриц}\label{sec:TransformationTripleMatrix}

Четверная матрица наследует от обычной матрицы  Гёрица структуру преобразований на ней, поскольку преобразования на матрицах отвечают за изменения диаграмм относительно разрешений двухнитевых кос, находящихся между двумя белыми областями, скобкой Кауффмана (объединение/разделение областей), что переносится и на случай бипартитных диаграмм.

\medskip

\noindent {\bf (I)} Напомним, что первое преобразование в \eqref{GoeritzMovie1} отвечало разделению областей $i$ и $j$ на области без пересечений, что сохраняется для четверных матриц. На уровне матриц это означает обнуление соответствующего недиагонального элемента $\mathfrak{g}_{i j}$:

\begin{equation}\label{QuadroGoeritzMovie1}
\mathcal{G}=\begin{pmatrix}
\ddots & \\
& \mathfrak{g}_{ii} & \dots & \boxed{\mathfrak{g}_{ij}} \\
& \vdots & \ddots & \vdots \\
& \mathfrak{g}_{ji} & \dots & \mathfrak{g}_{jj} \\
& & & & \ddots \\
\end{pmatrix}\quad \mapsto \quad
\mathcal{G}^{(I)}=\begin{pmatrix}
\ddots & \\
& \mathfrak{g}_{ii} + \mathfrak{g}_{ij} & \dots & 0 \\
& \vdots & \ddots & \vdots \\
& 0 & \dots & \mathfrak{g}_{jj} + \mathfrak{g}_{ij} \\
& & & & \ddots \\
\end{pmatrix}.   
\end{equation}


\noindent Явный вид первого преобразования для элемента $\mathfrak{g}_{i j} = x_{ij}+\widetilde{y}_{ij}+\overline{z}_{ij}+\widehat{t}_{ij}$ выглядит следующим образом:


\begin{equation}
\begin{aligned}
\mathfrak{g}_{i i}   \quad &\mapsto \quad \mathfrak{g}_{i i}+\mathfrak{g}_{i j} = x_{ii} +x_{ij} +\widetilde{y}_{ii} +\widetilde{y}_{ij}+\overline{z}_{ii}  +\overline{z}_{ij}+\widehat{t}_{ii}+\widehat{t}_{ij}\,, \\
\mathfrak{g}_{j j} \quad &\mapsto \quad \mathfrak{g}_{j j}+\mathfrak{g}_{i j} = x_{jj} +x_{ij} +\widetilde{y}_{jj} +\widetilde{y}_{ij}+\overline{z}_{jj}  +\overline{z}_{ij}+\widehat{t}_{jj}+\widehat{t}_{ij}, \\
\mathfrak{g}_{i j}, \mathfrak{g}_{j i} \quad &\mapsto \quad 0\,.
\end{aligned}
\end{equation}


% \medskip

\noindent {\bf (II)} Аналогично, второе преобразование $\mathcal{G} \;\mapsto\; \mathcal{G}^{(II)}$ отвечает за соединение областей $i$ и $j$ на бипартитной диаграмме. Как и в \eqref{GoeritzMovie2}, из-за объединения областей размер матрицы уменьшается на 1 по причине удаления $j$-ых столбца и строки:

\begin{equation}\label{QuadroGoeritzMovie2}
\begin{picture}(300,100)(90,-45)
    \put(0,0){\mbox{$\mathcal G=\begin{pmatrix}
\ddots & & & & \vdots \\
& \mathfrak{g}_{ii} & \mathfrak{g}_{ik} & \dots & \boxed{\mathfrak{g}_{ij}} \\
& \mathfrak{g}_{ki} & \ddots & & \mathfrak{g}_{kj} \\
& \vdots & & \ddots & \vdots \\
\dots & \mathfrak{g}_{ji} & \mathfrak{g}_{jk} & \dots & \mathfrak{g}_{jj} & \dots \\
& & & & \vdots &  \ddots \\
\end{pmatrix} \quad \mapsto \quad \mathcal G^{(II)} =
\begin{pmatrix}
\ddots & & & & {\vdots} \\
& \mathfrak{g}_{ii} + \mathfrak{g}_{jj} + 2\mathfrak{g}_{ij} & \mathfrak{g}_{ik} + \mathfrak{g}_{jk} & \dots & \mathfrak{g}_{ij} \\
& \mathfrak{g}_{ki} + \mathfrak{g}_{kj} & \ddots & & \mathfrak{g}_{kj} \\
& \vdots & & \ddots & \vdots \\
{\dots} & \mathfrak{g}_{ji} & \mathfrak{g}_{jk} & \dots & \mathfrak{g}_{jj} & {\dots} \\
& & & & {\vdots} &  \ddots \\
\end{pmatrix}. $}}

\thicklines

{\color{red}

\put(420,-53){\line(0,1){110}}
\put(237,-25){\line(1,0){225}}

}

\end{picture}
\end{equation}
Диагональный элемент $\mathfrak{g}_{i i}$ и недиагональные элементы на $i$-ых столбце и строке  $\mathfrak{g}_{i k}, \mathfrak{g}_{k i}$ изменяются из-за объединения пересечений между областями $i$ и $k$ с пересечениями между областями $j$ и $k$, так как области $i$ и $j$ соединяются в одну:

\begin{equation}
\begin{aligned}
& \mathfrak{g}_{i i} \quad \mapsto \quad \mathfrak{g}_{i i}+\mathfrak{g}_{j j}+2 \mathfrak{g}_{i j} = x_{ii}+x_{jj} +2x_{ij} +\widetilde{y}_{ii} +\widetilde{y}_{jj} +2\widetilde{y}_{ij}+\overline{z}_{ii}  +\overline{z}_{jj}  +2\overline{z}_{ij}+\widehat{t}_{ii}+\widehat{t}_{jj}+2\widehat{t}_{ij}\,, \\
& \mathfrak{g}_{i k} \quad \mapsto \quad \mathfrak{g}_{i k}+\mathfrak{g}_{ki} = x_{ik} + x_{ki} +\widetilde{y}_{ik}+\widetilde{y}_{ki}+\overline{z}_{ik}+\overline{z}_{ki}+\widehat{t}_{ik}++\widehat{t}_{ki}, \; \text { для всех } \; k \neq i\,, \\
& \mathfrak{g}_{k i} \quad \mapsto \quad \mathfrak{g}_{k i}+\mathfrak{g}_{k j} = x_{ik} + x_{ki} +\widetilde{y}_{ik}+\widetilde{y}_{ki}+\overline{z}_{ik}+\overline{z}_{ki}+\widehat{t}_{ik}++\widehat{t}_{ki}, \; \text { для всех } \; k \neq i\,.
\end{aligned}
\end{equation} 

%\medskip

\noindent {\bf (III)} Третье преобразование  $\mathcal{G} \;\mapsto\; \mathcal{G}^{(III)}$ для диагональных матриц снова, как и для обычных матриц Гёрица, соответствует диаграмме, в которой все области, кроме одной, пересекаются только лишь с одной другой (см. рис. \ref{fig:diag-Goeritz-ex}), которой соответствовали отбрасываемые столбец и строка при редуцировании четверной матрицы Гёрица. Продолжая аналогию, планарное разрешение всех пересечений между любыми двумя областями для этих диаграмм даёт одинаковые диаграммы с точностью до замкнутых циклов, которые можно заменить на множители $D_N$. Тогда третье преобразование должно фиксировать исчезновение одной из областей, что позволяет вычеркнуть $i$-ую строку и столбец:


\begin{equation}
    \mathcal G = {\rm diag}(\dots,\, \mathfrak{g}_{i-1},\, \boxed{\mathfrak{g}_i}\,,\, \mathfrak{g}_{i+1},\, \dots) \quad \mapsto \quad \mathcal G^{(III)} = {\rm diag}(\dots ,\, \mathfrak{g}_{i-1},\, \cancel{\mathfrak{g}_i},\, \mathfrak{g}_{i+1},\, \dots)\,. 
\end{equation}


\subsection{Инвариант матриц $\mathcal{M}$ и полином ХОМФЛИ--ПТ}\label{sec:HOMFLYfromTripleGoeritz}

Далее наша цель --- ввести функцию $\mathcal{M}[\mathfrak{g}_{i j}]$, которая будет выполнять преобразования на четверных матрицах Гёрица, соответствующие результату планарного разложения бипартитной диаграммы (см. рис.\,\ref{fig:pladeco}). В разделе \ref{sec:muInv} мы построили аналогичную функцию для обычных диаграмм зацеплений, пользуясь интуицией от разрешения двухнитевой косы. Последуем этому примеру и рассмотрим двухнитевую косу, но уже состоящую из бипартитных <<замков>>; пример разрешения такой косы приведём на рис.\,\ref{fig:KaufBipBraid}. Как мы уже отмечали, бипартитные диаграммы можно представлять как состоящие из двухнитевых кос с расположенными последовательно бипартитными пересечениями разных типов\footnote{Мы пользуемся свойством равенства полиномов ХОМФЛИ--ПТ для диаграмм, различающихся на произвольную перестановку бипартитных <<замков>>в двухнитевых косах.}. Поэтому мы сконцентрируемся на подобном общем примере.

\begin{figure}[h!]
		\centering	
		\includegraphics[width =\linewidth]{KaufBipBraid.png}
		\caption{\footnotesize Разрешение двухнитевой бипартитной косы при помощи планарного разложения. Над стрелками показаны коэффициенты, с которыми происходят соответствующие разрешения. Данные коэффициенты согласованы с коэффициентами действия функции $\mathcal{M}[\mathfrak{g}_{i j}]$ на недиагональный элемент четверной матрицы Гёрица. При разрешении косы, соответствующей действию $\mathcal{M}[\mathfrak{g}_{i j}]$ на диагональные элементы, изменяются знаки перед параметрами $x_{ij},\widetilde{y}_{ij}, \overline{z}_{ij}, \widehat{t}_{ij}$ в преобразованиях, что явно видно в \eqref{StepHOMFLYfromGoeritz2}.} 
        \label{fig:KaufBipBraid}
	\end{figure}

Так же как и при разрешении обычной косы, разрешение косы из $n$ бипартитных <<замков>> одного типа выдаёт одно вертикальное разрешение и $n-1$ горизонтальное разрешение, которые совпадают друг с другом с точностью до выделившихся замкнутых циклов, соответствующих множителям $D_N$. Суммирование всех горизонтальных разрешений даёт комбинаторные множители $(P_x, \widetilde{P}_{\widetilde{y}}, \overline{P}_{\overline{z}},\widehat{P}_{\widehat{t}})$, которые должны также возникать при преобразовании элементов четверной матрицы Гёрица:


\begin{equation}\label{PPolynomials} 
\left\{\begin{split} 
P_{x}(\phi,\overline{\phi}, D_N) = \sum^{|x|}_{k=1} \begin{pmatrix}
|x| \\
k 
\end{pmatrix} D_N^{k-1} \phi^{|x|/2-k} \,  , \ \ \ \  \widetilde{P}_{\widetilde{y}}(\phi,\overline{\phi}, D_N) = \sum^{|\widetilde{y}|}_{k=1} \begin{pmatrix}
|\widetilde{y}| \\
k 
\end{pmatrix} D_N^{k-1} \overline{\phi}^{k-|\widetilde{y}|/2}, \\
\overline{P}_{\overline{z}}(\phi,\overline{\phi}, D_N) = \sum^{|\overline{z}|}_{k=1} \begin{pmatrix}
|\overline{z}| \\
k 
\end{pmatrix} D_N^{k-1} \overline{\phi}^{|\overline{z}|/2-k}, \ \ \ \ \widehat{P}_{\widehat{t}}(\phi,\overline{\phi}, D_N) = \sum^{|\widehat{t}|}_{k=1} \begin{pmatrix}
|\widehat{t}| \\
k 
\end{pmatrix} D_N^{k-1} \phi^{k-|\widehat{t}|/2} \,.
\end{split}\right.
\end{equation}
Мы хотим, чтобы функция $\mathcal{M} [\mathfrak{g}_{ij}]$ выражалась через комбинаторные множители от разных типов бипартитных пересечений, поскольку она должна соответствовать разрешению сразу всех бипартитных <<замков>> между областями $i$ и $j$. Вид действия функции $\mathcal{M} [\mathfrak{g}_{ij}]$ на недиагональный элемент $\mathfrak{g}_{ij}$ ясен из анализа разрешения косы общего вида (см. рис. \ref{fig:KaufBipBraid}): 

\begin{equation}\label{StepHOMFLYfromGoeritz1}
\begin{aligned}
\boxed{\mathcal{M} [\mathfrak{g}_{ij}] = \mathcal{U}_1[\mathfrak{g}_{\normalfont{ij}}] \mathcal{M}\left[\mathfrak{g}_{ij}^{(I)}\right] + \mathcal{U}_2[\mathfrak{g}_{ij}] \mathcal{M}\left[\mathfrak{g}_{ij}^{(II)}\right]\,,}
\end{aligned}
\end{equation}
где мы ввели для краткости обозначения:
\begin{equation}
\boxed{\begin{aligned}
    \mathcal{U}_1[\mathfrak{g}_{\normalfont{ij}}] &= \phi^{(x_{ij}+\widehat{t}_{ij})/2}\overline{\phi}{}^{-(\widetilde{y}_{ij}+\overline{z}_{ij})/2}\,, \\
    \mathcal{U}_2[\mathfrak{g}_{ij}] &= \phi^{\widehat{t}_{ij}/2}\overline{\phi}{}^{-(\widetilde{y}_{ij}+\overline{z}_{ij})/2} P_{x_{ij}} + \left(\phi^{x_{ij}/2}+D_NP_{x_{ij}}\right)\cdot \\ 
    &\cdot \left[\left(\overline{\phi}{}^{-\widetilde{y}_{ij}/2}+  D_N\widetilde{P}_{-\widetilde{y}_{ij}}\right)\left(\overline{\phi}{ \ }^{-\overline{z}_{ij}/2}\widehat{P}_{\widehat{t}_{ij}}+\phi^{\widehat{t}_{ij}/2}\overline{P}_{-\overline{z}_{ij}}+D_N\overline{P}_{-\overline{z}_{ij}}\widehat{P}_{\widehat{t}_{ij}}\right)+\phi^{\widehat{t}_{ij}/2}\overline{\phi}{ \ }^{-\overline{z}_{ij}/2}\widetilde{P}_{-\widetilde{y}_{ij}} \right].
\end{aligned}}
\end{equation}
Аналогично алгоритму Бонингера, подобными преобразованиями мы действуем на четверную матрицу до момента, когда получим выражение от диагональных матриц. Для диаграмм и шахматных раскрасок это означает, что среди всех результатов планарного разложения остались диаграммы, у которых все области имеют пересечения только лишь с одной областью, которая и соответствовала номеру вычеркнутых строки и столбца при построении четверной матрицы Гёрица, то есть наблюдается картина, аналогичная рис. \,\ref{fig:diag-Goeritz-ex}. Значит, вертикальные и горизонтальные разрешения пересечений планарным разложением между двумя областями дадут диаграммы, изотопные друг другу с точностью до выделившихся замкнутых циклов. Заметим также, что замыкание косы добавит к вертикальному разрешению множитель $D_N$. Из данных соображений следует действие на элементы диагональных четверных матриц:  

\begin{equation}\label{StepHOMFLYfromGoeritz2}
\boxed{\begin{aligned}
\mathcal{M} [\mathfrak{g}_{i}] = 
\mathscr{D}[\mathfrak{g}_{i}]\mathcal{M}\left[\mathfrak{g}_{i}^{(III)}\right],
\end{aligned}}
\end{equation}
где мы ввели следующее сокращенное обозначение:
\begin{equation}
\boxed{\begin{aligned}
    \mathscr{D}[\mathfrak{g}_{i}] &= \phi^{-(x_{i}+\widehat{t}_{i})/{2}}\overline{\phi}{}^{(\widetilde{y}_{i}+\overline{z}_{i})/{2}} D_N+\phi^{-\widehat{t}_{i}/{2}}\overline{\phi}{}^{(\widetilde{y}_{i}+\overline{z}_{i})/{2}} P_{-x_{i}} +  \\ 
    &+ \left(\phi^{-{x_{i}}/{2}}+D_N P_{-x_{i}}\right)\left[\left(\overline{\phi}{}^{{\widetilde{y}_{i}}/{2}}+  D_N\widetilde{P}_{\widetilde{y}_{i}}\right)\left(\overline{\phi}{ \ }^{{\overline{z}_{i}}/{2}}\widehat{P}_{-\widehat{t}_{i}}+\phi^{-{\widehat{t}_{i}}/{2}}\overline{P}_{\overline{z}_{i}}+D_N\overline{P}_{\overline{z}_{i}}\widehat{P}_{-\widehat{t}_{i}}\right)+\phi^{-{\widehat{t}_{i}}/{2}}\overline{\phi}{ \ }^{{\overline{z}_{i}}/{2}}\widetilde{P}_{\widetilde{y}_{i}} \right].
\end{aligned}}
\end{equation}
На последнем шаге, как и в алгоритме Бонингера, оставшееся выражение пропорционально действию функции $\mathcal{M}$ на пустое множество, соответствующее одному замкнутому циклу, что определяет нормировку:

\begin{equation}\label{NormHOMFLYinAlgoritm}
\mathcal{M}[\varnothing]=D_N=\frac{A-A^{-1}}{q-q^{-1}}\,.
\end{equation}
Тогда, пользуясь эквивалентностью $\mathcal{M}[\mathcal{G}]$ и планарного разложения бипартитной диаграммы, мы получаем выражение для вычисления бипартитных полиномов ХОМФЛИ--ПТ методом Гёрица:
\begin{equation}\label{HOMFLYNormBip}
    H^{\cal L} = A^{-2(N_\bullet- N_\bullet^v- N_\circ+N_\circ^v)} \cdot \phi^{(N_\bullet-N_\bullet^h-N_\bullet^v)/2}\bphi^{(N_\circ-N_\circ^h-N_\circ^v)/2}\left(\phi+D_N\right)^{N_\bullet^h}\left(\bphi+D_N\right)^{N_\circ^h}\mathcal{M}[\mathcal{G}]\,,
\end{equation}
где $N_\bullet$ и $N_\circ$ --- числа верхних и нижних <<замковых>> элементов с рис.\,\ref{fig:pladeco}, индексы $v$ и $h$ отвечают числу таких вертикальных ($N_\bullet^v$ и $N_\circ^v$) и горизонтальных ($N_\bullet^h$ и $N_\circ^h$) <<замков>>, которые разделяют одну и ту же область, подробнее о них в подразделе \ref{sec:RetCalM}.


\subsubsection{Пересечение областей несколькими разделёнными косами }\label{sec:ManyBraidsCalM}

Полученная функция $\mathcal{M}[\mathcal{G}]$ и четверная матрица Гёрица сохраняют особенности функции $\mu[G]$ и обычной матрицы Гёрица, что мы прокомментируем в этом и следующем подразделах. Рассмотрим элемент четверной матрицы Гёрица $\mathfrak{g}_{ij}$, соответствующий областям $i$ и $j$, которые пересекаются в нескольких разделённых бипартитных двухнитевых тэнглах (аналогично рис. \ref{fig:sum-par}). Действие $\mathcal{M}[\mathfrak{g}_{ij}]$ на него разрешает все двухнитевые тэнглы между областями $i$ и $j$ одновременно. Данный факт легко осознать, если учесть, что вклад каждого типа <<замков>> можно рассматривать отдельно сразу для всех двухнитевых тэнглов. Для каждого типа бипартитных пересечений очевидно, если рассмотрим разрешение пересечений сразу во всех $k$ разделённых бипартитных двухнитевых тэнглах, что коэффициент перед вертикальным разрешением будет пересчитывать все пересечения в показателях функций $\phi$ и $\overline{\phi}$: $\Big(\phi^{\underset{k}\sum x_k/2},\overline{\phi}^{-\underset{k}\sum \widetilde{y}_k/2},\overline{\phi}^{\underset{k}\sum \overline{z}_k/2},\phi^{-\underset{k}\sum \widehat{t}_k/2}\Big)$, играющих роль множителей перед функцией $\mathcal{M}\left[\mathfrak{g}_{ij}'^{(I)}\right]$, обозначающей вертикальное разрешение пересечений $\mathfrak{g}_{ij}$ планарным разложением. Комбинаторные коэффициенты, соответствующие горизонтальным разрешениям, будут аналогичны \eqref{PSumFormula} и будут удовлетворять следующим соотношениям:


\begin{equation}\label{QPPolynomials} 
\begin{split} 
P_{x_1+x_2} = \phi^{x_1/2}P_{x_2}+\phi^{x_2/2}P_{x_1}+P_{x_1}P_{x_2}D_N \,  ,  \ \ \ \  \widetilde{P}_{-(\widetilde{y}_1+\widetilde{y}_2)} = \overline{\phi}^{-\widetilde{y}_1/2}\widetilde{P}_{-\widetilde{y}_2}+\overline{\phi}^{-\widetilde{y}_2/2}\widetilde{P}_{-\widetilde{y}_1}+\widetilde{P}_{-\widetilde{y}_1}\widetilde{P}_{-\widetilde{y}_2}D_N, \\
\overline{P}_{\overline{z}_1+\overline{z}_2} = \overline{\phi}{ \ }^{\overline{z}_1/2}\overline{P}_{\overline{z}_2}+\overline{\phi}{ \ }^{\overline{z}_2/2}\overline{P}_{\overline{z}_1}+\overline{P}_{\overline{z}_1}\overline{P}_{\overline{z}_2}D_N, \ \ \ \ \widehat{P}_{-(\widehat{t}_1+\widehat{t}_2)}= \phi^{-\widehat{t}_1/2}\widehat{P}_{-\widehat{t}_2} + \phi^{-\widehat{t}_2/2}\widehat{P}_{-\widehat{t}_1} + \widehat{P}_{-\widehat{t}_1}\widehat{P}_{-\widehat{t}_2}D_N\,.
\end{split}
\end{equation}

Итеративным образом комбинаторные коэффициенты $\Big(P_{\underset{k}\sum x_k},\widetilde{P}_{-\underset{k}\sum \widetilde{y}_k},\overline{P}_{\underset{k}\sum \overline{z}_k},\widehat{P}_{-\underset{k}\sum \widehat{t}_k}\Big)$ обобщаются на случай многих тэнглов. Данные выражения \eqref{QPPolynomials} можно получить как из определения комбинаторных коэффициентов \eqref{PPolynomials}, так и из разрешения пересечений при помощи планарного разложения. Из последнего способа явно видно, что каждое слагаемое соответствует своей диаграмме в итоговом разрешении\footnote{Под итоговым подразумевается разрешение сразу всех типов бипартитных пересечений между двумя рассматриваемыми областями.}: слагаемое с множителем $D_N$ отвечает несвязной сумме двух некоторых зацеплений, а два остальных слагаемых --- связной сумме этих же зацеплений. Но с точки зрения метода Гёрица диаграммы этих сумм эквивалентны, поскольку четверные матрицы для них совпадают (пересечений между областями $i$ и $j$ нет у обоих диаграмм, а в остальном они полностью идентичны). Пользуясь приведёнными аргументами, можно представить, как происходит действие функции $\mathcal{M}[\mathfrak{g}_{ij}']$ на недиагональный элемент $\mathfrak{g}_{ij}'$, полученный из пересчёта <<замков>> в $k$ разделённых бипартитных двухнитевых тэнглах между областями $i$ и $j$:



\begin{equation}\label{StepHOMFLYfromGoeritz3}
\begin{aligned}
&\mathcal{M} [\mathfrak{g}_{ij}'] = \phi^{\underset{k}\sum (x_k-\widehat{t}_k)/2}\overline{\phi}{}^{\underset{k}\sum (\overline{z}_k-\widetilde{y}_k)/2} \mathcal{M}\left[\mathfrak{g}_{ij}'^{(I)}\right]+\mathcal{M}\left[\mathfrak{g}_{ij}'^{(II)}\right] \Big(\phi^{-\underset{k}\sum \widehat{t}_k/2}\overline{\phi}{}^{\underset{k}\sum (\overline{z}_k-\widetilde{y}_k)/2} P_{\underset{k}\sum x_k} + \left(\phi^{\underset{k}\sum x_k/2}+D_NP_{\underset{k}\sum x_k}\right) \cdot\\
&\cdot \left[\left(\overline{\phi}{}^{-\underset{k}\sum \widetilde{y}_k/2}+  D_N\widetilde{P}_{-\underset{k}\sum \widetilde{y}_k}\right)\left(\overline{\phi}{ \ }^{-\underset{k}\sum \overline{z}_k/2}\widehat{P}_{-\underset{k}\sum \widehat{t}_k}+\phi^{-\underset{k}\sum \widehat{t}_k/2}\overline{P}_{\underset{k}\sum \overline{z}_k}+D_N\overline{P}_{\underset{k}\sum \overline{z}_k}\widehat{P}_{-\underset{k}\sum \widehat{t}_k}\right)+\phi^{-\underset{k}\sum \widehat{t}_k/2}\overline{\phi}{ \ }^{\underset{k}\sum \overline{z}_k/2}\widetilde{P}_{-\underset{k}\sum \widetilde{y}_k} \right]\Big), 
\end{aligned}
\end{equation}

\begin{equation}
    \mathfrak{g}_{ij}' = \underset{k}\sum x_k -\underset{k}\sum \widetilde{y}_k  +\underset{k}\sum \overline{z}_k  -\underset{k}\sum \widehat{t}_k \ .
\end{equation}
Аналогично устроено действие функции $\mathcal{M}[\mathcal{G}]$ на диагональный элемент. Таким образом, распределение <<замковых>> элементов между любыми двумя различными областями неважно, а функция $\mathcal{M}[\mathcal{G}]$ с одинаковым результатом разрешает такие диаграммы.

\subsubsection{Ретуширование полинома $\mathcal{M}$}\label{sec:RetCalM}

Проблемы c определением полинома $\mathcal{M}$, как и в разделе \ref{sec:RetMu} для обычных матриц Гёрица, возникают при рассмотрении самопересечений между одной и той же областью, то есть, когда некоторая область будет разделяться бипартитными <<замками>>. Пример подобных самопересечений для положительного вертикального и отрицательного горизонтального бипартитных пересечений приведён на рис.\,\ref{fig:QRetoucher} под номерами II и IV, соответственно. Для других типов <<замков>> (обратных) ситуация аналогичная. В конечном итоге, необходимость учёта самопересечений приводит к изменению нормировки полинома $\mathcal{M}[\mathcal{G}]$ из \eqref{HOMFLYNorm}, что мы называем ретушированием. 


\begin{figure}[h!]
		\centering	
		\includegraphics[width =1.0\linewidth]{QRetoucher.png}
		\caption{\footnotesize{Самопересечения областей для положительного вертикального и отрицательного горизонтального бипартитных пересечений и шахматная раскраска на полученных диаграммах.}}
        \label{fig:QRetoucher}
	\end{figure}


Как и всегда, возможны два вида шахматных раскрасок. В первом случае (I и III) бипартитное самопересечение  увеличивает число областей, изменяя тем самым размер четверной матрицы Гёрица и итоговое выражение для полинома $\mathcal{M}(\phi,\overline{\phi},D_N)$. Это компенсируется изменением нормировочного множителя \eqref{HOMFLYNorm} из-за увеличения числа <<замков>> ($N_\bullet$ или $N_\circ$). Для подобных раскрасок метод Гёрица остаётся таким же, как был описан выше.

Для второй раскраски (II и IV) новая область, сепарированная новым бипартитным пересечением, будет чёрной. А значит, количество белых областей не изменится, как и не изменится число пересечений между ними. Из этого следует, что не претерпит изменений и четверная матрица Гёрица. При этом нормировка для планарного разложения \eqref{HOMFLYNorm} почувствует появление нового бипартитного <<замка>>. Значит, нам нужно ввести компенсирующий множитель, который <<отретуширует>> полином $\mathcal{M}[\mathcal{G}]$ от бипартитных пересечений, невидимых для четверной матрицы и метода Гёрица. При этом горизонтальное и вертикальное бипартитные пересечения ведут себя различным образом, что побуждает вводить для них различные множители.


Более простая ситуация наблюдается для вертикальных <<замков>> (II). Разрешение самопересечения планарным разложением даёт множители $\left(\phi^{-1/2}+\phi^{1/2}D_N\right) = A^{2}\phi^{-1/2}$ и $\left(\overline\phi{}^{-1/2}+\overline\phi{}^{1/2}D_N\right) = A^{-2}\overline\phi{}^{-1/2}$ для положительного и отрицательного бипартитных пересечений соответственно. Из рис.\,\ref{fig:QRetoucher} же явно видно, что вертикальные самопересекающиеся <<замки>> не меняют зацепления относительно своего удаления, поскольку тождественны двум первым движениям Райдемайстера. Тогда в нормировочный множитель должны входить зафиксированные выше результаты разрешения вертикального <<замка>> планарным разложением в степенях, соответствующих количеству вертикальных положительных ($N_\bullet^v$) и отрицательных ($N_\circ^v$) бипартитных самопересечений соответственно. 


Горизонтальные же бипартитные <<замки>> (IV), как видно из рисунка, соответствуют появлению новой компоненты\footnote{Важно отметить, что на уровне обычного метода Гёрица (диаграмм-предшественников) подобные самопересечения можно было не учитывать в нормировке, а просто удалить их из рассматриваемой диаграммы (распутать по первому движению Райдемайстера). С вертикальными <<замками>>, которые соответствуют двум последовательным первым движениям Райдемайстера, такое ещё можно было бы сделать, но появление новой компоненты для горизонтального самопересечения нуждается в более аккуратных действиях, поскольку требует изменения полинома ХОМФЛИ--ПТ.}, что на языке разрешения самопересечения планарным разложением означает появление множителя $\left(\phi^{1/2}+\phi^{-1/2}D_N = \phi^{-1/2}\left(\phi+D_N\right)\right)$  для отрицательного горизонтального бипартитного пересечения и $\left(\overline\phi{}^{1/2}+\overline\phi{}^{-1/2}D_N = \overline\phi{}^{-1/2}\left(\bphi+D_N\right)\right)$ для положительного горизонтального бипартитного пересечения. Эти множители не достаются из преобразований на четверную матрицу Гёрица, поэтому необходимо добавить их дополнительно в степенях, соответствующих количеству положительных ($N_\circ^h$) и отрицательных ($N_\bullet^h$) горизонтальных <<замков>>. При этом планарную нормировку из \eqref{HOMFLYNorm} это не изменит, поскольку горизонтальные <<замковые>> самопересечения действительно изменяют зацепление.



Тем не менее, если учесть ретуширование полинома $\mathcal{M}[\mathcal{G}]$, метод Гёрица выдаёт полином ХОМФЛИ--ПТ для любой бипартитной диаграммы. Общий вид компенсационного множителя $\mathcal{N}_{com}$ принимает следующий вид:

\begin{equation}\label{HOMFLYNormBipCom}
    \mathcal{N}_{com} = \left(A^{-2}\phi^{1/2}\right)^{-N_{\bullet}^v}\left(A^{2}\overline\phi{}^{1/2}\right)^{-N_{\circ}^v}\phi^{-N_{\bullet}^h/2}\left(\phi+D_N\right)^{N_\bullet^h}\overline\phi{}^{-N_{\circ}^h/2}\left(\bphi+D_N\right)^{N_\circ^h} .
\end{equation}


\section{Примеры вычисления полиномов ХОМФЛИ--ПТ}
\label{sec:HOMFLY-ex}
\setcounter{equation}{0}

В этом разделе мы приведём примеры вычисления полиномов ХОМФЛИ--ПТ по четверным матрицам Гёрица. Мы рассмотрим примеры твистованных и двухнитевых узлов как обширных, и в то же время простых семейств узлов, каждый представитель которых имеет бипартитную диаграмму. Также мы приведём примеры вычисления полиномов ХОМФЛИ--ПТ для отдельных претцельных, рациональных и монтезиносовых узлов, на которых мы показывали существование бипартитных диаграмм для данных классов узлов в разделе \ref{sec:bip-diag-obtain}.


\subsection{Твистованные узлы $\rm Tw_m$}\label{sec:HOMFLYTwist}

\begin{wrapfigure}[9]{r}{0.5\textwidth}
   \centering
    \vspace{-1.7cm}
    \includegraphics[width =\linewidth]{QuarterCheckboardForEvenTwist.png}
    \caption{\footnotesize Шахматная раскраска для бипартитных диаграмм твистованных узлов ${\rm Tw}_m$ при чётном $m$.}
        \label{fig:QuarterCheckboardForEvenTwist}
\end{wrapfigure}

Одним из самых простых семейств с точки зрения вычисления общего вида полиномов ХОМФЛИ--ПТ этого семейства методом Гёрица являются твистованные узлы ${\rm Tw}_m$, поскольку в бипартитном виде они фактически представляются косой из бипартитных <<замков>> всего двух типов, что очевидно для узлов с чётным $m$, и явно продемонстрировано в разделе \ref{sec:TwistKnots} для нечётных $m$. Покажем вычисление полиномов ХОМФЛИ--ПТ для обоих типов диаграмм. Начнём со случая чётных $m$, четверная матрица Гёрица для первой раскраски I имеет очень простой вид, поскольку остаётся всего две незакрашенные области:


\begin{equation}\label{QuarterGoeritzTwistEven1}
\widetilde{\mathcal G}^{\rm Tw_m}_I  =
\begin{pmatrix}
 \begin{array}{cc}  -\frac{\widetilde{m}}{2}-1 & \frac{\widetilde{m}}{2}+1 \\  \frac{\widetilde{m}}{2}+1 & -\frac{\widetilde{m}}{2}-1
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal G^{\rm Tw_m}_I  = \left(-\frac{\widetilde{m}}{2}-1\right)\,.
\end{equation}
Из этой матрицы полином ХОМФЛИ--ПТ достаётся тривиальным образом в общем виде:


\begin{equation}\label{HOMFLYFromBipTwist}
    H^{{\rm Tw}_{m}} = \left(A^{-2}\phi^{1/2}\right)\left(A^{2}\overline{\phi}^{1/2}\right)^{m/2}\mathcal{M}\left[-\frac{\widetilde{m}}{2}-1\right]\,,
\end{equation}

\begin{equation}\label{HOMFLYFromBipTwist2}
    H^{{\rm Tw}_{m}} = A^{m-2}\frac{(D_N^2-1)\phi+(D_N+\phi)(1+D_N\overline{\phi})^{m/2}}{D_N} = \frac{A^2-A^{2+m}-q^2-A^2q^2+A^mq^2+A^{4+m}q^2+A^2q^4+A^{2+m}q^4}{(A^2-1)A^2q^2}\,.
\end{equation}



Для второй раскраски узла ${\rm Tw}_m$ имеется $\frac{m}{2}$ незакрашенных областей (см. рис. \ref{fig:QuarterCheckboardForEvenTwist}), что определяет размер $(\frac{m}{2}\times\frac{m}{2})$ четверных матриц Гёрица для твистованных узлов. Их структура будет аналогична обычным двухнитевым матрицам Гёрица \eqref{GoeritzMatrixTorKont2} с учётом различных типов пересечений: 


\begin{equation}\label{QuarterGoeritzTwistEven2}
\widetilde{\mathcal{G}}_{II}^{{\rm Tw}_{m}}  =
\begin{pmatrix}
\overline{1}+\widehat{1} & -\overline{1} & 0 & \dots  & 0 &-\widehat{1}\\
-\overline{1} & \overline{2} & -\overline{1} & \dots & & 0 \\
0 & -\overline{1} & \ddots &  & &\vdots\\

\vdots  & \vdots & &\ddots & -\overline{1} & 0 \\

0  & & & -\overline{1} & \overline{2} & -\overline{1} \\
-\widehat{1}& 0 & \dots & 0 &-\overline{1} &\overline{1}+\widehat{1}  \\

\end{pmatrix}\quad  \mapsto \quad \mathcal{G}_{II}^{{\rm Tw}_{m}}=\begin{pmatrix}
\overline{2} & -\overline{1} & 0 & \dots  & 0\\
-\overline{1} & \overline{2} & -\overline{1} & \dots  \\
0 & -\overline{1} & \ddots &  &\vdots\\

\vdots  & \vdots & & \ddots & -\overline{1} \\
0 & & \dots &-\overline{1} & \overline{1}+\widehat{1}  \\

\end{pmatrix}. 
\end{equation}
Как и для получения полиномов Джонса узлов $T[2,p]$ \eqref{ExampleTorKnot2},  преобразования Гёрица, применённые к данным матрицам, приведут к комбинаторному выражению для полинома $\mathcal{M}[\mathcal{G}]$:


\begin{equation}\label{HOMFLYFromBipTwist3}
    \mathcal{M} [\mathcal{G}_{II}^{\rm Tw_m}] = \sum_{k=0}^{m/2-2}\left\{\begin{pmatrix}
 \begin{array}{c}  m/2-1  \\  k     
 \end{array}
 \end{pmatrix}\overline{\phi}^{(m/2-1-k)/2}\overline{P}_{-{\overline{1}}}^{k}D_N^{m/2-2-k}\right\}\mathcal{M}\begin{bmatrix}\begin{pmatrix}  \overline{1} & 0\\0 & \widehat{1}     
 \end{pmatrix}

 \end{bmatrix} + \overline{P}_{-\overline{1}}^{m/2-1}\mathcal{M}[\overline{1}+\widehat{1}]\,.
\end{equation}
\begin{wrapfigure}[15]{r}{0.5\textwidth}
   \centering
    \vspace{-1cm}
    \includegraphics[width =\linewidth]{QuarterCheckboardForOddTwist.png}
    \caption{\footnotesize Шахматная раскраска для бипартитных диаграмм твистованных узлов ${\rm Tw}_m$ при нечётном $m$. Нижние пересечения в исходной диаграмме заменяются на обратные согласно алгоритму перехода к бипартитной диаграмме на рис.\,\ref{fig:TwistToBip}.}
        \label{fig:QuarterCheckboardForOddTwist}
\end{wrapfigure}
Значение полинома ХОМФЛИ--ПТ определяется той же нормировкой, что и в \eqref{HOMFLYFromBipTwist} (количество и типы <<замков>> те же самые). А итоговый ответ с очевидностью совпадает с \eqref{HOMFLYFromBipTwist2}.



Для нечётных $m$ действия метода Гёрица полностью идентичны шагам для твистованных узлов с чётным $m$ и по количеству незакрашенных областей в шахматной раскраске, и по структуре четверных матриц, поскольку различие всего в одном бипартитном <<замке>>. Так, четверные матрицы Гёрица для раскраски I с рис.\,\ref{fig:QuarterCheckboardForOddTwist} имеют следующий вид:

\begin{equation}\label{QuarterGoeritzTwistOdd1}
\widetilde{\mathcal G}^{\rm Tw_m}_I  =
\begin{pmatrix}
 \begin{array}{cc}  -\frac{\widetilde{m}+\widetilde{1}}{2}+\overline{1} & \frac{\widetilde{m}+\widetilde{1}}{2}-\overline{1} \\  \frac{\widetilde{m}+\widetilde{1}}{2}-\overline{1} & -\frac{\widetilde{m}+\widetilde{1}}{2}+\overline{1}
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal G^{\rm Tw_m}_I  = \left(-\frac{\widetilde{m}+\widetilde{1}}{2}+\overline{1}\right)\,.
\end{equation}
Полином ХОМФЛИ--ПТ примет следующее значение:


\begin{equation}\label{HOMFLYFromBipTwistOdd}
    H^{{\rm Tw}_{m}} = \left(A^{-2}\overline{\phi}{}^{1/2}\right)^{m/2+1}\mathcal{M}\left[-\frac{\widetilde{m}+\widetilde{1}}{2}-1\right]\,.
\end{equation}
Вторая раскраска отвечает матрицам размера $\frac{m+1}{2}\times\frac{m+1}{2}\,$:

\begin{equation}\label{QuarterGoeritzTwistOdd2}
\widetilde{\mathcal{G}}_{II}^{{\rm Tw}_{m}}  =
\begin{pmatrix}
\overline{1}-\widetilde{1} & -\overline{1} & 0 & \dots  & 0 &\widetilde{1}\\
-\overline{1} & \overline{2} & -\overline{1} & \dots & & 0 \\
0 & -\overline{1} & \ddots &  & &\vdots\\

\vdots  & \vdots & &\ddots & -\overline{1} & 0 \\

0  & & & -\overline{1} & \overline{2} & -\overline{1} \\
\widetilde{1}& 0 & \dots & 0 &-\overline{1} &\overline{1}-\widetilde{1}  \\

\end{pmatrix}\quad  \mapsto \quad \mathcal{G}_{II}^{{\rm Tw}_{m}}=\begin{pmatrix}
\overline{2} & -\overline{1} & 0 & \dots  & 0\\
-\overline{1} & \overline{2} & -\overline{1} & \dots  \\
0 & -\overline{1} & \ddots &  &\vdots\\

\vdots  & \vdots & & \ddots & -\overline{1} \\
0 & & \dots &-\overline{1} & \overline{1}-\widetilde{1}  \\

\end{pmatrix}. 
\end{equation}
Данная матрица, как и \eqref{QuarterGoeritzTwistEven2}, приводит к комбинаторному выражению для $\mathcal{M}[\mathcal{G}]$:


\begin{equation}\label{HOMFLYFromBipOddTwist3}
    \mathcal{M} [\mathcal{G}_{II}^{{\rm Tw}_m}] = \sum_{k=0}^{(m-3)/2}\left\{\begin{pmatrix}
 \begin{array}{c}  (m-1)/2  \\  k     
 \end{array}
 \end{pmatrix}\overline{\phi}^{((m-1)/2-k)/2}\overline{P}_{-{\overline{1}}}^{k}D_N^{(m-3)/2-k}\right\}\mathcal{M}\begin{bmatrix}\begin{array}{cc}  \overline{1} & 0\\0 & -\widetilde{1}     
 \end{array}

 \end{bmatrix} + \overline{P}_{-\overline{1}}^{(m-1)/2}\mathcal{M}[\overline{1}-\widetilde{1}]\,.
\end{equation}
С учётом нормировки, данное выражение даёт тот же ответ, что и \eqref{HOMFLYFromBipTwistOdd}, а именно:

\begin{equation}\label{HOMFLYFromBipTwistOdd2}
\begin{aligned}
    H^{{\rm Tw}_{m}} &= A^{m+3}\frac{(D_N^2-1)\overline{\phi}+(D_N+\overline{\phi})(1+D_N\overline{\phi})^{(m+1)/2}}{D_N} = \\ 
    &= \frac{A^2-A^{3+m}-A^2q^2-A^4q^2+A^{m+1}q^2+A^{5+m}q^2+A^2q^4-A^{3+m}q^4}{(1-A^2)q^2}
\end{aligned}
\end{equation}
Таким образом, вычисление общего вида фундаментальных полиномов ХОМФЛИ--ПТ для твистованных узлов методом Гёрица не представляет какой-либо сложности.


\subsection{Двухнитевые зацепления $T[2,p]$}\label{sec:HOMFLY2Torus}

Двухнитевые зацепления, они же торические $T[2,p]$, являются довольно простыми, если их представлять обычными диаграммами. В этой связи они всегда интересны для демонстрации того или иного вычисления. Бипартитные диаграммы двухнитевых узлов усложняются, но имеют понятную структуру, описанную в подразделе \ref{sec:TwoBraidsKnotsAlgorithm}, а именно, новые пересечения <<наматываются>> на диаграммы других двухнитевых зацеплений с меньшим $p$ (см. рис. \ref{fig:BipTorTangle}). Этот факт помогает выбрать однообразные раскраски на бипартитных диаграммах для $T[2,p]$, чтобы мы могли сопоставить однообразные четверные матрицы Гёрица всему семейству двухнитевых зацеплений и с их помощью выработать чёткие шаги для вычисления полинома ХОМФЛИ--ПТ произвольного двухнитевого зацепления. В качестве одного из вариантов однообразных раскрасок можно поставить в жёсткое соответствие незакрашенным областям <<накручиваемые>> бипартитные пересечения, явно это продемонстрировано на рис. \ref{fig:SixBipTorCheckboardDiagramm} и \ref{fig:GeneralBipTorCheckboardDiagramm}. Чем меньше номер белой области, тем ближе она к пересечениям, которые появились для меньших $p$. Тогда за несколько оборотов незакрашенные области <<закрываются>> от новых белых областей и не имеют пересечений с новыми областями. Это означает, что у четверных матриц Гёрица для двухнитевых диаграмм по общему принципу будут заполнены только главная диагональ и по две смежные к главной диагонали по каждой стороне. 


\begin{figure}[h!]
		\centering	
		\includegraphics[width =\linewidth]{SixBipTorCheckboardDiagramm.png}
        \caption{\footnotesize Шахматные раскраски для бипартитных диаграмм первых шести двухнитевых зацеплений, начиная от узла-трилистника.}
        \label{fig:SixBipTorCheckboardDiagramm}
	\end{figure}

Далее приведём нередуцированные четверные матрицы Гёрица для выбранной нами общей раскраски и первых шести двухнитевых зацеплений, начиная от узла-трилистника. Принцип сопоставления белых областей конкретным <<замкам>> позволит <<закрыть>> области 0 и 1 уже на последних диаграммах с рис. \ref{fig:SixBipTorCheckboardDiagramm}. Это означает, что для диаграмм с $p>8$ первые две строки и два столбца не будут иметь других ненулевых элементов, чем те, которые есть у матриц $\widetilde{\mathcal{G}}^{T[2,7]} $\eqref{BipGoeritz1Tor27} и $\widetilde{\mathcal{G}}^{T[2,8]} $\eqref{BipGoeritz1Tor28}. Из этих нередуцированных матриц мы явным образом (отбрасыванием строки и столбца, соответствующих области 0) будем однозначно получать четверные матрицы Гёрица для двухнитевых зацеплений. Далее для данных матриц мы приведём явные выражения функций $\mathcal{M}[\mathcal{G}]$ и, учтя нормировку на <<замковые>> элементы, получим полиномы ХОМФЛИ--ПТ для первых шести двухнитевых зацеплений. Функции $\mathcal{M}[\mathcal{G}]$ зацеплений с более большими $p$, как мы показываем в приложении~\ref{sec:App2}, будут выражаться через $\mathcal{M}[S_3]$ и $\mathcal{M}[C_3]$, то есть через функции для зацеплений $T[2,7]$ и $T[2,8]$. Поэтому мы сначала подробно рассмотрим частные примеры для $p \in [3,6]$, а потом, опираясь на эти примеры, поймём, как вычислить бипартитный полином ХОМФЛИ--ПТ для произвольного двухнитевого зацепления в приложении \ref{sec:App2}.

\begin{equation}\label{BipGoeritz1Tor23}
\widetilde{\mathcal{G}}^{T[2,3]}  =
\begin{pmatrix}
 \begin{array}{cc}  \widehat{1}-1 & 1-\widehat{1} \\  1-\widehat{1} & \widehat{1}-1       
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal{G}^{T[2,3]}  = S_1 = (\widehat{1}-1), \ \ \ \ \  \widetilde{\mathcal{G}}^{T[2,4]}  =
\begin{pmatrix}
 \begin{array}{cc}  \widehat{1}-2 & 2-\widehat{1} \\  2-\widehat{1} & \widehat{1}-2       
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal{G}^{T[2,4]} =C_1 = (\widehat{1}-2), 
\end{equation}





\begin{equation}\label{BipHOMFLYPTT23}
H^{T[2,3]} = \left(A^{-2}\phi^{1/2}\right)^2\mathscr{D}[\widehat{1}-1] = \frac{(A^2 - q^2 + A^2 q^4)(A-A^{-1})}{A^4 q^2(q-q^{-1})}, 
\end{equation}

\begin{equation}\label{BipHOMFLYPTT24}
H^{T[2,4]} = \left(A^{-2}\phi^{1/2}\right)^3\mathscr{D}[\widehat{1}-2] = \frac{(A^2 - q^2 - A^2 q^2 + q^4 + A^2 q^4 - q^6 - A^2 q^6 + A^2 q^8)(A-A^{-1})}{A^5 q^4(q-q^{-1})^2}\,,
\end{equation}


\begin{equation}\label{BipGoeritz1Tor25}
\widetilde{\mathcal{G}}^{T[2,5]}  =
\begin{pmatrix}
 \begin{array}{ccc}  \widehat{1}-2 & 1-\widehat{1}  & 1  \\  1-\widehat{1} & \widehat{2}-1&-\widehat{1}  \\ 1&-\widehat{1}&\widehat{1}-1    
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal{G}^{T[2,5]}  = S_2 = \begin{pmatrix}
 \begin{array}{cc}  \widehat{2}-1 & -\widehat{1} \\  -\widehat{1} & \widehat{1}-1       
 \end{array}
 \end{pmatrix}\,, 
\end{equation}


\begin{equation}\label{MPolynomialForTor25}
    \mathcal{M}\left[S_2\right] = \mathcal{U}_1[-\widehat{1}]\mathscr{D}[\widehat{1}-1]\mathscr{D}[ -1] +\mathcal{U}_2[-\widehat{1}]\mathscr{D}\left[\widehat{2}+\overline{1}-\widetilde{1}   \right] =\left( \phi^{-2}+4D_N\phi^{-1}+3+3D_N^2+4D_N\phi+\phi^2\right)D_N\,,
\end{equation}

\begin{equation}\label{HOMFLYTor25}
    H^{T[2,5]} =\left(A^{-2}\phi^{1/2}\right)^4\mathcal{M}\left[S_2\right]= \frac{(A^2 - q^2 + A^2 q^4 - q^6 + A^2 q^8)(A-A^{-1})}{A^6 q^4(q-q^{-1})}\,,
\end{equation}





\begin{equation}\label{BipGoeritz1Tor26}
\widetilde{\mathcal{G}}^{T[2,6]}  =
\begin{pmatrix}
 \begin{array}{ccc}  \widehat{1}-2 & 1-\widehat{1}  & 1  \\  1-\widehat{1} & \widehat{2}-2&1-\widehat{1}  \\ 1&1-\widehat{1}&\widehat{1}-2    
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal{G}^{T[2,6]}  = C_2 = \begin{pmatrix}
 \begin{array}{cc}  \widehat{2}-2 &1 -\widehat{1} \\ 1 -\widehat{1} & \widehat{1}-2       
 \end{array}
 \end{pmatrix}\,, 
\end{equation}

\begin{equation}\label{MPolynomialForTor26}
    \mathcal{M}\left[C_2\right] = \mathcal{U}_1[1-\widehat{1}]\mathscr{D}[\widehat{1}-1]\mathscr{D}[ -1] +\mathcal{U}_2[1-\widehat{1}]\mathscr{D}\left[\widehat{2}+\overline{1}-\widetilde{1}   \right] = \small{\frac{D_N (D_N + 3 \phi + 2 D_N^2 \phi + 9 D_N \phi^2 + D_N^3 \phi^2 + 
   4 \phi^3 + 6 D_N^2 \phi^3 + 5 D_N \phi^4 + \phi^5)}{\phi^{5/2}}}\,,
\end{equation}

\begin{equation}\label{HOMFLYTor26}
    H^{T[2,6]} =\left(A^{-2}\phi^{1/2}\right)^5\mathcal{M}\left[C_2\right]= \frac{(A^2 - q^2 - A^2 q^2 + q^4 + A^2 q^4 - q^6 - A^2 q^6 + q^8 + 
 A^2 q^8 - q^{10} - A^2 q^{10} + A^2 q^{12})(A-A^{-1})}{A^7 q^5(q-q^{-1})^2}\,.
\end{equation}

Матрицы для зацеплений $T[2,p]$ с большим $p$ будут иметь общую структуру, что мы явно продемонстрируем в приложении \ref{sec:App2}. Там же мы продемонстрируем вычисление общего вида фундаментального полинома ХОМФЛИ-ПТ для произвольного двухнитевого зацепления.



\subsection{Примеры претцельных, рациональных и монтезиносовых узлов}\label{sec:HOMFLYPrRatMon}

Претцельные, рациональные и монтезиносовые узлы являются обширными и довольно сложными семействами узлов, общий вид полиномов ХОМФЛИ--ПТ для которых неизвестен. Тем не менее, по отдельности, вычисления методом Гёрица довольно просты для каждого узла и даже групп узлов из этих семейств, что мы продемонстрируем далее на примерах. 

\paragraph{Претцельный узел $P(3,3,2)$.}


Выбор данного узла для демонстрации метода Гёрица для претцельных полиномов ХОМФЛИ--ПТ обусловлен тем, что в разделе \ref{sec:BipForPretzelKnots} он служил нам примером претцеля, имеющего бипартитную диаграмму. Шахматные раскраски для неё имеют следующий вид:

\begin{figure}[h!]
		\centering	
		\includegraphics[width =0.5\linewidth]{P332BipCheckboard.png}
        \caption{\footnotesize Два примера шахматной раскраски диаграммы узла $8_5$, он же претцельный $P(3,3,2)$.}
        \label{fig:P332BipTorCheckboard}
	\end{figure}

Поскольку число незакрашенных областей на диаграммах для обоих раскрасок будет равняться четырём, то четверные матрицы Гёрица для $P(3,3,2)$ будут размера $3 \times 3$, и их будет по четыре варианта для каждой раскраски; для каждой из них приведём для иллюстрации по одной четверной матрице Гёрица: 
    \begin{equation}\label{BipGoeritz1Pretzel332}
\widetilde{\mathcal{G}}^{P(3,3,2)}_I  =
\begin{pmatrix}
 \begin{array}{cccc} \widehat{1}-2 & 1-\widehat{1}  & 0 & 1 \\  1-\widehat{1} & \widehat{2}-2&1-\widehat{1} & 0 \\ 0&1-\widehat{1}&\widehat{1}-\widetilde{1}-1 & \widetilde{1}  \\ 1 & 0 & \widetilde{1}& -\widetilde{1} - 1    
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal{G}^{P(3,3,2)}_I  =  \begin{pmatrix}
 \begin{array}{ccc}    \widehat{2}-2&1-\widehat{1} & 0 \\ 1-\widehat{1}&\widehat{1}-\widetilde{1}-1 & \widetilde{1}  \\  0 & \widetilde{1}& -\widetilde{1} - 1  
 \end{array}
 \end{pmatrix},
\end{equation}



\begin{equation}\label{BipGoeritz1Pretzel332}
\widetilde{\mathcal{G}}^{P(3,3,2)}_{II}  =
\begin{pmatrix}
 \begin{array}{cccc} \widehat{3}+\overline{1} & -\widehat{1}  & -\widehat{1} & -\widehat{1}-\overline{1} \\  -\widehat{1} & \widehat{1}-1&0 & 1 \\ -\widehat{1}&0&\widehat{1}-1 & 1  \\ -\widehat{1}-\overline{1} & 1 & 1& \widehat{1} +\overline{1}- 2    
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal{G}^{P(3,3,2)}_{II}  =\begin{pmatrix}
 \begin{array}{ccc}  \widehat{3}+\overline{1} & -\widehat{1}  & -\widehat{1} \\  -\widehat{1} & \widehat{1}-1&0  \\ -\widehat{1}&0&\widehat{1}-1     
 \end{array}
 \end{pmatrix}. 
\end{equation}
Для первой из них приведём вычисление полинома $\mathcal{M}[\mathcal{G}]$ явно, для остальных матриц итоговый ответ очевидно будет тем же:

\begin{equation}\label{HOMFLYPretzelP332N1}
    \mathcal{M}\left[\mathcal{G}_I^{8_5}\right] =\left( \mathcal{U}_1[1-\widehat{1}]\mathcal{U}_1[\widetilde{1}]D_N+\mathcal{U}_1[1-\widehat{1}]\mathcal{U}_2[\widetilde{1}]+\mathcal{U}_2[1-\widehat{1}]\mathcal{U}_1[\widetilde{1}]\right)\mathscr{D}\left[-1\right]\mathscr{D}\left[ \widehat{1}-1\right] D_N+\mathcal{U}_2[1-\widehat{1}]\mathcal{U}_2[\widetilde{1}]\mathscr{D}\left[\widehat{1}-2  \right]D_N \,,
\end{equation}

\begin{equation}\label{HOMFLYPretzelP332N2}
    \mathcal{M}\left[\mathcal{G}_{II}^{8_5}\right] =\mathcal{U}^2_1[-\widehat{1}]\mathscr{D}^2\left[-1\right]\mathscr{D}\left[\widehat{1}+\overline{1}\right]D_N+2\mathcal{U}_1[-\widehat{1}]\mathcal{U}_2[-\widehat{1}]\mathscr{D}[-1]\mathscr{D}\left[ \widehat{1}-1+\overline{1}\right]D_N +\mathcal{U}^2_2[-\widehat{1}]\mathscr{D}\left[\widehat{1}-2 +\overline{1} \right]D_N \,,
\end{equation}

\begin{equation}\label{HOMFLYPretzelP3320N3}
    \small{\mathcal{M}\left[\mathcal{G}_{I}^{8_{5}}\right] = \mathcal{M}\left[\mathcal{G}_{II}^{8_{5}}\right] = D_N\frac{\left(1+D_N\phi\right)\left(1+2D_N{\phi}+{\phi}^2\right)^2+\left\{D_N+\left(3+2D_N^2\right)\phi+\left(9+D_N^2\right)D_N\phi^2+2\left(2+3D_N^2\right)\phi^3+5D_N\phi^4+\phi^5\right\}\overline{\phi}}{\phi^{5/2}\overline{\phi}{}^{1/2}}} \,.
\end{equation}
 С помощью нормировочных множителей и замены переменных придём к полиному ХОМФЛИ--ПТ для $P(3,3,2)$:

  \begin{equation}\label{HOMFLYFromBipForMontesinos10140}
    H^{8_5} = A^{2}\overline{\phi}{}^{1/2}\left(A^{-2}\phi^{1/2}\right)^5\mathcal{M}\left[\mathcal{G}^{8_{5}}\right]=\small{ \frac{(A-A^{-1})\left\{q^2 (1 + q^4) (1 - q^2 + q^4) + A^4 (q + q^5)^2 + A^2 (-1 + q^2 - 3 q^4 + q^6 - 3 q^8 + q^{10} - q^{12})\right\}}{A^6q^6(q-q^{-1})}}\,.
\end{equation}

\paragraph{Семейство рациональных узлов.}\label{sec:HOMFLYForRatioKnotsFamily}
    \begin{wrapfigure}[15]{r}{0.3\textwidth}
   \centering
    \vspace{-0.5cm}
    \includegraphics[width =\linewidth]{BipFamilyRatio.png}
    \caption{\footnotesize Шахматная раскраска, позволяющая запараметризовать семейство рациональных узлов с рис.\,\ref{fig:RatKnotBExample}.}
        \label{fig:BipFamilyRatio}
\end{wrapfigure}

Метод Гёрица позволяет производить вычисление общего вида полинома ХОМФЛИ--ПТ для параметрически заданных семейств узлов. Это возможно, если параметризуется число бипартитных зацеплений в бипартитных двухнитевых косах между белыми областями. Тогда размер четверной матрицы Гёрица $\mathcal{G}_{par}$ и, как следствие, количество и вид слагаемых для функции $\mathcal{M}[\mathcal{G}_{par}]$ (в терминах $\mathcal{U}_1,\mathcal{U}_2,\mathscr{D}$) будет постоянным для любых значений таких параметров.

Для демонстрации рассмотрим семейство рациональных узлов, бипартитные диаграммы для которых (см. рис. \ref{fig:RatKnotBExample}) мы обсуждали в разделе \ref{sec:ratioknots}. Данная группа узлов задаётся дробью \eqref{RatTangleExample}, которая в свою очередь определяется значением $B$, им же будет параметризоваться и всё рассматриваемое семейство рациональных узлов. Приведём такую раскраску, чтобы параметр $b=|B|$ оставался явно в четверных матрицах Гёрица и не влиял на размер этой матрицы (см. рис. \ref{fig:BipFamilyRatio}). Тогда данные матрицы примут следующий вид, когда вместо двухнитевой косы $B$ на рисунке будет коса из положительных горизонтальных <<замков>> $B_{+}$:



\begin{equation}\label{BipRatioPlusFamily}
\widetilde{\mathcal{G}}^{B_+}  =
\begin{pmatrix}
 \begin{array}{ccc}  \widehat{1}-1-\widetilde{b} & 1+\widetilde{b}  & -\widehat{1}  \\  1+\widetilde{b} & -2-\widetilde{b}&1 \\ -\widehat{1}&1&\widehat{1}-1   
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal{G}^{B_+}  = \begin{pmatrix}
 \begin{array}{cc} -2-\widetilde{b}&1 \\  1&\widehat{1}-1  
 \end{array}
 \end{pmatrix}\, .
\end{equation}
Когда параметризующая коса будет состоять из отрицательных горизонтальных <<замков>> $B_{-}$, четверная матрица для рассматриваемого семейства изменится только значением параметра:

\begin{equation}\label{BipRatioMinusFamily}
\widetilde{\mathcal{G}}^{B_-}  =
\begin{pmatrix}
 \begin{array}{ccc}  \widehat{1}-1+\widehat{b} & 1-\widehat{b}  & -\widehat{1}  \\  1-\widehat{b}  & \widehat{b} -2&1 \\ -\widehat{1}&1&\widehat{1}-1   
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal{G}^{B_-}  = \begin{pmatrix}
 \begin{array}{cc}  \widehat{b} -2&1 \\  1&\widehat{1}-1  
 \end{array}
 \end{pmatrix}\, .
\end{equation}
Функции $\mathcal{M}$ для положительного и отрицательного вариантов преобразуются простым образом:

\begin{equation}\label{MPolynomialForRatioFamily} 
\left\{\begin{split} 
\mathcal{M}\left[\mathcal{G}^{B_+}\right] = \mathcal{U}_1[1]\mathscr{D}[\widehat{1}]\mathscr{D}[ -1-\widetilde{B}]D_N +\mathcal{U}_2[1]\mathscr{D}[\widehat{1}-1-\widetilde{B}]D_N , \\
\mathcal{M}\left[\mathcal{G}^{B_-}\right] = \mathcal{U}_1[1]\mathscr{D}[\widehat{1}]\mathscr{D}[ \widehat{B}-1]D_N +\mathcal{U}_2[1]\mathscr{D}[\widehat{1}+\widehat{B}-1]D_N .\ \ 
\end{split}\right.
\end{equation}
В переменных $\phi,\, \overline{\phi},\, D_N$ функции $\mathcal{M}$ имеют, как и ожидалось, схожее выражение по структуре для обеих матриц. Положительный вариант переходит в отрицательный простой заменой $\overline{\phi}\to\phi$, что легко можно видеть из явной записи функций $\mathcal{M}$: 

\begin{equation}\label{MPolynomialSecondForRatioFamily} 
\left\{\begin{split} 
\mathcal{M}\left[\mathcal{G}^{B_+}\right] = \overline{\phi}^{-b/2}\phi^{-3/2}\left\{\phi\left(D_N^2-1\right)\left(1+\phi\left(\phi+D_N\right)\right)+\left(\phi+D_N\right)\left(1+2D_N\phi+\phi^2\right)\left(1+D_N\overline{\phi}\right)^b\right\}, \\
\mathcal{M}\left[\mathcal{G}^{B_-}\right] = \phi^{-(b+3)/2}\left\{\phi\left(D_N^2-1\right)\left(1+\phi\left(\phi+D_N\right)\right)+\left(\phi+D_N\right)\left(1+2D_N\phi+\phi^2\right)\left(1+D_N{\phi}\right)^b\right\}.\ \ \
\end{split}\right.
\end{equation}
Выражения для полиномов ХОМФЛИ--ПТ получим добавлением нормировочных множителей. Для узлов с косой $B_{+}$ --- это $\left(A^{-2}\phi^{1/2}\right)^3\left(A^{2}\overline{\phi}^{1/2}\right)^b$, для узлов с косой $B_{-}$ --- $\left(A^{-2}\phi^{1/2}\right)^{3+b}$. Итоговый ответ принимает следующий вид:

\begin{equation}\label{HOMFLYPTForRatioFamily} 
\left\{\begin{split} 
H^{B_+} = \frac{A^{2+2b}\left(A^2-q^2\right)\left(A^2q^2-1\right)(1-q^2+q^4)+\left(A^2(1+q^4)-q^2\right)\left(A^2(1-q^2+q^4)-q^2\right)}{A^7q^4(q-q^{-1})}\,, \ \ \ \ \ \ \\
H^{B_-} = A^{2b}\frac{A^{2}\left(A^2-q^2\right)\left(A^2q^2-1\right)(1-q^2+q^4)+A^{2b}\left(A^2(1+q^4)-q^2\right)\left(A^2(1-q^2+q^4)-q^2\right)}{A^7q^4(q-q^{-1})}\,. 
\end{split}\right.
\end{equation}
Аналогичным образом можно без громоздких вычислений находить фундаментальные полиномы ХОМФЛИ--ПТ для других обширных групп зацеплений, которые параметризуются числом <<замков>> в бипартитных двухнитевых косах.

\paragraph{Узел $10_{140}$ в нотации Монтезиноса.}

 \begin{wrapfigure}[11]{r}{0.3\textwidth}
   \centering
    \vspace{-0.9cm}
    \includegraphics[width =\linewidth]{Mont10140BipCheckboard.png}
    \caption{\footnotesize Шахматная раскраска для узла Монтезиноса $10_{140}=K\left(-\frac{2}{3},\,\frac{2}{3},\, -\frac{1}{4}\right)$.}
        \label{fig:Mont10140BipCheckboard}
\end{wrapfigure}

В качестве примера монтезиносова узла, про который явно неизвестны записи в претцельной и рациональной нотации, рассмотрим узел $10_{140}$. Нам он интересен не только тем, что имеет бипартитную диаграмму (см. рис. \ref{fig:Mont10140BipCheckboard}), но и тем, что его бипартитная диаграмма имеет все четыре типа <<замков>>, а значит, и четверная матрица Гёрица будет содержать все четыре параметра. Принципы построения четверных матриц более чем подробно изложены выше на различных примерах, поэтому здесь мы ограничимся демонстрацией метода только для одной раскраски, для которой приведём нередуцированную матрицу и одну из возможных четверных матриц Гёрица для неё:





\begin{equation}\label{BipGoeritzForMontesinos10140}
\widetilde{\mathcal{G}}^{10_{140}}  =
\begin{pmatrix}
 \begin{array}{ccc}  \widehat{3}-1 & 1-\widehat{1}  & -\widehat{2}  \\  1-\widehat{1} & \widehat{1}+\overline{1}-\widetilde{1}-1&\widetilde{1} -\overline{1} \\ -\widehat{2}&\widetilde{1}-\overline{1}&\overline{1}+\widehat{2}-\widetilde{1}    
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal{G}^{10_{140}}  = \begin{pmatrix}
 \begin{array}{cc}  \widehat{3}-1 & 1-\widehat{1}   \\  1-\widehat{1} & \widehat{1}+\overline{1}-\widetilde{1}-1    
 \end{array}
 \end{pmatrix}\, .
\end{equation}
Функция $\mathcal{M}$ для данного узла выразится следующим образом:

\begin{equation}\label{HOMFLYMontesinos10140N1}
    \mathcal{M}\left[\mathcal{G}^{10_{140}}\right] = \mathcal{U}_1[1-\widehat{1}]\mathscr{D}[\widehat{2}]\mathscr{D}[ \overline{1}-\widetilde{1}]D_N +\mathcal{U}_2[1-\widehat{1}]\mathscr{D}\left[\widehat{2}+\overline{1}-\widetilde{1}   \right]D_N \,,
\end{equation}

\begin{equation}\label{HOMFLYMontesinos10140N2}
    \mathcal{M}\left[\mathcal{G}^{10_{140}}\right] = \small{\frac{\phi\left(D_N+2\phi+D_N\phi^2\right)\left(1+2D_N\overline{\phi}+\overline{\phi}^2\right)+\left(1+\phi\left(D_N+\phi\right)\right)\left\{D_N\overline{\phi}+\overline{\phi}{}^2+\left(1+D_N\overline{\phi}\right)\left(1+\phi+\left(2+D_N{\phi}\right)\left(D_N+\overline{\phi}\right)\right)\right\}}{\phi^2\overline{\phi}}}D_N \,.
\end{equation}
  Тогда с нормировкой на количество <<замковых>> элементов получаем полином ХОМФЛИ--ПТ для $10_{140}$:

  \begin{equation}\label{HOMFLYFromBipForMontesinos10140}
    H^{10_{140}} = \left(A^{-2}\phi^{1/2}\right)^4\left(A^{2}\overline{\phi}{}^{1/2}\right)^{2}\mathcal{M}\left[\mathcal{G}^{10_{140}}\right]= \frac{(A^6q^4-q^2(1+q^4)+A^2(1+q^4)^2-A^4q^2(1+q^4))(A-A^{-1})}{A^6q^4(q-q^{-1})}\,.
\end{equation}


\section{Заключение}
 В данной работе мы явно показали, что метод, позволяющий по матрице Гёрица для шахматной раскраски диаграммы зацепления вычислять полином Джонса ~\cite{boninger2023jones}, является способом иначе взглянуть на разрешение диаграммы зацепления скобкой Кауффмана. Пользуясь наработанной на примере этого метода интуицией, мы построили новый метод, но уже для вычисления бипартитных полиномов ХОМФЛИ--ПТ. Этот подход в свою очередь является содержательно близким планарному разложению для бипартитных полиномов ХОМФЛИ--ПТ ~\cite{anokhina2024planar,anokhina2025bipartite,anokhina2025planar}. Для реализации нашего метода мы ввели новые правила шахматной раскраски для бипартитных диаграмм и новый объект --- четверную матрицу Гёрица, которая содержит числа <<замков>> бипартитной диаграммы, разделяющих две соседние области. Также нами был придуман алгоритм, позволяющий сопоставить полином в переменных планарного разложения для четверной матрицы Гёрица, который при правильной нормировке и даёт полином ХОМФЛИ--ПТ, что в свою очередь было продемонстрировано на многочисленных примерах: твистованных, двухнитевых, претцельных, рациональных и монтезиносовых узлах и зацеплениях. Новый метод оказался довольно удобным для вычисления общего вида полиномов ХОМФЛИ--ПТ отдельных классов зацеплений, различающихся количеством бипартитных <<замков>> в отдельных бипартитных двухнитевых косах.

