\section{Матрица Гёрица и полином ХОМФЛИ--ПТ произвольного \\ двухнитевого зацепления}\label{sec:App2}

Продолжим демонстрацию метода Гёрица на примере вычисления общего вида фундаментальных полиномов ХОМФЛИ--ПТ для торических зацеплений $T[2,p]$. Ниже мы находим полиномы ХОМФЛИ--ПТ для торических зацеплений $T[2,7]$ и $T[2,8]$:

\begin{equation}\label{BipGoeritz1Tor27}
\widetilde{\mathcal{G}}^{T[2,7]}  =
\begin{pmatrix}
 \begin{array}{cccc} \widehat{1}-2 & 1-\widehat{1}  & 1 & 0 \\  1-\widehat{1} & \widehat{2}-2&-\widehat{1} & 1 \\ 1&-\widehat{1}&\widehat{2}-1 & -\widehat{1}  \\ 0 & 1 & -\widehat{1}& \widehat{1} - 1    
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal{G}^{T[2,7]}  = S_3 = \begin{pmatrix}
 \begin{array}{ccc}  \widehat{2}-2 & -\widehat{1} & 1 \\  -\widehat{1} & \widehat{2}-1 & -\widehat{1} \\ 1 & -\widehat{1} & \widehat{1}-1      
 \end{array}
 \end{pmatrix}\,, 
\end{equation}

\begin{equation}\label{MPolynomialForTor27}
\begin{aligned}
&\mathcal{M}\left[S_3\right] = \left\{\mathcal{U}^2_1[-\widehat{1}]\left(\mathcal{U}_1[1]D_N+\mathcal{U}_2[1]\right)+\mathcal{U}_2[-\widehat{1}]\mathcal{U}_1[1-\widehat{1}]\right\}D_N\mathscr{D}\left[\widehat{1}-1\right]\mathscr{D}\left[ -1\right] +\\
&+\left\{\mathcal{U}_1[-\widehat{1}]\mathcal{U}_2[-\widehat{1}]\left(\mathcal{U}_1[1]D_N+\mathcal{U}_2[1]\right)+\mathcal{U}_2[-\widehat{1}]\mathcal{U}_2[1-\widehat{1}]\right\}D_N\mathscr{D}\left[\widehat{1}-2  \right] ,
\end{aligned}
\end{equation}

\begin{equation}\label{MPolynomialForTor27Two}
\mathcal{M}\left[S_3\right] = \left(\phi^{-3}+6D_N\phi^{-2}+\left(6+9D_N^2\right)\phi^{-1}+4 D_N (4 + D_N^2)+5 (1 + 2 D_N^2)+6D_N\phi^2+\phi^3\right)D_N\,,
\end{equation}

\begin{equation}\label{HOMFLYTor27}
    H^{T[2,7]} =\left(A^{-2}\phi^{1/2}\right)^6\mathcal{M}\left[S_3\right]= \frac{(A^2 - q^2 + A^2 q^4 - q^6 + A^2 q^8 - q^{10} + A^2 q^{12})(A-A^{-1})}{A^8 q^6(q-q^{-1})}\,,
\end{equation}





\begin{equation}\label{BipGoeritz1Tor28}
\widetilde{\mathcal{G}}^{T[2,8]}  =
\begin{pmatrix}
 \begin{array}{cccc} \widehat{1}-2 & 1-\widehat{1}  & 1 & 0 \\  1-\widehat{1} & \widehat{2}-2&-\widehat{1} & 1 \\ 1&-\widehat{1}&\widehat{2}-2 & 1-\widehat{1}  \\ 0 & 1 & 1-\widehat{1}& \widehat{1} - 2    
 \end{array}
 \end{pmatrix}\quad \mapsto \quad \mathcal{G}^{T[2,8]}  = C_3 = \begin{pmatrix}
 \begin{array}{ccc}  \widehat{2}-2 & -\widehat{1} & 1 \\  -\widehat{1} & \widehat{2}-2 & 1-\widehat{1} \\ 1 & 1-\widehat{1} & \widehat{1}-2      
 \end{array}
 \end{pmatrix}\,, 
\end{equation}

\begin{equation}\label{MPolynomialForTor28}
\begin{aligned}
&\mathcal{M}\left[C_3\right] = \left\{\mathcal{U}_1[1-\widehat{1}]\mathcal{U}_1[-\widehat{1}]\left(\mathcal{U}_1[1]D_N+\mathcal{U}_2[1]\right)+\mathcal{U}_2[1-\widehat{1}]\mathcal{U}_1[1-\widehat{1}]\right\}D_N\mathscr{D}\left[\widehat{1}-1\right]\mathscr{D}\left[ -1\right] +\\
&+\left\{\mathcal{U}_1[1-\widehat{1}]\mathcal{U}_2[-\widehat{1}]\left(\mathcal{U}_1[1]D_N+\mathcal{U}_2\right)+\mathcal{U}^2_2[1-\widehat{1}]\right\}D_N\mathscr{D}\left[\widehat{1}-2  \right] ,
\end{aligned}
\end{equation}


\begin{equation}\label{MPolynomialForTor28Two}
\mathcal{M}\left[C_3\right] = \small{\frac{D_N + 4 \phi + 3 D_N^2 \phi + 18 D_N \phi^2 + 3 D_N^3 \phi^2 + 
 10 \phi^3 + 24 D_N^2 \phi^3 + D_N^4 \phi^3 + 25 D_N \phi^4 + 
 10 D_N^3 \phi^4 + 6 \phi^5 + 15 D_N^2 \phi^5 + 
 7 D_N \phi^6 + \phi^7}{\phi^{7/2}}D_N}\,,
\end{equation}

\begin{equation}\label{HOMFLYTor28}
    H^{T[2,8]} =\left(A^{-2}\phi^{1/2}\right)^7\mathcal{M}\left[C_3\right]= \frac{(-q^2 + (1 - q^2 + q^4) (q^4 - q^{10} + A^2 (1 - q^6 + q^{12})))(A-A^{-1})}{A^9 q^7(q-q^{-1})^2}\,.
\end{equation}
  Стоит отметить, что все такие матрицы можно разделить на два типа по чётности $p$, которые отличаются содержанием элементов в матрице. Мы выбрали раскраски так, что диаграммы узлов с чётными $p$ имеют белую внешнюю область, назовём это $C$-типом четверной матрицы Гёрица для двухнитевых узлов. Тогда у диаграмм с нечётными $p$, названных нами $S$-типом, внешняя область будет закрашена, что демонстрируется рис.\,\ref{fig:GeneralBipTorCheckboardDiagramm}.

