\vdots  & \ddots & \ddots&\ddots & \ddots & \ddots&\ddots& 0 \\
{ \ } &{ \ } & \ddots & \ddots & \ddots& \widehat{2}-2&-\widehat{1}&1
\\
\vdots &{ \ } & 
{ \ } &\ddots & \ddots & -\widehat{1} & \widehat{2}-2&1-\widehat{1} \\
0 & \dots & { \ }  &\dots & 0 &1 &1-\widehat{1} & \widehat{1}-2  

\end{pmatrix} \quad  \mapsto \quad 
\begin{pmatrix}
\begin{array}{ccccccc}
 \widehat{2}-2 & -\widehat{1} & 1 &0 & \dots & \dots & 0\\
 -\widehat{1}& \widehat{2}-2  & -\widehat{1}& \ddots &\ddots & { \ } & \vdots\\
1&-\widehat{1}&\widehat{2}-2&\ddots&\ddots&\ddots&\vdots \\

 0 & \ddots&\ddots & \ddots & \ddots&\ddots& 0 \\
 \vdots& \ddots & \ddots & \ddots& \widehat{2}-2&-\widehat{1}&1
\\
\vdots &{ \ } &\ddots & \ddots & -\widehat{1} & \widehat{2}-2&1-\widehat{1} \\
0 & \dots &\dots & 0 &1 &1-\widehat{1} & \widehat{1}-2 \\
