	\section{The standard method to calculate SDE free energy\label{standard}}
	We still focus on the minimal free energy to describe SDE. The superconductivity susceptibility in the coefficient $\alpha_{\boldsymbol{q}}$ is calculated by
	\begin{align}
		\chi(\boldsymbol{q})=k_BT\sum_{\boldsymbol{k},i\omega_n}Tr\left[\Gamma^{\dagger}\mathcal{G}\left(\boldsymbol{k+\frac{q}{2}},i\omega_n\right)\Gamma\mathcal{G}^T\left(\boldsymbol{-k+\frac{q}{2}},-i\omega_n\right)\right]. \label{chi}
	\end{align}
	We use the Rashba system and unconventional Rashba system for examples. An in-plane magnetic field should be applied to these models, to achieve SDE. In the first order of the field, the Green's function is
	\begin{align}
		\mathcal{G}\left(\boldsymbol{k},i\omega_n\right)=\left[i\omega_n-H_0(\boldsymbol{k})-\boldsymbol{B}\cdot\boldsymbol{\sigma}\right]^{-1}=\mathcal{G}_0\left(\boldsymbol{k},i\omega_n\right)+\mathcal{G}_0\left(\boldsymbol{k},i\omega_n\right)(\boldsymbol{B}\cdot\boldsymbol{\sigma})\mathcal{G}_0\left(\boldsymbol{k},i\omega_n\right), \label{gf}
	\end{align}
	where $\mathcal{G}_0\left(\boldsymbol{k},i\omega_n\right)$ is the bare Green's function without field. Plugging Eqs. (\ref{chi}) and (\ref{gf}), to the first order of the field, the susceptibility is contributed by two terms
	\begin{align}
		\chi(\boldsymbol{q})&=\chi_0(\boldsymbol{q})+\chi_{\boldsymbol{B}}(\boldsymbol{q}), \\
		\chi_0(\boldsymbol{q})&=k_BT\sum_{\boldsymbol{k},i\omega_n}Tr\left[\Gamma^{\dagger}\mathcal{G}_0\left(\boldsymbol{k+\frac{q}{2}},i\omega_n\right)\Gamma\mathcal{G}_0^T\left(\boldsymbol{-k+\frac{q}{2}},-i\omega_n\right)\right], \label{chi0} \\
		\chi_{\boldsymbol{B}}(\boldsymbol{q})&=k_BT\sum_{\boldsymbol{k},i\omega_n}\left\{Tr\left[\Gamma^{\dagger}\mathcal{G}_0\left(\boldsymbol{k+\frac{q}{2}},i\omega_n\right)(\boldsymbol{B}\cdot\boldsymbol{\sigma})\mathcal{G}_0\left(\boldsymbol{k+\frac{q}{2}},i\omega_n\right)\Gamma\mathcal{G}_0^T\left(\boldsymbol{-k+\frac{q}{2}},-i\omega_n\right)\right]\right. \notag  \\
		&\left.+Tr\left[\Gamma^{\dagger}\mathcal{G}_0\left(\boldsymbol{k+\frac{q}{2}},i\omega_n\right)\Gamma\mathcal{G}_0^T\left(\boldsymbol{-k+\frac{q}{2}},-i\omega_n\right)(\boldsymbol{B}\cdot\boldsymbol{\sigma}^T)\mathcal{G}_0^T\left(\boldsymbol{-k+\frac{q}{2}},-i\omega_n\right)\right]\right\}. \label{chiB}
	\end{align}
	\subsection{Rashba system}
	For a Rashba system with Hamiltonian
	\begin{equation}
		H_R\left(\boldsymbol{k}\right)=\xi_{\boldsymbol{k}}\sigma^0+\lambda_{R}\left(\boldsymbol{k}\times\boldsymbol{\sigma}\right)\cdot\hat{\boldsymbol{z}},
	\end{equation}
	the Fermi surface can not be regarded as a single circle, but splits to inner and outer ones, we use $s\in\{+,-\}$ to label them. The two Fermi momenta $k_{F}^{s}=\left(\sqrt{\lambda_{R}^2+4t\mu}-s\lambda_{R}\right)/2t$, $s=+$ for the inner circle while $s=-$ for the outer circle, and $\xi_{\boldsymbol{k}}=tk^2-\mu$ is the standard electron dispersion. One can find the corresponding Fermi velocities are the same
	\begin{align}
		v_F\equiv2tk_F^{s}+s\lambda_{R}=\sqrt{\lambda_{R}^2+4t\mu}.
	\end{align}
	The Green's function for electron is
	\begin{align}
		\mathcal{G}_0\left(\boldsymbol{k},i\omega_n\right)=\left[i\omega_n-H_R(\boldsymbol{k})\right]^{-1}=g_{++}\sigma^0+g_{+-}\left(\hat{\boldsymbol{k}}\times\boldsymbol{\sigma}\right)\cdot\hat{\boldsymbol{z}},
	\end{align}
	with $g_{\alpha\beta}=\alpha/\left[i\omega_n-E_{+}(\boldsymbol{k})\right]+\beta/\left[i\omega_n-E_{-}(\boldsymbol{k})\right]$, and $E_{\pm}(\boldsymbol{k})=\xi_{\boldsymbol{k}}\pm\lambda_Rk$. Then we can calculate the superconductivity susceptibility with 
	\begin{align}
		\mathcal{G}_0\left(\boldsymbol{k+\frac{q}{2}},i\omega_n\right)&=g_{++}\sigma^0+g_{+-}\left\{\left[\left(1-\frac{\hat{\boldsymbol{k}}\cdot\boldsymbol{q}}{2k}\right)\hat{\boldsymbol{k}}+\frac{\boldsymbol{q}}{2k}\right]\times\boldsymbol{\sigma}\right\}\cdot\hat{\boldsymbol{z}}, \label{G01} \\
		\mathcal{G}_0^T\left(-\boldsymbol{k+\frac{q}{2}},-i\omega_n\right)&=h_{++}\sigma^0+h_{+-}\left\{\left[-\left(1+\frac{\hat{\boldsymbol{k}}\cdot\boldsymbol{q}}{2k}\right)\hat{\boldsymbol{k}}+\frac{\boldsymbol{q}}{2k}\right]\times\boldsymbol{\sigma}^T\right\}\cdot\hat{\boldsymbol{z}}. \label{G02}
	\end{align}
	Since the band splitting is much larger than the superconducting order parameter, we neglect the contribution from bands deviating from the Fermi surface (e.g., $g_{++}^+=g_{+-}^+=1/[i\omega_n-E_{+}(\boldsymbol{k})]$). There are the relations
	\begin{align}
		g_{++}^{s}\left(\boldsymbol{k},\boldsymbol{q},i\omega_n\right)&=s g_{+-}^{s}\left(\boldsymbol{k},\boldsymbol{q},i\omega_n\right), \\
		h_{++}^{s}\left(\boldsymbol{k},\boldsymbol{q},i\omega_n\right)&=s h_{+-}^{s}\left(\boldsymbol{k},\boldsymbol{q},i\omega_n\right).
	\end{align}
	And the explicit values to the order we care are
	\begin{align}
		&g_{++}^{s}=\frac{G}{2}\left[1+G\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}+s\lambda_{R}\left|\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right|\right)+G^2\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}\right)\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}+2s\lambda_{R}\left|\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right|\right) \notag\right. \\
		&\phantom{=\;\;}\left.+ G^3\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}\right)^2\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}+3s\lambda_{R}\left|\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right|\right)+ G^4\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}\right)^3\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}+4\nu\lambda_{R}\left|\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right|\right)\right], \label{g++} \\
		&h_{++}^{s}=-\frac{\tilde{G}}{2}\left[1+\tilde{G}\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}-s\lambda_{R}\left|-\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right|\right)+\tilde{G}^2\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}\right)\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}-2s\lambda_{R}\left|-\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right|\right) \notag\right. \\
		&\phantom{=\;\;}\left.+ \tilde{G}^3\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}\right)^2\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}-3s\lambda_{R}\left|-\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right|\right)+ \tilde{G}^4\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}\right)^3\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}-4s\lambda_{R}\left|-\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right|\right)\right]. \label{h++}
	\end{align}
	Here, the velocity $\boldsymbol{v}^{s}\equiv2t\boldsymbol{k}_F^{s}=\left(v_F-s\lambda_{R}\right)\hat{\boldsymbol{k}}$, the Green's functions are $G=(i\omega_n-\xi_{\boldsymbol{k}})^{-1}$ and $\tilde{G}=(i\omega_n+\xi_{-\boldsymbol{k}})^{-1}$. It is covenient to calculate the summation with the formula
	\begin{align}
		\langle &G^l\tilde{G}^m\rangle=k_BT\sum_{\boldsymbol{k},i\omega_n}\frac{1}{\left(i\omega_n-\xi_{\boldsymbol{k}}\right)^l}\frac{1}{\left(i\omega_n+\xi_{\boldsymbol{-k}}\right)^m}=\frac{N_F}{(l-1)!(m-1)!}\tilde{\chi}_{l+m}, \\
		&\tilde{\chi}_{l+m}=\begin{cases}
			-\ln\left(C/T\right),\quad l+m=2 \\
			\frac{4(l+m-2)!}{(2i)^{l+m}}\left[1+(-1)^{l+m}\right]\left[1-\left(\frac{1}{2}\right)^{l+m-1}\right]\frac{\zeta(l+m-1)}{\left(\pi k_BT\right)^{l+m-2}}. \label{chilm}
		\end{cases}
	\end{align}
	Here, $\zeta(x)$ is the Reimann zeta function. One can find that the nonzero contributions are the terms in even order of the Green's function, or to say, $l+m$ is even. Using the result
	\begin{align}
		&\left(gh\right)_{s}\equiv g_{++}^{s}h_{++}^{s}=g_{+-}^{s}h_{+-}^{s} \notag \\
		&=-\frac{G\tilde{G}}{4}\left\{1+\left(G^2+\tilde{G}^2+G\tilde{G}\right)\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}\right)^2+2s\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}\right)\lambda_{R}\left[\left(G^2+\frac{G\tilde{G}}{2}\right)\left|\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right|-\left(\tilde{G}^2+\frac{G\tilde{G}}{2}\right)\left|-\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right|\right]\right. \notag \\
		&+\left(G^4+\tilde{G}^4+G^3\tilde{G}+G\tilde{G}^3+G^2\tilde{G}^2\right)\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}\right)^4+s\left(\boldsymbol{v}^{s}\cdot\frac{\boldsymbol{q}}{2}\right)^3\lambda_{R}\left[\left(4G^4+3G^3\tilde{G}+G\tilde{G}^3+2G^2\tilde{G}^2\right)\left|\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right| \notag\right. \\
		&\phantom{=\;\;}\left.\phantom{=\;\;}\left.-\left(4\tilde{G}^4+G^3\tilde{G}+3G\tilde{G}^3+2G^2\tilde{G}^2\right)\left|-\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right|\right]\right\}, \label{gh}
	\end{align}
	thus,
	\begin{align}
		\left\langle\left(gh\right)_{s}\right\rangle=-\frac{N_F^{s}}{4}\left[\tilde{\chi}_2+\frac{1}{2}v_F^2\tilde{\chi}_4\left\langle\left(\hat{\boldsymbol{k}}\cdot\boldsymbol{q}\right)^2\right\rangle+\frac{1}{24}v_F^4\tilde{\chi}_6\left\langle\left(\hat{\boldsymbol{k}}\cdot\boldsymbol{q}\right)^4\right\rangle\right]. \label{gh}
	\end{align}
	The field free susceptibility is calculated as
	\begin{align}
		\chi_0(\boldsymbol{q})=2\sum_{s}\langle g_{++}^{s}h_{++}^{s}+g_{+-}^{s}h_{+-}^{s}\rangle=-\left(N_{F}^{+}+N_{F}^{-}\right)\left(\tilde{\chi}_2+\frac{1}{4}\tilde{\chi}_4v_F^2q^2\right)
	\end{align}
	The field-dependent susceptibility is contributed by values as follows
	\begin{align}
		\left(g^2h\right)_{s}&\equiv g_{++}^{s}g_{+-}^{s}h_{++}^{s}=\left(g_{++}^{s}\right)^2h_{+-}^{s}=\left(g_{+-}^{s}\right)^2h_{+-}^{s}, \\
		\left(gh^2\right)_{s}&\equiv g_{++}^{s}h_{++}^{s}h_{+-}^{s}=g_{+-}^{s}\left(h_{++}^{s}\right)^2=g_{+-}^{s}\left(h_{+-}^{s}\right)^2.
	\end{align}
	These values have nonzero parts which are proportional to $\hat{\boldsymbol{k}}\cdot\boldsymbol{q}$ and $\left(\hat{\boldsymbol{k}}\cdot\boldsymbol{q}\right)^3$. Therefore, we get the nonzero term of $\chi_{\boldsymbol{B}}$ 
	\begin{align}
		\chi_{\boldsymbol{B}}\left(\boldsymbol{q}\right)=8\sum_{s}\left\langle\left[\left(g^2h\right)_{s}-\left(gh^2\right)_{s}\right]\left(\hat{\boldsymbol{k}}\times\boldsymbol{B}\right)\cdot\hat{\boldsymbol{z}}\right\rangle. 
	\end{align}
	Calculations show that 
	\begin{align}
		\left\langle\left(g^2h\right)_{s}\left(\hat{\boldsymbol{k}}\times\boldsymbol{B}\right)\cdot\hat{\boldsymbol{z}}\right\rangle=-\left\langle\left(gh^2\right)_{s}\left(\hat{\boldsymbol{k}}\times\boldsymbol{B}\right)\cdot\hat{\boldsymbol{z}}\right\rangle=-\frac{N_F^{s}}{16}\left\{\left(s v^{s}+\lambda_{R}\right)\tilde{\chi}_4+\frac{1}{8}\left[s\left(v^{s}\right)^3+3\lambda_{R}\left(v^{s}\right)^2\right]\tilde{\chi}_6q^2\right\}\left(\boldsymbol{q}\times\boldsymbol{B}\right)\cdot\hat{\boldsymbol{z}}. 
	\end{align}
	Plugging $N_F^{s}=\left(1-s\lambda_{R}/v_F\right)N_F/2$, we get
	\begin{equation}
		\chi_{\boldsymbol{B}}\left(\boldsymbol{q}\right)=N_F\left(\tilde{\chi}_4+\frac{1}{8}\tilde{\chi}_6v_F^2q^2\right)\lambda_{R}\left(\boldsymbol{q}\times\boldsymbol{B}\right)\cdot\hat{\boldsymbol{z}}.
	\end{equation}
	The coefficient for the free energy is obtained
	\begin{align}
		\alpha_{\boldsymbol{q}}=\frac{1}{V}+N_F\left[\left(\tilde{\chi}_2+\frac{1}{4}\tilde{\chi}_4v_F^2q^2\right)-\left(\tilde{\chi}_4+\frac{1}{8}\tilde{\chi}_6v_F^2q^2\right)\lambda_{R}\boldsymbol{q}\cdot\left(\boldsymbol{B}\times\hat{\boldsymbol{z}}\right)\right]. \label{aq}
	\end{align}
	\subsection{Unconventional Rashba system}
	The bare Green's function for unconventional Rashba model is
	\begin{align}
		\mathcal{G}_0(\boldsymbol{k},i\omega_n)&=G_{++++}\sigma^0\tau^0+G_{+-+-}\hat{\boldsymbol{k}}\cdot\left(\boldsymbol{\sigma}\times\hat{\boldsymbol{z}}\right)\tau^x+G_{++--}\left[\frac{\lambda_Rk}{\sqrt{\lambda^2+\lambda_R^2k^2}}\hat{\boldsymbol{k}}\cdot\left(\boldsymbol{\sigma}\times\hat{\boldsymbol{z}}\right)\tau^0+\frac{\lambda}{\sqrt{\lambda^2+\lambda_R^2k^2}}\sigma^z\tau^y\right] \notag \\
		&+G_{+--+}\left[\frac{\lambda_Rk}{\sqrt{\lambda^2+\lambda_R^2k^2}}\sigma^0\tau^x-\frac{\lambda}{\sqrt{\lambda^2+\lambda_R^2k^2}}\hat{\boldsymbol{k}}\cdot\boldsymbol{\sigma}\tau^z\right], 
	\end{align}
	with $G_{\alpha\beta\gamma\delta}=(\alpha G_{++}+\beta G_{+-}+\gamma G_{-+}+\delta G_{--})/4$, and 
	\begin{align}
		&G_{\alpha\beta}(\boldsymbol{k},i\omega_n)=\frac{1}{i\omega_n-E_{\alpha\beta}(\boldsymbol{k})}, \\
		&E_{\alpha\beta}(\boldsymbol{k})=\xi_{\boldsymbol{k}}+\alpha\sqrt{\lambda^{2}+\lambda_{R}^{2}k^{2}}+\beta\varepsilon\lambda_{R}k.
	\end{align}
	Since the Fermi surface is setted in the gap, we ignore the contribution from the upper two bands. We can simplify the Green's function to 
	\begin{align}
		&\mathcal{G}_0(\boldsymbol{k},i\omega_n)=G_{++++}\left[\sigma^0\tau^0-\frac{\lambda_Rk}{\sqrt{\lambda^2+\lambda_R^2k^2}}\hat{\boldsymbol{k}}\cdot\left(\boldsymbol{\sigma}\times\hat{\boldsymbol{z}}\right)\tau^0-\frac{\lambda}{\sqrt{\lambda^2+\lambda_R^2k^2}}\sigma^z\tau^y\right] \notag \\
		&+G_{+-+-}\left[\hat{\boldsymbol{k}}\cdot\left(\boldsymbol{\sigma}\times\hat{\boldsymbol{z}}\right)\tau^x-\frac{\lambda_Rk}{\sqrt{\lambda^2+\lambda_R^2k^2}}\sigma^0\tau^x+\frac{\lambda}{\sqrt{\lambda^2+\lambda_R^2k^2}}\hat{\boldsymbol{k}}\cdot\boldsymbol{\sigma}\tau^z\right].
	\end{align}
	Ignoring pairings deviating from Fermi surface, for electron and hole, we get the Green's functions
	\begin{align}
		&\mathcal{G}_0(\boldsymbol{k+\frac{q}{2}},i\omega_n)=\frac{\tilde{g}_{++}}{2}\left[\sigma^0\tau^0-\sin\phi_{\boldsymbol{q}}\frac{\boldsymbol{k}+\boldsymbol{q}/2}{\left|\boldsymbol{k}+\boldsymbol{q}/2\right|}\cdot\left(\boldsymbol{\sigma}\times\hat{\boldsymbol{z}}\right)\tau^0-\cos\phi_{\boldsymbol{q}}\sigma^z\tau^y\right] \notag \\
		&+\frac{\tilde{g}_{+-}}{2}\left[\frac{\boldsymbol{k}+\boldsymbol{q}/2}{\left|\boldsymbol{k}+\boldsymbol{q}/2\right|}\cdot\left(\boldsymbol{\sigma}\times\hat{\boldsymbol{z}}\right)\tau^x-\sin\phi_{\boldsymbol{q}}\sigma^0\tau^x+\cos\phi_{\boldsymbol{q}}\frac{\boldsymbol{k}+\boldsymbol{q}/2}{\left|\boldsymbol{k}+\boldsymbol{q}/2\right|}\cdot\boldsymbol{\sigma}\tau^z\right], \label{URG1} \\
		&\mathcal{G}_0^T(\boldsymbol{-k+\frac{q}{2}},-i\omega_n)=\frac{\tilde{h}_{++}}{2}\left[\sigma^0\tau^0+\sin\phi_{-\boldsymbol{q}}\frac{\boldsymbol{k}-\boldsymbol{q}/2}{\left|\boldsymbol{k}-\boldsymbol{q}/2\right|}\cdot\left(\boldsymbol{\sigma}^T\times\hat{\boldsymbol{z}}\right)\tau^0+\cos\phi_{-\boldsymbol{q}}\sigma^z\tau^y\right] \notag \\
		&-\frac{\tilde{h}_{+-}}{2}\left[\frac{\boldsymbol{k}-\boldsymbol{q}/2}{\left|\boldsymbol{k}-\boldsymbol{q}/2\right|}\cdot\left(\boldsymbol{\sigma}^T\times\hat{\boldsymbol{z}}\right)\tau^x+\sin\phi_{-\boldsymbol{q}}\sigma^0\tau^x+\cos\phi_{-\boldsymbol{q}}\frac{\boldsymbol{k}-\boldsymbol{q}/2}{\left|\boldsymbol{k}-\boldsymbol{q}/2\right|}\cdot\boldsymbol{\sigma}^T\tau^z\right]. \label{URG2}
	\end{align}
	Here, the Green's functions correspond to the previous values Eqs. (\ref{g++},\ref{h++}) by $\tilde{g}(\tilde{h})=g\left(h\right)|_{\lambda_{R}\to\varepsilon\lambda_{R}}$. Then we get the susceptibilities
	\begin{align}
		\chi_0\left(\boldsymbol{q}\right)&=2\sum_{s}\left\langle \left(1+\cos\phi_{\boldsymbol{q}}\cos\phi_{-\boldsymbol{q}}+\sin\phi_{\boldsymbol{q}}\sin\phi_{-\boldsymbol{q}}\right)\left(gh\right)_{s}\right\rangle=-N_F\left(\tilde{\chi}_2+\frac{1}{4}\tilde{\chi}_4v_F^2q^2\right). 
	\end{align}
	We have ignored the value to the order of $\left(q/k_F\right)^2$. The field-dependent susceptibility is related to the values
	\begin{align}
		&\left(g_{++}^{s}\right)^2h_{++}^{s}=\left(g_{+-}^{\nu}\right)^2h_{++}^{s}=g_{++}^{s}g_{+-}^{s}h_{+-}^{s}=s\left(g^2h\right)_{s}, \\
		&g_{++}^{s}\left(h_{++}^{s}\right)^2=g_{++}^{s}\left(h_{+-}^{s}\right)^2=g_{+-}^{s}h_{++}^{s}h_{+-}^{s}=s\left(gh^2\right)_{s}.
	\end{align}
	And the result is
	\begin{align}
		\chi_{\boldsymbol{B}}\left(\boldsymbol{q}\right)&=-8\sum_{s}s\sin\phi\left\langle\left[\left(g^2h\right)_{s}-\left(gh^2\right)_{s}\right]\left(\hat{\boldsymbol{k}}\times\boldsymbol{B}\right)\cdot\hat{\boldsymbol{z}}\right\rangle \notag \\
		&=N_F\left(\tilde{\chi}_4+\frac{1}{8}\tilde{\chi}_6v_F^2q^2\right)\frac{\lambda_Rk_F}{\sqrt{\lambda^2+\lambda_R^2k_F^2}}v_F\left(\boldsymbol{q}\times\boldsymbol{B}\right)\cdot\hat{\boldsymbol{z}} \notag \\
		&\approx\frac{2\mu}{\lambda}N_F\left(\tilde{\chi}_4+\frac{1}{8}\tilde{\chi}_6v_F^2q^2\right)\lambda_R\left(\boldsymbol{q}\times\boldsymbol{B}\right)\cdot\hat{\boldsymbol{z}}. 
	\end{align}
	With the assumption of $\lambda\approx\mu$, we get the final line. This result shows that $\chi_{\boldsymbol{B}}^{UR}=\left(2\mu/\lambda\right)\chi_{\boldsymbol{B}}^{R}$. 

	\section{The simplified method to calculate SDE free energy\label{simplified}}
	We simplify the calculation by writting the superconducting model in band space, for example, the Hamiltonian for Rashba system can be written as
	\begin{align}
		H_R=\sum_{\boldsymbol{k},s}\xi_{\boldsymbol{k}s}c^{\dagger}_{\boldsymbol{k}s}c_{\boldsymbol{k}s}-V\sum_{\boldsymbol{k},\boldsymbol{k'},s}c^{\dagger}_{\boldsymbol{k}s}c^{\dagger}_{-\boldsymbol{k}s}c_{-\boldsymbol{k'}s}c_{\boldsymbol{k'}s},
	\end{align}
	where $s\in\{+,-\}$ denotes the chiral spin configuration in two types. Without external field, the eigenstates for free electrons are $\xi_{\boldsymbol{k}s}=tk^2-\mu+s\lambda_Rk$. Applying an in-plane magnetic field, the system is discribed by a mean field model
	\begin{align}
		H_R(\boldsymbol{B})=\sum_{\boldsymbol{k},s}\left[\tilde{\xi}_{\boldsymbol{k}s}c^{\dagger}_{\boldsymbol{k},s}c_{\boldsymbol{k},s}+\Delta(\boldsymbol{q})c^{\dagger}_{\boldsymbol{k}+\frac{\boldsymbol{q}}{2},s}c^{\dagger}_{-\boldsymbol{k}+\frac{\boldsymbol{q}}{2},s}+\Delta^*(\boldsymbol{q})c_{-\boldsymbol{k}+\frac{\boldsymbol{q}}{2},s}c_{\boldsymbol{k}+\frac{\boldsymbol{q}}{2},s}\right]+\frac{|\Delta(\boldsymbol{q})|^2}{V}. 
	\end{align}
	The eigenenergy for free electron is $\tilde{\xi}_{\boldsymbol{k}s}(\boldsymbol{B})=tk^2-\mu+s\left|\lambda_R\boldsymbol{k}+\boldsymbol{B}\times\hat{\boldsymbol{z}}\right|$, which is approximated to $\tilde{\xi}_{\boldsymbol{k}s}(\boldsymbol{B})=tk^2-\mu+s\left[\lambda_Rk+\hat{\boldsymbol{k}}\cdot\left(\boldsymbol{B}\times\hat{\boldsymbol{z}}\right)\right]$ in the weak field limit. The coefficient for $|\Delta(\boldsymbol{q})|^2$ free energy term is calculated as
	\begin{equation}
		\alpha_{\boldsymbol{q}}=\frac{1}{V}-k_BT\sum_{\boldsymbol{k},i\omega_n,s}\mathcal{G}_s(\boldsymbol{k}+\frac{\boldsymbol{q}}{2},i\omega_n)\mathcal{G}_s(-\boldsymbol{k}+\frac{\boldsymbol{q}}{2},-i\omega_n). \label{alphaq}
	\end{equation}
	Here, $\mathcal{G}_s(\boldsymbol{k},i\omega_n)=\left(i\omega_n-\tilde{\xi}_{\boldsymbol{k}s}\right)^{-1}$ is the electron's Matsubara Green's function, which can be expanded to the series of the field and momentum $\boldsymbol{q}$. To the first order, the eigenenergy is
	\begin{align}
		\tilde{\xi}_{\nu\boldsymbol{k}+\frac{\boldsymbol{q}}{2},s}=\xi_{\boldsymbol{k}s}+\nu\frac{\boldsymbol{q}}{2}\cdot\nabla_{\boldsymbol{k}}\xi_{\boldsymbol{k}s}+s\nu\left(1+\frac{\boldsymbol{q}}{2}\cdot\nabla_{\boldsymbol{k}}\right)\hat{\boldsymbol{k}}\cdot\left(\boldsymbol{B}\times\hat{\boldsymbol{z}}\right)=\xi_{\boldsymbol{k}s}+\delta_{\boldsymbol{k}s}^{\nu}. \label{dks}
	\end{align}
	We assume the small value of $\delta_{\boldsymbol{k}s}/k_BT$, thus the Matsubara Green's function can be expanded as
	\begin{align}
		\mathcal{G}_s(\nu\boldsymbol{k}+\frac{\boldsymbol{q}}{2},\nu i\omega_n)=\mathcal{G}_{\nu\boldsymbol{k}s}^0+\sum_{l=1}^{\infty}\left(\mathcal{G}_{\nu\boldsymbol{k}s}^0\right)^{l+1}\left(\delta_{\boldsymbol{k}s}^{\nu}\right)^l.
	\end{align}
	The Green's function $\mathcal{G}_{\nu\boldsymbol{k}s}^0=\left(\nu i\omega_n-\xi_{\boldsymbol{k}s}\right)^{-1}$ is the zero momentum one for band $s$ without field. We define a function for convenience
	\begin{align}
		G_{l,m}=k_BT\sum_{\boldsymbol{k},i\omega_n}\left(\mathcal{G}_{\boldsymbol{k}s}^0\right)^l\left(\mathcal{G}_{-\boldsymbol{k}s}^0\right)^m=\frac{(-1)^{m}N_{F,s}}{(l-1)!(m-1)!}\tilde{\chi}_{l+m},
	\end{align}
	where $\tilde{\chi}_{l+m}$ is in the same defination as Eq. (\ref{chilm}), and $N_{F,s}$ is the density of states on band $s$. Therefore the summation of the product in Eq. (\ref{alphaq}) is
	\begin{align}
		k_BT\sum_{\boldsymbol{k},i\omega_n}\mathcal{G}_s(\boldsymbol{k}+\frac{\boldsymbol{q}}{2},i\omega_n)\mathcal{G}_s(-\boldsymbol{k}+\frac{\boldsymbol{q}}{2},-i\omega_n)=G_{1,1}+\sum_{l=1}^{\infty}\left[G_{1,l+1}\left(\delta_{\boldsymbol{k}s}^{-}\right)^l+G_{l+1,1}\left(\delta_{\boldsymbol{k}s}^{+}\right)^l\right]+\sum_{l,m}G_{l+1,m+1}\left(\delta_{\boldsymbol{k}s}^{+}\right)^l\left(\delta_{\boldsymbol{k}s}^{-}\right)^m. \label{sum1}
	\end{align}
	We shall see, once the $\delta_{\boldsymbol{k}s}$ is obtained, the free energy will be solved. 
	\begin{align}
		\delta_{\boldsymbol{k}s}^{\nu}&=\nu\left[v_{F,s}\hat{\boldsymbol{k}}\cdot\frac{\boldsymbol{q}}{2}+s\left(\hat{\boldsymbol{k}}+\frac{\boldsymbol{q}}{2k}-\frac{\hat{\boldsymbol{k}}\cdot\boldsymbol{q}}{2k}\hat{\boldsymbol{k}}\right)\cdot\left(\boldsymbol{B}\times\hat{\boldsymbol{z}}\right)\right], \\
		\left\langle\delta_{\boldsymbol{k}s}^2\right\rangle_{\boldsymbol{k}}&=\frac{1}{8}v_F^2q^2+\frac{1}{2}sv_F\boldsymbol{q}\cdot\left(\boldsymbol{B}\times\hat{\boldsymbol{z}}\right), \label{d2}\\
		\left\langle\delta_{\boldsymbol{k}s}^4\right\rangle_{\boldsymbol{k}}&=\frac{3}{16}sv_F^3q^2\boldsymbol{q}\cdot\left(\boldsymbol{B}\times\hat{\boldsymbol{z}}\right). \label{d4}
	\end{align}
	Cutting the result to the fourth order of $\delta_{\boldsymbol{k}s}/k_BT$, we get the value
	\begin{align}
		&G_{1,1}+\left[G_{2,2}\delta_{\boldsymbol{k}s}^{+}\delta_{\boldsymbol{k}s}^{-}+G_{1,3}\left(\delta_{\boldsymbol{k}s}^{-}\right)^2+G_{3,1}\left(\delta_{\boldsymbol{k}s}^{+}\right)^2\right] \notag \\
		&+\left[G_{3,3}\left(\delta_{\boldsymbol{k}s}^{+}\right)^2\left(\delta_{\boldsymbol{k}s}^{-}\right)^2+G_{2,4}\delta_{\boldsymbol{k}s}^{+}\left(\delta_{\boldsymbol{k}s}^{-}\right)^3+G_{4,2}\left(\delta_{\boldsymbol{k}s}^{+}\right)^3\delta_{\boldsymbol{k}s}^{-}+G_{1,5}\left(\delta_{\boldsymbol{k}s}^{-}\right)^4+G_{5,1}\left(\delta_{\boldsymbol{k}s}^{+}\right)^4\right] \notag \\
		=&-N_{F,s}\left(\tilde{\chi}_2+2\tilde{\chi}_4\delta_{\boldsymbol{k}s}^2+\frac{2}{3}\tilde{\chi}_6\delta_{\boldsymbol{k}s}^4\right). \label{sum2}
	\end{align}
	Plugging $N_{F,s}=(N_F/2)(1-s\lambda_R/v_F)$ and Eqs. (\ref{alphaq},\ref{sum1},\ref{d2},\ref{d4},\ref{sum2}), the coefficient Eq. (\ref{aq}) is obtained again. For unconventional Rashba systems, the eigenenergy for free electron changes to
	\begin{equation}
		\tilde{\xi}_{\boldsymbol{k}s}'=\underbrace{\xi_{\boldsymbol{k}s}-\sqrt{\lambda^2+\lambda_R^2k^2}}_{\xi_{\boldsymbol{k}s}'}-\frac{\lambda_R\boldsymbol{k}}{\sqrt{\lambda^2+\lambda_R^2k^2}}\cdot\left(\boldsymbol{B}\times\hat{\boldsymbol{z}}\right).
	\end{equation}
	Eq. (\ref{dks}) is substituted by
	\begin{align}
		\tilde{\xi}'_{\nu\boldsymbol{k}+\frac{\boldsymbol{q}}{2},s}=\xi_{\boldsymbol{k}s}'+\nu\frac{\boldsymbol{q}}{2}\cdot\nabla_{\boldsymbol{k}}\xi_{\boldsymbol{k}s}'-\nu\left(1+\frac{\boldsymbol{q}}{2}\cdot\nabla_{\boldsymbol{k}}\right)\frac{\lambda_R\boldsymbol{k}}{\sqrt{\lambda^2+\lambda_R^2k^2}}\cdot\left(\boldsymbol{B}\times\hat{\boldsymbol{z}}\right)=\xi_{\boldsymbol{k}s}'+\nu\delta_{\boldsymbol{k}s},
	\end{align}
	where 
	\begin{align}
		\delta_{\boldsymbol{k}s}=v_{F,s}\hat{\boldsymbol{k}}\cdot\frac{\boldsymbol{q}}{2}-\frac{\lambda_R}{\sqrt{\lambda^2+\lambda_R^2k^2}}\left(\boldsymbol{k}+\frac{\boldsymbol{q}}{2}\right)\cdot\left(\boldsymbol{B}\times\hat{\boldsymbol{z}}\right).
	\end{align}
	Repeat the calculation, we get Eq. (8) in the main text. 

	Notably, the band energy difference between states with momenta $\boldsymbol{k}$ and $-\boldsymbol{k}$ can be expressed as $\Delta E_s(\boldsymbol{k})=(\delta_{\boldsymbol{k}s}^+-\delta_{\boldsymbol{k}s}^-)|_{\boldsymbol{q}=\boldsymbol{0}}$. Therefore, $\delta_{\boldsymbol{k}s}^{\nu}=\nu\delta_{\boldsymbol{k}s}$ decomposes into the $\boldsymbol{q}$-dependent and -independent terms as
	\begin{equation}
		\delta_{\boldsymbol{k}s}=\frac{1}{2}\left[\boldsymbol{v}_{F,s}\cdot\boldsymbol{q}+\Delta E_s(\boldsymbol{k})\right]. 
	\end{equation}
	Ignoring the factor from averaging the Fermi surface, the contribution to nonreciprocity is obtained by even powers of $\delta_{\boldsymbol{k}s}$ and proportional to $\sum_{s,l}q^{2l+1}C_{l}N_{F,s}[v_{F,s}(k_{F,s})]^{2l+1} \Delta E_s$, where $l$ are integers and $C_{l}$ are $l$-dependent factors. Plugging $N_{F,s}\propto k_{F,s}/v_{F,s}$, we get the nonreciprocal contribution as
	\begin{equation}
		\sum_{s,l}q^{2l+1}C_{l}k_{F,s}\left[v_{F,s}(k_{F,s})\right]^{2l} \Delta E_s. 
	\end{equation}

	\section{The fake '$\alpha_{\boldsymbol{q}}$' for Rashba system\label{fake}}
	Starting with Eqs. (\ref{chi0},\ref{chiB},\ref{G01},\ref{G02}), we get Green's functions different from the ones in the standard method, since we do not ignore the contribution from the band deviating from the Fermi surface. They are
	\begin{align}
		g_{++}\left(\boldsymbol{k},\boldsymbol{q},i\omega_n\right)&=G+\left(\boldsymbol{v_F}\cdot\boldsymbol{\frac{q}{2}}\right)G^2+\left(\boldsymbol{v_F}\cdot\boldsymbol{\frac{q}{2}}\right)^2G^3, \label{g2} \\
		h_{++}\left(\boldsymbol{k},\boldsymbol{q},i\omega_n\right)&=-\tilde{G}-\left(\boldsymbol{v_F}\cdot\boldsymbol{\frac{q}{2}}\right)\tilde{G}^2-\left(\boldsymbol{v_F}\cdot\boldsymbol{\frac{q}{2}}\right)^2\tilde{G}^3, \\
		g_{+-}\left(\boldsymbol{k},\boldsymbol{q},i\omega_n\right)&=\lambda_RkG^2+2\lambda_Rk\left(\boldsymbol{v_F}\cdot\boldsymbol{\frac{q}{2}}\right)G^3+3\lambda_Rk\left(\boldsymbol{v_F}\cdot\boldsymbol{\frac{q}{2}}\right)^2G^4, \\
		h_{+-}\left(\boldsymbol{k},\boldsymbol{q},i\omega_n\right)&=\lambda_Rk\tilde{G}^2+2\lambda_Rk\left(\boldsymbol{v_F}\cdot\boldsymbol{\frac{q}{2}}\right)\tilde{G}^3+3\lambda_Rk\left(\boldsymbol{v_F}\cdot\boldsymbol{\frac{q}{2}}\right)^2\tilde{G}^4. \label{h2}
	\end{align}
	Here, Green's functions are still $G=(i\omega_n-\xi_{\boldsymbol{k}})^{-1}$ and $\tilde{G}=(i\omega_n+\xi_{-\boldsymbol{k}})^{-1}$, the Fermi velocity $\boldsymbol{v_F}=\nabla_{\boldsymbol{k}} \xi_{\boldsymbol{k}}$. Plugging (\ref{chi0},\ref{chiB},\ref{G01},\ref{G02}), the field-independent and -dependent susceptibilities are gotten
	\begin{align}
		\chi_0(\boldsymbol{q})&=2\langle g_{++}h_{++}\rangle=-N_F\left(\tilde{\chi}_2+\frac{1}{4}\tilde{\chi}_4v_F^2q^2\right), \\
		\chi_{\boldsymbol{B}}(\boldsymbol{q})&=\langle2g_{++}h_{++}\left(g_{+-}+h_{+-}\right)-g_{++}^2h_{+-}-h_{++}^2g_{+-}\rangle\left(\frac{\boldsymbol{q}}{k}\times\boldsymbol{B}\right)\cdot\hat{\boldsymbol{z}}=-2N_{F}\left(\tilde{\chi}_4+\frac{1}{4}\tilde{\chi}_6v_F^2q^2\right)\lambda_R\left(\boldsymbol{q}\times\boldsymbol{B}\right)\cdot\hat{\boldsymbol{z}}.
	\end{align}
	The fake '$\alpha_{\boldsymbol{q}}$' is
	\begin{align}
		\alpha_{\boldsymbol{q}}=\frac{1}{V}+N_F\left[\tilde{\chi}_2+\frac{1}{4}\tilde{\chi}_4v_F^2q^2+2\left(\tilde{\chi}_4+\frac{1}{4}\tilde{\chi}_6v_F^2q^2\right)\lambda_R\left(\boldsymbol{q}\times\boldsymbol{B}\right)\cdot\hat{\boldsymbol{z}}\right]. 
	\end{align}
	This result has an 'SDE' with a minus efficiency comparing with the real one, and it also gives the wrong quantitative value. However, it is sufficient to reveal the band asymmetry from this fake '$\alpha_{\boldsymbol{q}}$'. 

