\begin{align}
    \expval**{\oper{O}}{\Psi_{\beta}}=\expval**{\oper{\rho}({\scriptstyle\frac{\beta}{2}}) \left(\oper{O}_{\text{odd}} + \oper{O}_{\text{even}}\right) \oper{\rho}({\scriptstyle\frac{\beta}{2}})}{\Psi_T}
    % \nn
    % &~~=
