\end{align}
and we can calculate the odd and even terms, respectively
\begin{widetext}
\begin{align}
\label{eq:expval_numerator_odd_term}
&\expval**{\oper{\rho}({\scriptstyle\frac{\beta}{2}}) \cdot \oper{O}_{\text{odd}}\cdot \oper{\rho}({\scriptstyle\frac{\beta}{2}})}{\Psi_T} = \nn
&= \expval**{
