    \mathcal{O}_{\text{odd}}(\m{}{};\tau)
    = \frac{
        \mel{\m{}{L+1}}{\oper{O}_{\text{odd}}\cdot e^{-\tau \H_{\text{odd}}}}{\m{}{L+2}}
        }{
        \mel{\m{}{L+1}}{e^{-\tau \H_{\text{odd}}}}{\m{}{L+2}}
