\section{Additional derivations}
\subsection{Commutation between $\oper{\pi}\sub{\mathcal{L}}$ and $\H$}
\label{sec:commutation_parity_H}

Starting from the definitions of the Hamiltonian of the system
\begin{align}
    \label{eq:hamiltonian_op_quantum_system_SUP}
    \H = \sum_{i=1}^N \K{i} - g \sum_{\expval{ij}} \V{ij},
\end{align}
and the operator for the parity of the total angular momentum
\begin{align}
    \label{eq:definition_parity_op}
    \oper{\pi}\sub{\mathcal{L}} = \frac{\1 - e^{\i \pi \L}}{2} ,
\end{align}
we have
\begin{align}
    \comm{\oper{\pi}\sub{\mathcal{L}}}{\H}
    =& \comm{\frac{\1 - e^{\i \pi \L}}{2}}{\H}
    \nn
    =& \comm{\frac{\1 - e^{\i \pi \sum_{k=1}^N \L_{k}}}{2}}{\sum_{i=1}^N \K{i} - g \sum_{\expval{ij}} \V{ij}}
    \nn
    =&\frac{g}{2} \sum_{\expval{ij}}\comm{e^{\i \pi \sum_{k=1}^N \L_{k}}}{\V{ij}}
    \nn
    =&\frac{g}{2} \sum_{\expval{ij}} \prod_{k\neq i,j} \comm{e^{\i \pi \left(\L_{i} + \L_{j}\right)}}{\V{ij}} .
\end{align}
Here,
\begin{align}
    \comm{e^{\i \pi \left(\L_{i} + \L_{j}\right)}}{\V{ij}} =& ~ e^{\i \pi \left(\L_{i} + \L_{j}\right)}\V{ij} - \V{ij}e^{\i \pi \left(\L_{i} + \L_{j}\right)}
    \nn
    \comm{e^{\i \pi \left(\L_{i} + \L_{j}\right)}}{\V{ij}} \ket{m_i,m_j} =& ~ e^{\i \pi \left(\L_{i} + \L_{j}\right)}\V{ij} \ket{m_i,m_j} - \V{ij}e^{\i \pi \left(\L_{i} + \L_{j}\right)}\ket{m_i,m_j}
    \nn
    =& ~ \left( e^{\i \pi \left(\L_{i} + \L_{j}\right) } - e^{\i \pi \left(m_{i} + m_{j}\right)} \right)\V{ij} \ket{m_i,m_j}
    \nn
    =& ~ \left( e^{\i \pi \left(\L_{i} + \L_{j}\right) } - e^{\i \pi \left(m_{i} + m_{j}\right)} \right) 
        \times \nn & \hspace{1cm} \times 
         \left( \frac{3}{4}\ket{m_i+1,m_j+1} + \frac{1}{4}\ket{m_i+1,m_j-1} + \frac{1}{4}\ket{m_i-1,m_j+1} + \frac{3}{4}\ket{m_i-1,m_j-1}\right),
\end{align}
where we can notice that 
\begin{align}
    \left( e^{\i \pi \left(\L_{i} + \L_{j}\right) } - e^{\i \pi \left(m_{i} + m_{j}\right)} \right)  \ket{m_i\pm1,m_j\pm1} 
    =& \left( e^{\i \pi \left(m_i + m_j \pm 2\right) } - e^{\i \pi \left(m_{i} + m_{j}\right)} \right)  \ket{m_i\pm1,m_j\pm1}
    \nn
    =& \left( e^{\pm \i 2\pi } - 1\right)  e^{\i \pi \left(m_{i} + m_{j}\right)}  \ket{m_i\pm1,m_j\pm1}
    \nn
    =& ~ 0 .
\end{align}
Therefore,
\begin{align}
    \comm{e^{\i \pi \left(\L_{i} + \L_{j}\right)}}{\V{ij}} \ket{m_i,m_j} = 0
    \implies 
    \comm{e^{\i \pi \left(\L_{i} + \L_{j}\right)}}{\V{ij}} = 0,
\end{align}
implying that
\begin{align}
    \label{eq:commutation_pi_H}
    \comm{\oper{\pi}\sub{\mathcal{L}}}{\H}
    = 0.
\end{align}

\subsection{Commutation between $\oper{\pi}\sub{\mathcal{L}}$ and $\oper{\rho}(\tau)$}
\label{sec:commutation_parity_propagator}

Starting from the definition of $\oper{\rho}(\tau) \equiv e^{- \tau \H}$ we have
\begin{align}
    \comm{\oper{\pi}\sub{\mathcal{L}}}{\oper{\rho}(\tau)}
    = \comm{\oper{\pi}\sub{\mathcal{L}}}{e^{- \tau \H}}
    = \sum_{n=0}^{\infty} \frac{(-\tau)^n}{n!} \comm{\oper{\pi}\sub{\mathcal{L}}}{\H^n} .
\end{align}
From the commutator we get the recursion relation
\begin{align}
    \comm{\oper{\pi}\sub{\mathcal{L}}}{\H^n}
    =& \oper{\pi}\sub{\mathcal{L}} \H^n - \H^n \oper{\pi}\sub{\mathcal{L}}
    \nn
    =& \oper{\pi}\sub{\mathcal{L}} \H \H^{n-1} - \H^n \oper{\pi}\sub{\mathcal{L}}    
    \nn
    =& \oper{\pi}\sub{\mathcal{L}} \H \H^{n-1} - \H \oper{\pi}\sub{\mathcal{L}} \H^{n-1} + \H \oper{\pi}\sub{\mathcal{L}} \H^{n-1} - \H^n \oper{\pi}\sub{\mathcal{L}}
    \nn
    =& \comm{\oper{\pi}\sub{\mathcal{L}}}{ \H} \H^{n-1} + \H \comm{ \oper{\pi}\sub{\mathcal{L}} }{ \H^{n-1}}
    ,
\end{align}
that gives
\begin{align}
    \comm{\oper{\pi}\sub{\mathcal{L}}}{\H^n}
    = \sum_{p=1}^n  \H^{p-1} \comm{\oper{\pi}\sub{\mathcal{L}}}{ \H} \H^{n-p} 
    = 0
    ,
\end{align}
where in the last step it was used the result from Eq. \eqref{eq:commutation_pi_H}, and hence,
\begin{align}
    \comm{\oper{\pi}\sub{\mathcal{L}}}{\oper{\rho}(\tau)} = 0 .
\end{align}


\subsection{Derivative of $\expval{K}$ with respect to $g$}
\label{sec:dKdg_derivation}

Starting with
\begin{align}		
\label{eq:partition_function_PIMC_trotter_Heven_Hodd_ini_SUP}
    \Z(\beta) 
    \approx \sum_{\{\m{}{p}\}_{2L}} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}},
\end{align}
for
\begin{equation}
    \label{eq:def_rho_tau_op_SUP}
    \oper{\rho}_p(\tau) =
    \left\{
    \begin{aligned}
        e^{ -\tau \H_{\text{odd}}} & \text{, for $p$ odd,} \\
        e^{ -\tau \H_{\text{even}}} & \text{, for $p$ even,} 			
    \end{aligned}
    \right.
\end{equation}
we have
\begin{align}
  \expval{\K{}} = \frac{1}{\Z}  \sum_{\{\m{}{l}\}_{2L}} \mathcal{K} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}},
\end{align}
for $\mathcal{K} \equiv \mel{\m{}{L+1}}{\K{}}{\m{}{L+1}} = \left(\m{}{L+1}\right)^2 = \sum_{i=1}^N \left(\m{i}{L+1}\right)^2$. Then,
\begin{align}
    \label{eq:dKdg}
  \dv{\expval{\K{}}}{g} 
    =& \dv{\Z^{-1}}{g} \sum_{\{\m{}{l}\}_{2L}} \mathcal{K} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
    + \frac{1}{\Z} \sum_{\{\m{}{l}\}_{2L}} \mathcal{K} \dv{g} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
    \nn
    =& -\frac{1}{\Z} \dv{\Z}{g} ~ \frac{1}{\Z} \sum_{\{\m{}{l}\}_{2L}} \mathcal{K} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
    + \frac{1}{\Z} \sum_{\{\m{}{l}\}_{2L}} \mathcal{K} \dv{g} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
    \nn
    =& - \expval{\K{}} \frac{1}{\Z} \sum_{\{\m{}{l}\}_{2L}} \dv{g} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
    + \frac{1}{\Z} \sum_{\{\m{}{l}\}_{2L}} \mathcal{K} \dv{g} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
    .
\end{align}
The derivative of the product is
\begin{align}
     \dv{g} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
     =& \sum_{q=1}^{2L} \mel*{\m{}{q}}{\dv{\oper{\rho}_q(\tau)}{g}}{\m{}{q+1}} \prod_{p\neq q} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
     \nn
     =& \sum_{q=1}^{2L} 
     \frac{\mel*{\m{}{q}}{\dv{\oper{\rho}_q(\tau)}{g}}{\m{}{q+1}}}{\mel*{\m{}{q}}{\oper{\rho}_q(\tau)}{\m{}{q+1}}} 
     \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
     ,
\end{align}
where we can write
\begin{equation}
    \dv{\oper{\rho}_q(\tau)}{g} =
    \left\{
    \begin{aligned}
        \dv{g} e^{ -\tau ~\H_{\text{odd}}} & \approx \tau \V{\text{odd}} e^{ -\tau \H_{\text{odd}}}, & \text{ for $q$ odd,} \\
        \dv{g} e^{ -\tau ~ \H_{\text{even}}} & \approx \tau e^{ -\tau \H_{\text{even}}} \V{\text{even}}, & \text{ for $q$ even,} 			
    \end{aligned}
    \right.
\end{equation}
so that
\begin{align}
     \dv{g} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
     =& \tau \sum_{q=1}^{2L} 
     \frac{\mel*{\m{}{q}}{\dv{\oper{\rho}_q(\tau)}{g}}{\m{}{q+1}}}{\mel*{\m{}{q}}{\oper{\rho}_q(\tau)}{\m{}{q+1}}} 
     \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
     \nn
     =& \beta \frac{1}{L}\sum_{l=1}^{L} 
     \frac{\mel*{\m{}{2l-1}}{ \V{\text{odd}} e^{ -\tau \H_{\text{odd}}} }{\m{}{2l}}}{\mel*{\m{}{2l-1}}{e^{ -\tau \H_{\text{odd}}}}{\m{}{2l}}} 
     +\frac{\mel*{\m{}{2l}}{ e^{ -\tau \H_{\text{odd}}} \V{\text{even}} }{\m{}{2l+1}}}{\mel*{\m{}{2l}}{e^{ -\tau \H_{\text{even}}}}{\m{}{2l+1}}}
     \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
     \nn
     =& \beta \frac{1}{L}\sum_{l=1}^{L} 
        \left( \mathcal{V}_{l,\text{odd}} + \mathcal{V}_{l,\text{even}}\right)
     \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
     \nn
     =& \sum_{l=1}^{L} 
     \mathcal{V}_l
     \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
     ,
\end{align}
for $\mathcal{V}_{l} \equiv \mathcal{V}_{l,\text{odd}} + \mathcal{V}_{l,\text{even}}$. Then, by defining $\mathcal{V}_{\text{all}} \equiv \frac{1}{L} \sum_{l=1}^L \mathcal{V}_l$, Eq. \eqref{eq:dKdg} becomes
\begin{align} 
    \label{eq:dKdg_final}
  \dv{\expval{\K{}}}{g} 
    =& -\beta \expval{\K{}} \frac{1}{\Z} \sum_{\{\m{}{l}\}_{2L}} \mathcal{V}_{\text{all}} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
    +\beta \frac{1}{\Z} \sum_{\{\m{}{l}\}_{2L}} \mathcal{K} \cdot \mathcal{V}_{\text{all}} \prod_{p=1}^{2L} \mel*{\m{}{p}}{\oper{\rho}_p(\tau)}{\m{}{p+1}}
    \nn
    =& \beta \left[\expval{\mathcal{K} \cdot \mathcal{V}_{\text{all}}} - \expval{\K{}}\cdot\expval{\V{}}_{\text{all}} \right]
    .
\end{align}

\section{Computational details for the MCMC algorithm}

A system of $N=150$ planar rotors with $\mmax=5$ was simulated for different values of the dipole-dipole interaction strength $g$, above and below the estimated critical interaction strength of $g_c \sim 0.5$. For all  the simulations, a total of $10^5$ MC steps were used. In order to insure faster equilibration, the initial simulation started at a high $g$ with a random initial state, and the next simulations for lower $g$'s had their grid state initialized with the final configuration of the previous simulation. During the data processing procedure the average total angular momentum squared $\expval{\oper{L}^2}$ as a function of simulation steps was calculated for different dipole-dipole interaction strengths $g$ (see Fig. \ref{fig:L2_vs_MC}) for the purpose of setting the equilibration time.
