\section{An overview of 2-body case}\label{sec2}
\setcounter{equation}{0}

Here we briefly recall the result of \cite{AtZ1}.
Namely , we describe the field analogue of 2-body Calogero-Moser model
and represent it in the form of the Landau-Lifshitz magnet.


\paragraph{Classical mechanics.} The 2-body Calogero-Moser model is described by the Hamiltonian
%
(\ref{aa03}). Equations of motion take the form
  %
 \beq\label{aa101}
 \begin{array}{c}
   \displaystyle{
 \dot{p}=\frac{c ^2}{8} \wp'(q), ~~~ \dot{q}=p\,.
 }
 \end{array}
  \eq
  %
  They are represented in the Lax form
   %
 \beq\label{aa102}
 \begin{array}{c}
   \displaystyle{
 \dot{L}^{\hbox{\tiny{CM}}}(z)\equiv\{H^{\hbox{\tiny{CM}}}, L^{\hbox{\tiny{CM}}}(z)\}
 =[L^{\hbox{\tiny{CM}}}(z), {M}^{\hbox{\tiny{CM}}}(z)]
 }
 \end{array}
  \eq
  %
with the Lax pair
 %
 \beq\label{aa103}
 \begin{array}{c}
   \displaystyle{
 L^{\hbox{\tiny{CM}}}(z)=\left(\begin{array}{cc}
p & \displaystyle{\frac{c}{2}\, \phi(-z, q) }\\
\displaystyle{ \frac{c}{2}\, \phi(-z, -q) } & -p
\end{array}\right),
 }
 \quad
  \displaystyle{
 M^{\hbox{\tiny{CM}}}(z)=\frac{1}{4}\left(
\begin{array}{cc}
 0 & c  f(-z,q) \\
  c  f(-z,-q) & 0 \\
\end{array}
\right),
 }
 \end{array}
  \eq
  %
where the functions $\phi$ and $f$ are given in the Appendix in (\ref{a01}) and (\ref{a04})
respectively.

 \paragraph{1+1 field theory.} In this case the momentum and coordinate become fields
on a unit circle ${\mathbb S}^1$, and the canonical Poisson bracket  turns into
   %
 \beq\label{aa104}
 \begin{array}{c}
   \displaystyle{
 \left\{p(x), q(y)\right\}= \delta(x-y)\,.
 }
 \end{array}
  \eq
  %
 Equations of motion takes the form:
  %
 \beq\label{aa105}
 \begin{array}{c}
   \displaystyle{
 q_t={p}\left( 1-\frac{{{k}^{2}}q_{x}^{2}}{{{c}^{2}}} \right)\,,
 }
 \\ \ \\
    \displaystyle{
  p_t=-\frac{ k^2}{ c^2} \partial_{x}\left(p^{2} q_{x}\right)-\frac{(3{{k}^{2}}q_{x}^{2}-{{c}^{2}})}{8}\wp'(q)+\frac{3 k^2}{4} \partial_{x}\left( q_{x} \wp(q) \right)+\frac{k^4}{4} \partial_{x}\left(\frac{q_{x x x} {\tilde\nu}-{\tilde\nu}_{x} q_{x x}}{{\tilde\nu}^{3}}\right)\,,
  }
  \end{array}
   \eq
   %
where
%$\tilde\nu=\sqrt{c^2-k^2q_x^2}$.
  %
 \beq\label{aa106}
 \begin{array}{c}
   \displaystyle{
\tilde\nu=\sqrt{c^2-k^2q_x^2}\,,\quad c={\rm const}\,.
  }
  \end{array}
   \eq
%   %
%

%L-A pair
   %
 \beq\label{aa107}
 \begin{array}{c}
   \displaystyle{
 U^{\hbox{\tiny{2dCM}}}(z)=\frac12\mat{2p-kq_xE_1(z)}{\tilde\nu\phi(-z,q)}{\tilde\nu\phi(-z,-q)}{-2p+kq_xE_1(z)}
 }
 \end{array}
  \eq
  %



\paragraph{Landau-Lifshitz magnet.}  By inserting three components of $\vec S(t,x)$
into the traceless $2\times 2$ matrix $S=\sum_{\al=1}^3\sigma_\al S_\al$ in the Pauli matrices
$\sigma_\al$ basis, the Landau-Lifshitz equation takes the form:
  %
 \beq\label{aa110}
 \begin{array}{c}
   \displaystyle{
 \partial_{t} S=[J(S), S]-\alpha_0\left[S, S_{x x}\right]\,,\quad S_{xx}=\p_x^2S\,,
 }
 \end{array}
  \eq
  %
 where $J(S)$ is the linear map describing the anisotropy in the magnet
   %
 \beq\label{aa1101}
 \begin{array}{c}
   \displaystyle{
J(S)=\sum\limits_{\al=1}^3 S_\al J_\al\sigma_\al\,,\quad J_\al=-\frac{1}{2}\,\wp(\om_\al)
 }
 \end{array}
  \eq
  %
and
    %
 \beq\label{aa111}
 \begin{array}{c}
   \displaystyle{
\alpha_0=k^2/(8\lambda^2)
 }
 \end{array}
  \eq
  %
is a constant parameter. Here $\lambda\in\mC$ (also constant) is an eigenvalue of the matrix $S$ -- the norm of the vector $(S_1,S_2,S_3)$, and $k$ is the constant coefficient behind $\p_x$.
 % where

The Landau-Lifshitz equation (\ref{aa110}) has the Hamiltonian formulation with the Poisson brackets
%
 \beq\label{aa113}
 \begin{array}{c}
   \displaystyle{
 \left\{S_{\alpha}(x), S_{\beta}(y)\right\}=-\sqrt{-1} \varepsilon_{\alpha \beta \gamma} S_{\gamma}(x)\delta (x-y)\,,
 }
 \end{array}
  \eq
  %
  %
and the Hamiltonian
%
 \beq\label{aa114}
 \begin{array}{c}
   \displaystyle{
  \mH^{\hbox{\tiny{LL}}}=\frac{1}{2}\oint dx \Big( \tr(SJ(S))-\al_0\tr(S_x^2) \Big)\,.
 }
 \end{array}
  \eq
  %
The $U$-matrix (it is $2\times 2$ matrix) entering the Zakharov-Shabat equation has the form \cite{Skl,FT,STS}:
%
 \beq\label{aa116}
 \begin{array}{c}
   \displaystyle{
    U^{\hbox{\tiny{LL}}}(z)=\sum\limits_{k=1}^3 S_k\vf_k(z)\sigma_k\,,
     }
 \end{array}
   \eq
  %
where  $\vf_1(z)=e^{\pi\imath z}\phi(z,\frac{\tau}{2})$,
  $\vf_1(z)=e^{\pi\imath z}\phi(z,\frac{1+\tau}{2})$, $\vf_3(z)=\phi(z,\frac{1}{2})$.

\paragraph{Gauge equivalence.} The gauge transformation (\ref{aa05}) with the matrix
%
 \beq\label{aa117}
 \begin{array}{c}
   \displaystyle{
 G(z)=\frac{1}{\rho}\left(
\begin{array}{cc}
 \theta_{00} (z+q \,|\, 2 \tau ) {\tilde\nu}  & -\theta_{00} (q-z \,|\, 2\tau ) \left(c+k q_{x}\right) \\ \ \\
 -\theta_{10} (z+q \,|\, 2 \tau ) {\tilde\nu}  & \theta_{10} (q-z \,|\, 2 \tau ) \left(c+k q_{x}\right)
\end{array}
\right)\,,
 }
 \end{array}
  \eq
  %
  where $\ti\nu$ is from (\ref{aa106}) and
  %
  \beq\label{aaa118}
  \begin{array}{c}
    \displaystyle{
  \rho=\sqrt{\ti\nu(c+k q_{x})\vartheta(z) \vartheta(q)}\,,
  }
  \end{array}
   \eq
   %
leads to the following change of variables:
%
 \beq\label{aa120}
 \left\{\begin{array}{l}
   \displaystyle{
   S_{1}(p,q,c) =\Big(p-\frac{c}{2}\,\frac{k^2q_{xx}}{c^2-k^2q_x^2}\Big) \frac{\theta_{01}(0)}{\vartheta^{\prime}(0)} \frac{\theta_{01}(q)}{\vartheta(q)}+\frac{c}{2}\, \frac{\theta_{01}^{2}(0)}{\theta_{00}(0) \theta_{10}(0)} \frac{\theta_{00}(q) \theta_{10}(q)}{\vartheta^{2}(q)}\,,
   }
    \\ \ \\
    \displaystyle{
   S_{2}(p,q,c) =\Big(p-\frac{c}{2}\,\frac{k^2q_{xx}}{c^2-k^2q_x^2}\Big) \frac{\sqrt{-1}\theta_{00}(0)}{ \vartheta^{\prime}(0)} \frac{\theta_{00}(q)}{\vartheta(q)}
   +\frac{c}{2}\, \frac{\sqrt{-1}\theta_{00}^{2}(0)}{ \theta_{10}(0) \theta_{01}(0)}
    \frac{\theta_{10}(q) \theta_{01}(q)}{\vartheta^{2}(q)}\,,
   }
    \\ \ \\
   \displaystyle{
    S_{3}(p,q,c) =\Big(p-\frac{c}{2}\,\frac{k^2q_{xx}}{c^2-k^2q_x^2}\Big) \frac{\theta_{10}(0)}{\vartheta^{\prime}(0)} \frac{\theta_{10}(q)}{\vartheta(q)}+\frac{c}{2}\, \frac{\theta_{10}^{2}(0)}{\theta_{00}(0) \theta_{01}(0)} \frac{\theta_{00}(q) \theta_{01}(q)}{\vartheta^{2}(q)}\,.
 }
 \end{array}
 \right.
  \eq
  %
  In the above formulae the notations (\ref{a121}) are used.

