\section{$N$-body case: description of models}\label{sec3}
\setcounter{equation}{0}

\subsection{Field analogue of $N$-body elliptic Calogero-Moser model.}

\paragraph{Hamiltonian and equations of motion.}
The $N$-body Calogero-Moser model in classical mechanics is described by the Hamiltonian (\ref{aa201}).
 Its field generalization was derived in \cite{Krich22}. The Hamiltonian takes the form
 %
 \beq\label{aa202}
 \begin{array}{c}
   \displaystyle{
\mH^{\hbox{\tiny{2dCM}}}= \oint dx\, \mH^{\hbox{\tiny{2dCM}}}(x)
 }
 \end{array}
  \eq
  %
  with the density\footnote{In the limit to the finite-dimensional mechanics all the fields become independent of $x$.
  This corresponds to the limit $k\rightarrow 0$. In this limit $\mH^{\hbox{\tiny{2dCM}}}(x)\rightarrow 2cH^{\hbox{\tiny{CM}}}$.}
 %
 \beq\label{aa203}
 \begin{array}{c}
   \displaystyle{
\mH^{\hbox{\tiny{2dCM}}}(x)= \sum_{i=1}^{N} p_{i}^{2}
\left(c-k q_{i x}\right)-\frac{1}{N c}\Big(\sum_{i=1}^{N} p_{i}\left(c-k q_{i x}\right)\Big)^{2}-
 }
 \\
 \displaystyle{
 -\sum_{i=1}^{N} \frac{k^{4} q_{i x x}^{2}}{4\left(c-k q_{i x}\right)}+\frac{k^{3}}{2} \sum_{i \neq j}^N
 \Big(q_{i x} q_{j x x}-q_{j x} q_{i x x}\Big) \zeta\left(q_{i}-q_{j}\right) -
 }
  \\
 \displaystyle{
-\frac{1}{2} \sum_{i \neq j}^N\Big(\left(c-k q_{i x}\right)^{2}
\left(c-k q_{j x}\right)+\left(c-k q_{i x}\right)
\left(c-k q_{j x}\right)^{2}-c k^{2} \left(q_{i x}-q_{j x}\right)^{2}\Big)  \wp\left(q_{i}-q_{j}\right)\,.
 }
 \end{array}
  \eq
  %
Together with the canonical Poisson structure
 %
 \beq\label{aa2031}
 \begin{array}{c}
   \displaystyle{
\{q_i(x),p_j(y)\}=\delta(x-y)\,,\quad
\{q_i(x),q_j(y)\}=\{p_i(x),p_j(y)\}=0
 }
 \end{array}
  \eq
  %
it provides equations of motion
