\frac{2 }{N c}\sum_{l=1}^{N} p_{i} p_{l}\left(c-k q_{l x}\right)
\Big)
+
 }
 \\
  \displaystyle{
+2 \sum_{j:j \neq i}^N\Big(k^{3} q_{j x x x} \zeta \left(q_{i}-q_{j}\right) - 3 k^{2} \left(c-k q_{j x}\right) q_{j x x} \wp \left(q_{i}-q_{j}\right) + \left(c-k q_{j x}\right)^{3}\wp' \left(q_{i}-q_{j}\right) \Big)\,.
