\subsection{Higher rank Landau-Lifshitz model}
\paragraph{Notations.}
Introduce
the special matrix basis in $\Mat$:
%
  \beq\label{aa231}
  \begin{array}{l}
  \displaystyle{
T_a=T_{a_1 a_2}=\exp\left(\frac{\pi\imath}{{ N}}\,a_1
 a_2\right)Q^{a_1}\Lambda^{a_2}\,,
 \qquad
 a=(a_1,a_2)\in\mZ_{ N}\times\mZ_{ N}\,,\quad \mZ_N=\mZ/N\mZ\,,
 }
 \\ \ \\
  \displaystyle{
(Q)_{kl}=\delta_{kl}\exp(\frac{2\pi
 \imath}{{ N}}k)\,,
 \qquad
 (\Lambda)_{kl}=\delta_{k-l+1=0\,{\hbox{\tiny{mod}}}\,
 { N}}\,,\quad k,l=1,..,N\,.
 }
 \end{array}
 \eq
%
The basis matrices are numerated by a pair of numbers $(a_1,a_2)$, $a_1,a_2=0,...,N-1$ defined modulo $N$.
In particular, $T_{(0,0)}=1_N$ -- identity $N\times N$ matrix. Then
%
  \beq\label{aa232}
 \begin{array}{c}
  \displaystyle{
T_\al T_\be=\kappa_{\al,\be} T_{\al+\be}\,,\ \ \
\kappa_{\al,\be}=\exp\left(\frac{\pi \imath}{N}(\be_1
\al_2-\be_2\al_1)\right)\,,
 }
 \end{array}
 \eq
%
The basis has the property $\tr(T_\al T_\be)=N\delta_{\al+\be,(0,0)}$.
 See details in the Appendix of the paper \cite{ZZ}.
 %
Below we use the following set of functions:
 %
 \beq\label{aa233}
 \begin{array}{c}
  \displaystyle{
 \vf_a(z,\om_a+\hbar)=\exp (2\pi\imath\,\frac{a_2z}{N})\,\phi(z,\om_a+\hbar)=
 \exp (2\pi\imath z\p_\tau\om_a)\,\phi(z,\om_a+\hbar)\,,
 \quad a\in\,\mZ_{ N}\times\mZ_{ N}

 }
 \end{array}
 \eq
  %
  where
  %
 \beq\label{aa234}
 \begin{array}{c}
  \displaystyle{
 \om_a=\frac{a_1+a_2\tau}{N}\,,
 \quad a\in\,\mZ_{ N}\times\mZ_{ N}\,.
 }
 \end{array}
 \eq
 %
 The classical elliptic Belavin-Drinfeld $r$-matrix \cite{BD} takes the following simple form:
 %
 \beq\label{aa235}
 \begin{array}{c}
  \displaystyle{
 r_{12}(z)=E_1(z)1_N\otimes 1_N+\sum\limits_{a\neq(0,0)} T_a\otimes T_{-a}
 \exp (2\pi\imath\,\frac{a_2z}{N})\,\phi(z,\frac{a_1+a_2\tau}{N})\,,
 }
 \end{array}
 \eq
%
where the sum over $a$ goes over all $a\in\mZ_N\times\mZ_N$, $a\neq(0,0)$. We use this notation
in what follows.

Notice that the described above matrix basis reproduces (up to signs) the Pauli matrices
in the $N=2$ case.

The transition between the standard matrix basis and the basis $T_a$ is performed as follows.
Let $B$ be an arbitrary $N\times N$ matrix with entries $B_{ij}$ in the standard basis and
with $B_{(a_1,a_2)}$ components in the basis $T_a$. Then with the short notation
$\bfe(x)=\exp(2\pi\imath x)$ we have
%
  \beq\label{aa2361}
  \begin{array}{c}
  \displaystyle{
B_a=B_{(a_1,a_2)}=\frac{1}{N}\,\tr(B T_{-a})=\frac{1}{N}\,\bfe(-\frac{a_1a_2}{2N})\sum\limits_{k=1}^N B_{k,k+a_2}\,
\bfe(-\frac{a_1 k}{N})
 }
 \end{array}
 \eq
 %
and
%
 \beq\label{aa2362}
 \begin{array}{c}
 B_{ij}=\left\{
 \begin{array}{l}
   \displaystyle{
   \sum\limits_{a_1=0}^{N-1}B_{(a_1,j-i)}\bfe\Big(\frac{a_1(i+j)}{2N}\Big)\,,\quad j\geq i\,,
   }
 \\
   \displaystyle{
    \sum\limits_{a_1=0}^{N-1}B_{(a_1,j-i+N)}\bfe\Big(\frac{a_1(i+j-N)}{2N}\Big)\,,\quad j<i\,.
   }
 \end{array}
 \right.
 \end{array}
 \eq

\paragraph{Equations of motion and Hamiltonian formulation.} In ${\rm gl}_N$ case
the Landau-Lifshitz equation (\ref{aa110}) is generalized as \cite{AtZ4}:
  %
 \beq\label{aa237}
 \begin{array}{c}
  \displaystyle{
\partial_{t} S = 2 c [S, J(S)] + \frac{k^{2}}{c} [S, S_{xx}]-2 k [S, E(S_{x})]\,,
 }
 \end{array}
 \eq
 %
 where $S=S(t,x)\in\Mat$ is a matrix of dynamical variables (fields). Here we assume this matrix
 is not an arbitrary but the one, which has a special set of eigenvalues $0,..,0,c$:
   %
 \beq\label{aa238}
 \begin{array}{c}
  \displaystyle{
{\rm Spec}(S)=(0,...,0, c), ~~~\tr(S)= c\,.
 }
 \end{array}
 \eq
 %
 The latter means that $S$ is a rank one matrix. It satisfies the property
    %
 \beq\label{aa2381}
 \begin{array}{c}
  \displaystyle{
S^2=  c S\,.
 }
 \end{array}
 \eq
 %
 The linear maps $J(S)$ and $E(S)$ entering equation (\ref{aa237}) are of the following form:
     %
 \beq\label{aa2382}
 \begin{array}{c}
  \displaystyle{
J(S)=\frac{N \vth'''(0)}{3\vth'(0)}1_N S_{(0,0)}-N \sum\limits_{a\neq(0,0)} T_a S_a
 E_2\Big(\frac{a_1+a_2\tau}{N}\Big)=
 }
 \\
  \displaystyle{
 =\frac{N \vth'''(0)}{3\vth'(0)}\,S-N \sum\limits_{a\neq(0,0)} T_a S_a
 \wp\Big(\frac{a_1+a_2\tau}{N}\Big)
 }
 \end{array}
 \eq
 %
 and
     %
 \beq\label{aa2383}
 \begin{array}{c}
  \displaystyle{
E(S)=N \!\sum\limits_{a\neq(0,0)} \!T_a S_a\Big(2\pi\imath\,
  \frac{a_2}{N}+E_1\Big(\frac{a_1\!+\!a_2\tau}{N}\Big) \Big)\,.
 }
 \end{array}
 \eq
 %
 Notice that in the $N=2$ case $E(S)=0$ for any matrix $S$ and the original Landau-Lifshitz
 equation (\ref{aa110}) is reproduced.

 The equation (\ref{aa237}) has the Hamiltonian description, that is
    %
 \beq\label{aa239}
 \begin{array}{c}
  \displaystyle{
\partial_{t} S(t,x) = \{S(t,x), \mH^{\hbox{\tiny{LL}}} \}
 }
 \end{array}
 \eq
 %
 with the following Hamiltonian
  %
 \beq\label{aa240}
 \begin{array}{c}
  \displaystyle{
\mH^{\hbox{\tiny{LL}}}=\oint d x \mH^{\hbox{\tiny{LL}}}(x)\,,
 }
 \end{array}
 \eq
 %
   %
 \beq\label{aa241}
 \begin{array}{c}
  \displaystyle{
  \mH^{\hbox{\tiny{LL}}}(x)=
N c \tr(S J(S))- \frac{N k^{2}}{2 c} \tr\left(\partial_{x} S \partial_{x} S\right)+ N k \tr\left(\partial_{x} S E(S)\right)
 }
 \end{array}
 \eq
 %
 and the Poisson brackets
   %
 \beq\label{aa242}
 \begin{array}{c}
  \displaystyle{
\left\{S_{i j}(x), S_{k l}(y)\right\}=\frac{1}{N}\left(S_{i l}(x) \delta_{k j}-S_{k j}(x) \delta_{i l}\right) \delta(x-y)\,.
 }
 \end{array}
 \eq
 %

 \paragraph{$U-V$ pair.}
 It is helpful to use the following notation
   %
 \beq\label{aa243}
 \begin{array}{c}
  \displaystyle{
L(S,z)=\tr_{2} \Big(r_{12}(z) (1_N\otimes S) \Big)=NS_{0,0}E_1(z)1_N+
N \sum_{a\neq(0,0)} T_a S_a \varphi_a\left(z, \omega_a\right)\,,
 }
 \end{array}
 \eq
 %
 where $\tr_2$ is the trace over the second tensor component and $r_{12}(z)$
 is the classical elliptic $r$-matrix (\ref{aa235}).
 The above expression, in fact, is the Lax matrix of the elliptic Euler-Arnold
 top \cite{LOZ,LOZ14} in finite-dimensional classical
 mechanics. Equations of motion for this model ${\dot S}=2c[S,J(S)]$ are obtained from (\ref{aa237}) in the
 limit $k\rightarrow 0$. It was also explained in  \cite{LOZ} that the $U$-matrix in the field theory case
 has the same form
   %
 \beq\label{aa244}
 \begin{array}{c}
  \displaystyle{
U^{\hbox{\tiny{LL}}}(z)=L(S,z)
 }
 \end{array}
 \eq
 %
 although here we imply $S=S(t,x)$, while in mechanics $S=S(t)$.
 %This expression is known as the Sklyanin's Lax operator \cite{Skl2}.
 For $V$-matrix we have
   %
 \beq\label{aa245}
 \begin{array}{c}
  \displaystyle{
V^{\hbox{\tiny{LL}}}(z)= V_{1}(z)- c V_{2}(z)+\frac{N c^2 \vth'''(0)}{3\vth'(0)} 1_N\,,
 }
 \end{array}
 \eq
 %
 where
%
 \beq\label{aa246}
 \begin{array}{c}
  \displaystyle{
V_1(z)= -N c \partial_z L(S,z)+ L(E(S)S,z)
 }
 \end{array}
 \eq
 %
 and
 %
 \beq\label{aa247}
 \begin{array}{c}
  \displaystyle{
V_{2}(z)=L\left(W, z\right)\,,\qquad W=-\frac{k}{c^{2}}\left[S, S_{x}\right]\,.
 }
 \end{array}
 \eq
 %
The matrix $W$ is a solution of the equation $-k \partial_{x}S=\left[S, W \right]$.





