\section{IRF-Vertex relation and change of variables}\label{sec4}
\setcounter{equation}{0}

\paragraph{Gauge equivalence.}
Let us introduce the following matrix:
 %
 \beq\label{aa401}
 \begin{array}{c}
  \displaystyle{
G(z)=b(x, t) \Xi(z,q)D^{-1}(q)\in\Mat\,,
 }
 \end{array}
 \eq
 %
 where the matrix $\Xi(z)$ and the diagonal matrix $D(q)$ are defined as follows:
  %
 \beq\label{aa402}
 \begin{array}{c}
  \displaystyle{
\Xi_{i j}(z, q)=\theta \left[\begin{array}{c}
\frac{i}{N}-\frac{1}{2} \\
\frac{N}{2}
\end{array}\right]\left(z+N \bar{q}_{j} \mid N \tau\right)\,,
\quad \bar{q}_{j}=q_j-\frac{1}{N}\sum\limits_{k=1}^Nq_k\,,
 }
 \end{array}
 \eq
 %
  %
 \beq\label{aa403}
 \begin{array}{c}
  \displaystyle{
D_{i j}(q)=\delta_{i j} \prod_{k \neq i} \vartheta\left(q_{i}-q_{k}\right)\,.
 }
 \end{array}
 \eq
 %
 The coefficient function $b(x,t)$ in (\ref{aa401}) has the form
  %
 \beq\label{aa404}
 \begin{array}{c}
  \displaystyle{
b(x,t)=\prod\limits_{k<l}^N \vartheta\left(q_{l}-q_{k}\right)^{\frac{1}{N}}
\prod\limits_{m=1}^N\Big(N \left(k q_{m,x}-c\right) \Big)^{\frac{1}{2N}}\,.
 }
 \end{array}
 \eq
 %
In the above formulae the condition (which is by definition of ${\bar q}_j$)
  %
 \beq\label{aa405}
 \begin{array}{c}
  \displaystyle{
\sum_{k=1}^{N} \bar{q}_{k}=0
 }
 \end{array}
 \eq
 %
is necessary. The defined above matrix $G(z)$
is (up to the function $b(x,t)$) the matrix of the IRF-Vertex transformation
\cite{Jimbo,LOZ,Z24}.

The reason why we use this matrix is as follows. The $U$-matrices for both models
have certain quasi-periodic behaviour in spectral parameter:
  %
 \beq\label{aa406}
 \begin{array}{c}
  \displaystyle{
U^{\hbox{\tiny{2dCM}}}(z+1)=U^{\hbox{\tiny{2dCM}}}(z)\,,
}
\\ \ \\
  \displaystyle{
 U^{\hbox{\tiny{2dCM}}}(z+\tau)=\exp(2\pi\imath\,{\rm diag}(q_1,...,q_N))U^{\hbox{\tiny{2dCM}}}(z)
 \exp(-2\pi\imath\,{\rm diag}(q_1,...,q_N)-
}
\\ \ \\
  \displaystyle{
 -2\pi\imath c 1_N+2\pi\imath k\p_x{\rm diag}(q_1,...,q_N)
 }
 \end{array}
 \eq
 %
 and
%
 \beq\label{aa407}
 \begin{array}{c}
  \displaystyle{
U^{\hbox{\tiny{LL}}}(z+1)=Q^{-1}U^{\hbox{\tiny{LL}}}(z)Q\,,
}
\\ \ \\
  \displaystyle{
 U^{\hbox{\tiny{LL}}}(z+\tau)=\Lambda^{-1} U^{\hbox{\tiny{LL}}}(z)}
 \Lambda-2\pi\imath c 1_N\,,
 \end{array}
 \eq
 %
 where $Q,\Lambda$ are the matrices from (\ref{aa231}). The matrix $G(z)$ has very special
 structure. The action by $G(z)$ as in the gauge transformation
 %
 \beq\label{aa408}
 \begin{array}{c}
   \displaystyle{
U^{\hbox{\tiny{LL}}}(z)=G(z) U^{\hbox{\tiny{2dCM}}}(z) G^{-1}(z)+k G_x(z) G^{-1}(z)
 }
 \end{array}
  \eq
  %
  maps the quasi-periodic properties (\ref{aa406})
 into  (\ref{aa407}).
   On the one hand, the matrix $G(z)$ is degenerated at $z=0$:
 $\det G(0)=0$, that is $G^{-1}(z)$ has simple pole at $z=0$.
 On the other hand, the conjugation of $U^{\hbox{\tiny{2dCM}}}(z)$ by $G(z)$ does not provide
 the second order pole in $U^{\hbox{\tiny{LL}}}(z)$. Details can be found in \cite{LOZ}
 for a similar relation at the level of classical finite-dimensional mechanics.
 %
See also \cite{VZ}, where different aspects of the transformation matrix $G(z)$ are discussed.


\paragraph{Change of variables.} The gauge transformation (\ref{aa408}) relates
both $U$-matrices. It allows to compute
explicit change of variables between the models. For any $a=(a_1,a_2)\in\mZ_N\times \mZ_N$ we have
 %
 \beq\label{aa410}
 \begin{array}{c}
   \displaystyle{
 S_{a}(p,q,c)=\frac{c}{N}\, \delta_{a, (0,0)} +
 }
 \\ \ \\
    \displaystyle{
+(-1)^{a_{1}+a_{2}}\frac{e^{\pi\imath a_2\om_a}}{N^{2}} \left(\frac{\vartheta\left(\omega_{\alpha}\right)}{\vartheta^{\prime}(0)}\right)^N
\sum\limits_{m=1}^{N}
 \Big(P_{m}+c\sum\limits_{k:k\neq m}E_1(q_{mk}+\omega_a)\Big)
  \prod_{l: l \neq m}^{N} \varphi_a\left(q_{m}-q_{l}, \omega_a\right),
 }
 \end{array}
  \eq
  %
  where $\om_a$ is from (\ref{aa234}) and
 %
 \beq\label{aa411}
 \begin{array}{c}
   \displaystyle{
P_{m}=-p_{m}-\frac{k \alpha _{m, x}}{\alpha _m}+
 \sum\limits_{l: l\neq m}^{N} \alpha_{l}^{2} E_{1} \left( q_m-q_l\right)
 =
  }
 \\ \ \\
 \displaystyle{
 =
-p_{m}-\frac12\frac{k^2 q_{m,xx}}{kq_{m,x}-c}+
 \sum\limits_{l: l\neq m}^{N} (kq_{l,x}-c) E_{1} \left( q_m-q_l\right).
 }
 \end{array}
  \eq
  %
  Using (\ref{aa2362}) one can write the formulae (\ref{aa410}) in the standard matrix basis as well.

\paragraph{Poisson map.} The statement that the obtained change of variables provides the Poisson map between
two models means that the canonical Poisson brackets (\ref{aa2031}) are mapped into the Lie-Poisson
brackets (\ref{aa242}). Put it differently, the Poisson brackets for $S_{ij}(p,q,c)$ computed
by means of (\ref{aa2031}) should reproduce (\ref{aa242}).

In fact, this statement was implicitly obtained in \cite{Z24}. It was proved that the field
analogue of the elliptic Calogero-Moser model is described by the non-ultralocal Maillet type
$r$-matrix structure
%
  \beq\label{aa412}
  \begin{array}{c}
  \displaystyle{
\{U^{\hbox{\tiny{2dCM}}}_1(z,x),U^{\hbox{\tiny{2dCM}}}_2(w,y)\}=
  }
  \\ \ \\
  \displaystyle{
\Big(-k\p_x {\bf r}_{12}(z,w|x)
+ [U^{\hbox{\tiny{2dCM}}}_1(z,x),{\bf r}^{\hbox{\tiny{2dCM}}}_{12}(z,w|x)]
-[U^{\hbox{\tiny{2dCM}}}_2(w,y),{\bf r}^{\hbox{\tiny{2dCM}}}_{21}(w,z|x)]\Big)\delta(x-y)-
  }
  \\ \ \\
  \displaystyle{
  -\Big({\bf r}^{\hbox{\tiny{2dCM}}}_{12}(z,w|x)+{\bf r}_{21}^{\hbox{\tiny{2dCM}}}(w,z|x)\Big)k\delta'(x-y)\,,
 }
 \end{array}
 \eq
 %
where the classical $r$-matrix ${\bf r}^{\hbox{\tiny{2dCM}}}_{12}(z,w|x)$
 is very similar to its finite-dimensional version\footnote{Similar results are also known for the
 field analogue of the spin generalization of the Calogero-Moser systems and other 2d models \cite{Z}.}.
  At the same time the classical $r$-matrix
 structure for the Landau-Lifshitz model is
%
  \beq\label{aa413}
  \begin{array}{c}
  \displaystyle{
\{U^{\hbox{\tiny{LL}}}_1(z,x),U^{\hbox{\tiny{LL}}}_2(w,y)\}=
  }
  \\ \ \\
  \displaystyle{
\Big(
[U^{\hbox{\tiny{LL}}}_1(z,x),{\bf r}^{\hbox{\tiny{LL}}}_{12}(z,w|x)]
-[U^{\hbox{\tiny{LL}}}_2(w,y),{\bf r}^{\hbox{\tiny{LL}}}_{21}(w,z|x)]\Big)\delta(x-y)\,,
 }
 \end{array}
 \eq
 %
where ${\bf r}^{\hbox{\tiny{LL}}}_{12}(z,w|x)$ is the elliptic non-dynamical $r$-matrix (\ref{aa235}).
It was shown in \cite{Z24} that the gauge transformation (\ref{aa408}) transforms (\ref{aa412})
into (\ref{aa413}). This is exactly what we need since (\ref{aa242}) follows from
(\ref{aa413}).

Existence of the classical $r$-matrix structures for both models means
the Poisson commutativity
$\{\tr(T^k(z,2\pi)),\tr(T^m(w,2\pi))\}=0$ for the corresponding monodromy matrices
 %
 \beq\label{aa414}
 \begin{array}{c}
  \displaystyle{
 T(z,x)={\rm Pexp}\Big( \frac{1}{k}\int\limits_0^x dy\,  U(z,y) \Big)\,.
  }
 \end{array}
\eq
 %
Due to the gauge equivalence the monodromies of both models are equal to each other.
This provides relation between the Hamiltonians.
Exact relation is as follows:
 %
 \beq\label{aa415}
 \begin{array}{c}
  \displaystyle{
H^{\hbox{\tiny{2dCM}}}(x)=H^{\hbox{\tiny{LL}}}(x)-\frac{N^2 c^3 \vth'''(0)}{3\vth'(0)}\,.
  }
 \end{array}
\eq
 %
 This relation was verified numerically. Its direct proof will be given elsewhere.

