\renewcommand{\theequation}{A\arabic{equation}}
\section{Spectral representation of nonlinear susceptibility} \label{sec:spectralrep}
We present the spectral representation of the second- and third-order susceptibilities \cite{Liu2022}.
Let $\mathcal{H}_0$ be the unperturbed Hamiltonian, with its many-body eigenstates $\{ \vert n \rangle \}$ and eigenenergies $\{ \varepsilon_n \}$.
The ground state of $\mathcal{H}_0$ is denoted by $\vert 0 \rangle$.
For generality, we consider a set of physical quantities $\{ Q^{\alpha} \}$ that are linearly coupled to external fields $\{ f_{\beta}(t) \}$ as
\begin{align}
\mathcal{V}(t) = - \sum_{\beta} Q^\beta f_{\beta}(t).
\end{align}
The nonlinear response function is generally expressed as
\begin{align}
&\chi_{\alpha\beta_1 \cdots \beta_n}^{(n)}(t;t_1,t_2,\dots,t_n) \notag \\
&= \mathrm{i}^n \varTheta(t-t_1)\varTheta(t_1-t_2)\cdots\varTheta(t_{n-1}-t_n) \notag \\
&\quad\times \left\langle [[\cdots [[\hat{Q}^{\alpha}(t),\hat{Q}^{\beta_1}(t_1)],\hat{Q}^{\beta_2}(t_2)],\cdots ], \hat{Q}^{\beta_n}(t_n)] \right\rangle_0.
\label{eq:chi_general}
\end{align}
By inserting the resolution of the identity, $1 = \sum_n \vert n \rangle \langle n \vert$, into Eq.~\eqref{eq:chi_general} and performing the Fourier transformation, we obtain the expression for the second-order response function in the ground state as
\begin{align}
&\chi_{\alpha\beta_1\beta_2}^{(2)}(\omega_1, \omega_2) \notag \\*
&= \sum_{mn} \Biggl[
\frac{Q^{\alpha}_{0m} Q^{\beta_1}_{mn} Q^{\beta_2}_{n0}}{(\omega_1^+ + \omega_2^+ - \varepsilon_m + \varepsilon_0) (\omega_2^+ - \varepsilon_n + \varepsilon_0)} \notag \\
&\quad +
\frac{Q^{\beta_2}_{0m} Q^{\beta_1}_{mn} Q^{\alpha}_{n0}}{(\omega_1^+ + \omega_2^+ - \varepsilon_0 + \varepsilon_n) (\omega_2^+ - \varepsilon_0 + \varepsilon_m)} \notag \\
&\quad -
\frac{Q^{\beta_2}_{0m} Q^{\alpha}_{mn} Q^{\beta_1}_{n0}}{(\omega_1^+ + \omega_2^+ - \varepsilon_n + \varepsilon_m) (\omega_2^+ - \varepsilon_0 + \varepsilon_m)} \notag \\
&\quad -
\frac{Q^{\beta_1}_{0m} Q^{\alpha}_{mn} Q^{\beta_2}_{n0}}{(\omega_1^+ + \omega_2^+ - \varepsilon_n + \varepsilon_m) (\omega_2^+ - \varepsilon_n + \varepsilon_0)}
\Biggr],
\label{eq:chi2_spectral}
\end{align}
with $Q_{mn}^{\alpha} = \langle m \vert Q^{\alpha} \vert n \rangle$.
Similarly, the spectral representation of the third-order response function is given by
\begin{align}
&\chi_{\alpha\beta_1\beta_2\beta_3}^{(3)}(\omega_1, \omega_2, \omega_3) \notag \\*
&= \sum_{lmn} \biggl[
- \frac{Q^{\alpha}_{0l} Q^{\beta_1}_{lm} Q^{\beta_2}_{mn} Q^{\beta_3}_{n0}}{(\omega_1^+ + \omega_2^+ + \omega_3^+ - \varepsilon_{l0}) (\omega_2^+ + \omega_3^+ - \varepsilon_{m0}) (\omega_3^+ - \varepsilon_{n0})} \notag \\
&\quad +
\frac{Q^{\beta_3}_{0l} Q^{\beta_2}_{lm} Q^{\beta_1}_{mn} Q^{\alpha}_{n0}}{(\omega_1^+ + \omega_2^+ + \omega_3^+ - \varepsilon_{0n}) (\omega_2^+ + \omega_3^+ - \varepsilon_{0m}) (\omega_3^+ - \varepsilon_{0l})} \notag \\
&\quad +
\frac{Q^{\beta_1}_{0l} Q^{\alpha}_{lm} Q^{\beta_2}_{mn} Q^{\beta_3}_{n0}}{(\omega_1^+ + \omega_2^+ + \omega_3^+ - \varepsilon_{ml}) (\omega_2^+ + \omega_3^+ - \varepsilon_{m0}) (\omega_3^+ - \varepsilon_{n0})} \notag \\
&\quad +
\frac{Q^{\beta_2}_{0l} Q^{\alpha}_{lm} Q^{\beta_1}_{mn} Q^{\beta_3}_{n0}}{(\omega_1^+ + \omega_2^+ + \omega_3^+ - \varepsilon_{ml}) (\omega_2^+ + \omega_3^+ - \varepsilon_{nl}) (\omega_3^+ - \varepsilon_{n0})} \notag \\
&\quad +
\frac{Q^{\beta_3}_{0l} Q^{\alpha}_{lm} Q^{\beta_1}_{mn} Q^{\beta_2}_{n0}}{(\omega_1^+ + \omega_2^+ + \omega_3^+ - \varepsilon_{ml}) (\omega_2^+ + \omega_3^+ - \varepsilon_{nl}) (\omega_3^+ - \varepsilon_{0l})} \notag \\
&\quad -
\frac{Q^{\beta_3}_{0l} Q^{\beta_2}_{lm} Q^{\alpha}_{mn} Q^{\beta_1}_{n0}}{(\omega_1^+ + \omega_2^+ + \omega_3^+ - \varepsilon_{nm}) (\omega_2^+ + \omega_3^+ - \varepsilon_{0m}) (\omega_3^+ - \varepsilon_{0l})} \notag \\
&\quad -
\frac{Q^{\beta_3}_{0l} Q^{\beta_1}_{lm} Q^{\alpha}_{mn} Q^{\beta_2}_{n0}}{(\omega_1^+ + \omega_2^+ + \omega_3^+ - \varepsilon_{nm}) (\omega_2^+ + \omega_3^+ - \varepsilon_{nl}) (\omega_3^+ - \varepsilon_{0l})} \notag \\
&\quad -
\frac{Q^{\beta_2}_{0l} Q^{\beta_1}_{lm} Q^{\alpha}_{mn} Q^{\beta_3}_{n0}}{(\omega_1^+ + \omega_2^+ + \omega_3^+ - \varepsilon_{nm}) (\omega_2^+ + \omega_3^+ - \varepsilon_{nl}) (\omega_3^+ - \varepsilon_{n0})}
\biggr],
\label{eq:chi3_spectral}
\end{align}
where $\varepsilon_{mn} = \varepsilon_{m} - \varepsilon_{n}$.
In Eqs.~\eqref{eq:chi2_spectral} and \eqref{eq:chi3_spectral}, $\omega_i^+$ denotes a complex frequency with a positive imaginary part.
It was shown in Ref.\ \cite{Ono2025} that applying the following substitution yields good agreement between the nonlinear responses obtained from real-time simulations and those derived from the spectral representation:
\begin{align}
\omega_3^+ &\to \omega_3 + \mathrm{i} \eta, \\
\omega_2^+ + \omega_3^+ &\to \omega_2 + \omega_3 + \mathrm{i} \eta, \\
\omega_1^+ + \omega_2^+ + \omega_3^+ &\to \omega_1 + \omega_2 + \omega_3 + \mathrm{i} \eta,
\end{align}
where $\eta$ is set to the relaxation rate in Eq.~\eqref{eq:vonNeumann}, i.e., $\eta = \varGamma$.
Additionally, the nonlinear susceptibilities in Eqs.~\eqref{eq:chi2_spectral} and \eqref{eq:chi3_spectral} need to be symmetrized in accordance with Eq.~\eqref{eq:chi_symmetrized}.


