\title{Photogalvanic effect in hydrodynamic flows of nonreciprocal electron liquids}

\author{E. Kirkinis}
\affiliation{Center for Computation and Theory of Soft Materials, Robert R. McCormick School of Engineering and Applied Science, Northwestern University, Evanston IL 60208 USA}

\author{L. Bonds}
\affiliation{Department of Physics, University of Washington, Seattle, Washington 98195, USA}

\author{A. Levchenko}
