As mentioned in the introduction, instead of directly computing the coefficients of $\log(Z(G;x))$ we will actually compute the coefficients of its derivative.% which we recall to be equal to
%\[      
%\frac{d}{dx}\log(Z(G;x))=\sum_{v\in V} \frac{R_{G,v}(x)}{1+R_{G,v}(x)}.
%\]
% of calculating the coefficient of the Taylor series of $\log(Z(G,\lambda))$ we will focus on its derivative 
%\begin{equation*}
%    R_G(\lambda)=\lambda\frac{\partial}{\partial\lambda}\log(Z(G,\lambda))=\sum_{v\in V}\frac{Z^\textrm{in}_v(G,\lambda)}{Z(G;\lambda)}=\sum_{v\in V}\frac{Z^\textrm{in}_v(G,\lambda)}{Z^\textrm{out}_v(G,\lambda)+ Z^\textrm{in}_v(G,\lambda)}.
%\end{equation*}
%It is easy to see that $k$th coefficient of the Taylor-series of $R_G(x)$ is $k$ times the $k$th coefficient of $\log(Z(G;x))$.

It will be convenient to introduce the following notation.
For $S\subseteq V$ and $v\in S$ let us define.
\begin{equation}\label{eq:ratio ind}
R_{S,v}(x)=\frac{Z^{v \textrm{ in}}(G[S];x)}{Z^{v \textrm{ out}}(G[S];x)}
\end{equation}
and let $R_{S,v}^{[k]}(x)$ be the $k$th Taylor polynomial of $R_{S,v}(x)$ around $0$.
% . In general for a function $f:\mathbb{C}\to\mathbb{C}$ let $f^{[k]}(z)$ denote the $k$th Taylor-polynomial around $0$.
Using this notation, we see that by~\eqref{eq:derivative log=sum ratios},

\begin{equation}\label{eq:ratio_sum}
\left(x\frac{d}{dx}\log(Z(G;x))\right)^{[m]}
    =\sum_{v\in V} R_{V,v}^{[m]}(x)\st{m}\left(\frac{1}{1+R_{V,v}(x)}\right)^{[m]},
    % =\sum_{v\in V(G)}\sum_{k=0}^{m-1} (-1)^{k}\left(R^{[m]}_{V(G),v}(x)^{k+1}\right)^{[m]},
\end{equation}
Since $R_{S,v}(0)=0$ we can apply Lemma~\ref{lemma:reciprocial} to obtain that the right-hand side of~\eqref{eq:ratio_sum} is computable in at most $O(n m^3)$ time if we have access to 
$\{R_{V,v}^{[m]}(x)\}_{v\in V}$. 

% Clearly, the right hand side is computable using $m$ polynomial multiplication (e.g. Horner-scheme) of polynomials of degree at most $m-1$.  
% To be precise, let $\st{k}$ denote polynomial multiplication where we keep the coefficients up to $x^{k-1}$, i.e.
% \[
% p(x)\st{k}q(x)=\left(p(x)q(x)\right)^{[k]}.
% \]
% Note that, $p(x)\st{k}q(x)=p^{[k]}(x)\st{k}q^{[k]}(x)$, which  means that to compute $p(x)\st{k}q(x)$ we need  at most $O(k^2)$ many operations. (Using fast polynomial multiplication one could obtain a better running time.)

Our main task is therefore to devise an algorithm to compute the $k$th Taylor polynomial of $R_{V,v}(x)$. This is the content of the next proposition.

\begin{proposition}\label{prop:alg ind}
Under Assumption~\ref{as:computation}, there is an $O(\Delta^{k+1} k^3)$-time algorithm that on input of a graph $G=(V,E)$ of maximum degree at most $\Delta$ a vertex $v\in V$ and $k\in \mathbb{N}$ computes $R_{G,v}^{[k]}(x)$.
\end{proposition}
\begin{proof}
We first describe an algorithm to compute $R_{S,v}^{[k]}(x)$ for a subset $S$ of $V$ and $v\in S$. 
Here the algorithm has access to $V\setminus S$ so that it can determine $N_G(v)\cap S$ by simply removing any element from $N_G(v)$ that is contained in $V\setminus S$.

If $k=0$, then by definition we can output $R_{S,v}^{[k]}(x)=0$. 
Otherwise, let $\{u_1,\dots,u_\ell\}=S\cap N_{G}(v)$. 
By Lemma~\ref{lemma:independence} we know that
\begin{align*}
R_{S,v}(x)&=\frac{Z^{\textrm{ in}}(G[S];x)}{Z^{v \textrm{ out}}(G[S];x)}=\frac{x Z(G[S\setminus N[v]];x)}{Z(G[S-v];x)}\\
&=\frac{x}{\prod_{i=1}^\ell\frac{Z(G[S\setminus\{v,u_1,\dots,u_{i-1}\}];x)}{Z(G[S\setminus\{v,u_1,\dots,u_{i}\}];x)}}=\frac{x}{\prod_{i=1}^\ell\left(1+R_{S\setminus\{v,u_1,\dots,u_{i-1}\},u_i}(x)\right)}.
\end{align*}
Therefore
% \[
% R_{S,v}^{[k]}(x)=z\left(\sum_{j=0}^{k-1} F(x)^j\right)^{[k-1]},
% \]
\[
R_{S,v}^{[k]}(x)=x\left(\frac{1}{1+F(x)}\right)^{[k-1]},
\]
where $F(x)=\left(\prod_{i=1}^\ell1+R^{[k-1]}_{S\setminus\{v,u_1,\dots,u_{i-1}\},u_i}(x)\right)^{[k-1]}-1$. 


Now let us estimate the computation time based on this formula. 
Let $\tau(k)$ denote the computational time needed to compute $R_{S,v}^{[k]}(x)$ for any $S\subseteq V$ such that $V\setminus S$ has size at most $O(k\Delta)$. 
We would like to show inductively that $\tau(k) \leq C\Delta^{k+1}k^3$ for some positive constant $C$.

Note that at the start of the algorithm $S=V$ and in every recursive call the set is decreased by at most $\Delta+1$ so that throughout $|V\setminus S|\leq k(\Delta+1)=O(\Delta k)$.
To compute $F(x)$ we need to determine $S\cap N_G(v)$, which takes time $O(\Delta^2 k)$, we need to determine $R^{[k-1]}_{S\setminus\{v,u_1,\dots,u_{i-1}\},u_i}(x)$ for $i=1\ldots, \ell$, which takes time $\ell \tau(k-1)$ and finally we need to carry out $\ell\leq \Delta$ multiplications, which takes time at most $\Delta O(k^2).$
So in total this gives a bound of $\Delta(O(k^2+O(\Delta k))+\tau(k-1))$ on the time to compute $F(x).$
By Lemma~\ref{lemma:reciprocial} we can compute $R_{S,v}^{[k]}(x)$ from $F(x)$ in time $O(k^3)$. 
This means that
\[
    \tau(k)\le O(k^3)+O(\Delta^2k)+\Delta(O(k^2)) +\Delta \tau(k-1),
\]
and thus by induction
\[
\tau(k)\le O(k(k^2+k\Delta+\Delta^2))+\Delta C(\Delta^k (k-1)^3)\leq C(\Delta^{k+1}k^3),
\]
provided $C$ is large enough.

% Clearly, we can compute $F(z)$ with $\ell\le \Delta$ many polynomial multiplication i.e. in time at most $O(\Delta k^2)$, and by Lemma~\ref{lemma:reciprocial} we can compute $R^{[k]}_{S,v}(z)$ from $F(z)$ using at most $O(k^3)$ time. Observe that each time to compute $R_{S,v}^{[k]}(z)$ we have to access a similar Taylor polynomials of ratios with smaller degree, thus the total number of recursive calls is at most $\Delta^k$, thus the total time to compute $R_{S,v}^{[k]}(z)$ is at most $O(\Delta^k\cdot (\Delta k^2+k^3))$.
\end{proof}

We have recorded the algorithm used in the proof of Proposition~\ref{prop:alg ind} as Algorithm 1 in pseudo code.

Theorem~\ref{thm:hard-core} now follows as a direct corollary to this proposition.
The algorithm is recorded in pseudo code as Algorithm 2 below.


