\begin{algorithm}[H]
\caption{$R(G,S,v,k)$}\label{alg:indep_ratio}
\begin{algorithmic}[1]
\Require graph $G$, $S\subseteq V(G)$ $v\in S$, $k\in\mathbb{N}$
\Ensure $p(x)=R_{S,v}^{[k]}(x)$
\If{$k=0$}
    \State $p=0$
\ElsIf{$|S|=1$}
    \State $p=x$
\ElsIf{$k>0$ and $|S|>1$}
    \State Let $\{u_1,\dots u_\ell\}=N_G(v)\cap S$
    \State $S_0 \gets S\setminus \{v\}$

    \For{ $i=1,\dots,\ell$}
        \State $R_i \gets R(G,S_0,u_i,k-1)$ \Comment{This is the recursive call}
        \State $S_0 \gets S_0\setminus\{u_i\}$
    \EndFor

    \State $F(x)=1$
    \For{$i=1,\dots,\ell$}
        \State $F(x) \gets F(x)\st{k-1} (1+R_i)$
    \EndFor
    \State $F(x)\gets F(x)-1$
    \State $p(x) \gets x\left(\frac{1}{1+F(x)}\right)^{[k-1]}$ \Comment{Apply Lemma~\ref{lemma:reciprocial}}
    % \State $g(x)\gets 1-F(x)$ \Comment{Apply Lemma~\ref{lemma:reciprocial}}
    % \State $p(x)=1$
    % \For{i=1,\dots,k-1}
    %     \State $p(x) \gets \left(p(x)\st{k-1} g(x)\right)+1$
    % \EndFor
    % \State $p(x) \gets x\cdot p(x)$
\EndIf
\end{algorithmic}
\end{algorithm}


