\section{Graph homomorphisms}\label{sec:graph hom}
Throughout we fix $A$ to be an $q\times q$ symmetric matrix. 
For a graph $G=(V,E)$ we write
\[
H(G;x)=q^{-|V|}\hom(G,J+x(A-J)).
\]
In this section we will describe our algorithm for computing the low-order coefficients of $\log(H(G,x))$.

We first need a few definitions to realize $H(G,x)$ as a forest generating function.
Consider a total ordering $<$ on the edges of $G$. 
Let for a tree $T\subseteq E$
\[
w_T=w_T(x)=q^{-(|T|+1)}\sum_{\phi:V(T)\to[q]}x^{|T|}\prod_{ij\in T}(A-J)_{\phi(i),\phi(j)}\prod_{ij\in E(V(T))_T}(J+x(A-J))_{\phi(i),\phi(j)},
\]
where $E(S)_T$ denote the collection of broken edges of $T$ in the graph $G[S]$.
%Note that for a given tree $T$, $w_T$ can be computed in time $O(q^{|V(T)|}$.
Next define
\[
F_G(w)=F_G((w_T)_{T \text{ tree}})=\sum_{\substack{F\in \mathcal{F}_G}}\prod_{T\in \mathcal{C}(F)}w_T,
\]
where $\mathcal{F}_G$ denotes the collection of forests of $G$ and $\mathcal{C}(F)$ denotes the collection of non-trivial components of $F$ (i.e. components with at least one edge).

\begin{lemma}\label{lem:forest graph hom} For any graph $G$ with a total ordering on its edges we have
\[
F_G(w_T)=H(G;x),
\]
where $F_G(w_T)$ is defined above.
\end{lemma}
We postpone the proof of the lemma to the end of this section, noting that it can be proved along very similar lines as~\cite{bencs2024approximatingvolumetruncatedrelaxation}*{Proposition 2.3}.

Now let us express the Taylor series of $x\frac{d}{d x}\log(H(G;x))$. We have that
\begin{align*}
x\frac{d}{d x}H(G;x)&=\sum_{T\in\mathcal{T}_G}\underbrace{(x \frac{d}{d x} w_T(x)) \cdot  H(G-V(T);x)}_{H_T(G;x)}
\\
&=\sum_{e\in E}\underbrace{\sum_{\substack{T\in\mathcal{T}_G\\ e=\min(T)}}(x \frac{d}{d x} w_T(x)) \cdot  H(G-V(T);x)}_{H^{e}(G;x)}.
\end{align*}
 Therefore,
\[
    \left(x\frac{d}{d x}\log(H(G;x))\right)^{[m]}=\sum_{\substack{T\in\mathcal{T}_G\\ 1\le|T|\le m}}\left(\frac{H_T(G;x)}{H(G;x)}\right)^{[m]}=\sum_{e\in E }\sum_{\substack{T\in\mathcal{T}_G\\ |T|\le m\\ e=\min(T)}}\left(\frac{H_T(G;x)}{H(G;x)}\right)^{[m]}.
\]
As before we aim to describe a procedure to compute 
\[
    \left(\frac{H_T(G;x)}{H(G;x)}\right)^{[m]}=(x\tfrac{d}{d x}w_T(x))^{[m]}\left(\frac{H(G-V(T);x)}{H(G;x)}\right)^{[m-|T|]}.
\]
Note that in this equation we used the fact that $x\tfrac{d}{d x}\left(w_T(x)\right)=O(x^{|T|})$.
For a tree $T$ on $k$ vertices the contribution $w_T(x)^{[m]}$ can be computed in time $O(\Delta k^2)+O(q^{k}(\Delta k)(m-k))=O(q^k \Delta k m)$, since if $k>m$ we have $w_T(x)^{[m]}=0$ otherwise after calculating the broken edges we take all possible $V(T)\to [q]$ colorings and compute the corresponding contributions.  %It is $(m-k)$ because we have to take product of linear functions up to degree $m-k$

Let us define for any $S\subseteq V(G)$ and $v\in S$ the rational function 
\begin{equation}\label{eq:ratio graph hom}
 R_{S,v}(x)=\frac{H(G[S-v],x)}{H(G[S],x)}.   
\end{equation} 
Then for any $\{v_1,\ldots,v_\ell\}\subseteq S$ we have
\[
\frac{H(G[S-\{v_1,\dots,v_\ell\}];x)}{H(G[S];x)}=\prod_{i=1}^\ell R_{S\setminus\{v_1,\dots,v_{i-1}\},v_i }(x).
\]
This means that for any tree $T$ if we let $V(T)=\{v_1,\dots,v_\ell\}$, then
\[\left(\frac{H^e(G;x)}{H(G;x)}\right)^{[m]}=\sum_{\substack{T\in\mathcal{T}_G\\|T|\le m\\e=\min(T)}}\left(x\tfrac{d}{d x}w_T(x)\right)^{[m]}\prod_{i=1}^\ell R^{[m-|T|]}_{V(G)\setminus \{v_1,\dots,v_{i-1}\},v_i}(x).\]
% \[
%     \left(\frac{H^e(G,x)}{H(G,x)}\right)^{[m]}=\sum_{T\in\mathcal{T}_G: e=\min(T)}(xw'_T(x))^{[m]}\prod_{i=1}^{\ell} R_{}.
% \]
By Proposition~\ref{prop:enumerate tree} we can enumerate the trees involved in the summation in time at most $O((e\Delta)^m\Delta m)$. Using the next lemma we obtain the desired algorithm.

\begin{lemma}\label{lem:alg graph hom}
  Under Assumption~\ref{as:computation} there exists an algorithm that on input of a graph $G=(V,E)$ of maximum degree at most $\Delta$ with a given total ordering of its edges, a vertex $v\in V$ and $m\in \mathbb{N}$ computes
\[
 R_{V,v}^{[m]}(x)
\]
in time $O(((q+1)e\Delta)^mm^3)$.
\end{lemma}
\begin{proof}
    The proof essentially follows the same line of proof as our proof of Lemma~\ref{lem:compute R chrom}. 

We first describe an algorithm for computing $R_{S,v}(x)$ for $S\subseteq V$.
For this we will need the following recursion for $R_{S,v}(x)$.
For an arbitrary ordering on the induced edges of $S$ we have
    \begin{align*}
        \frac{1}{R_{S,v}(x)}&=\frac{H(G[S];x)}{H(G[S-v];x)}=\sum_{F\in \mathcal{F}_{G[S]}}\prod_{T\in \mathcal{C}(F)}\frac{w_T}{H(G[S-v];x)}\\
        &=\sum_{\substack{F\in \mathcal{F}_{G[S]}\\ v\notin V(F)}}\prod_{T\in \mathcal{C}(F)}\frac{w_T}{H(G[S-v];x)}+\sum_{\substack{F\in \mathcal{F}_{G[S]}\\ v\in V(F)}}\prod_{T\in \mathcal{C}(F)}\frac{w_T}{H(G[S-v];x)}\\
        &=1+\sum_{\substack{F\in \mathcal{F}_{G[S]}\\ v\in V(F)}}\prod_{T\in \mathcal{C}(F)}\frac{w_T}{H(G[S-v];x)}\\
        &=1+\sum_{\substack{T:T\in\mathcal{T}_{G[S]}\\ v\in V(T),|T|\ge 1}}w_T\frac{H(G[S-V(T)],x)}{H(G[S-v];x)}
    \end{align*}
    This means that
    \[
        R_{S,v}^{[m]}(x)=\frac{1}{1+F^{[m]}(x)},
    \]
    where
    \[
        F^{[m]}(x)=\sum_{\substack{T:T\in\mathcal{T}_{G[S]}\\ v\in V(T),1\le |T|\le m}}w_T^{[m]}\left(\frac{H(G[S-V(T)];x)}{H(G[S-v];x)}\right)^{[m-|T|]}.
    \]
If we denote $V(T)=\{v,v_1,\dots,v_\ell\}$ for a $T$ appearing in this sum, then we can express
    \begin{equation}\label{eq:prod}
        \left(\frac{H(G[S-\{v,v_1,\dots,v_\ell\}];z)}{H(G[S];z)}\right)^{[m-|T|]}=\prod_{i=1}^\ell \left(R_{S\setminus\{v,v_1,\dots,v_{i-1}\},v_i }(z)\right)^{[m-|T|]}.
    \end{equation}
    % therefore the $\left(\frac{H(G[S-V(T)];z)}{H(G[S-v];z)}\right)^{[m-1]}$ can be computed with at most $\ell\le m$ recursive calls.

Now let us denote by $\tau(m)$ the time needed to calculate $R_{S,v}^{[m]}(z)$ for any $S\subseteq V(G)$ such that $|V\setminus S|\le m$ and $v\in S$.
It is our aim to show by induction that $\tau(m)\leq C(e(q+1)\Delta)^mm^3$.

   To compute $R_{S,v}^{[m]}$ from $F^{[m]}$ takes time $O(m^3)$ by Lemma~\ref{lemma:reciprocial}. 
    To compute $F^{[m]}(z)$ we need to enumerate all trees $T$ in $G[S]$ containing $v$ with at most $m$ edges and compute for each such $T$ the polynomials $w_T^{[m]}$ and $\left(\frac{H(G[S-\{v,v_1,\dots,v_\ell\}];z)}{H(G[S];z)}\right)^{[m-|T|]}$ and their product.
    The enumeration can be done in $(e\Delta)^mO(\Delta m)$ time by Proposition~\ref{prop:enumerate tree}.
   As remarked earlier, the computation of $w_T^{[m]}$ can be done in $O(q^k\Delta km)$ time for a tree with $k$ vertices. 
   By~\eqref{eq:prod}, $\left(\frac{H(G[S-\{v,v_1,\dots,v_\ell\}];z)}{H(G[S];z)}\right)^{[m-|T|]}$ can be computed as product of $\ell=|T|$ polynomials with $\ell$ calls to the algorithm, giving a running time $O(\ell(m-\ell)^2)+\tau(m-\ell)\ell$. As the number of trees containing a given vertex of $\ell$ edges is at most $(e\Delta)^\ell$ by~\cite{Borgsetal}*{Lemma 2.1}, we can bound $\tau(m)$ by

    \begin{align*}
    &O(m^3) + (e\Delta)^mO(\Delta m)+\sum_{k=1}^{m} (e\Delta)^k \left(O(q^{k+1}\Delta k(m-k))+ \tau(m-k) k +k O((m-k)^2)\right)\\
        % &\le O(m^3)+(e\Delta)^mO(\Delta m)+((q+1)e\Delta)^m\left(O(m^2)+\tfrac{3}{4}Cm^3\right)\\
        \le &O(m^3)+(e\Delta)^mO(\Delta m)+((q+1)e\Delta)^m\left((qe\Delta)m+\tfrac{3}{4}Cm^3+m^2\tfrac{e\Delta}{(q+1)^m}\right)\\
        \le &O(m^3)+(e\Delta)^m O(\Delta m)+\tfrac{4}{5}C((q+1)e\Delta)^mm^3\\
        \le &C((q+1)e\Delta)^mm^3
    \end{align*}
    where the last two inequalities follow provided $C$ is sufficiently large and using the fact that $ \sum_{k\geq 1}kx^k=\tfrac{x}{(1-x)^2}$ and where for we use induction in the second inequality.
This proves the lemma.
% So in order to compute efficiently the Taylor polynomial of $\log(H(G,x))$ we need an algorithm to compute all subtrees of the graph that contains a specific vertex  of size at most $m$ and an algorithm to compute the $w_T(x)$. The first is can be simply obtained similarly as for the chormatic polynomial i.e. $O((e\Delta)^m)$, while the computation of $w_T$ can be done by definition in at most  $O(q^m(\Delta m)^2$time.
\end{proof}

In exactly the same as in the proof of Theorem~\ref{thm:chrom} we can now deduces Theorem~\ref{thm: graph hom}. We leave the details to the reader.

\subsection{Proof of Lemma~\ref{lem:forest graph hom}}
Here we provide a proof of Lemma~\ref{lem:forest graph hom}, based on~\cite{bencs2024approximatingvolumetruncatedrelaxation}*{Section 2}.

We require the following lemma of Penrose~\cite{penrose}.
\begin{lemma}
Let $G=(V,E)$ be a graph with a fixed total ordering of the edges. Then the collection of connected subgraphs of $G$ can be partitioned into intervals of the form $\{F\mid T\subseteq F\subseteq T\cup B(T)\}$, where T is a tree.
\end{lemma}
As remarked in~\cite{bencs2024approximatingvolumetruncatedrelaxation} this lemma can be proved by assigning a connected subgraph to its minimum weight spanning tree.

We can now prove Lemma~\ref{lem:forest graph hom}.
\begin{proof}[Proof of Lemma~\ref{lem:forest graph hom}]
By expanding the product we can write 
\begin{align*}
H(G;x)&=q^{-|V|}\hom(G,J+x(A-J))=q^{-|V|}\sum_{\phi:V\to [q]}\prod_{uv\in E}(J+x(A-J))_{\phi(u),\phi(v)}
\\
&=\sum_{\phi:V\to [q]}q^{-|V|}\sum_{F\subseteq E}\prod_{uv\in F}(x(A-J))_{\phi(u),\phi(v)}
\\
&=\sum_{F\subseteq E}q^{-|V(F)|}\sum_{\phi:V(F)\to [q]}\prod_{uv\in F}(x(A-J))_{\phi(u),\phi(v)},
\end{align*}
where $V(F)$ denotes the collection of vertices incident with some edge of $F$.

Clearly, for a fixed set $F\subseteq E$ its contribution to the sum is multiplicative over its components. 
By the previous lemma we can uniquely realize each connected subgraph $C$ as $C=T\cup B$ with $B\subseteq B(T)$, the broken edges of $T$.
This implies that we can write 
\begin{align*}
H(G;x)&=\sum_{F\in \mathcal{F}_G}\prod_{T\in \mathcal{C}(F)}q^{-(|T|+1})\sum_{\phi:V(T)\to [q]}\sum_{B\subseteq E(T)}\prod_{uv\in T\cup B}(x(A-J))_{\phi(u),\phi(v)}
\\
&=\sum_{F\in \mathcal{F}_G}\prod_{T\in \mathcal{C}(F)}\frac{x^{|T|}}{q^{|T|+1}}\sum_{\phi:V(T)\to [q]}\prod_{uv\in T}(A-J)_{\phi(u),\phi(v)}\cdot\prod_{uv\in B(T)}(J+x(A-J))_{\phi(u),\phi(v)}
\\
&=\sum_{F\in \mathcal{F}_G}\prod_{T\in \mathcal{C}(F)}w_T,
\end{align*}
as desired.
\end{proof}

