\begin{algorithm}
\caption{$R(G,S,v,k)$}\label{alg:cap}
\begin{algorithmic}
\Require graph $G$, $S\subseteq V(G)$ $v\in S$, $k\in\mathbb{N}$
\Ensure $p=R_{S,v}^{[k]}(z)$
\If{$k=0$}
    \State $p=0$
\ElsIf{$|S|=1$}
    \State $p=z$
\ElsIf{$k>0$ and $|S|>1$}
    \State Let $\{u_1,\dots u_\ell\}=N_G(v)\cap S$
    \State $S_0 \gets S\setminus \{v\}$

    \For{ $i=1,\dots,\ell$}
        \State $R_i \gets R(G,S_0,u_i,k-1)$ \Comment{This is the recursive call}
        \State $S_0 \gets S_0\setminus\{u_i\}$
    \EndFor

    \State $F(z)=1$
    \For{$i=1,\dots,\ell$}
        \State $F(z) \gets F(z)\st{k-1} (1+R_i)$
    \EndFor
    \State $F(z)\gets 1-F(z)$
    \State $p=1$
    \For{i=1,\dots,k-1}
        \State $p \gets \left(p\st{k-1} F(z)\right)+1$
    \EndFor
    \State $p \gets z\cdot p$
\EndIf
\end{algorithmic}
\end{algorithm}


