\ElsIf{$m>0$ and $|S|\ge 1$}
    \State $p(z)\gets 0$
    \For{$v\in V(G)$} \Comment{Computation of $R_{G}(z)$}
        \State $R_v(z)\gets R(G,V(G),v,m)$

