%$$A\Big( -\frac{\Delta Q_{st} - \Delta Q_{rs}}{\overline{S}_{st} - \overline{S}_{rs}} \Big) - \Big( -\frac{\Delta Q_{st} - \Delta Q_{rs·}}{\overline{S}_{st} - \overline{S}_{rs}}\Big)\overline{S}_{st} - \Delta Q_{st}\,,$$
%or for the initial dual, leading to the solution of Problem~\eqref{pb:oneConstraint} given by:

%Its maximum is given by:
%\begin{equation} x^* =(\overline{S}_{st} - \overline{S}_{rs})^{-1}\Big( A'\Big( -\frac{\Delta Q_{st} - \Delta Q_{rs·}}{\overline{S}_{st} - \overline{S}_{rs}}\Big) - \overline{S}_{st} \Big)\,,
%\end{equation}
%with $A'$ the derivative of $A$ and notation $\Delta Q_{ij} =\frac{Q_j-Q_i}{j-i}$.\\ The useful maximum value for pruning is constrained by the domain of $\D^*$ and the positiveness of $x$. With the domain $(m,M)$ for $\D^*$ (with possible infinite bound) and notations $r_m = \frac{m - \overline{S}_{st}}{\overline{\mathbf{S}}_{st} - \overline{S}_{rs}}$, $r_M = \frac{M - \overline{S}_{st}}{\overline{\mathbf{S}}_{st} - \overline{S}_{rs}}$; the maximum of the dual is  the closest point for $x^*$ in $[0,x_{max}) = [\min\{r_m,r_M\}, \max\{r_m,r_M\}) \cap \R^+$.\\

\subsection{DUST algorithm}
\label{subsec:dust1constraint}

We have designed our new pruning method as straightforward and practical as the PELT rule. The DUST multiple change-point detection algorithm is described in Algorithm~\ref{algo:dust}. Here, the value $c(y_{st})$ is defined as the minimum of the segment cost function $\ttheta \mapsto c(y_{st}; \ttheta)$. For the smallest index in $\mathcal{T}_t$, we use the standard PELT pruning rule by default. The index $r$ is selected from a given probability distribution $p_{r}$ over the indices in $\mathcal{T}_t$ that are smaller than $s$, while the value $\mu_0$ is sampled from a distribution $p_{\mu}$ supported on the segment $[0, \mu_{\text{max}} \le 1)$. For one-parametric cost functions, we can consider a Dirac data-dependent $p_{\mu}$ which matches relation~\eqref{eq:DUSTexact1D1C} in addition to its limit cases.

Simulations (Section~\ref{sec:simus}) explore several choices for the distributions $p_r$ and $p_{\mu}$. In the single-constraint setting, an effective strategy is to select $r$ as the closest index below $s$, and to choose $\mu_0$ as the argument that maximises the dual function, using a simple iterative maximisation procedure or relation~\eqref{eq:DUSTexact1D1C} for one-parametric cost functions. For simplicity, the algorithm is presented with the dual $\D$ with bounded domain, but a similar algorithm can be written with decision function  $\mathbb{D}$. From the output of Algorithm~\ref{algo:dust}, we can easily recover the optimal segmentation for the initial problem~\eqref{eq:global_cost} via a standard backtracking step described in Algorithm~\ref{algo:backtrack}.


\begin{algorithm}[!ht]
\caption{DUST algorithm}
\label{algo:dust}
\begin{algorithmic}[1]
\Require Time series $y_{0n}$, penalty value $\beta>0$, rules $p_r$, $p_{\mu}$
\Ensure Sequences of global costs $Q_{0n}$ and last changes $\hat s_{0n}$ 
\State $Q_0 \gets 0,\quad \mathcal{T}_1 \gets \{0\}$
\For{$t = 1,\dots, n$} \Comment{OP step}
    \State $Q_t \gets \min_{s \in \mathcal{T}_t} \left\{ Q_s + c(y_{st}) + \beta \right\}$
    \State $\hat s_t \gets \argmin_{s \in \mathcal{T}_t} \left\{Q_s + c(y_{st}) + \beta \right\}$
    \For{$s \in \mathcal{T}_t$}  \Comment{DUST pruning step}
       \State Draw $r$ in $\mathcal{T}_t$ such that $r < s$ from distribution $p_{r}$
        \State Compute $\mu_{max} = \mu_{max}^{r,s,t}$ (data dependent) 
        \State Draw $\mu_0$ in $[0, \mu_{max})$ from distribution $p_{\mu}$
         \If {$\D(\mu_0) > Q_t + \beta$}  \Comment{DUST test}
         \State {$\mathcal{T}_t \gets \mathcal{T}_t \backslash\{s\}$}
       \EndIf
    \EndFor
 \State $\mathcal{T}_{t+1} \gets \mathcal{T}_t \cup  \{t\}$
\EndFor
\end{algorithmic}
\end{algorithm}


\begin{algorithm}[!ht]
\caption{Backtracking the change-point locations}
\label{algo:backtrack}
\begin{algorithmic}[1]
\Require $\hat s_{0n}$
\Ensure Set of optimal change point indices $\widehat{\Tau} = \{\tau_1, \tau_2,\dots\}$
% \State {\bf procedure} $(y_{1:n}, \beta)$
\State $\tau \gets n$, $\widehat{\Tau} \gets \emptyset$
\While{$\tau>0$}
\State $\widehat{\Tau} \gets (\tau, \widehat{\Tau})$, $t \gets \hat{s}_{\tau}$
\EndWhile
\end{algorithmic}
\end{algorithm}



\begin{remark}
DUST extends PELT by evaluating the dual function beyond zero. While PELT applies the test $\mathcal{D}(0) > Q_t + \beta$, derived from the unconstrained form of Problem~\eqref{pb:oneConstraint}, DUST samples $\mu_0$ in $[0, \mu_{\text{max}})$, potentially yielding stronger pruning. This makes DUST especially effective in time series with few change points, where PELT tends to prune poorly. Despite its improved pruning, DUST maintains a complexity close to PELT, with minimal overhead from computing $\mu_{\text{max}}$ and selecting $r$ and $\mu_0$.
\end{remark}




\subsection{Example of the change-in-mean-and-variance problem}
\label{subsec:example}

Detecting changes in both the mean and variance of a large Gaussian time series is challenging. To the best of our knowledge, no efficient implementation currently exists in this setting due to two main difficulties. First, the problem involves two parameters, which limit the applicability of methods like FPOP \cite{maidstone2017optimal}. Second, a logarithmic term in the cost function complicates root-finding, making methods such as geomFPOP \cite{pishchagina2024geometricbased} difficult to apply. We address this challenge using the DUST method. We write down the likelihood of segment $y_{st}$ with mean $m$ and variance $\sigma^2$,
$$
\mathcal{L}(y_{st}; [m; \sigma^2])=  \prod_{i=s+1}^t \biggr[ \frac{1}{\sqrt{2\pi\sigma^2}}\exp\Big(-\frac{(m-y_i)^2}{2\sigma^2}\Big) \biggr]\,,
$$
and its associated cost:
$$c(y_{st}; [m; \sigma^2]) =  (t-s)\Big(\frac{(m-\overline{y}_{st})^2 + V (y_{st})}{2\sigma^2} + \frac{1}{2}\log(\sigma^2)\Big)\,.$$

With the change of variable $(\theta_1,\theta_2) = (\frac{m}{\sigma^2}; -\frac{1}{2\sigma^2}) \in \R \times \R^-$, we obtain the canonical form of Example~\ref{ex:MeanAndVar} with $A(\theta_1,\theta_2) =-\frac{\theta_1^2}{4\theta_2} + \frac{1}{2}\log(-\frac{1}{2\theta_2})$. We can now derive the exact maximum value of the associated decision function.

\begin{lemma}
The one-dimensional decision function for the change-in-mean-and-variance problem with a single constraint from the cost function \eqref{eq:MeanAndVar} is given by the function:
$$
\mathbb{D}(x) =  \frac{1}{2}\Bigg[1+ \log\Big( \overline{S^2_{st}}+x\Delta\overline{S_{rst}^2}-(\overline{S}_{st}+ x\Delta\overline{S}_{rst})^2\Big)\Bigg]- \Big(\overline{Q}_{st} + x\Delta \overline{Q}_{rst}\Big)\,,$$
with $x \in (x_0 - \sqrt{x_1}, x_0 + \sqrt{x_1})$ and 
$$x_0 = \frac{1}{2}\Big(\frac{V(y_{st}) - V(y_{rs})}{(\Delta\overline{S}_{rst})^2} - 1\Big)\,\quad x_1 = x_0^2 +  \frac{V(y_{st})}{(\Delta\overline{S}_{rst})^2}$$
and its maximum, with notation $x_2 = \Delta \overline{Q}_{rst}$, is evaluated in:
$$x^{\star} = \max \Big\{0, x_0 + (2 x_2)^{-1} - \operatorname{sign}(x_2) \sqrt{x_1 + (2 x_2)^{-2}}\Big\}$$
\end{lemma}

In Figure~\ref{fig:pruningMV}, we evaluate the efficiency of DUST for this example. For each index~$s$ considered for pruning, we choose the biggest non-pruned index smaller than $s$ and evaluate the dual at its maximum position $x^{\star}$. With $n=10^4$, $\beta = 4 \log(n)$ and data with no change ($\mathcal{N}(0,1)$), only $2.95\%$ of the indices remain non-pruned and the overall number of indices to be considered is reduced by a factor $28$ compared to PELT (left panel). %Running times with dust Rcpp package are clear, for $n = 10^5$ and no change, $T(DUST) = 4.7 s$ while $T(PELT) = 82s$.

