\section{Useful relations between means}
\label{app:means_relations}


\begin{proposition}
 \label{lemma1}
For all $i\in \{1,\ldots,t-1\}$ we have
\begin{align}
 t V(y_{0t}) - (t-i)&V(y_{it}) - iV(y_{0i})\notag \\
\label{lemmaroots1}
   &=  \frac{(t-i)i}{t} \left(\overline{y}_{it}-\overline{y}_{0i}\right)^2\\
\label{lemmaroots2}
 &=\frac{ti}{t-i} \left(\overline{y}_{0t}-\overline{y}_{0i}\right)^2\\
\label{lemmaroots3}
  &=\frac{t(t-i)}{i} \left(\overline{y}_{0t}-\overline{y}_{it}\right)^2\\
\label{lemmaroots4}
   &=i\left(\overline{y}_{0t}-\overline{y}_{0i}\right)^2+(t-i) \left(\overline{y}_{0t}-\overline{y}_{it}\right)^2
\end{align} 
 \end{proposition}


 \begin{proof}
For any $(a,b) \in (\mathbb{N}^*)^2$ with $a<b$ we easily get the following expressions:

\begin{align}
\label{relationMu1}
   &\overline{y}_{0b}-\overline{y}_{0a} = \frac{b-a}{b}\left(\overline{y}_{ab}- \overline{y}_{0a}\right) \,,\\
\label{relationMu2}
 &\overline{y}_{0b}-\overline{y}_{ab} = \frac{a}{b}\left(\overline{y}_{0a}- \overline{y}_{ab}\right) \,.
\end{align} 
With $a=i$ and $b=t$, we derive from \eqref{lemmaroots1}  the relation \eqref{lemmaroots2} using \eqref{relationMu1} and also derive relation \eqref{lemmaroots3} using \eqref{relationMu2}. Expression \eqref{lemmaroots4} is the result of $\frac{t-i}{t}\eqref{lemmaroots2} + \frac{i}{t}\eqref{lemmaroots3}$. Therefore, we only need to prove relation \eqref{lemmaroots1}. Expanding the squares in variance expressions we get:
\begin{align*}
S &=  t V(y_{0t}) - (t-i)V(y_{it}) - iV(y_{0i})\\
   &= -t (\overline{y}_{0t})^2  + (t-i)(\overline{y}_{it})^2+ i(\overline{y}_{0i})^2\\
  & = i((\overline{y}_{0i})^2-(\overline{y}_{0t})^2) + (t-i) ((\overline{y}_{it})^2-(\overline{y}_{0t})^2)\\
  &=i(\overline{y}_{0i}-\overline{y}_{0t})(\overline{y}_{0i}+\overline{y}_{0t}) + (t-i)(\overline{y}_{it}-\overline{y}_{0t})(\overline{y}_{it}+\overline{y}_{0t})\,.
\end{align*} 
Using again relations \eqref{relationMu1} and \eqref{relationMu2}, we have
  $$S =\frac{(t-i)i}{t}\Big(\overline{y}_{0i}-\overline{y}_{it})(\overline{y}_{0i}+\overline{y}_{0t}) +(\overline{y}_{it}-\overline{y}_{0i})(\overline{y}_{it}+\overline{y}_{0t})\Big)\,,$$
  and we get the expression \eqref{lemmaroots1} by simplifying this last expression. 
 \end{proof}

\section{Proof of Proposition \ref{prop:max_pruning}}
\label{app:max_pruning}

If we would remove index $s_0$ from $\Tau_{t}$ while still having a point $\ttheta_0 \in \Theta$ such that:
\begin{equation}
\label{eq:conditionsNonOptimal}
\left\{\begin{aligned}
&Q_t(\ttheta_0) = q_t^{s_0}(\ttheta_0)< q_t^{s}(\ttheta_0)\quad  \hbox{for} \quad  s \ne s_0\,,\\
& Q_t + \beta > q_t^{s_0}(\ttheta_0)\,,\end{aligned}
\right.
\end{equation}
we show that removing $s_0$ could lead to an under-optimal solution for \eqref{eq:fpop} and then for \eqref{eq:global_cost} at some data time $t_0 > t$. We will choose data points after time $t$ to create such a solution, i.e., with $\argmin_{\ttheta} Q_{t_0}(\ttheta)$ attained by a value on function $q_{t_0}^{s_0}$. To that end, for all further iteration $t' > t$ we choose data points $y_{t'}$ with unitary cost:
$$c(y_{t'}; \theta) = A(\ttheta) - \ttheta\cdot\mathbf{T}(y_{t'})= A(\ttheta) - \ttheta\cdot\nabla A(\ttheta_0) = c(\ttheta)\,.$$

{\it Case 1: non-optimal indices $s \ne s_0 \in \{0,\ldots, t-1\}$.} By continuity of function $Q_t(\cdot)$ there exists a ball centred on $\ttheta_0$ with small radius~$\epsilon$, $B(\ttheta_0, \epsilon)$, such that  $Q_t(\ttheta) = q_t^{s_0}(\ttheta) < q_t^{s}(\ttheta)$ for points $\ttheta$ in this ball. We consider $\ttheta$ outside $B(\ttheta_0, \epsilon)$. By strong convexity of $A$, there exists a constant $a>0$ such that: 
$$c(\ttheta) > c(\ttheta_0) + a \|\ttheta - \ttheta_0\|^2\ge c(\ttheta_0) + a \epsilon^2\,,$$
for all $\ttheta$ outside $B(\ttheta_0, \epsilon)$. We also write
$\Delta = q_t^{s_0}(\ttheta_0) - Q_t \ge 0$.
We consider $T = \lceil\frac{\Delta}{a\epsilon^2}\rceil$, then:
$$Tc(\ttheta) > Tc(\ttheta_0) + aT \epsilon^2 \ge Tc(\ttheta_0) + \Delta\,.$$
Thus,
$$Q_t + Tc(\ttheta)    >  Q_t +  Tc(\ttheta_0) + \Delta   =  Tc(\ttheta_0) + q_t^{s_0}(\ttheta_0)\,,$$
for all $\ttheta$ outside $B(\ttheta_0, \epsilon)$. Thus, the minimum of $Q_{t_0}(\cdot) = Q_{t+T}(\cdot)$ can only be in the ball. All points outside the ball corresponding to indices $s \ne s_0$ in $\{0,\ldots, t-1\}$ are not optimal, which proves case 1.\\


{\it Case 2: non-optimal indices $s \in \{t,\ldots, t+T\}$.} We first consider $s=t$. The second assumption in Equation \eqref{eq:conditionsNonOptimal} ($Q_t + \beta > q_t^{s_0}(\ttheta_0)$) ensures that values visible for function $q_t^{s_0}$ are not all too large and pruned by function $q_{t+1}^t$. We have:
\begin{align*} 
q_{t_0}^t(\ttheta) = Q_t + Tc(\ttheta) + \beta    &> q_t^{s_0}(\ttheta_0) + Tc(\ttheta)  \,,\\
&  \ge q_t^{s_0}(\ttheta_0) + Tc(\ttheta_0) \,,\\
& = q_{t+T}^{s_0}(\ttheta_0) = q_{t_0}^{s_0}(\ttheta_0)\,.
\end{align*}
All points on the function $q_{t_0}^t$ are higher than $q_{t_0}^{s_0}(\ttheta_0)$, consequently index $t$ can not be optimal. 
For $s \in \{t+1,\ldots, t+T\}$, we have for index $\overline{s} < t$:
$$\min_{\ttheta}c(y_{\overline{s}t}; \ttheta) + (s-t)c(\ttheta_0) \le \min_{\ttheta}c(y_{\overline{s}s}; \ttheta)\,,$$
or, 
$$\min_{\ttheta}c(y_{\overline{s}t}; \ttheta) +Tc(\ttheta_0) \le  \min_{\ttheta}c(y_{\overline{s}s}; \ttheta) + (t_0-s)c(\ttheta_0)\,.$$
Using for $\overline{s}$ the best index for last change point in $Q_s$ (written $\overline{s}_0$) we have 
$Q_{\overline{s}_0} + \min_{\ttheta}c(y_{\overline{s}_0s}; \ttheta)+ \beta = Q_s$ and we get:
$$ Q_{\overline{s}_0} + \min_{\ttheta}c(y_{\overline{s}_0t}; \ttheta) +\beta + Tc(\ttheta_0)  \le  Q_s + (t_0-s)c(\ttheta_0)\,.$$
By definition of $Q_t$ (see \eqref{eq:fpop}) we have 
$Q_t \le Q_{\overline{s}_0} + \min_{\ttheta}c(y_{\overline{s}_0t}; \ttheta) + \beta $ and eventually:
\begin{align*} 
q_{t_0}^t(\ttheta_0) = Q_t+T c(\ttheta_0) + \beta   & \le Q_s + (t_0-s)c(\ttheta) + \beta   \,,\\
& \le Q_s + (t_0-s)c(\ttheta) + \beta = q_{t_0}^s(\ttheta) \,.
\end{align*}

The global minimum of the function $Q_{t_0}(\cdot)$ cannot be attained in index $s$, as we proved that it cannot either in index $t$. By exclusion of all indices, except $s_0$, we have shown that the global minimum is attained at a value of the function $q_{t_0}^{s_0}$; consequently, removing $s_0$ from $\Tau_t$ would lead to an under-optimal solution.





\section{Worst-case time series}
\label{app:worstcase}


\subsection{Proof of Proposition \ref{prop:worstcaseGauss}}
\label{app:worstcaseGauss}


The minimum of the function $q_t^s$ is defined as $m_t^s$. A sufficient condition for no pruning is to meet the condition $m_n^0 = m_n^1 = \cdots = m_n^{n-1}$ obtained at distinct values. This is the case for a strictly increasing time series. We assume that the global minimum is always attained for index $0$ and that the time series is increasing; thus, using the variance notation in Appendix \ref{app:means_relations}, we solve:
$$m_n^0 = nV(y_{0n}) = (n-t)V(y_{tn}) + tV(y_{0t}) + \beta\,,\quad \hbox{for all} \,\, t = 1,\dots, n-1\,.$$
By relations in Appendix~\ref{app:means_relations}, this leads to equations
$$ \frac{nt}{n-t} \left(\overline{y}_{0n}-\overline{y}_{0t}\right)^2 = \beta \,,\quad \hbox{for all} \,\, t = 1,\dots, n-1\,.$$
With $t=1$, we obtain $ \overline{y}_{0n} = \sqrt{\beta\frac{n-1}{n}}$ having chosen first data value $y_1 = 0$, and therefore, with other indices, we get:
$$y_1+\cdots +y_{t} = t\sqrt{\beta\frac{n-1}{n}}- \sqrt{\beta \frac{t(n-t)}{n}}\,.$$
We then find the proposed expression easily. We need to verify that the time series is strictly increasing and that the global minimum is associated with the first data point at each time step. Indeed,
$$y_{t+1} - y_t = \sqrt{\frac{\beta}{n}}\Big(-\sqrt{(t+1)(n-t-1)}+2\sqrt{t(n-t)} -\sqrt{(t-1)(n-t+1)} \Big)$$
is positive as $t \mapsto -\sqrt{t(n-t)}$ is strictly convex on interval $[0,n]$. The last change point is always associated with the first data point, as we have an increasing sequence of data with equality of the minima at the ending instant $n$ ($m_n^0 = m_n^1 = \cdots = m_n^{n-1}$).




\subsection{No pruning in the exponential family}
\label{app:worstCase2}

We say that a time series increases if it is increasing coordinate by coordinate. Under some mild assumptions, we can build a no-pruning example of increasing time series in a more general setting.


\begin{proposition} 
\label{prop:worstcase}
We consider costs of type "$a A(\ttheta) + b \cdot \ttheta + c$" derived from the natural exponential family with continuous density. We consider the following equations in variable~$x$:
\begin{equation}
\label{eq:worstEquation}
E(t): \quad g_t(x) = \frac{\beta}{n} + \mathcal{D^*}(Y)\,,\quad t = 1,\ldots,n-1\,,
\end{equation}
with
$$
\left\{
    \begin{aligned}
    &\mathcal{D^*}(x) = x\cdot (\nabla A)^{-1}(x) - A((\nabla A)^{-1}(x)),,\quad x \in \Omega\,,\\
     &g_t(x) = \frac{t}{n}\mathcal{D^*}(x)  + \frac{n-t}{n}\mathcal{D^*}\Big(\frac{nY - tx}{n-t}\Big)\,,\quad x \in \Omega_t \subset \Omega\,.\\
    \end{aligned}
    \right.
$$
If $Y \in \Omega_0 = \cap_{t=1}^{n-1}\Omega_t$ and $\beta$ is chosen such that:
$$\sup_{x \in \Omega_0\,,\,x \le Y} \{g_1(x)\} > \frac{\beta}{n} + \mathcal{D^*}(Y)\,,$$
there exists an increasing sequence of data $y_1,\ldots,y_n$ with zero pruning solving \eqref{eq:global_cost} which verifies:
$$
\left\{
    \begin{aligned}
    &Y = \overline{y}_{0n} = \frac{1}{n}\sum_{t=1}^{n}y_t\,,\\
    &x = s_t \quad \hbox{solution of}\quad E(t)\,,\\
    &y_t = t s_t - (t-1)s_{t-1}\quad t=1,\ldots,n\,,\quad \hbox{with}\quad s_0 = 0\,.
    \end{aligned}
    \right.
$$
\end{proposition}

\begin{proof}

The proof is an extension of the evidence of Proposition~\ref{prop:worstcaseGauss} and is based on a similar strategy. We look for data configurations for which the minimum of functions $q_t^s$, denoted $m_t^s$, are all the same: $m_n^0 = m_n^1 = \cdots = m_n^{n-1}$. There is no possible pruning if we find an increasing time series realising such conditions. For density from the natural exponential family, we get the relations:
$$ m_n^{t} = Q_t + (n-t)(A(\rho_t) - \overline{y}_{tn}\cdot\rho_t)  + \beta = Q_0 + n(A(\rho_0) - \overline{y}_{0n}\cdot\rho_0) + \beta  =  m_n^{0}\,,$$
with $\rho_i = (\nabla A)^{-1}(\overline{y}_{in})$. We have also $Q_0 = 0$ and $Q_t = t(A((\nabla A)^{-1}(\overline{y}_{0t})) - \overline{y}_{0t}\cdot(\nabla A)^{-1}(\overline{y}_{0t})) + \beta$ as data is not spit into segments (we have only one large segment and the minimum for $Q_t(\cdot)$ is attained on $q_t^0$). This leads to:
$$\frac{t}{n}\mathcal{D^*}(\overline{y}_{0t})  + \frac{n-t}{n}\mathcal{D^*}\Big(\overline{y}_{tn}\Big) = \frac{\beta}{n} + \mathcal{D^*}(\overline{y}_{0n})\,,$$
with $\mathcal{D^*}(x) = x\cdot (\nabla A)^{-1}(x) - A((\nabla A)^{-1}(x))$. We get Equations \eqref{eq:worstEquation} denoted $E(t)$ with $x = \overline{y}_{0t}$, $Y = \overline{y}_{0n}$ and relation $\frac{nY - tx}{n-t} = \overline{y}_{tn}$. It remains to find conditions for the existence of a solution. We define $g_t(x) = \frac{t}{n}\mathcal{D^*}(x)  + \frac{n-t}{n}\mathcal{D^*}\Big(\frac{nY - tx}{n-t}\Big)$ and study this function. We have:
$$
\left\{\begin{aligned}
&g_t(Y) = \mathcal{D^*}(Y)\,,\\
&\nabla g_t(Y) = 0\,,\\
&g_t \quad \hbox{strictly convex}\,,\\
&g_{t+1} > g_{t} \quad \hbox{except in point }\, Y\,.\\
\end{aligned}
\right.
$$
Evaluation of $g_t$ in $Y$ is obvious, for the gradient we get: 
$$ \nabla g_t(x) = \frac{t}{n}\Big( \nabla\mathcal{D^*}(x) - \nabla\mathcal{D^*}\Big(\frac{nY - tx}{n-t}\Big)\Big)\,,$$
and then $\nabla g_t(Y) = 0$. Moreover, function $g_t$ is strictly convex: $\nabla^2 g_t(x) =  \frac{t}{n} \nabla^2\mathcal{D^*}(x) + \frac{t^2}{n(n-t)}\nabla^2\mathcal{D^*}\Big(\frac{nZ - tx}{n-t}\Big)$; its Hessian is definite positive since the Hessian of $ \mathcal{D^*}$ is. We prove $g_{t+1} >g_t$ considering $t$ as a continuous variable. We define $h_x(t) = g_{t}(x)$ and we have:

$$\nabla h_x(t) = \frac{1}{n}\mathcal{D^*}(x) - \frac{1}{n}\mathcal{D^*}\Big(\frac{nY - tx}{n-t}\Big) + \frac{Y-x}{n-t}\cdot \nabla \mathcal{D^*}\Big(\frac{nY - tx}{n-t}\Big)\,.$$
However, by a characterisation of the strict convexity of $\mathcal{D^*}$ we have for $x \ne Y$:
$$ \mathcal{D^*}(x) > \mathcal{D^*}\Big(\frac{nY - tx}{n-t}\Big) + n\frac{Y-x}{n-t}\cdot \nabla \mathcal{D^*}\Big(\frac{nY - tx}{n-t}\Big)\,,$$
as $n\frac{Y-x}{n-t} = x -   \frac{nY-tx}{n-t}$. This leads obviously to $\nabla h_x(t) > 0$ and consequently to $h_x(t+1) - h_x(t) > 0$ or with the $g$ notation: $g_{t+1}(x) >g_t(x)$ for all $t$ and all $x \ne Y$. 

Now, with $\Omega_t$ the convex domain of $g_t$, if $\Omega_0 = \cap_{t=1}^{n-1}\Omega_t$ is not empty, we can choose $Y$ in $\Omega_0$. We also choose $\beta$ such that 
$\sup_{x \in \Omega_0\,,\,x \le Y} \{g_1(x)\} > \frac{\beta}{n} + \mathcal{D^*}(Y)$. By continuity of $g_t$ we can find $x = s_1$ solving $E(1)$. Using the fact that $g_{2}>g_1$ and $\min_{x\in \Omega_0} g_2(x) = \D^*(Y)$ we can now find $x = s_2 > s_1$ solving $E(2)$. Step by step, we build the sequence $(s_t)$ corresponding to an increasing sequence of means $\overline{y}_{0t}$. From this point, it is easy to extract the increasing time series $(y_t)$, which concludes the proof.
\end{proof}


Notice that the multiple independent Poisson model leads to the expression \eqref{eq:worstEquation} written as:
$$\frac{t}{n}x \log(x)  - Y \log (Y) + \Big(Y-\frac{t}{n}x\Big)\log\Big(\frac{Y - \frac{t}{n}x}{1-\frac{t}{n}}\Big) = \frac{\beta}{n}\,,$$
where $x \in \Omega_0 = \Big(0, \frac{n}{n-1}Y\Big) = \Big(0, \frac{n}{n-1}Y_1\Big)\times \cdots \times\Big(0, \frac{n}{n-1}Y_d\Big) \subset \R^d$. The set $\Omega_0$ is not empty and the limit of  $g_1$ in zero leads to the condition for beta: $\beta \le n\log\Big(\frac{n}{n-1}\Big)\Big(\sum_{i=1}^dY_i\Big)$. This bound is much lower than usual values chosen for penalty, bounded by a $\log(n)$ term \cite{cleynen2017model}. As the Poisson model needs integer data points, the solution we get has to be approximated by $\tilde y_t = \lceil y_t \rceil$ and the resulting data and functional cost $Q_n(\cdot)$ have some of their indices pruned as illustrated in Figure~\ref{fig:worstcase_poisson}. If $Y$ is chosen very large, the approximation improves and the obtained time series converges to the Gaussian data with no pruning.\\


