\subsection{Extensions}
\label{Extensions}
Extensions of Hopf algebras were discussed by various authors in
various contexts. We follow the expositions in \cites{andrus-devoto,schneiderext}.
\begin{definition}
\label{ExactSequenceDef}
A sequence of morphisms of Hopf algebras
\begin{align*}
\xymatrix@C-10pt{\ku\ar  @{->}[r]^{} & W \ar  @{->}[r]^{\jmath }
&  H  \ar  @{->}[r]^{\wp } & K \ar  @{->}[r]^{}&  \ku },
\end{align*}
is \emph{exact}, in which case we say that $H$ is an {\em extension} of $K$ by $W$,
if 

\begin{enumerate}[leftmargin=7ex,label=\rm{(\alph*)}]
\item\label{item:suc-exacta-1} $\jmath$ is injective, and we identify $W$ with $\jmath(W)$,

\medbreak
\item\label{item:suc-exacta-2} 
$\wp$ is surjective,

\medbreak
\item\label{item:suc-exacta-3} 
$\ker \wp = H\, W^+$,
for $W^+=\ker \epsilon_W$
and

\medbreak
\item\label{item:suc-exacta-4} $W = H^{\operatorname{co} \wp}$.
\end{enumerate}
\end{definition}

\vspace{1ex}

We often abbreviate
$W \overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow} K$
for an exact sequence $\xymatrix@C-10pt{
\ku\ar  @{->}[r]^{} & W \ar  @{->}[r]^{\jmath }&  H \ar  @{->}[r]^{\wp } 
& K \ar  @{->}[r]^{}&  \ku}$.


\begin{remark}\label{rem:extension-fflat}
Let $W \xhookrightarrow[]{\jmath} H$ be an injective morphism of Hopf algebras
such that $H$ is a faithfully flat $W$-module via $\jmath$ and 
$\jmath(W)$ is stable by the left adjoint action of $H$.
Define $K$ by \ref{item:suc-exacta-3}, i.e., $K = H/ H\jmath(W)^+$ and let $H\overset{\wp}{\twoheadrightarrow} K$
be the natural projection.
Then \ref{item:suc-exacta-4} holds, 
 we have an exact sequence $W \overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow} K$, and $H$ is a faithfully coflat $K$-comodule via $\wp$,
see \cite{andrus-devoto}*{Corollaries 1.2.5 and 1.2.14} and \cite{schneiderext}.
\end{remark}

\begin{remark}\label{rem:extension-fcoflat}
Let  $H\overset{\wp}{\twoheadrightarrow} K$
be a surjective morphism of Hopf algebras
such that $H$ is a faithfully coflat $K$-comodule via $\wp$.
Define $W$ by \ref{item:suc-exacta-4}, i.e., $W = H^{\operatorname{co} \wp}$ and let 
 $W \xhookrightarrow[]{\jmath} H$ be the natural inclusion, $\jmath(W)$ is stable by the left adjoint action of $H$.
Then \ref{item:suc-exacta-3} holds, 
and we have an exact sequence $W \overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow} K$,
see \cite{andrus-devoto}*{Corollary 1.2.5 and 1.2.14} and \cite{schneiderext}.
\end{remark}

\vspace{1ex}

The following result is useful to verify  faithful flatness over Hopf subalgebras.

\begin{remark}
Let $H$ be a Hopf algebra with bijective antipode and $W \subset H$ a (not necessarily normal) Hopf subalgebra of $H$. Then the following conditions are equivalent, cf. \cite{schneider-normal}*{Corollary 1.8}:
\begin{enumerate}[leftmargin=7ex]
\item\label{item:fflat-1} $H$ is faithfully flat as a left $W$-module.

\medbreak
\item\label{item:fflat-2} $H$ is projective as a left $W$-module.

\medbreak
\item\label{item:fflat-3} $H$ is a flat left $W$-module 
and $W$ is a direct summand of $H$, as a left $W$-module.

\medbreak
\item\label{item:fflat-4} Any of the conditions above with right instead of left.
\end{enumerate}
\end{remark}

