\section{Equivariant deformation sequences}\label{sec:equivariant-deformation}
In this section, we will closely follow the approach in \cite{negron}, where instead of a finite group scheme $G$, we will consider a finite-dimensional Hopf algebra $K$. Some results will hold without the assumption of the cocommutativity of $K$.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Equivariant deformation sequences} We look at deformation sequences that preserve the action of a finite-dimensional Hopf algebra $K$.

\begin{definition}\label{def:equiv-defor-seq} \cites{negron-pevtsova, negron}
Let $K$ be a finite-dimensional Hopf algebra. A deformation sequence 
$Z \overset{\iota}{\hookrightarrow} Q \overset{\pi}{\twoheadrightarrow}  R$ 
is \emph{$K$-equivariant}
if  $Z$, $Q$ and $R$ are $K$-module algebras and $\iota$ and $\pi$ 
are $K$-module algebra maps. 
In this case, we say that  $R$ admits a \emph{$K$-equivariant deformation sequence}.

Analogously, a formal deformation sequence 
$\widehat{Z} \overset{\widehat{\iota}}{\hookrightarrow} \widehat{Q} \overset{\widehat{\pi}}{\twoheadrightarrow}  R$ is \emph{$K$-equivariant}
if  $\widehat{Z}$, $\widehat{Q}$ and $R$ are $K$-module algebras and
$\iota$ and $\pi$ are $K$-module algebra maps. 
In this case, we say that  $R$ 
admits
an \emph{$K$-equivariant formal deformation sequence}.
\end{definition}

\begin{remark}
Instead of smoothness of $\Spec Z$ imposed in Definition \ref{def:defor-seq} \ref{item:deformation-Z},
it is just required in \cites{negron,negron-pevtsova}
that  $\epsilon_Z$ is a nonsingular point of $\Spec Z$. 
\end{remark} 



The following lemma, an extension of Lemma \ref{lem:formal-deformation}, shows that 
we may turn every $K$-equivariant deformation sequence for $R$ into  a formal one. 




\begin{lemma}\label{lem:formal-deformation-equivariant} \cite{negron}*{Proposition 4.3} 
Let $K$ be a finite-dimensional Hopf algebra.  Suppose that
$Z \overset{\iota}{\hookrightarrow} Q \overset{\pi}{\twoheadrightarrow}  R$
is a $K$-equivariant deformation sequence. Then 
\[\widehat{Z} \overset{\widehat{\iota}}{\hookrightarrow} \widehat{Q} \overset{\widehat{\pi}}{\twoheadrightarrow}  R\]
is a $K$-equivariant formal deformation sequence, 
where $\widehat{Z}$ is the completion of the localization $Z_{\mgo}$ with respect to the
$\mgo$-adic topology and $\widehat{Q} \coloneqq \widehat{Z} \otimes_{Z} Q$
for $\mgo = Z^+$.  
\end{lemma}

\begin{proof}
By Lemma \ref{lem:formal-deformation},
we need only check equivariance
of the deformation sequence given there.
Since $\epsilon_Z=  \epsilon_R\circ \pi\circ \iota: Z\to \ku$ is $K$-linear, the maximal ideal $\mgo$ is $K$-stable. Hence, both $\widehat{Z}$ and $\widehat{Q}$ are $K$-module algebras 
(cf. \cite{negron}*{Proposition 4.3}), and the corresponding algebra maps between them are also $K$-linear. In particular, the unique maximal ideal $\mgo=(x_1,\ldots,x_n)$ in $\widehat{Z}$ is $K$-invariant. 
\end{proof}


\vspace{1ex}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{dg $K$-module algebras}
Let $K$ be a finite-dimensional Hopf algebra and denote by $\Rep K$ the tensor category of $K$-modules.

We recall here some properties of dg $K$-module algebras and later associate them to an equivariant deformation sequence to show the fgc property. We refer to \cite{yekutieli-book} for generalities on differential graded (dg) algebras. 


\begin{definition}
We define dg objects
carrying an action of the Hopf algebra $K$.
\begin{itemize}
\item[(i)] A {\em dg $K$-module algebra}
is a dg algebra $A$ internal to $\Rep K$, i.e., a dg algebra $A$ 
which is also a $K$-module algebra such that all the dg algebra structure maps are $K$-linear.
\item[(ii)]
A {\em dg $K$-module $M$ over $A$} is a dg module over $A$ internal to $\Rep K$, i.e., a dg module $M$ over $A$ that is a $K$-module for which the dg module structure maps on $M$ are $K$-linear.
\item[(iii)]
Let 
$A\dgMod(\Rep K)$ denote the category of dg $K$-modules over $A$.
\end{itemize}
\end{definition}

\begin{remark} For a dg $K$-module algebra $A$, the smash product
$A \rtimes K$ becomes an ordinary dg algebra by setting $K$ to be concentrated in degree zero 
with zero differentials. Correspondingly, 
a dg $K$-module over $A$ is an ordinary dg module over $A \rtimes K$. In summary, we have an equivalence $A\dgMod(\Rep K)\simeq (A\rtimes K)\dgMod$.
In view of this, we denote by $D_\dg(A \rtimes K)$ the derived category of dg $K$-modules over $A$.
\end{remark}


We say that two $K$-module dg algebras $A,B$ are \emph{homotopically isomorphic} 
(see \cite{negron})
if there is a zig-zag of $K$-linear dg algebra quasi-isomorphisms 
\[
A\xleftarrow{\sim }  S_1\xrightarrow{\sim}S_2\xrightarrow{\sim } \cdots \xleftarrow{\sim}S_n\xrightarrow{\sim } B.
\]
Any homotopy isomorphism between two dg $K$-module algebras $A$ and $B$ provides 
a triangulated equivalence between their corresponding derived categories of dg modules:
\[D_\dg(A \rtimes K) \overset{\simeq}{\rightarrow}D_{\dg}(B \rtimes K)\]

Let $S$ be a dg $K$-module algebra, and  $M=\bigoplus_{i\in \mathbb Z} M_i$,
$N=\bigoplus_{i\in \mathbb Z}N_i$ two dg $K$-modules over $S$. Recall that 
\begin{align*}
\Hom_S(M,N)=\bigoplus_{i\in \mathbb Z}\Hom_{\gr  S}(M,N[i])
\end{align*}
where $\Hom_{\gr  S}(M,N[i])=\{f\in \Hom_S(M,N)\,|\, f(M_t)=N_{t+i}\}$ is a complex with differentials 
given by $(df)(m)=df(m)-(-1)^{|f|}f(dm)$. 
It is easy to see (cf. \cite{KKZ2009}*{Lemma 5.8}) 
that $\Hom_S(M,N)$ becomes a graded right $K$-module via 
\begin{align}\label{Kaction}
(f\cdot h)(m)=\sum \Ss(h\_1) \cdot f(h\_2\cdot m)
\end{align}
for any $f\in \Hom_S(M,N)$, $h\in K$, and $m\in M$, where $\Ss$ is the antipode of $K$. This $K$-action on $\Hom_S(M,N)$ is different from the one defined in \cite{negron}*{Section 2.5}. However, when $K$ is cocommutative, we can apply the antipode of $K$ to make $\Hom_S(M,N)$ into a left $K$-module which coincides with the module structure in \cite{negron}*{Section 2.5}.

Moreover, the image
$\RHom_S(M,N)$ of the right derived functor of $\Hom_S$ lies in $D(K)$, the derived category of $\Rep K$ \cite{negron}*{Lemma 2.3}, and thus extends to a functor
\[
\RHom_S(-,-)\colon D_\dg(S\rtimes K)^{\text{op}}\times D_\dg(S\rtimes K)\rightarrow D(K).
\]
It is direct to check that the composition map
\[\Hom_S(P,N)\times \Hom_S(M,P)\to \Hom_S(M,N)\] 
is $K$-linear for any dg $K$-modules $M$, $P$, and $N$ over $S$. Consequently, $\REnd_S(M)$ is a dg $K$-module algebra. 

\begin{lemma}\cite{negron}*{Lemma 2.4} \label{DG}
Let $K$ be a finite-dimensional Hopf algebra, $S$ a dg $K$-module algebra and $M$ a dg $K$-module over $S$. Then we have that:
\begin{enumerate}[leftmargin=7ex,label=\rm{(\roman*)}]
\item The dg $K$-module algebra $\REnd_S(M)$ is well-defined up to homotopy isomorphism. 
\item If $M$ and $N$ are isomorphic in $D_\dg(S\rtimes K)$, then $\REnd_S(M)$ and $\REnd_S(N)$ are homotopically isomorphic. 
\end{enumerate}  
\end{lemma}

\begin{proof}
The statement in \cite{negron}*{Lemma 2.4} considers a finite group scheme $G$, however, the proof does not require cocommutativity. 
\end{proof}


\vspace{1ex}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Constructing dg $K$-module algebras associated to a deformation sequence}\label{subsec:constructing}

This subsection summarizes the construction of certain $K$-equivariant dg algebras associated to an equivariant deformation sequence that were used in \cite{negron} to prove fgc for Drinfeld doubles of finite group schemes. This can be considered as a $K$-equivariant version of the dg algebra tools from \cite{negron-pevtsova} employed to show fgc for augmented algebras that admit a (non-equivariant) deformation sequence. We will rely on these tools in Section \ref{sec:fgc_smash} to prove the fgc property for the smash product $R\rtimes K$ when the augmented algebra $R$ admits a $K$-equivariant deformation sequence.

It is important to point out that in order to modify the dg resolution from \cite{negron-pevtsova} to the $K$-equivariant setting, we need $K$ to be cocommutative where its representation category has a symmetric braiding given by the usual flipping map.

Throughout this subsection we consider the following setting: let $K$ be a finite-dimensio\-nal cocommutative Hopf algebra, $R$ a finite-dimensional augmented $K$-module algebra and
\begin{align*}
Z\hookrightarrow Q\twoheadrightarrow R
\end{align*}
a $K$-equivariant formal deformation sequence such that $Z=\ku[[x_1,\cdots,x_n]]$ with $K$-inva\-riant maximal ideal $\mgo=(x_1,\ldots,x_n)$.
\begin{lemma}\cite{negron}*{Lemma 3.1 and Lemma 5.2}\label{dgK}
% Then, 
There is a dg $K$-module algebra $\mathcal K$ satisfying:
\begin{enumerate} [leftmargin=7ex,label=\rm{(\roman*)}]
\item $\mathcal K$ is a $Z$-algebra that is finite and flat over $Z$.

\medbreak
\item $\mathcal K$ is homotopically isomorphic to $\ku$ and $\ku\otimes_Z\mathcal K$ is homotopically isomorphic to $B_Z$, the exterior algebra on the cotangent space $\mgo/ \mgo^2$ 
shifted to degree $-1$ with zero differentials.


\medbreak
\item Consider $\mathcal K$ as a $Z$-central dg $\mathcal K$-bimodule in $D(\mathcal K\otimes_Z  \mathcal K^{\text{op}})$. Then the dg $K$-module algebra $\REnd_{\mathcal K\otimes_Z\mathcal K^{\op}}(\mathcal K)$ is homotopically isomorphic to $A_Z$, the symmetric algebra on the tangent space $\mgo/ \mgo^2$ shifted to degree $2$ with zero differentials.

\medbreak
\item The dg $K$-module algebra $\mathcal K_Q \coloneqq Q\otimes_Z\mathcal K$ is homotopically isomorphic to $R$ and finite and flat over $Z$. 

\end{enumerate}
\end{lemma}

\begin{proof}
The construction of the dg $K$-module algebra $\mathcal K$ and its properties stated in (i) and (ii) are provided in \cite{negron}*{Lemma 3.1}. 
Property (iii) is \cite{negron}*{Lemma 5.2}. For (iv), the construction of $\mathcal K_Q=Q\otimes_Z\mathcal K$ and the fact that it is homotopically isomorphic to $R$ are explained in \cite{negron}*{Section 5.1}. Since $Q$ is finite and flat over $Z$, it is clear that $\mathcal K_Q$ is finite and flat over $Z$ by (i). 
\end{proof}


Consider the dg $K$-module algebras $\mathcal K$ and $\mathcal K_Q=\mathcal K\otimes_Z Q$ from Lemma \ref{dgK} that are homotopically isomorphic to $\ku$ and $R$, respectively. In \cite{negron}*{Section 5.2}, the authors construct a functor 
\[ \mathfrak{def}^K: D_{\dg}((\mathcal K\otimes_Z\mathcal K^{\op})\rtimes K)
\rightarrow
D_{\dg}(\mathcal K_Q\rtimes K)\]
from the derived  category of dg $K$-modules over $\mathcal K\otimes_Z\mathcal K^{\op}$ to that of dg $K$-modules over $\mathcal K_Q$. In particular,  for any dg $K$-module $M$ over $\mathcal K_Q$, there is a dg $K$-module algebra map 
\begin{multline}\label{eq:action_of_S}
\mathfrak{def}^K_M: \quad \mathcal T\coloneqq\REnd_{\mathcal K\otimes_Z\mathcal K^{\op}}(\mathcal K)\xrightarrow{-\otimes^L_ZQ} \REnd_{\mathcal K_Q\otimes_Q\mathcal K^{\op}_Q}(M)
\\
\longrightarrow
\REnd_{\mathcal K_Q\otimes \mathcal K^{\op}_Q}(M)\xrightarrow{-\otimes^L_{\mathcal K_Q}M} \REnd_{\mathcal K_Q}(M).
\end{multline}
Moreover, for any dg $K$-modules $M$ and $N$ over $\mathcal K_Q$, the dg $K$-module algebra $\mathcal T$ acts on the dg $K$-module $\RHom_{\mathcal K_Q}(M,N)$ via either $\mathfrak{def}^K_M$ or $\mathfrak{def}^K_N$ with actions coinciding. The following summarizes the finite generation property derived from a $K$-equivariant formal deformation sequence, which is an equivariantization of 
\cite{negron-pevtsova}*{Corollary 4.7}.


\begin{lemma}\cite{negron}*{Theorem 5.4}\label{fgcR}
Retain the above notation. Let $M,N$ be two dg $K$-modules over $\mathcal K_Q$ such that $\coh(M)$ and $\coh(N)$ are finite-dimensional. Then
\begin{enumerate} [leftmargin=7ex,label=\rm{(\roman*)}]
\item $\coh(\mathfrak{def}^K_M): \coh(\mathcal T)\to \coh(\REnd_{\mathcal K_Q}(M))$ is a finite map of graded dg $K$-module algebras.
\item $\coh(\RHom_{\mathcal K_Q}(M,N))$ is a finitely generated module over $\coh(\mathcal T)$.
\end{enumerate}
\end{lemma}
\begin{proof}
Similarly to Lemma \ref{dgK}, the statement and proof appear in \cite{negron}*{Theorem 5.4} in terms of a finite group scheme $G$ instead of the cocommutative Hopf algebra $K$.
\end{proof}

