\subsection{Alternative formulations of fgc}\label{subsec:alternatives-fgc}
In this subsection, $K$ is a finite-dimensional Hopf algebra.
Lemma \ref{lem:fgc=hfg} is the starting point for the following characterizations of the fgc property.
Notice that the equivalence of the first four items was established in \cite{NWW2021}*{Lemma 3.3} while the equivalence with the last item is implicit in \cite{negron}.

\begin{prop}\label{intP}
If $K$ is power reductive, then the following are equivalent:
\begin{enumerate}[leftmargin=7ex,label=\rm{(\roman*)}]
\item\label{item:alternative1} $K$ has fgc. 

\medbreak
\item\label{item:alternative2} $\coh(K, M)$ is a Noetherian $\coh(K, R)$-module, 
for any affine commutative $K$-module
algebra $R$ and any finitely generated $(R \rtimes K)$-module $M$.


\medbreak
\item\label{item:alternative3} $\coh(K, R)$ is finitely generated for any affine commutative $K$-module algebra $R$.

\medbreak
\item\label{item:alternative4} Let $T$ be a finitely generated non-negatively graded Noetherian $K$-module algebra
and let $M$ be a finitely generated $(T\rtimes K)$-module. 
Then $\coh(K, M)$ is Noetherian over $\coh(K, T)$
whenever $T$ is module finite over a graded central $K$-module subalgebra $Z$.  


\medbreak
\item\label{item:alternative5} 
Let $S$ be a dg $K$-module algebra and $M$ be a dg $K$-module over $S$. 
Assume that

\smallbreak
\begin{enumerate}[label=\rm{(\alph*)}]
\item $\coh(S)$ is affine graded-commutative and concentrated in non-negative degrees,

\smallbreak
\item $\coh(M)$ is finitely generated over $\coh(S)$, and

\smallbreak
\item $S$ is homotopically isomorphic to its cohomology ring $\coh(S)$.
\end{enumerate}

\medbreak
\noindent
 Then the cohomology $\coh(\RHom_K(\ku, M))$ is Noetherian over 
 $\coh(\RHom_K(\ku, S))$.
\end{enumerate}
\end{prop}

\begin{proof}
The equivalences \ref{item:alternative1} $\iff$ \ref{item:alternative2}
$\iff$ \ref{item:alternative3} $\iff$ \ref{item:alternative4} are proved in \cite{NWW2021}*{Lemma 3.3}.
The delicate part
 is  \ref{item:alternative1} $\implies$ \ref{item:alternative2}; 
 we recap the other implications as follows.


\begin{itemize}
\item 
For \ref{item:alternative2} $\implies$ \ref{item:alternative3}, take $M = R$.

\smallbreak
\item
For
\ref{item:alternative3} $\implies$ \ref{item:alternative1}, take $R = \ku$ to 
see that \ref{item:fgca} 
holds and
then take $R = \ku \oplus M$ (with $M^2 = 0$) for a finite $K$-module $M$ to see
that \ref{item:fgcb} holds.


\smallbreak
\item
For
\ref{item:alternative2} $\implies$ \ref{item:alternative4},
take $R = Z^{\text{even}}$ 
to see that $\coh(K,M)$ is a Noetherian module
over $\coh(K, Z^{\text{even}})$.
Then $\coh(K,M)$ is a Noetherian module over $\coh(K,T)$
because the action of $\coh(K,T)$  on $\coh(K,M)$
restricts to the action of $\coh(K,Z^{\text{even}})$.

\smallbreak
\item
For
\ref{item:alternative4} $\implies$ \ref{item:alternative2},
take $T=R$ to be the affine commutative $K$-module algebra concentrated in degree zero.
\end{itemize}

\medbreak
We now turn to the new part of the lemma. 
For
\ref{item:alternative5} $\implies$ \ref{item:alternative1},
take $S$ to be the trivial dg algebra
$\ku$ concentrated in degree zero. Since 
$\coh(\RHom_K(\ku, \ku))\cong \Ext_K (\ku, \ku)$ the result follows by applying Lemma \ref{lem:fgc=hfg}.

We prove \ref{item:alternative4} 
$\implies$ \ref{item:alternative5}. 
By the assumptions in \ref{item:alternative5}, it is clear that both $\coh(S)$ and $\coh(M)$ are bounded below. Let $P_{\bullet}\to \ku$ 
be a projective resolution of $\ku$ as a $K$-module. 
This gives a double complex $\Hom_K(P_\bullet,M)$ whose cohomology yields a bounded spectral sequence
\begin{align*}
E_2^{p, q}(M)
=\Ext^{q}_K(\ku,\coh^p (M))
\implies E_\infty(M)=\coh^{p+q}(\RHom_K(\ku, M)).
\end{align*}

Take the finitely generated graded-commutative $K$-algebra $T=\coh(S)$ (which is also Noetherian by Lemma \ref{lema:graded-Noetherian} \ref{item:A-Noeth-affine}), and $N=\coh(M)$, which is a finitely generated module over $T$ and thus over $T\rtimes K$. 
We conclude by \ref{item:alternative4}
that $\coh(K,N)$ is Noetherian over $\coh(K,T)$ or, equivalently, 
that 
$E_2(M)=\coh(\RHom_K(\ku,\coh(M))$
 is Noetherian over $E_2(S)=\coh(\RHom_K(\ku,\coh(S))$. 

We claim that $E_2(S)\cong E_\infty(S)$. This follows from assumption \ref{item:alternative5}(c) 
that there is a homotopical isomorphism  between $S$ and $\coh(S)$, which induces an isomorphism of cohomology rings 
\[
E_2(S)=\coh(\RHom_K(\ku, \coh(S))
\ \cong \
\coh(\RHom_K(\ku, S))
=E_\infty(S).
\]



It remains to show $E_\infty(M)$ is Noetherian over $E_\infty(S)$, which follows from a classical argument of Friedlander and Suslin 
\cite{friedlander-suslin}*{Lemma 1.6}.
Indeed, since the spectral sequence $E_2(M)\implies E_\infty(M)$ is compatible with the action of the cohomology ring $E_2(S)\cong E_\infty(S)$, we have submodules over
$E_2(S)$
\[
B_2(M)\subseteq B_3(M)\subseteq \cdots \subseteq B_\infty(M)\subset Z_\infty(M)\subseteq \cdots \subseteq Z_3(M)\subseteq Z_2(M) 
\]
with $E_i(M)\cong Z_i(M)/B_i(M)$ for $i\ge 2$. 
We take quotients by $B_2(M)$.
As
$Z_{\infty}(M)/B_2(M)$
is a submodule of the
Noetherian $E_2(S)$-module $Z_2(M)/B_2(M)=E_2(M)$,
it is also
Noetherian,
and hence its quotient
$$
(Z_{\infty}(M)/B_2(M))
\ / \ 
(B_{\infty}(M)/B_2(M))
\ \cong\ 
Z_{\infty}(M)/B_{\infty}(M)
= E_{\infty}(M)
$$
is Noetherian as well.
\end{proof}

