\subsection{Deformation sequences of Hopf algebras} \label{subsec:deformations-hopf-alg} 
We combine the notions of deformation sequence and exact sequence of Hopf algebras in the following concept. 

\begin{definition}
\label{def:dfor-seq-hopf}
A \emph{deformation sequence of Hopf algebras} is an exact sequence of Hopf algebras (cf.~Definition \ref{ExactSequenceDef})
\begin{align*}
W \overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow} K\end{align*}
which is also a deformation sequence with respect to the counit $\epsilon_W$ of $W$ (cf.~Definition \ref{def:defor-seq}). In this case, we say the Hopf algebra $K$
{\em admits a deformation 
sequence of Hopf algebras}.
\end{definition}

\vspace{1ex}

\begin{remark}
Note that a deformation sequence of Hopf algebras
is a pair of  Hopf algebra maps 
$W\overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow} K$
satisfying 
\begin{itemize}
\item[\ref{item:suc-exacta-1}\ ] 
$\jmath$ is injective, and we identify $W$ with $\jmath(W)$,
\item[\ref{item:suc-exacta-2}\ ]
$\wp$ is surjective,
\item[\ref{item:suc-exacta-3}\ ] 
$\ker \wp = H\, W^+$
for $W^+=\ker \epsilon_W$,
\item[\ref{item:deformation-flat}'] 
$H$ is finitely generated as a left
$W$-module, 
\item[\ref{item:deformation-Z}\ ]
$W$ is smooth, finitely generated, and central in $H$, and
\item[\ref{item:finite-global-dim}\ ] 
$H$ has finite global dimension.
\end{itemize}
We argue that these six conditions are indeed sufficient
to imply those of Definitions~\ref{ExactSequenceDef}
and~\ref{def:defor-seq}.
Conditions \ref{item:deformation-flat}',
\ref{item:deformation-Z},
and
\ref{item:finite-global-dim}
imply that
$H$ is a finitely generated, right Noetherian PI Hopf algebra
by Remark \ref{rem:Noetherian}
and thus
faithfully flat over 
as a left module
over any Hopf subalgebra by \cite{skryabin-flatness-PI}*{Corollary 4.6},
giving condition \ref{item:deformation-flat}
of
Definition \ref{def:defor-seq}.
Condition
\ref{item:suc-exacta-4} 
of Definition~\ref{ExactSequenceDef}
 holds by Remark
\ref{rem:extension-fflat} 
and condition \ref{item:augmented-sequence} of
Definition~\ref{def:defor-seq}
holds as $\jmath$ and $\wp$ are Hopf algebra maps.
\end{remark}


\begin{remark}
When $\car \ku = 0$, a commutative Hopf algebra  is  smooth whenever it is finitely generated, 
see \cite{milneiAG}*{Theorem 3.38}.
\end{remark}

\begin{remark}\label{rem:antipode}
Let $W \hookrightarrow H \twoheadrightarrow K$ be a 
deformation sequence of Hopf algebras. It is well-known that the antipodes
of $W$ and $K$ are bijective, since $W$ is commutative and $K$ is finite-dimensional (cf. Remark~\ref{LastTermFiniteDimensional}). 
The antipode of $H$ is bijective as well
by \cite{skryabin-newresults}*{Corollary 2}
since $H$ is a Noetherian, PI, finitely generated algebra (see Remark \ref{rem:Noetherian}).
\end{remark}



\begin{remark}
The definition of 
{\em integrable Hopf algebra} in
\cite{negron-pevtsova} requires that $W$ is a coideal subalgebra;
here we assume  that $W$ is a Hopf subalgebra
in view of our applications below. 
\end{remark}

We conclude immediately from Theorem \ref{thm:negron-pevtsova}:

\begin{cor}\label{cor:Kfgc} \cite{negron-pevtsova}
A finite-dimensional  Hopf algebra 
admitting a deformation
sequence of Hopf algebras 
has  fgc. 
\end{cor}


\vspace{1ex}


Deformation sequences of Hopf algebras form a category: a {\em morphism}
$\mathbf{\Psi}: \Cgot \to \Cgot'$
from
\[\Cgot: W \overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow}K \quad\text{ to }\quad \Cgot': W' \overset{\jmath'}{\hookrightarrow} H' \overset{\wp'}{\twoheadrightarrow}K'\]
is a morphism of Hopf algebras $\Psi: H \to H'$ such that $\Psi(W)  \subseteq W'$,
thus inducing a commutative diagram
\begin{align*}
\xymatrix@R-5pt@C-5pt{W\ar  @{->}[r]^{\jmath } \ar@{->}[d]
& H \ar  @{->}[r]^{\wp } \ar@{->}[d]^{\Psi } &  K\ar@{->}[d]
\\
W'\ar  @{->}[r]^{\jmath' } & H' \ar  @{->}[r]^{\wp' }&  K'.}
\end{align*}

It would be interesting to understand the subcategory of those deformation sequences of Hopf algebras with fixed $K$, where the induced map from $K$ to $K$ is the identity.

\vspace{1ex}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Smash product of deformation sequences}\label{subsec:smash-defor-seq}
We explore the fgc for smash products by
formalizing an idea of deformation sequences
equivariant with respect to a
deformation sequence of Hopf algebras.


\begin{definition} 
\label{def:smash-product-def-seq}
Let $K$ be a Hopf algebra admitting
a deformation sequence of
Hopf algebras 
$\Cgot: W \overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow} K$.
A deformation sequence of algebras 
\[\Mgot\colon Z \overset{\iota}{\hookrightarrow} Q \overset{\pi}{\twoheadrightarrow} R\]
is \emph{$\Cgot$-equivariant}
if
\medbreak
\begin{enumerate}[leftmargin=7ex,label=\rm{(\alph*)}] \setcounter{enumi}{9}
\item\label{item:equivariant-Hmod}  
$Z$, $Q$ and $R$ are augmented 
$H$-module algebras
and
$\iota$ and $\pi$ are morphisms
of augmented $H$-module algebras,

\medbreak
\item
\label{item:equivariant-W-trivial} 
$W$ acts  trivially on $Q$, and

\medbreak
\item\label{item:equivariant-Z-stable} $H$ acts trivially on $Z$.
\end{enumerate}
In this case, 
we say $R$
admits a \textit{$\Cgot$-equivariant
deformation sequence}.
\end{definition}

\vspace{1ex}

The axioms in the above definition 
allow us to define a deformation sequence
for smash products in the next result.
Note that conditions \ref{item:equivariant-W-trivial} and \ref{item:equivariant-Z-stable}
imply
that $Z\ot W$ under component-wise multiplication
is a subalgebra of $Q\rtimes H$.


\begin{prop}\label{lema:equivariant}
Let $\Cgot: W \overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow} K$ be a deformation sequence of Hopf algebras and let $\Mgot: Z \overset{\iota}{\hookrightarrow} Q \overset{\pi}{\twoheadrightarrow} R$ be 
a $\Cgot$-equivariant deformation sequence. Then  

\begin{enumerate}[leftmargin=7ex,label=\rm{(\roman*)}]  
\item\label{item:equivariant-1}  $R$ is a $K$-module algebra and 
$\pi(h \cdot q) = \wp(h) \cdot \pi(q)$,  for all $h \in H$, $q \in Q$.

\medbreak
\item\label{item:equivariant-2} We have a  deformation sequence
\begin{equation} \label{eq:equiv-def-seq}
Z \otimes W \overset{\iota \rtimes \jmath}{\hookrightarrow} 
 Q \rtimes H \overset{\pi \rtimes \wp}{\twoheadrightarrow}  R \rtimes K.
\end{equation}
\end{enumerate}
\end{prop}

\begin{proof} 
For \ref{item:equivariant-1}: Let $\rho: H \to \End R$ be the associated representation. We have to check that $\rho(W^+) = 0$; then $\rho$ factors through $K$.

Choose $w \in W^+$ and $r \in R$; then $r = \pi(q)$ for some $q\in Q$
and
\begin{align*}
w\cdot r &= w\cdot \pi(q) = \pi(w\cdot q) = 0 
\end{align*}
since by condition~\ref{item:equivariant-W-trivial}
of Definition~\ref{def:smash-product-def-seq}, $w\cdot q = \epsilon(w) q = 0$.

\medbreak
For \ref{item:equivariant-2}: 
We check the conditions (a) through (h) of
Definition \ref{def:defor-seq}.
By \ref{item:equivariant-W-trivial}, $Z$ is a $W$-module subalgebra 
of $Q$, cf. Example \ref{exa:trivial-action}; hence
$\iota(w \cdot z) = \jmath(w) \cdot \iota(z)$,  for all $w \in W$, $z \in Z$.
Because of this and \ref{item:equivariant-1},  Lemma \ref{lema:smash}
implies that we have the algebra maps  $\iota \rtimes \jmath$ and $\pi \rtimes \wp$. 
We verify that they satisfy the conditions in Definition \ref{def:defor-seq}.
Evidently, \ref{item:suc-exacta-1} and \ref{item:suc-exacta-2} hold.
Next we check \ref{item:ker-pi-Z}:
\begin{align*}
\ker  (\pi \rtimes \wp)  &= \ker  \pi \otimes H + Q \otimes \ker  \wp = 
QZ^+ \otimes H + Q \otimes HW^+ 
\\
&= (Q \rtimes H) (Z^+ \otimes W + Z \otimes W^+) = (Q \rtimes H)(Z \rtimes W)^+. 
\end{align*}
Next, if $z\in Z$, $w\in W$, $q\in Q$ and $h \in H$, then
\begin{align*}
(z\otimes w) (q \otimes h)  &= z w\_{1} \cdot q \otimes w\_{2}h = zq \otimes wh,
\\
(q \otimes h)(z\otimes w)  &= q h\_{1} \cdot z \otimes h\_{2}w = qz \otimes hw,
\end{align*}
by \ref{item:equivariant-W-trivial} and \ref{item:equivariant-Z-stable}. 
Hence $z\otimes w$ is central in $Q \rtimes H$
and $Z \rtimes W = Z \otimes W$ is smooth and finitely generated, being the tensor product of two smooth and finitely generated algebras, 
thus \ref{item:deformation-Z} holds. 
Note that $Q \rtimes H$ is finite over $Z \otimes W$.

We argue that $Q \rtimes H$ is flat
over its subalgebra $Z \otimes W$
by viewing $Q\rtimes H$
as a twisted tensor product
algebra $Q\ott H$
(see \cite{CapSchichlVanzura})
with twisting map
$\tau: H\ot Q\rightarrow Q\ot H$
given by
$h\ot q\mapsto 
h\_{1}q \otimes h\_{2}$.
By Remark \ref{rem:antipode},
the antipode of $H$ is bijective
so $\tau$ is an invertible map
(e.g., see \cite{SheplerWitherspoon-TTP-AWEZ}*{Section 10}).
Corollary \ref{FlatTTPs}
with conditions \ref{item:equivariant-W-trivial} and \ref{item:equivariant-Z-stable}
implies that 
$Q \rtimes H=Q\ott H$ is flat
over $Z \otimes W=Z\rtimes W =Z\ott W$ and \ref{item:deformation-flat} holds.

Finally, by Definitions \ref{def:defor-seq} and \ref{def:dfor-seq-hopf}, 
$H$ and $Q$ have finite global dimension. 
By the main result of  \cite{LorenzLorenz}, $Q \rtimes H$ also has
finite global dimension, i.e., condition \ref{item:finite-global-dim} of Definition~\ref{def:defor-seq} holds. 
This proves that \eqref{eq:equiv-def-seq} is a deformation sequence.
\end{proof}

\vspace{1ex}

We obtain the third main result of the paper.

\begin{theorem}\label{thm:fgc-smash}
Let $K$ be a finite-dimensional Hopf algebra.
If $K$ admits a deformation sequence
$\Cgot$ of Hopf algebras
and $R$ is a finite-dimensional
algebra admiting
a $\Cgot$-equivariant deformation sequence, 
then the smash product $R \rtimes K$ has fgc.
\end{theorem}


\begin{proof} This follows from Proposition \ref{lema:equivariant} and Theorem \ref{thm:negron-pevtsova}.
\end{proof}

We immediately conclude:

\begin{cor}\label{cor:fgc-boson}
Let $K$ be a finite-dimensional Hopf algebra and $R$ a  Hopf algebra in $\yd{K}$, also finite-dimensional.
If $K$ admits a deformation sequence
$\Cgot$ of Hopf algebras
and $R$ admits
a $\Cgot$-equivariant deformation sequence, 
 then the bosonization $R \# K$ has fgc. \qed
\end{cor}





%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Applications to Nichols algebras}
\label{sec:examples}
\medbreak

The applications we present of our main results are based on the notion of the Nichols algebra of a braided vector space. We briefly recall the main features here and refer to \cite{andrus-leyva}, \cite{andrus-angiono} or \cite{andrus-schneider} for more 
details.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Deformation sequences of Nichols algebras}\label{subsec:nichols-examples}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
 Let $(V,c)$ be a braided vector space, that is, $V$ is a vector space and the map
$c \in \text{GL}(V \otimes V)$, called the {\em braiding}, satisfies the braid equation
\[ (c \otimes \id) (\id \otimes c)(c \otimes \id) =
(\id \otimes c)(c \otimes \id) (\id \otimes c).
\]
Then the tensor algebra $T(V)$ is a braided Hopf algebra in the sense of \cite{takeuchi-braided}. The 
{\em Nichols algebra} $\toba(V) \coloneqq T(V) / \Jc(V)$ is the quotient of
$T(V)$ by a graded Hopf ideal $\Jc(V)$,  determined by the property
\begin{align*}
\Pc (\toba(V)) &= V,
\end{align*}
where $\Pc(\toba(V))$ stands for the  space of   primitive elements. 
Thus $\toba(V)$ is a braided Hopf algebra in the sense of \cite{takeuchi-braided}.
Furthermore, if $\Bc = \bigoplus_{n \geq 0} \Bc^n$
is a graded braided Hopf algebra generated by $\Bc^1$ and $\Bc^1 \cong V$ as braided vector spaces, then there are morphisms of graded braided Hopf algebras
\[T(V) \twoheadrightarrow \Bc \twoheadrightarrow \toba(V)\]
which are the identity in degree one. A braided Hopf algebra like $\Bc$ above is called
a \emph{pre-Nichols algebra}.

\medbreak
Natural examples of braided vector spaces are the Yetter-Drinfeld modules 
over a Hopf algebra $H$ and, in turn, natural examples of braided Hopf algebras 
are the  Hopf algebras in $\yd{H}$. However a given braided vector space 
may arise in many ways as a Yetter-Drinfeld module 
over $H$ for many Hopf algebras  $H$, and similarly for braided Hopf algebras.
Precisely, we introduce the following terminology for further use:

\begin{itemize}[leftmargin=7ex]\renewcommand{\labelitemi}{$\circ$}
\item A \emph{realization} of a braided vector space $V$ over a Hopf algebra $H$
consists of an action and a coaction  of $H$ on $V$ 
such that $V$ becomes an object in $\yd{H}$ and 
the braiding of $V$ in $\yd{H}$ coincides with the original one.
If such a realization exists, then we say that $V$ \emph{can be realized} over $H$.

\medbreak
\item A \emph{realization} of a braided Hopf algebra $R$ over a Hopf algebra $H$
consists of an action and a coaction  of $H$ on $R$ 
such that $R$ becomes a Hopf algebra in $\yd{H}$ with the same multiplication,
comultiplication and  braiding  in $\yd{H}$ as  the original ones.
If such a realization exists, then we say that $R$ \emph{can be realized} over $H$.
\end{itemize}



\begin{remark} 
A realization of a braided vector space $V$  over $H$ induces realizations over $H$ of 
the Hopf algebras $T(V)$ and $\toba(V)$, but not necessarily of an arbitrary 
pre-Nichols algebra  $\Bc$ of $V$.
\end{remark}


\medbreak
We will analyze examples according to the following considerations. 

\begin{prop}\label{prop:toba-fgc}
Let $V$ be a braided vector space that can be realized over a finite-dimensional Hopf algebra $K$. 
Assume that the Nichols algebra $\toba(V)$ is finite-dimensional and has fgc. 
Then $\toba(V) \# K$ has fgc, provided that

\begin{enumerate}[leftmargin=7ex,label=\rm{(\roman*)}]

\medbreak
\item $K = \Bbbk G$, where $G$ is a finite group and $\operatorname{char} \Bbbk$ does not divide $\vert G\vert$; or

\medbreak
\item $K = \Bbbk^G$, where $G$ is a finite group.
\end{enumerate}  
\end{prop}  

\pf
By Theorem \ref{th:RtoRsmashH}.
\epf



\begin{prop}\label{prop:def-seq}
Let $V$ be a braided vector space that can be realized over a finite-dimensional Hopf algebra $K$. 
Assume that the Nichols algebra $\toba(V)$ is finite-dimensional and  
that it  admits a deformation sequence 
\[\Bg\colon Z \overset{\iota}{\hookrightarrow} \Bc \overset{\pi}{\twoheadrightarrow} \toba(V)\]
where $\Bc$ is a pre-Nichols algebra of $V$. Then $\toba(V) \# K$ has fgc, provided that

\begin{enumerate}[leftmargin=7ex,label=\rm{(\roman*)}]

\item $K$ is semisimple; or

\medbreak
\item $K$ is cocommutative and $\Bg$ is $K$-equivariant; or  

\medbreak
\item\label{item:def-seq-C-equivariant} $K$ admits a deformation sequence of Hopf algebras
$\Cgot\colon W\overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow} K$
such that $\Bg$ is  $\Cgot$-equivariant.  
\end{enumerate}
\end{prop}

\pf
By Theorems \ref{thm:K-semisimple-R-fgc},  \ref{theorem:negron} and \ref{thm:fgc-smash}.
\epf


\medbreak
There are several reasons to consider
this framework. First, Nichols algebras carry vital information
on the structure of pointed Hopf algebras, see \cite{andrus-schneider}.
Second, pre-Nichols algebras fitting in a deformation sequence as above appeared naturally
in the literature. Third, examples of Nichols algebras $\toba(V)$ such that 
$\toba(V) \# \ku \varGamma$ has fgc for a suitable finite abelian group $\varGamma$ 
have been studied in \cites{aapw,andruskiewitsch-natale};
but the methods in loc.~cit. do not allow us to conclude that 
$\toba(V) \# K$ has fgc for other Hopf algebras $K$.
We contribute to this problem here.

\vspace{1ex}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The quantum line}\label{subsec:equivariant-quantum line} 
In this subsection and the next we discuss the simplest examples of Nichols algebras
as an illustration of the considerations above.

\medbreak
Let $q$ lie in  $\kut$ and let $V$ be a vector space with $\dim V = 1$
and basis $\{v\}$.
Consider
the braided vector space 
$V_q \coloneqq (V, c)$ 
with braiding 
$c \in \text{GL}(V \otimes V)$ given by $c(v \otimes v) = q \, v \otimes v$. 
It is well-known, see e.g.\ \cite{andrus-schneider}, that 
the  Nichols algebra $\toba(V_q)$ has finite dimension if and only if 
\begin{align}\label{eq:q-hyp}
q \text{ is a root of 1}, &\text{ and } q \neq 1 \text{ when } \car \ku = 0.
\end{align} 
Assume in the rest of this subsection that $q$ is as in \eqref{eq:q-hyp}. 
Let $n \in \N$ be given by
\begin{align*}
n &= \begin{cases} p &\text{if } \car \ku = p >0 \text{ and } q =1;
\\ \ord q &\text{otherwise; notice that }(p, n) = 1 \text{ if } \car \ku = p >0.
\end{cases}
\end{align*}
Then the Nichols algebra $\toba (V_q) $ is isomorphic to $\ku[X]/\langle X^n \rangle$,
where $\ku[X]$ is the polynomial ring. Calling $\iota$ for the inclusion and $\pi$ for the natural projection, we claim that
\begin{equation}\label{eq:deformation-sequence-qline}
\Mgot_q\colon \ku[X^n]\overset{\iota}{\hookrightarrow} \ku[X] \overset{\pi}{\twoheadrightarrow} \ku[X]/\langle X^n \rangle \cong \toba (V_q),   
\end{equation}
is a deformation sequence, as the seven conditions of Definition~\ref{def:defor-seq} clearly hold.

\bigbreak
Realizations of 
$V_q$ in $\yd{K}$ are described by YD-pairs, a notion already 
implicit  in \cite{andrus-schneider-p3}.

\begin{definition} \cite{andrus-leyva}*{Example 20} 
Let $K$ be a Hopf algebra with antipode $\mathcal S$. A \emph{YD-pair} for $K$ is a pair
$(g, \chi)  \in G(K) \times \hom_{\text{alg}}(K, \Bbbk)$
such that
\begin{align*}
\chi(h)\,g  &= \chi(h_{(2)}) \, h_{(1)}\, g\, \mathcal S(h_{(3)}),& \text{for any } h \in K.
\end{align*}
If $(g, \chi)$ is a YD-pair for $K$, then $g\in Z(G(K))$, the center of the group $G(K)$ of group-like elements in $K$. 
\end{definition}

\medbreak
YD-pairs classify one-dimensional objects in $\yd{K}$: 
if $(g, \chi)$ is a YD-pair, then $\Bbbk_g^{\chi} = \Bbbk$
with action and coaction given by $\chi $ and $g$ respectively, is in $\yd{K}$;
the braiding of $\Bbbk_g^{\chi}$ is multiplication by $\chi(g)$.
Hence, $\Bbbk_g^{\chi}$ realizes $V_q$ if and only if $\chi(g) = q$.

\medbreak
The following fact 
was known under the hypothesis that $K$ is either a group algebra (of dimension prime to the characteristic of the base field) or a dual group algebra as in Proposition \ref{prop:toba-fgc};
otherwise it appears to be new.


\begin{prop}\label{exa:qline-bosonK}
Let $K$ be a finite-dimensional Hopf algebra that admits a YD-pair $(g, \chi)$  such that $\chi(g) = q$, so that
$\Bbbk_g^{\chi}$ realizes $V_q$ in $\yd{K}$. If $K$ is either semisimple or
cocommutative, then $\toba(V_q) \# K$ has fgc.
\end{prop}

\pf Proposition \ref{prop:def-seq} applies, 
since $\Bbbk [X]$ and $\Bbbk [X^n]$ become Hopf algebras in $\yd{K}$ and the deformation sequence $\Mgot_q$ in \eqref{eq:deformation-sequence-qline} is $K$-equivariant. 
\epf

When $K$ is neither semisimple nor cocommutative, we still can apply 
Proposition \ref{prop:def-seq} \ref{item:def-seq-C-equivariant}, i.e., Theorem \ref{thm:fgc-smash}.


\begin{prop}\label{exa:qline-bosonK2}
Let $K$ be a finite-dimensional Hopf algebra having a YD-pair $(g, \chi)$  
such that $\chi(g) = q$, so that $\Bbbk_g^{\chi}$ realizes $V_q$ in $\yd{K}$, and $\chi^n = \varepsilon$. 
Assume that 
\begin{itemize}[leftmargin=7ex]\renewcommand{\labelitemi}{$\circ$}
\item $K$ admits a deformation sequence of Hopf algebras $\Cgot: W \overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow} K$,

\item there exists $\gamma \in G(H)$ such that $\wp(\gamma) = g$ and 
$(\gamma, \chi\wp)$ is a YD-pair for $H$, and 


\item $\chi \wp_{\vert W} = \varepsilon$.
\end{itemize}
Then $\toba(V_q) \# K$ has fgc.
\end{prop}


\begin{proof} We claim that the deformation sequence $\Mgot_q$ in \eqref{eq:deformation-sequence-qline} is $\Cgot$-equivariant as in Definition 
\ref{def:smash-product-def-seq}. The YD-pair $(\gamma, \chi\wp)$  
induces a realizations of $\toba(V_q)$, $\ku[X]$ and $\ku[X^n]$ as Hopf algebras in $\yd{H}$;
hence \ref{item:equivariant-Hmod} holds.
Now $H$ acts  on $X^n$ by $(\chi\wp)^n = \chi^n\wp$, so if $\chi^n= \varepsilon$, then 
\ref{item:equivariant-Z-stable} holds. The last assumption gives
\ref{item:equivariant-W-trivial}. The claim is proved, and therefore $\toba(V_q) \# K$ has fgc by
Theorem \ref{thm:fgc-smash}.
\end{proof}


\vspace{1ex}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Quantum linear spaces}\label{subsec:equivariant-qls} 
Assume $\car \ku = p$. For $\theta\in \N$, we set $\I_{\theta} \coloneq \{1,2,\dots, \theta\}$. 
Fix a matrix $\bq = \left(q_{ij}\right)_{i, j \in \I_{\theta}}$ whose entries are roots of 1.  
Assume that
\begin{align*}
q_{ii} &\neq 1 & \text{ if } p &= 0,
\\
q_{ij}q_{ji} & = 1 &\text{ if }  i &\neq j \in \I_{\theta}.
\end{align*}
For $i \in \I_{\theta}$, set 
\begin{align}\label{eq:N_i}
N_{i} &= \begin{cases} p  &\text{if }  p >0 \text{ and } q_{ii} =1;
\\ \ord q_{ii} &\text{otherwise; so }(p, N_i) = 1 \text{ if }  p >0.
\end{cases}
\end{align}

Let $V$ be  a vector space of dimension $\theta$ with a fixed basis $v_1, \dots, v_{\theta}$.
Let $V_{\bq} \coloneqq (V, c)$ be  the braided vector space 
whose braiding  $c \in \text{GL}(V \otimes V)$ is given  by 
\begin{align}\label{eq:braiding-diagonal}
c(v_i \otimes v_j) &= q_{ij} v_j \otimes v_i & \text{for any } i,j \in \I_{\theta}.
\end{align}

\begin{lemma} The Nichols algebra $\toba(V_{\bq})$ has a presentation 
\begin{align*}
\toba(V_{\bq}) \cong \ku\langle X_1, \dots, X_{\theta} &\ \vert\   
X_{i}X_{j} -q_{ij}X_{j}X_{i}, \,  i \neq j \in \I_{\theta}; \ \ 
X_{i}^{N_i}, \, i\in \I_{\theta}  \rangle.
\end{align*} 
Therefore, the ordered monomials 
\begin{align*}
X_1^{h_1} \dots X_{\theta}^{h_{\theta}} :  \quad 
0 \leq h_i \leq N_i -1, \quad
i\in \I_{\theta},
\end{align*} 
form a basis for $\toba(V_{\bq})$ and in particular
$\dim \toba(V_{\bq}) = N_1 \dots N_{\theta}$.
\end{lemma}

As 
in \cite{andrus-schneider-p3}, we refer to $\toba(V_{\bq})$ as a quantum linear space.

\pf
This was proved in \cite{andrus-schneider-p3} for  
$p=0$ and is straightforward to establish for $p >0$.
\epf


Let $\ku_{\bq}[X_1, \dots, X_{\theta}]$ be the quotient of the free algebra $\ku\langle X_1, \dots, X_{\theta} \rangle$ by the ideal generated by $X_{i}X_{j} -q_{ij}X_{j}X_{i}$ for all $i \neq j \in \I_{\theta}$. By abuse of notation,
we denote by the same symbol the image of $X_i$ in $\ku_{\bq}[X_1, \dots, X_{\theta}]$. 
We have in $\ku_{\bq}[X_1, \dots, X_{\theta}]$ the equality
\begin{align}\label{eq:qls-powers}
X_i^{m} X_j &= q_{ij}^mX_{j}X_{i}^m, & 
i \neq j &\in \I_{\theta}, \quad m \in \N.
\end{align}
For $i\in \I_{\theta}$, we set
\begin{align*}
M_i &\coloneqq \lcm \big\{\ord q_{ij},  j \in \I_{\theta} \backslash \{i\}\big\}.
\end{align*}
Then $X_i^{M_i }$ is central in $\ku_{\bq}[X_1, \dots, X_{\theta}]$ by \eqref{eq:qls-powers}.
Recall \eqref{eq:N_i} and assume that 
\begin{align}\label{eq:qls-condition}
&M_i  \text{ divides }   N_i, && \text{for all } i \in \I_{\theta}. 
\end{align}
Then the subalgebra $Z_{\bq} = \ku\langle X_1^{N_1}, \dots, X_{\theta}^{N_{\theta}}\rangle$ of 
$\ku_{\bq}[X_1, \dots, X_{\theta}]$ is central by \eqref{eq:qls-powers}.
Hence 
\begin{equation}\label{eq:deformation-sequence-qls}
  \Mgot_{\bq} :  Z_{\bq}\hookrightarrow \ku_{\bq}[X_1, \dots, X_{\theta}] \twoheadrightarrow \toba(V_{\bq}) \cong \ku_{\bq}[X_1, \dots, X_{\theta}]/\langle X_1^{N_1}, 
\dots, X_{\theta}^{N_{\theta}} \rangle
\end{equation}
  is a deformation sequence; we recover, by Theorem \ref{thm:negron-pevtsova}, 
the well-known fact that the
quantum linear space $\toba(V_{\bq})$ has fgc, under the assumption \eqref{eq:qls-condition}. 

\medbreak
\begin{prop}\label{exa:qls-bosonK} Assume that the matrix $\bq$ satisfies
\eqref{eq:qls-condition}.
Let $K$ be a finite-dimensional Hopf algebra that admits a family
of YD-pairs  $\left(g_i, \chi_i\right)_{i \in \I_{\theta}}$ such that 
\begin{align}
 \label{eq:qls-realizationK}
\chi_j(g_i) &= q_{ij},& \text{for all }  i,j &\in \I_{\theta},
\end{align}
so that the family $\left(g_i, \chi_i\right)_{i \in \I_{\theta}}$ gives a 
realization of $V_{\bq}$ in $\yd{K}$. If $K$ is either semisimple or
cocommutative, then $\toba(V_{\bq}) \# K$ has fgc.
\end{prop}

This was known for $K$ a group algebra or a dual group algebra as in Proposition \ref{prop:toba-fgc}.

\begin{proof}
The family  $\left(g_i, \chi_i\right)_{i \in \I_{\theta}}$  induces a realization  of 
the tensor algebra $T(V_{\bq})$ as a Hopf algebra in $\yd{K}$; since the ideal generated by $X_{i}X_{j} -q_{ij}X_{j}X_{i}$ for all $i \neq j \in \I_{\theta}$ is  a subobject in $\yd{K}$, we see that
$\ku_{\bq}[X_1, \dots, X_{\theta}]$ is realized as a Hopf algebra in $\yd{K}$. 
Also $Z_{\bq} = \ku\langle X_1^{N_1}, \dots, X_{\theta}^{N_{\theta}}\rangle$ is a 
central Hopf subalgebra of $\ku_{\bq}[X_1, \dots, X_{\theta}]$ in $\yd{K}$;
i.e., $\Mgot_{\bq}$ is $K$-equivariant.
We can then apply Proposition \ref{prop:def-seq}.
\end{proof}

When $K$ is neither semisimple nor cocommutative, we still can apply 
Proposition \ref{prop:def-seq} \ref{item:def-seq-C-equivariant}, i.e., Theorem \ref{thm:fgc-smash}.

\begin{prop}\label{exa:qls-bosonK2}
Assume that the matrix $\bq$ satisfies \eqref{eq:qls-condition}.
Let $K$ be a finite-dimensional Hopf algebra that admits a family
of YD-pairs  $\left(g_i, \chi_i\right)_{i \in \I_{\theta}}$ such that 
\eqref{eq:qls-realizationK} holds and 
\begin{align}\label{eq:qls-bosonK-condition}
\chi_i^{N_i} &= \varepsilon,& \text{for all }  i &\in \I_{\theta}.
\end{align}
Assume that $K$ admits a deformation sequence of Hopf algebras $\Cgot: W \overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow} K$ such that 
\begin{itemize}[leftmargin=7ex]\renewcommand{\labelitemi}{$\circ$}
\item  there exists $\gamma_{i} \in G(H)$ such that $\wp(\gamma_{i}) = g_{i}$ and 
$\left(\gamma_{i}, \chi_{i}\wp\right)$ is a YD-pair for $H$, for all $i\in \I_{\theta}$, and 

\item $\chi_i \wp_{\vert W} = \varepsilon$ for all $i\in \I_{\theta}$.
\end{itemize}
Then $\toba(V_{\bq}) \# K$ has fgc.
\end{prop}


\begin{proof} As in the proof of Proposition \ref{exa:qls-bosonK}, the family $\left(g_i, \chi_i\right)_{i \in \I_{\theta}}$ gives a 
realization of $V_{\bq}$ in $\yd{K}$. As argued above, 
$\Mgot_{\bq}$ in \eqref{eq:deformation-sequence-qls} is a deformation sequence because of 
\eqref{eq:qls-condition}.
We claim that $\Mgot_{\bq}$ is $\Cgot$-equivariant as in Definition 
\ref{def:smash-product-def-seq}. Since $\chi_{j}\wp (\gamma_i) = \chi_{j}(g_i) = q_{ij}$ for all 
$i, j\in \I_{\theta}$, 
the family $(\gamma_i, \chi_i\wp)$  of YD-pairs
induces  realizations of $\toba(V_{\bq})$, $\ku_{\bq}[X_1, \dots, X_{\theta}]$ 
and $Z_{\bq}$ as Hopf algebras in $\yd{H}$;
hence \ref{item:equivariant-Hmod} holds.


Now $H$ acts  on $X_{i}^{N_i}$ by $(\chi_i\wp)^{N_i} = \chi_i^{N_i}\wp$; then 
\ref{item:equivariant-Z-stable} holds by \eqref{eq:qls-bosonK-condition}. The last assumption gives
\ref{item:equivariant-W-trivial}. The claim is proved, hence $\toba(V_{\bq}) \# K$ has fgc by
Theorem \ref{thm:fgc-smash}.
\end{proof}


\vspace{1ex}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Nichols algebras of diagonal type}\label{subsec:equivariant-cartan type}
We discuss informally how the methods exposed here apply to finite-dimensional 
Nichols algebras of diagonal type. See, e.g., the surveys \cites{andrus-leyva,andrus-angiono}
for detailed expositions, unexplained terminology and more references.

\medbreak
 In this subsection, set $\car \ku = 0$. Let $\theta\in \N$ and 
fix a matrix $\bq = \left(q_{ij}\right)_{i, j \in \I_{\theta}}$ whose entries are roots of 1.
We assume that the associated Dynkin diagram is connected.
Let $V$ be  a $\ku$-vector space of dimension $\theta$ with a fixed basis $\{v_1, \dots, v_{\theta}\}$.
Let $V_{\bq} \coloneqq (V, c)$ be the braided vector space 
whose braiding  $c \in \text{GL}(V \otimes V)$ is given  by \eqref{eq:braiding-diagonal}.
We summarize the main features of the theory:

\medbreak
\begin{itemize}  [leftmargin=7ex]
\item The classification of the matrices $\bq$ such that $\dim \toba(V_{\bq}) < \infty$
was achieved in \cite{heckenberger}. 
In \cite{andrus-angiono} an organization of the classification into several types was proposed; these types are:
\end{itemize}

\begin{itemize} [leftmargin=12ex] \renewcommand{\labelitemi}{$\circ$}
\medbreak
\item  Cartan type, related to finite-dimensional simple Lie algebras in $\car 0$.

\medbreak
\item Super type, related to finite-dimensional simple contragredient  Lie superalgebras in $\car 0$. 

\medbreak
\item Modular type, related to finite-dimensional simple Lie algebras or superalgebras in $\car> 0$,
not in the previous classes. 

\medbreak
\item UFO type, 12 examples not known to be related to Lie theory (yet).
\end{itemize} 

\medbreak
\begin{itemize}  [leftmargin=7ex]
\item The defining relations of the finite-dimensional $\toba(V_{\bq})$ were described in
\cite{angiono-crelle}. Motivated by some arguments in the proof and by the theory of quantum groups
developed by De Concini and Procesi, a \emph{distinguished} pre-Nichols algebra 
$\widetilde{\toba}(V_{\bq})$ was introduced in \cite{angiono-transfgps}. Furthermore, 
$\widetilde{\toba}(V_{\bq})$ has a normal braided Hopf subalgebra $Z^+(V_{\bq})$, see 
 \cite{angiono-transfgps}*{Theorem 31}. 

 \medbreak
 \item  We follow now the exposition in \cite{aay}*{Subsection 4.5}. Assume that the condition
 \cite{aay}*{Condition (4.26)} holds; notice that this extends \eqref{eq:qls-bosonK-condition}. 
 Then $Z^+(V_{\bq})$ is central in $\widetilde{\toba}(V_{\bq})$ and we have an exact sequence 
 \begin{equation}
 \label{defdiagonal}
Z^+(V_{\bq}) \overset{\iota}{\hookrightarrow} \widetilde{\toba}(V_{\bq}) \overset{\pi}{\twoheadrightarrow} \toba(V_{\bq})
\end{equation}
of braided Hopf algebras, see \cite{andrus-natale-braided} for this notion.
Now, for \eqref{defdiagonal} to be a deformation sequence, 
we need $\widetilde{\toba}(V_{\bq})$ to have finite global dimension.
If $\bq$ is of Cartan type, then $\widetilde{\toba}(V_{\bq})$
has finite global dimension by standard arguments, and one can check that \eqref{defdiagonal} is a deformation sequence. Otherwise, one of the degree 1 generators of $\widetilde{\toba}(V_{\bq})$ is nilpotent, which prevents $\widetilde{\toba}(V_{\bq})$ from having finite global dimension.

\medbreak
\item If $Z \overset{\iota}{\hookrightarrow} \Bc \overset{\pi}{\twoheadrightarrow} \toba(V_{\bq})$
is a deformation sequence where $\Bc$ is a pre-Nichols algebra of $V_{\bq}$, then
$\GK \Bc < \infty$ by Remark \ref{rem:Noetherian}. Up to a short list of exceptions, it is known that $\Bc$ is a quotient of $\widetilde{\toba}(V_{\bq})$, see \cites{andrus-sanmarco,angiono-etal} 
and references therein.
Therefore, when $\bq$ is not of Cartan type, $\Bc$ has infinite global dimension by the same argument as above. In conclusion, it appears that $\toba(V_{\bq})$ has a deformation sequence
only when $\bq$ is of Cartan type, up to some mild conditions on $\bq$.


\medbreak
\item By a different technique, it was shown in \cite{aapw} that $\toba(V_{\bq})$ has fgc
when $\bq$ "belongs to a family",
which leaves open only 27 examples of modular or UFO type.
\end{itemize}

\medbreak
In conclusion, the methods of the present paper apply in Cartan type. 
See \cite{aay}*{Subsection 4.5} for details of the following arguments. 
We need to introduce some notation.
Fix a matrix $\bq$ of Cartan type, i.~e., there exists a finite Cartan matrix 
$\mathbf{a} = (a_{ij})_{i, j \in \I_{\theta}}$ such that $q_{ij}q_{ji} = q_{ii}^{a_{ij}}$ for all 
$i \neq j \in \I_{\theta}$. 
Let $\varDelta_+$ be the set of positive roots corresponding to $\mathbf{a}$
with subset of simple roots $\{\alpha_{i}: i \in \I_{\theta}\}$. 
For $\alpha = \sum_{i \in \I_{\theta}} a_i \alpha_i$, $\beta = \sum_{i \in \I_{\theta}} b_i \alpha_i \in \varDelta_+$, we set:
\[
q_{\alpha\beta} = \prod_{i, j \in \I_{\theta}} q_{ij}^{a_ib_j} \qquad \text{ and } \qquad 
N_{\beta} = \ord q_{\beta\beta}.
\]
As explained in \cite{aay}, there exists $X_{\beta} \in \widetilde{\toba}(V_{\bq})$ (called $e_{\beta}$
in \emph{loc. cit.}), defined using the Weyl group automorphisms and which is in fact an
iterated braided commutator.
Then
\begin{align*}
Z^+(V_{\bq}) &= \ku\langle X_{\beta}^{N_{\beta}}: \beta \in  \varDelta_+\rangle.
\end{align*}
For $Z^+(V_{\bq})$ to be central in $\widetilde{\toba}(V_{\bq})$ we need 
to assume, cf. \cite{aay}*{Condition (4.26)}:
\begin{align}\label{eq:cartan-centrality}
q_{\alpha\beta}^{N_{\beta}} &= 1, & \text{for all } \alpha, \beta \in  \varDelta_+.
\end{align}
\begin{prop}\label{exa:cartan-bosonK}
Let $\bq$ be a matrix of Cartan type
satisfying \eqref{eq:cartan-centrality}. 
Let $K$ be a finite-dimensional Hopf algebra that admits a family
of YD-pairs  $\left(g_i, \chi_i\right)_{i \in \I_{\theta}}$ such that 
\eqref{eq:qls-realizationK} holds, so that it gives a 
realization of $V_{\bq}$ in $\yd{K}$. 
Assume that either $K$ is semisimple; or $K$ is cocommutative and \eqref{defdiagonal} is $K$-equivariant.
Then $\toba(V_{\bq}) \# K$ has fgc.
\end{prop}

For the case when $K$ is a group algebra or a dual group algebra, see \cite{aapw}
and \cite{MPSW}.


\pf As discussed above, $\gldim \widetilde{\toba}(V_{\bq}) < \infty$ in this case, so \eqref{defdiagonal} is a deformation sequence and Proposition \ref{prop:def-seq} applies.
\epf

When $K$ is neither semisimple nor cocommutative, we  can apply 
Proposition \ref{prop:def-seq} \ref{item:def-seq-C-equivariant}.

\begin{prop}\label{exa:cartan-bosonK2}
Let $\bq$ be a matrix of Cartan type satisfying \eqref{eq:cartan-centrality}.
Let $K$ be a finite-dimensional Hopf algebra admitting a family of YD pairs $\left(g_i, \chi_i\right)_{i \in \I_{\theta}}$ such that
\eqref{eq:qls-realizationK} and
\begin{align}\label{eq:cartan-bosonK-condition}
\chi_{\beta}^{N_{\beta}} &= \varepsilon,& \text{for all }  \beta &\in \varDelta_+,
\end{align}
hold, where for any $\beta = \sum_{i \in \I_{\theta}} b_i \alpha_i  \in \varDelta_+$, we set
\begin{align*}
\chi_{\beta} &= \prod_{i \in \I_{\theta}} q_{ij}^{b_i}.
\end{align*}



Assume that $K$ has a deformation sequence of Hopf algebras $\Cgot: W \overset{\jmath}{\hookrightarrow} H \overset{\wp}{\twoheadrightarrow} K$ such that 
\begin{itemize}[leftmargin=7ex]\renewcommand{\labelitemi}{$\circ$}
\item  there exists $\gamma_{i} \in G(H)$ such that $\wp(\gamma_{i}) = g_{i}$ and 
$\left(\gamma_{i}, \chi_{i}\wp\right)$ is a YD-pair for $H$, for all $i\in \I_{\theta}$, and 

\item $\chi_i \wp_{\vert W} = \varepsilon$ for all $i\in \I_{\theta}$.
\end{itemize}
Then $\toba(V_{\bq}) \# K$ has fgc.
\end{prop}

\pf The proof is analogous to that of Proposition \ref{exa:qls-bosonK2}, noting that
$H$ acts  on $X_{\beta}^{N_{\beta}}$ by $(\chi_{\beta}\wp)^{N_{\beta}} = \chi_{\beta}^{N_{\beta}}\wp$; then 
\ref{item:equivariant-Z-stable} holds by \eqref{eq:cartan-bosonK-condition}.
\epf

