\subsection{The restricted Jordan plane}\label{subsec:jordan} 
In this subsection, assume $\car \ku = p$ is an odd prime. 
Let  $\Vc(1,2)$ be the 2-dimensional braided vector space
with a basis $\{x,y\}$ and the braiding determined by
\begin{align}\label{equation:basis-block}
\begin{aligned}
c(x \ot  x) &=  x \ot  x,&c(y \ot  x) &=  x \ot  y, \\
c(x \ot  y) &=(y+ x) \ot  x,& c(y \ot  y) &=(y+x) \ot  y.
\end{aligned}
\end{align}
It was shown in \cite{clw} that the Nichols algebra $\toba\left(\Vc(1,2) \right)$, 
also called \emph{the restricted Jordan plane}, is presented as 
\begin{align*}
\toba\left(\Vc(1,2) \right)  \cong \ku\langle x, y\ \vert\  yx-xy+\tfrac{1}{2}x^2,
\ x^p,  \ y^p  \rangle.
\end{align*}
The  \emph{Jordan plane} is the algebra $J =\ku\langle x, y\ \vert\  yx-xy+\tfrac{1}{2}x^2  \rangle$. 
From \cite{clw}*{Lemma 3.8}, 
\begin{align*}
x^ny &=yx^n +\tfrac{n}{2}x^{n+1},
\\
y^n x &= \sum_{k=0}^{n} \binom{n}{k} \frac{(-1)^k k!}{2^k} x^{k+1} y^{n -k}. 
\end{align*}
We conclude that $Z_J \coloneqq\ku \langle x^p, y^p\rangle$ is a central subalgebra of $J$.
Actually, $Z_J$ is a braided Hopf subalgebra  of $J$, cf. \cite{clw}*{Lemma 3.8} and we have a  deformation sequence
\begin{align*}
\Jgot : Z_{J} \hookrightarrow J
\twoheadrightarrow  \toba\left(\Vc(1,2) \right).
\end{align*}
We recover the fact that $\toba\left(\Vc(1,2) \right)$ has fgc \cite{NWW2019}. We turn to
realizations of the restricted Jordan plane 
that can be obtained as follows.


\begin{definition} \cite{andrus-leyva}*{Example 23}
Let $K$ be a Hopf algebra with antipode $\mathcal S$. 
 A \emph{YD-triple} for $K$ is a collection $(g, \chi, \eta)$ where
$(g, \chi)$ is a YD-pair for $K$ and $\eta \in \Der_{\chi,\chi}(K, \ku)$
such that
\begin{align}\label{eq:YD-triple}
&&\eta(h) g &= \eta(h\_2) h\_1 g \Ss(h\_3), & \text{for any } h \in K,
\\ \label{eq:YD-triple-jordan}
&&\chi(g) &= \eta(g) = 1.
\end{align}
\end{definition}



\medbreak
A YD-triple $(g, \chi, \eta)$ gives rise to $\Vc_g(\chi,\eta) \in \yd{K}$, defined as the $\ku$-vector space with a basis $\{x,y\}$, whose $K$-action and $K$-coaction are respectively given by
\begin{align*}
h\cdot x &= \chi(h) x,& h\cdot y&=\chi(h) y + \eta(h)x,&h&\in K;& 
\delta(x) &= g\otimes x,& \delta(y) &= g\otimes y.
\end{align*}
By assumption \eqref{eq:YD-triple-jordan}, 
$\Vc_g(\chi, \eta)\cong \Vc(1,2)$ as a braided vector space, where the braiding of $\Vc_g(\chi, \eta)$ in $\yd{K}$ coincides with that of $\Vc(1,2)$ given in \eqref{equation:basis-block}.

It was observed that a finite-dimensional Hopf algebra that admits a YD-triple $(g, \chi, \eta)$
is not semisimple \cite{andruskiewitsch-natale}*{Remark 4.8}.
For cocommutative Hopf algebras, 
Proposition \ref{prop:def-seq}
implies the following fact.

\begin{prop} \label{exa:jordan}
Let $K$ be a finite-dimensional cocommutative Hopf algebra that admits
a YD-triple $(g, \chi, \eta)$   for $K$. Then 
$\toba \left(\Vc_g(\chi, \eta)\right) \# K$ has fgc. \qed
\end{prop}



\begin{example} \cite{andruskiewitsch-natale}*{Remark 4.9}
Let $G$ be a finite group and let $(g, \chi, \eta)$ be a YD-triple for $\ku G$,
so that $g \in Z(G)$ and $\chi \in \Hom_{\rm gps} (G, \ku^{\times})$.
Then the Hopf algebra $H  = \toba(\Vc_g(\chi, \eta)) \# \ku G$ 
fits into the abelian exact sequence 
\begin{align}\label{eq:boso-jordan-gral}
\ku \to K \overset{\iota}{\rightarrow} H \overset{\pi}{\rightarrow} L \to \ku 
\end{align}
defined as follows:
\begin{itemize}[leftmargin=7ex]\renewcommand{\labelitemi}{$\circ$} 

\item $K \coloneqq  \ku \langle x, \gamma: \gamma \in N\rangle 
\simeq \ku\langle x \rangle\# \ku N$, where $N \coloneqq \ker \chi \cap Z(G)\lhd F$;
\item $L \coloneqq \toba(\zeta) \# \ku (G/N) \simeq \ku[\zeta]/ (\zeta^p) \# \ku (G/N)$,
where $\ku \zeta \in \yd{\ku (G/N)}$ is given by the YD-pair $(e, \overline{\chi})$
and $\zeta$ is primitive;
\item $\iota$ is the inclusion and  $\pi$ is 
given by $\pi(x) = 0$, $\pi(y) = \zeta$ and $\pi(\gamma) =$  $\gamma N$ in $G/N$.
\end{itemize}
Observe that \eqref{eq:boso-jordan-gral} is not necessarily split, e.g., when
the exact sequence of groups $1 \to N \rightarrow G \rightarrow G/N \to 1$ is not split.

When $G = \Z^p$, $H$ has fgc by \cite{NWW2019} or by \cite{andruskiewitsch-natale}, 
with different proofs. Proposition \ref{exa:jordan} implies that $H$ has fgc for any $G$.
This fact also confirms that 
\cite{andruskiewitsch-natale}*{Question 1.1}, namely that
an extension of finite-dimensional Hopf algebras has fgc whenever the kernel and the cokernel have fgc,
has a positive answer.
\end{example}  

