\begin{equation}
\Delta_i^{\text{def}} = x_i^{\text{def}} - x_i^{\text{baseline}}
\end{equation}
where $x_i^{\text{no-def}}$ and $x_i^{\text{def}}$ represent the agent's final state in scenarios with malicious agents (without and with defense, respectively), and $x_i^{\text{baseline}}$ is the state in the ideal baseline scenario (no malicious agents). The absolute values of these deviations, $|\Delta_i^{\text{no-def}}|$ and $|\Delta_i^{\text{def}}|$, provide a measure of how far each agent deviates from ideal behavior.

\subsubsection{Normal Agent Performance}
Since our primary concern is protecting normal agents from malicious influences, we focus particularly on the average deviation across all normal agents:
\begin{equation}
\bar{\Delta}_{\text{normal}}^{\text{no-def}} = \frac{1}{|\mathcal{A}_{\text{normal}}|}\sum_{i \in \mathcal{A}_{\text{normal}}}|\Delta_i^{\text{no-def}}|
\end{equation}
\begin{equation}
\bar{\Delta}_{\text{normal}}^{\text{def}} = \frac{1}{|\mathcal{A}_{\text{normal}}|}\sum_{i \in \mathcal{A}_{\text{normal}}}|\Delta_i^{\text{def}}|
\end{equation}
where $\mathcal{A}_{\text{normal}}$ represents the set of normal agents. Lower values indicate better defense performance.

\subsubsection{Defense Improvement Percentage}
To quantify the benefit of our defense mechanism, we calculate the percentage reduction in deviation by the defense:
\begin{equation}
\text{Improvement (\%)} = \frac{\bar{\Delta}_{\text{normal}}^{\text{no-def}} - \bar{\Delta}_{\text{normal}}^{\text{def}}}{\bar{\Delta}_{\text{normal}}^{\text{no-def}}} \times 100\%
\end{equation}
This metric provides an intuitive measure of defense effectiveness, with higher values indicating greater improvement.

