\section{Pseudolattices and Mutations}\label{sec:PseudolatticesAnd Mutations}

In this section we give explicit sequences of (numerical) mutations which map the exceptional bases obtained in \ref{sec:construct-vc} to those corresponding to the exceptional collections \cite[Equation 2.3]{AKO06}. This is the content of Theorem \ref{thm:MutationSequence}. We give an application to the representation theory of string junctions in Section \ref{sec:GHS}. 
We use the language of pseudolattices, which we briefly summarize below.

\subsection{Surface-like pseudolattices}
\label{sec:surfacelikePseudolatt-prelim}

For the main results of the theory of surface-like pseudolattices, we direct the reader to \cite{VdB_dTdV,Kuz17_pseudolattices,Vial17}.

\begin{definition}
    A pseudolattice is a finitely generated abelian group $\rG$ equipped with a non-degenerate bilinear form $\pairing_\rG \colon \rG \times \rG \to \Z$. We say that $(\rG,\pairing_\rG)$ is unimodular if $\pairing_\rG$ induces an isomorphism $\rG \to \Hom (\rG,\Z)$.
\end{definition}



\begin{definition}
    An automorphism $\rS_\rG\colon \rG \to \rG$ of a pseudolattice $(\rG,\pairing_\rG)$ is a Serre operator if it satisfies
    \[\pair{v_1,v_2}_\rG = \pair{v_2,\rS_\rG(v_1)}_\rG \qquad \mbox{ for all } v_1,v_2\in \rG\]
\end{definition}

If a Serre operator exists then it is unique by the non-degeneracy of $\pairing_\rG$. Moreover, it has a convenient matrix description: if $\chi$ is a Gram matrix of $\pairing_\rG$, then, provided that $\chi^{-1}$ is an integral matrix, $\chi^{-1} \chi^T$ is a Serre operator. In particular, if $G$ is unimodular then $\chi^{-1}$ is integral, hence all unimodular pseudolattices have a Serre operator. 

An important class of unimodular pseudolattices is given by those admitting  an exceptional basis:

\begin{definition}
    An element $e\in \rG$ is called exceptional if $\pair{e,e}_\rG=1$. A sequence of elements $e_\bullet=(e_1,\ldots,e_n)$ is exceptional if every $e_i$ is exceptional, and $\pair{e_i,e_j}_\rG=0$ for all $i>j$. An exceptional basis of $\rG$ is an exceptional sequence whose elements form a basis of $\rG$.
\end{definition}

If $\rG$ admits an exceptional basis, then $\rG$ is unimodular as the Gram matrix of the pairing written in the exceptional basis is triangular with $1$ on the diagonal.

Let $e\in \rG$ be an exceptional element. 

\begin{definition}
\label{def:num-mutation}
    The left and right mutation with respect to $e$ are endomorphisms of $\rG$ defined, respectively, by 
    \begin{equation}
        \sfL_e(v) = v - \pair{e,v}e, \qquad \sfR_e(v) = v - \pair{v,e}e
    \end{equation}
\end{definition}

Given an exceptional sequence $e_\bullet = (e_1,\ldots, e_n)$, the sequences
\begin{equation}
\begin{alignedat}{3}
        \sfL_{i}(e_\bullet) & \coloneqq (e_1,\ldots, e_{i-1}, \sfL_{e_{i}}(e_{i+1}), e_i,  e_{i+2},\ldots, e_n)\\
        \sfR_{i}(e_\bullet) & \coloneqq (e_1,\ldots, e_{i-1},  e_{i+1},  \sfR_{e_{i+1}}(e_i),  e_{i+2},\ldots, e_n)
\end{alignedat}
\end{equation}
(here $i=0,\ldots,n-1$) are both exceptional, and these two operations are mutual inverses.



\begin{definition}
A pseudolattice $\rG$ is \textit{surface-like} if there exists a primitive element $\bfp\in \rG$, called a \textit{point-like} object, satisfying:
\begin{itemize}
    \item $\pair{\bfp,\bfp}_\rG=0$;
    \item $\pair{\bfp,v}_\rG = \pair{v,\bfp}_\rG$ for all $v\in \rG$;
    \item The bilinear form $\pairing_\rG$ is symmetric on $\bfp^\perp = {}^\perp\!\bfp$. 
\end{itemize}
\end{definition}

One then defines the \textit{rank} of an element $v$ in a surface-like pseudolattice $\rG$ to be 
\begin{equation}
    \label{eq:defRank}
    \rk(v) \coloneqq \pair{\bfp,v}_\rG = \pair{v,\bfp}_\rG
\end{equation}


There is a filtration 
\begin{equation}
    \label{eq:filtrationPseudolattice}
  \Z\bfp\subseteq \bfp^\perp=\ker(\rk) \subseteq \rG. 
\end{equation}
The middle factor $\bfp^\perp/\bfp$ is called the N\'eron--Severi group of $\rG$ and is denoted by $\NS(\rG)$. The pairing $\chi$ restricts on $\NS(\rG)$ to a \textit{symmetric} bilinear form.
When it exists, the Serre operator acts as the identity on the factors of \eqref{eq:filtrationPseudolattice}. 

In \cite[Section 4]{Kuz17_pseudolattices}, the problem of classifying surface-like pseudolattices leads to considering the \textit{norm} of an exceptional basis $e_\bullet$, defined as the quantity 
\[ \left\lVert e_\bullet \right\rVert \coloneqq \sum_{i=1}^n \rk(e_i)^2. \]
We say that $e_\bullet$ is norm-minimal if the norm of any exceptional basis obtained from $e_\bullet$ by a sequence of mutations is greater than or equal to the norm of $e_\bullet$.



\begin{example}[Del Pezzo surfaces]\label{ex:DP}
Let $X_d$ be a del Pezzo surface of degree $d$ that is a blowup of $\pr 2$ in $\ell=9-d$ distinct points.
By Orlov's blowup formula, there is a semiorthogonal decomposition (SOD)
\begin{equation}
    D^b(\Coh(X_d))=\left\langle D^b(\pr 2), \sO_{E_1},\ldots,\sO_{E_{\ell}}  \right\rangle
\end{equation}
where the $E_i$ are the exceptional divisors of the blow-up. 

We abbreviate $K_0(D^b(\Coh(X_d)))$ by $K_0(X_d)$.  The SOD above implies that the Euler pairing $\chi$ on $K_0(X_d)$ is non-degenerate, hence $K_0(X_d)$ coincides with the numerical Grothendieck group. Then, equipped with the Euler pairing, $K_0(X_d)$ is a pseudolattice of rank $3+\ell$.  A Serre operator is defined by the action of the Serre functor $- \otimes \omega_{X_d}[2]$ of $D^b(\Coh(X_d))$ on $K_0(X_d)$.

By picking, for example, the exceptional collection $D^b(\Coh(\pr 2))=(\sO_{\pr 2}, \sT(-1), \sO_{\pr 2}(1))$ we obtain an exceptional basis for $K_0(X_d)$: 
\begin{equation}
    ([\sO_{X_d}], [\pi^*\sT(-1)], [\sO_{X_d}(1)], [\sO_{E_1}],\ldots,[\sO_{E_\ell}])
\label{eq:ExcBasisDP}
\end{equation}
Here, $[-]$ denotes the class of an object of $D^b(\Coh(X_d))$ in $K_0(X_d)$.
The Gram matrix of the Euler pairing in the basis \eqref{eq:ExcBasisDP} reads
\begin{equation}\label{eq:GramDP}
{%\scriptsize
M_\ell\coloneqq \left(\begin{array}{c|c}
    \begin{array}{ccc}
      1  & 3 & 3        \\
       0  & 1 & 3      \\
        0  & 0 & 1      
    \end{array} &
    \begin{array}{ccc}
         1 & \ldots &  1 \\
        2 & \ldots &  2 \\
          1 & \ldots &  1 
    \end{array} \\
    \hline
    &\\
    \text{\large $0_{\ell \times 3}$} & \text{\large $I_{\ell\times \ell}$}\\
    &\\
    \end{array}\right)
    }
\end{equation}

The pseudolattice $(K_0(X_d),\chi)$ is surface-like with point-like element $\bfp\coloneqq [\sO_p]$ the class of a skyscraper sheaf on $X_d$. With this choice, the N\'eron--Severi lattice of $K_0(X_d)$ is identified with $\NS(X_d)$. A basis for $\NS(X_d)$ is given by the cohomology classes of the strict transform of a line from $\pr 2$ and of each exceptional divisor. Then,  it is immediate to see that $\NS(X_d)$ is the rank $\ell+1$ lattice $\sfI^{1,\ell}$, defined as $\Z^{\ell+1}$ equipped with the bilinear form $\mathrm{diag}(1,-1,\ldots,-1)$ with respect to the standard basis. 
Under this identification, a canonical divisor on $X_d$ has class 
\[ \bfk_\ell = (-3,1,\ldots,1). \]
The vector $\bfk_\ell$ 
is a canonical class in the sense of \cite[Section 3.3]{Kuz17_pseudolattices}. 
\end{example}


\begin{example}[Genus-$1$ Lefschetz fibrations]
\label{exa:HT}
    In Section \ref{sec:construct-Lf} we construct genus-$1$ Lefschetz fibrations $\wt_d \colon \Yt_d \to \CC$ with $d=1,2,3$ and equip their relative homology groups $H_2(\Yt_d,\Sigma;\Z)$ with the Seifert pairing. The result is a surface-like pseudolattice
\begin{equation} 
\label{eq:defOfHl}
\left( H_2(\Yt_d,\Sigma; \Z), \pairing_{\mathrm{Sft}} \right)    
\end{equation}
More generally, pseudolattices associated with genus-$1$ Lefschetz fibrations are studied in \cite[Section 4.2]{HarderThompson20}, where they are also constructed abstractly by gluing smaller pseudolattices along a spherical homomorphism. % \cite[Section 2.4]{HarderThompson20}.
The homomorphism in question is called the \emph{asymptotic charge} 
(see Section \ref{sec:GHS}). 
The Serre operator is induced by the action of global monodromy on the fibration. % \cite[Proposition~4.4]{HarderThompson20}.
By \cite[Corollary 4.17]{HarderThompson20} and \cite[Theorem 5.1]{HarderThompson20}, $H_2(\Yt_d,\Sigma; \Z)$ is isometric to $K_0(X_d)$. 

See \cite[Section 4]{GiovenzanaThompson} for a study of these pseudolattices for (non-Lefschetz) elliptic fibrations.
\end{example}

\begin{remark}\label{rmk:AKO-collections}
Let $(M_\ell, W_\ell)$ be the LG models constructed by \cite{AKO06} (see Section \ref{sec:geometry-cats}).
Choosing $W_\ell$ as a small perturbation of $W_0$ (so that three critical values lie near those of $W_0$ and the reminaing $\ell$ lie near $\infty$), 
\cite{AKO06} produces a full exceptional collection for $D^b(\lagvc(W_\ell))$. 
The exceptional collection gives rise to an exceptional basis for the pseudolattice $K_0(W_\ell) \simeq H_2(M_\ell,\Sigma;\Z)$ (where $\Sigma$ is a regular fiber). The Gram matrix of the pairing written in this exceptional basis coincides precisely with \eqref{eq:GramDP} (for $d=9-\ell$),
without the need to apply mutations. In particular, the Grothendieck groups $K_0(X_d)$ and $K_0(W_\ell)$ are immediately seen to be isometric.
\end{remark}


\subsection{Sequences of mutations}
\label{sec:thm}
Let $(Y^\prime, w^\prime)$ be an LG model obtained by restricting  to $\CC$ 
a rational minimal elliptic surface $S$ with a fibre $D$ of type $I_{d}$, with $d=1,2,3$.
This includes the LG models $(Y_d,w_d)$ in Equation \eqref{eq:Yw},   $(\widetilde{Y}_d,\widetilde{w}_d)$ in Equation \eqref{eq:TildeYw}, and  $(M_\ell,W_\ell)$ in \cite{AKO06}. 
Its Fukaya-Seidel category $\mathrm{FS}(Y^\prime, w^\prime)$ is equivalent to $D^b\lagvc(\wt_d)$, arguing as in the proof of Proposition \ref{prop:EquivalenceYtildeAko}, or as in Remark \ref{rem:Y-mirror}.
In particular, we may identify the corresponding Grothendieck groups $K_0(w^\prime)$, which, by Example \ref{exa:HT}, or, alternatively, Remark \ref{rmk:AKO-collections},  are all isometric to $K_0(X_d)$. Moreover, all possible exceptional bases produced by such LG models are related to one-another by a sequence of mutations. 


In this Section we exhibit explicit sequences of mutations  which send the bases \eqref{eq:vc-dP1},\eqref{eq:vc-dP2}, \eqref{eq:vc-dP3} of the pseudolattices $H_2(\Yt_d,\Sigma; \Z)=K_0(\wt_d)$ in \eqref{eq:defOfHl} to  bases 
with respect to which
the Gram matrix of the pairing 
coincides with the matrix $M_\ell$ in \eqref{eq:GramDP}. 

Thus, Theorem \ref{thm:MutationSequence} relates in a direct way the exceptional bases arising from our construction of Section \ref{sec:ConstructionLefschetzFibrations} to those appearing in \cite{AKO06}.



\begin{thm}\label{thm:MutationSequence}
The following sequences of mutations map the exceptional bases \eqref{eq:vc-dP3}, \eqref{eq:vc-dP2}, and \eqref{eq:vc-dP1} to the exceptional bases
\begin{equation}\label{eq:BasisAfterMutations}
a+b,2a-b,a-2b,\underbrace{-b,\ldots,-b}_{\ell \mbox{ copies}}   
\end{equation}
whose associated Gram matrices coincide with the matrices $M_\ell$ in \eqref{eq:GramDP}, $\ell=6,7,8$.

\begin{align}
    \label{eq:mutationsFord3}
    d=3 \colon \quad & \mathbf{\beta}_3 \coloneqq \sfL_1 \cdot (\sfL_2\sfL_3) \cdot \sfL_1 \cdot \sfL_3 \cdot \sfL_1 \cdot (\sfL_4 \sfL_5 \sfL_6  \sfL_7) 
 \cdot (\sfL_3 \sfL_4 \sfL_5) \cdot (\sfL_2  \sfL_3) \cdot \sfL_1\\   \label{eq:mutationsFord2}    d=2 \colon \quad & \beta_2\coloneqq  \beta_3  \cdot(\sfR_8 \cdot \ldots \cdot \sfR_1) \cdot (\sfR_8\cdot \sfR_7 \cdot \sfL_4)\\
 \label{eq:mutationsFord1} d=1 \colon \quad & \beta_1 \coloneqq \beta_2 \cdot (\sfR_9 \cdot \ldots \cdot \sfR_4) \cdot \sfL_6 
    \end{align}
\end{thm}


\begin{remark}
\label{rem:change-basis}
 The change of basis $a \mapsto -a$, $b\mapsto -(a+b)$ turns \eqref{eq:BasisAfterMutations}  into the exceptional basis obtained in \cite[Section 3.3]{AKO06}.    
\end{remark}

Let $(Y^\prime, w^\prime)$ be an LG model as above.
If $(Y^\prime, w^\prime)$ defines a Lefschetz fibration, Theorem \ref{thm:MutationSequence} provides a tool to obtain an explicit sequence of mutations realizing an isometry between $K_0(X_d)$ and the pseudolattice  $H_2(Y^\prime,\Sigma;\Z)$ (with $\Sigma$ a general fiber), mapping the exceptional basis of vanishing thimbles of $(Y',w')$ to the basis \eqref{eq:ExcBasisDP}. 
Indeed, in this case $Y'$ admits a Weierstrass equation: interpolating it with the equation of $\Yt$, 
one can keep track of the trajectories of the critical values, and these in turn yield a sequence of mutations relating the corresponding pseudolattices. %Fukaya--Seidel Categories. 
For example, if two critical values $\lambda_1,\lambda_2$ with associated exceptional pair $(L_1,L_2)$ with respect to arcs $(\gamma_1, \gamma_2)$ move as in Figure \ref{fig:Mutations_VC}, then the exceptional pair $(L_1',L_2')$ associated to the arcs $(\gamma_1',\gamma_2')$ is equivalent to the right mutation $(L_1,L_2) \mapsto 
%(L_1',L_2')=
(L_2,\sfR_{L_2}(L_1))$. 


