\begin{lem}\label{lem:1if}
	Let $B'$ be a support block in $\sigma_{\mathcal{B}}$, $c_i$ be a cut vertex of $B'$ processed in the first round, and $B_{ij}$ be an end block containing the vertex $c_i$. 

	\noindent(a) If $l_2(B_{ij})\geq 2$, then $\gamma(G)=\gamma(G')$, where $G'$ is obtained by relabelling $\max\{(3-|r(V(B_{ij}))|),0\}$ vertices of $B_{ij}$ with priority $c_i$ as $R$ and every other label remains the same.

	\noindent(b) If $l_2(B_{ij})= 1$, then $\gamma(G)=\gamma(G')$, where $G'$ is obtained by relabelling $\max\{(2-|r(V(B_{ij}))|),0\}$ vertices of $B_{ij}$ with priority $c_i$ as $R$ and every other label remains the same. 

	\noindent(c) If $l_2(B_{ij})=0$ and $l_1(B_{ij})\geq 1$, then $\gamma(G)=\gamma(G')$, where $G'$ is obtained by relabelling $\max\{(1-|r(V(B_{ij})|)),0\}$ vertices of $B_{ij}$ with priority $c_i$ as $R$ and every other label remains the same.
	%and $s_j=s_j-(3-r(B_p))$.

	\noindent(d) $\gamma(G)=\gamma(G')$, where $G'$ is obtained by relabelling $s_{max}-|r(V(B_{ij}))|$ vertices of $B_{ij}$ as $R$ with priority $c_i$ and every other label remains the same.
\end{lem}

\begin{proof}
	\noindent(a) Let $L$ be a minimum $M_{LVE}$-dominating set of $G$. Since $l_2(B_{ij})\geq 2$, there exists at least two edges of $B_{ij}$ which are not incident to $c_i$, say $e_p$ and $e_q$, with $k(e_p)=k(e_q)=2$. Now, by the definition of $L$, we have $|(N_G[e_p]\cup N_G[e_q])\cap L|\geq \max\{k(e_p)+k(e_q)-1,0\}=3$. Observe that $N_G[e_p]$ and $N_G[e_q]$ are the subset of vertices of $B_{ij}$. Since every vertex $v\in B_{ij}$ with $t(v)=R$ is in $L$, we have $r(V(B_{ij}))\subset L$. Therefore, $L$ must contain at least $\max\{(3-|r(V(B_{ij}))|),0\}$ vertices of $B_{ij}$ having $t$-label $B$ in $G$. Let $L'$ be the set obtained from $L$ by replacing $\max\{(3-|r(V(B_{ij}))|),0\}$ vertices of $B_{ij}$ having $t$-label $B$ in $G$ with the vertices of $B_{ij}$ having $t'$-label $R$ in $G'$. Since every other label remains the same, it is easy to observe that $L'$ is a $M_{LVE}$-dominating set of $G'$. Hence, we have $\gamma(G')\leq \gamma(G)$. 

	Conversely, let $L'$ be a minimum $M_{LVE}$-dominating set of $G'$. Since every edge of $G'$ has same $k$-label as $G$ and every vertex of $G'$ has the same $M_V$-label as $G$ except for $\max\{(3-|r(V(B_{ij}))|),0\}$ many vertices of $B_{ij}$. Therefore, $L'$ is a $M_{LVE}$-dominating set of $G$. Hence, we have 
	$\gamma(G)\leq \gamma(G')$. Thus, $\gamma(G)=\gamma(G')$. \qed

	\noindent(b) Let $L$ be a minimum $M_{LVE}$-dominating set of $G$. Since $l_2(B_{ij})=1$, there exists exactly one edge of $B_{ij}$ which is not incident to $c_i$, say $e_p$, with $k(e_p)=2$. Now, by the definition of $L$, we have $|N_G[e_p]\cap L|\geq k(e_p)=2$. Observe that $N_G[e_p]$ is the set of vertices of $B_{ij}$. Since every vertex $v\in B_{ij}$ with $t(v)=R$ is in $L$, we have $r(V(B_{ij}))\subset L$. Therefore, $L$ must contain at least $\max\{(2-|r(V(B_{ij}))|),0\}$ vertices of $B_{ij}$ having $t$-label $B$ in $G$. Let $L'$ be the set obtained from $L$ by replacing $\max\{(2-|r(V(B_{ij}))|),0\}$ vertices of $B_{ij}$ having $t$-label $B$ in $G$ with the vertices of $B_{ij}$ having $t'$-label $R$ in $G'$. Since every other label remains the same, it is easy to observe that $L'$ is a $M_{LVE}$-dominating set of $G'$. Hence, we have $\gamma(G')\leq \gamma(G)$. 

	Conversely, let $L'$ be a minimum $M_{LVE}$-dominating set of $G'$. Since every edge of $G'$ has same $k$-label as $G$ and every vertex of $G'$ has the same $M_V$-label as $G$ except for $\max\{(2-|r(V(B_{ij}))|),0\}$ many vertices of $B_{ij}$. Therefore, $L'$ is a $M_{LVE}$-dominating set of $G$. Hence, we have $\gamma(G)\leq \gamma(G')$. Thus, we have $\gamma(G)=\gamma(G')$.\qed

	\noindent(c) Let $L$ be a minimum $M_{LVE}$-dominating set of $G$. Since $l_2(B_{ij})=0$ and $l_1(B_{ij})\geq 1$, the maximum $k$-label of the edges of $B_{ij}$ which is not incident to $c_i$ is $1$. Let $e_p$ be such an edge with $k(e_p)=1$. Now, by the definition of $L$, we have $|N_G[e_p]\cap L|\geq k(e_p)=1$. Observe that $N_G[e_p]$ is the set of vertices of $B_{ij}$. Since every vertex $v\in B_{ij}$ with $t(v)=R$ is in $L$, we have $r(V(B_{ij}))\subset L$. Therefore, $L$ must contain at least $\max\{(1-|r(V(B_{ij}))|),0\}$ vertices of $B_{ij}$ having $t$-label $B$ in $G$. Let $L'$ be the set obtained from $L$ by replacing $\max\{(1-|r(V(B_{ij}))|),0\}$ vertices of $B_{ij}$ having $t$-label $B$ in $G$ with the vertices of $B_{ij}$ having $t'$-label $R$ in $G'$. Since every other label remains the same, it is easy to observe that $L'$ is a $M_{LVE}$-dominating set of $G'$. Hence, we have $\gamma(G')\leq \gamma(G)$. 

	Conversely, let $L'$ be a minimum $M_{LVE}$-dominating set of $G'$. Since every edge of $G'$ has same $k$-label as $G$ and every vertex of $G'$ has the same $M_V$-label as $G$ except for $\max\{(1-|r(V(B_{ij}))|),0\}$ many vertices of $B_{ij}$. Therefore, $L'$ is a $M_{LVE}$-dominating set of $G$. Hence, we have $\gamma(G)\leq \gamma(G')$. Thus, we have $\gamma(G)=\gamma(G')$.\qed

	\noindent(d) Let $L$ be a $M_{LVE}$-dominating set of $G$. Thus, for every vertex $v\in V$, we have $|N_G[v]\cap L|\geq s(v)$. Let $s_{max}=\max\{s(v ):v\in V(B_{ij})\setminus\{c_i\}\}$. Hence, $|N_G[v]\cap L|\geq s_{max}$ for any $v\in V(B_{ij})$. Now, for any vertex $v\in V(B_{ij})\setminus\{c_i\}$, $N_G[v]$ is a subset of $V(B_{ij})$. Since every vertex with $t$-label $R$ is in $L$, we have $r(V(B_{ij}))\subseteq L$. This implies that $L$ must contain at least $\max\{(s_{max}-|r(V(B_{ij}))|),0\}$ vertices of $V(B_{ij})$ having $t$-label $B$. Let $L'$ be the set obtained from $L$ by replacing the $\max\{(s_{max}-|r(V(B_{ij}))|),0\}$ vertices of $V(B_{ij})$ having $t$-label $B$ in $G$ with the $\max\{(s_{max}-|r(V(B_{ij}))|),0\}$ vertices of $V(B_{ij})$ having $t'$-label $R$ in $G'$. Since every other label remains the same, it is easy to observe that $L'$ is a $M_{LVE}$-dominating set of $G'$. Hence, we have $\gamma(G')\leq \gamma(G)$. 

	Conversely, let $L'$ be a minimum $M_{LVE}$-dominating set of $G'$. Since every edge of $G'$ has same $k$-label as $G$ and every vertex of $G'$ has the same $M_V$-label as $G$ except for $\max\{(s_{max}-|r(V(B_{ij}))|),0\}$ many vertices of $B_{ij}$. Therefore, $L'$ is a $M_{LVE}$-dominating set of $G$. Hence, we have $\gamma(G)\leq \gamma(G')$. Thus, we have $\gamma(G)=\gamma(G')$.
	%	Proof of (b) and (c) are similar to the proof of (a). The proofs are given in Appendix.
	%	
	%	Proof of (d) is moved to Appendix due to space constraints.\qed
\end{proof}

From Lemma \ref{lem:1if}, it follows that after the first round the labeling of $G$ is such that for any edge $e$ of any descendant block $B_{ij}$ of $B'$ which is not incident to the cut vertex $c_i$ of $B_{ij}$, $k(e)\leq |r(N_G[c_i])|$, for every pair of edges $(e,e')$ of every end block $B_{ij}$ of $B'$ which is not incident to the cut vertex $c_i$ of $B_{ij}$, $\max\{k(e)+k(e')-1,0\}\leq |r(N_G[c_i])|$ and for every non-cut vertex $v$ of every end block $B_{ij}$, $s(v)<|r(N_G[c_i])|$ where $c_i$ is the cut vertex of $B_{ij}$. Considering these assumptions, we now prove the correctness of the algorithm for the second round of processing of the cut vertices of the support block $B'$. 
