The following proposition guarantees that after the first round of processing of the edge $e_i$, the construction of the set $L_{i_1}$ is such that every edge $e_j$, where $i<j<min$, satisfies the conditions of liar's ve-domination.

\begin{pre}\label{Prop:everyedgefrmoitomin}
	At $i$-th iteration, after the first round of processing of the edge $e_i$, for any edge $e_j$ with $i<j<min$, $|N_G[e_j]\cap L_{i_1}|\geq 3$.
\end{pre}

\begin{proof}
	We prove this using contradiction. Let $e_j$ be an edge with $i<j<min$, such that $|N_G[e_j]\cap L_{i_1}|\leq 2$. Note that, if $|N_G[e_j]\cap L_{i_1}|<2$, then there is an edge $e_j$ with $i<j<min$ which contradicts the fact that $e_{min}$ be the minimum index edge with such property. Therefore, assume that $|N_G[e_j]\cap L_{i_1}|=2$. Since $j<min$, we have $N_G[e_j]\cap L_{i_1}\neq N_G[e_i]\cap L_{i_1}$. Thus, there is a vertex $v\in N_G[e_j]\cap L_{i_1}$ such that $v\notin N_G[e_i]$. Hence, by Observation \ref{Obs:vnotintheedgee} we have $r(e_i)<l(v)$ or $l(e_i)>r(v)$. Since $v\in N_G[e_j]$, we have $r(e_j)>l(v)$ and $l(e_j)<r(v)$. Thus, we have $l(e_j)<r(v)<l(e_i)$ and using the fact that $r(e_j)\geq r(e_i)$ as $j>i$, we have $I(e_i)\subseteq I(e_j)$. Thus, for any vertex $u\in N_G[e_i]$, we have $I(u)\cap I(e_j)\neq \emptyset$. This implies that $|N_G[e_j]\cap L_{i_1}|\geq 3$ which is a contradiction. Therefore, after the first round, for any edge $e_j$ with $i<j<min$, we have $|N_G[e_j]\cap L_{i_1}|\geq 3$. 
\end{proof}

The next two propositions ensure that after the second round of processing of the edge $e_i$, every pair of edges $(e_i,e_j)$, where $e_j$ is an edge in $\sigma_E$ with $j>min$, and $N_G[e_i]\cap N_G[e_j]\neq \emptyset$, satisfies the condition $(ii)$ of liar's ve-domination.

\begin{pre}\label{Prop:secondcondition}
	At $i$-th iteration, after the first round of processing of the edge $e_i$, if $|N_G[e_{min}]\cap L_{i_1}|<2$, then for every edge $e_j$ such that $j>min$ and $N_G[e_i]\cap N_G[e_j]\neq \emptyset$ , there is a vertex $v\in T^q[N_G[e_{min}]\setminus L_{i_1}]$ such that $v\in N_G[e_i]\cup N_G[e_j]$, where $q=2-|N_G[e_{min}]\setminus L_{i_1}|$. 
\end{pre}

\begin{proof}
	Let $v\in T^q[N_G[e_{min}]\setminus L_{i_1}]$ be a vertex such that $v\notin N_G[e_i]$. Hence, by Observation \ref{Obs:vnotintheedgee} either $l(v)>r(e_i)$ or $r(v)<l(e_i)$. Also, note that $v\in N_G[e_{min}]$ and $min>i$. Thus, $r(v)>l(e_{min})$ and $r(e_{min})>l(v)$. Suppose that $r(v)<l(e_i)$. Therefore, we have $I(e_i)\subset I(e_{min})$ which contradicts the fact that $|N_G[e_{min}]\cap L_{i_1}|<2$. Hence,  $l(v)>r(e_i)$. Since $N_G[e_i]\cap N_G[e_j]\neq \emptyset$, suppose that $u\in N_G[e_i]\cap N_G[e_j]$. Now, $l(u)<r(e_j)$ and $r(u)>l(e_j)$. Also, $l(u)<r(e_i)$ and $r(u)>l(e_i)$. Therefore, $l(u)<r(e_i)<l(v)$ and if $r(u)>r(v)$, then $I(v)\subset I(u)$ which is a contradiction. Hence, $r(u)<r(v)$. Now, $r(e_j)>r(e_{min})>l(v)$ and $r(v)>r(u)>l(e_j)$. Therefore, $I(v)\cap I(e_j)\neq \emptyset$. Hence, $v\in N_G[e_i]\cup N_G[e_j]$.
\end{proof}

\begin{pre}\label{Prop:thirdcondition}
	At $i$-th iteration, after the first round of processing of the edge $e_i$, if $N_G[e_{min}]\cap L_{i_1}= N_G[e_i]\cap L_{i_1}$, then for every edge $e_j$ such that $j>min$ and $N_G[e_i]\cap N_G[e_j]\neq \emptyset$, there is a vertex $v\in T^1[N_G[e_{min}]\setminus L_{i_1}]$ such that $v\in N_G[e_i]\cup N_G[e_j]$.
\end{pre}

\begin{proof}
	The proof is similar to the proof of Proposition \ref{Prop:secondcondition} and hence, omitted.
	%Let $u\in L_{i_1}$ such that $u\in N_G[e_i]\cap N_G[e_{min}]$. Thus, $u\in N_G[e_j]$ for any edge $e_j$ with $j>min$ and $N_G[e_i]\cap L_{i_1}=N_G[e_j]\cap L_{i_1}$. This implies that $r(u)>l(e_j)$ and $l(u)<r(e_j)$. Since $u\in N_G[e_{min}]$, we have $r(u)>l(e_{min})$ and $l(u)<r(e_{min})$. Also, $v\in N_G[e_{min}]$ and thus $r(v)>l(e_{min})$ and $l(v)<r(e_{min})$. Now, either $r(u)< r(v)$ and $l(v)>l(u)$ or $r(v)<r(u)$ and $l(v)<l(u)$. If $r(u)< r(v)$, then $l(e_j)<r(v)$. Also, $r(e_j)\geq r(e_{min})$ and thus $r(e_j)>l(v)$. Therefore, $I(e_j)\cap I(v)\neq \emptyset$. Note that, $r(u)>l(e_i)$ and $l(u)<r(e_i)$. Now, if $r(u)>r(v)$ and $l(v)<l(u)$, then $l(v)<r(e_i)$ and $r(v)>r(e_{min})\geq r(e_i)>l(e_i)$. Therefore, $I(v)\cap I(e_i)\neq \emptyset$. This implies that $v\in N_G[e_i]$. Thus, $v\in N_G[e_i]\cup N_G[e_j]$.
\end{proof}
Note that, after the second round of processing of $e_i$, either $L_{i}=L_{i_1}\cup T^q[N_G[e_{min}]\setminus L_{i_1}]$ or $L_{i}=L_{i_1}\cup T^1[N_G[e_{min}]\setminus L_{i_1}]$. Therefore, we have $|(N_G[e_i]\cup N_G[e_j])\cap L_i|\geq 3$, for any edge $e_j$ with $j\geq min$, and $N_G[e_j]\cap N_G[e_i]\neq \emptyset$.

In Algorithm \ref{Algo:Interval}, at $i$-th iteration there are two cases. If $|N_G[e_i]\cap L_{i-1}|\geq 3$, then $L_{i-1}=L_i$. If $|N_G[e_i]\cap L_{i-1}|\leq 2$, then it is easy to see that after the first round of $i$-th iteration, we have $|N_G[e_i]\cap L_{i_1}|= 2$. Since $L_{i_1}\subseteq L_i$, for every edge $e_j\in E_{i}$, we have $|N_G[e_i]\cap L_{i}|\geq 2$. Hence, we have the following observation.

\begin{obs}\label{Obs:firstcondition}
	At $i$-th iteration after the first round of processing of $e_i$, $L_{i}$ satisfy the condition that for every $e_j\in E_{i}$, $|N_G[e_j]\cap L_{i}|\geq 2$.
\end{obs}

Now, we show that after $i$-th iteration, every edge in $E_i$ satisfies the conditions of liar's ve-domination. 

\begin{pre}\label{Prop:Liar'sdomset}
	After the first round of processing of $e_i$, let $L_{i_1}$ be the set such that $|N_G[e_i]\cap L_{i_1}|\geq 2$. Also, assume that $e_{min}$ be the edge with minimum index in $\sigma_E$ such that $min>i$ and either $|N_G[e_{min}]\cap L_{i_1}|<2$ or $N_G[e_{min}]\cap L_{i_1}=N_G[e_i]\cap L_{i_1}$, where $|N_G[e_i]\cap L_{i_1}|=2$. After $i$-th iteration, $L_{i}$ satisfies the following properties:

	\noindent(a) $|N_G[e_k]\cap L_{i}|\geq 2$, for every edge $e_k$ in $E_i$

	\noindent(b) $|(N_G[e_k]\cup N_G[e_a])\cap L_{i}|\geq 3$, for every pair of distinct edges $e_k,e_a\in E_i$

	\noindent(c) $|(N_G[e_k]\cup N_G[e_a])\cap L_{i}|\geq 3$, where $e_k\in E_i$ and $e_a\in E\setminus E_i$ such that either $i<a\leq min$ or $a>min$ and $N_G[e_i]\cap N_G[e_a]\neq \emptyset$.
\end{pre}

\begin{proof}
	We prove this using induction on $i$. The proof of part $(a)$ follows from Observation \ref{Obs:firstcondition}. 

	Next, we prove part $(b)$. At $i=1$, there is only one edge in $E_i$ and thus, the statement is vacuously true. After the second round of processing of the edge $e_{i-1}$, let $L_{(i-1)_1}$ be the set of vertices such that $|N_G[e_{i-1}]\cap L_{(i-1)_1}|\geq 2$ and $e_{{min}_1}$ be the edge with minimum index in $\sigma_E$ such that ${min}_1>(i-1)$ and either $|N_G[e_{{min}_1}]\cap L_{(i-1)_1}|\geq 2$ or $N_G[e_{{min}_1}]\cap L_{(i-1)_1}=N_G[e_{i-1}]\cap L_{(i-1)_1}$. After $(i-1)$-th iteration, let $L_{i-1}$ be a set having the following properties: for every edge $e_k\in E_{i-1}$, $|N_G[e_k]\cap L_{i-1}|\geq 2$, for every pair of distinct edges $e_k,e_a\in E_{i-1}$, $|(N_G[e_k]\cup N_G[e_a])\cap L_{i-1}|\geq 3$, and for every pair of edges $(e_k,e_a)$, where $e_k\in E_{i-1}$ and $e_a$ be an edge such that either $(i-1)<a\leq min_1$ or $a>min_1$ and $N_G[e_{i-1}]\cap N_G[e_a]\neq \emptyset$. Observe that, $i\leq min_1$ and $L_{i-1}\subseteq L_i$. Therefore, for every edge $e_k\in E_{i-1}$, we have $|(N_G[e_k]\cup N_G[e_i])\cap L_i|\geq 3$.



	Finally, we prove part $(c)$. At $i=1$, after the first round $|N_G[e_1]\cap L_{1_1}|=2$, where $L_{1_1}=T^2[N_G[e_1]]$. Let $u\in T^2[N_G[e_1]]$ such that $r(u)\leq r(v)$ for any $v\in T^2[N_G[e_1]]$. Since $G$ is connected and $r(e_2)\leq r(u)$, we have $r(e_2)\leq r(v)$ and thus $l(e_2)\leq r(v)$ for any $v\in T^2[N_G[e_1]]$. Also, $l(v)<r(e_1)\leq r(e_2)$ and therefore, $I(v)\cap I(e_2)\neq \emptyset$ for any $v\in T^2[N_G[e_1]]$. Hence, $N_G[e_2]\cap L_{1_1}=N_G[e_1]\cap L_{1_1}$. Since $L_{1_1}\subseteq L_1$, using Proposition \ref{Prop:thirdcondition}, we have $|(N_G[e_1]\cup N_G[e_a])\cap L_{1}|\geq 3$ for any edge $e_a$ with $a\geq 2$, and $N_G[e_1]\cap N_G[e_a]\neq \emptyset$. Let us assume that after $(i-1)$-th iteration, $|(N_G[e_k]\cup N_G[e_a])\cap L_{i-1}|\geq 3$, for every pair of edges $e_k\in E_{i-1}$ and $e_a\in E\setminus\{e_k\}$ with $N_G[e_a]\cap N_G[e_k]\neq \emptyset$. From Observation \ref{Obs:firstcondition}, we have $|N_G[e_i]\cap L_{i_1}|\geq 2$. If $|N_G[e_i]\cap L_{i_1}|\geq 3$, then we are done. Otherwise, let $|N_G[e_i]\cap L_{i_1}|=2$ and $e_{min}$ be the minimum index edge such that $min>i$ and $N_G[e_i]\cap L_{i_1}=N_G[e_{min}]\cap L_{i_1}$ where $L_{i_1}=L_{i-1}\cup T^q[N_G[e_i]\setminus L_{i-1}]$. From Proposition \ref{Prop:secondcondition} and \ref{Prop:thirdcondition}, for every pair of edges $e_j$ with $j\geq min$ and $N_G[e_i]\cap N_G[e_j]\neq \emptyset$, we have $|(N_G[e_i]\cup N_G[e_{j}])\cap L_{i}|\geq 3$. Let $e_k$ be an edge such that $i<k<min$. From Proposition \ref{Prop:everyedgefrmoitomin}, we have $|N_G[e_k]\cap L_{i}|\geq 3$. Hence, $|(N_G[e_k]\cup N_G[e_a])\cap L_{i}|\geq 3$, for every pair of edges $e_k\in E_i$ and $e_a\in E\setminus E_i$ such that either $i<a\leq min$ or $a>min$ and $N_G[e_a]\cap N_G[e_i]\neq \emptyset$.
\end{proof}
