Next, we show the minimality of the liar's ve-dominating set returned by Algorithm \ref{Algo:Interval}. We prove this using induction. We show that after $i$-th iteration, under different cases, $L_i$ is contained in a minimum liar's ve-dominating set. Therefore, at the end of the algorithm, it returns a minimum liar's ve-dominating set.

\begin{lem}
	At $i$-th iteration, let $|N_G[e_i]\cap L_{i-1}|\leq 2$. If $L_{i-1}$ is contained in some minimum liar's ve-dominating set $L$ of $G$, then there exists a minimum liar's ve-dominating set $L'$ of $G$ containing $L_i=L_{i-1}\cup T^q[N_G[e_i]\setminus L_{i-1}]$, where $q=2-|N_G[e_i]\cap L_{i-1}|$. 
\end{lem}

\begin{proof}
	Since $|N_G[e_i]\cap L_{i-1}|\leq 2$, there are $q=2-|N_G[e_i]\cap L_{i-1}|$ number of vertices, namely $\{v_1,v_2,\ldots,v_q\}$ in $N_G[e_i]\cap (L\setminus L_{i-1})$. Let us assume that $\{w_1,w_2\ldots,w_q\}\in T^q[N_G[e_i]\setminus L_{i-1}]$. If $v_j\in T^q[N_G[e_i]\setminus L_{i-1}]$ for every $j\in \{1,2,\ldots,q\}$, then we are done. Therefore, suppose that there is a vertex $v_j\in \{v_1,v_2,\ldots,v_q\}$ such that $v_j\notin T^q[N_G[e_i]\setminus L_{i-1}]$. Clearly, $r(v_j)<r(w_k)$, for any $k\in \{1,2,\ldots,q\}$. Let $e_a$ be an edge such that $v_j\in N_G[e_a]$ and $a\neq i$. Therefore, $r(v_j)>l(e_a)$ and $l(v_j)<r(e_a)$. Suppose that $a<i$. Now, from Proposition \ref{Prop:Liar'sdomset}, after $(i-1)$-th iteration, for any edge in $e_a\in E_{i-1}$, we have $|N_G[e_a]\cap L_{i-1}|\geq 2$ and for any edge $e_b$ such that $b>(i-1)$ and $N_G[e_a]\cap N_G[e_b]\neq \emptyset$, we have $|(N_G[e_a]\cup N_G[e_b])\cap L_{i-1}|\geq 3$. This implies that the vertices of $L_{i-1}$ is sufficient to satisfy the conditions of liar's ve-domination for the edge $e_a$. Also, if $a>i$, then $r(e_a)\geq r(e_i)$. Since $r(v_j)<r(w_k)$ for any $k\in\{1,2,\ldots,q\}$, we have $r(w_k)>l(e_a)$. Note that, $l(v_j)<l(w_k)$ otherwise $I(v_j)\subseteq I(w_k)$. Since $w_k\in N_G[e_i]$, we have $l(w_k)<r(e_i)\leq r(e_a)$. Hence $I(w_k)\cap I(e_a)\neq \emptyset$. Therefore, for every edge $e_a$ with $a>i$ which is ve-dominated by $v_j$, is also ve-dominated by $w_k\in T^q[N_G[e_i]\setminus L_{i-1}]$. Hence, $L'=(L\setminus\{v_1,v_2,\ldots,v_q\})\cup \{w_1,w_2,\ldots, w_q\}$ is a minimum liar's ve-dominating set of $G$. 
\end{proof}

\begin{lem}
	At $i$-th iteration, after the first round of processing of the edge $e_i$, let $L_{i-1}\subseteq L_{i_1}$, $|N_G[e_i]\cap L_{i_1}|=2$, and $e_{min}$ be the edge in $\sigma_E$ such that $min>i$, $|N_G[e_{min}]\cap L_{i_1}|<2$ and for every edge $i<p<min$, $|N_G[e_p]\cap L_{i_1}|\geq 3$. If $L_{i_1}$ is contained in some minimum liar's vertex-edge dominating set $L$ of $G$, then there exists a minimum liar's vertex-edge dominating set $L'$ of $G$ containing $L_i=L_{i_1}\cup T^q[N_G[e_{min}]\setminus L_{i_1}]$, where $q=2-|N_G[e_{min}]\setminus L_{i_1}|$.
\end{lem}

\begin{proof}
	Since $|N_G[e_{min}]\cap L_{i_1}|<2$, there are $q=2-|N_G[e_{min}]\setminus L_{i_1}|$ vertices, namely $\{v_1,v_2,\ldots,v_q\}$ in $N_G[e_{min}]\cap (L\setminus L_{i_1})$. Let us assume that $\{w_1,w_2\ldots,w_q\}\in T^q[N_G[e_{min}]\setminus L_{i_1}]$.  If $v_j\in T^q[N_G[e_i]\setminus L_{i-1}]$ for every $j\in \{1,2,\ldots,q\}$, then we are done. Therefore, suppose that there is a vertex $v_j\in \{v_1,v_2,\ldots,v_q\}$ such that $v_j\notin T^q[N_G[e_i]\setminus L_{i-1}]$. Clearly, $r(v_j)<r(w_k)$, for any $k\in \{1,2,\ldots,q\}$. Let $e_a$ be an edge such that $v_j\in N_G[e_a]$ and $a\neq i$. Therefore, $r(v_j)>l(e_a)$ and $l(v_j)<r(e_a)$. Suppose that $a<i$. Now, from Proposition \ref{Prop:Liar'sdomset}, after $(i-1)$-th iteration, for any edge in $e_a\in E_{i-1}$, we have $|N_G[e_a]\cap L_{i-1}|\geq 2$ and for any edge $e_b$ such that $b>(i-1)$ and $N_G[e_a]\cap N_G[e_b]\neq \emptyset$, we have $|(N_G[e_a]\cup N_G[e_b])\cap L_{i-1}|\geq 3$. This implies that the vertices of $L_{i-1}$, and hence vertices of $L_{i_1}$, are sufficient to satisfy the conditions of liar's ve-domination for the edge $e_a$. Now, for any edge $e_p$ with $i<p<min$, we have $|N_G[e_p]\cap L_{i_1}|\geq 3$. Therefore, if $i<a<min$, then $|N_G[e_a]\cap L_{i_1}|\geq 3$. Thus, vertices of $L_{i_1}$ are sufficient to satisfy the conditions of liar's ve-domination for the edge $e_a$. 
	Finally, assume that $a\geq min$. Since $r(v_j)<r(w_k)$ for any $k\in\{1,2,\ldots,q\}$, we have $r(w_k)>l(e_a)$. Note that, $l(v_j)<l(w_k)$, otherwise $I(v_j)\subseteq I(w_k)$. Since $w_k\in N_G[e_{min}]$, we have $l(w_k)<r(e_{min})\leq r(e_a)$. Hence $I(w_k)\cap I(e_a)\neq \emptyset$. Therefore, for every edge $e_a$ with $a>min$, which is ve-dominated by $v_j$, is also ve-dominated by $w_k\in T^q[N_G[e_{min}]\setminus L_{i_1}]$. Hence, $L'=(L\setminus\{v_1,v_2,\ldots,v_q\})\cup \{w_1,w_2,\ldots, w_q\}$ is a minimum liar's ve-dominating set of $G$.
	%If $v_j=w_j$ for every $j\in \{1,2,\ldots,q\}$, then we are done. So, let $v_j\notin \{w_1,w_2\ldots,w_q\}$. 
\end{proof}



\begin{lem}
	At $i$-th iteration, after the first round of processing of the edge $e_i$, let $L_{i-1}\subseteq L_{i_1}$, $|N_G[e_i]\cap L_{i_1}|=2$, and $e_{min}$ be the edge in $\sigma_E$ such that $min>i$,  $N_G[e_{min}]\cap L_{i_1}=N_G[e_i]\cap L_{i_1}$, and for every edge $i<p<min$, $|N_G[e_p]\cap L_{i_1}|\geq 3$. If $L_{i_1}$ is contained in some minimum liar's vertex-edge dominating set $L$ of $G$, then there exists a minimum liar's vertex-edge dominating set $L'$ of $G$ containing $L_i=L_{i_1}\cup T^1[N_G[e_{min}]\setminus L_{i_1}]$.
\end{lem}



\begin{proof}
	%From Proposition $9$, for any edge $e_j$ with $i<j<min$, we have $|N_G[e_j]\cap L_{i_1}|\geq 3$.
	Since $N_G[e_{min}]\cap L_{i_1}=N_G[e_i]\cap L_{i_1}$, to satisfy the condition $(ii)$ of liar's ve-domination for the pair of edges $(e_i,e_{min})$, there is a vertex, say $v$, in $(N_G[e_i]\cup N_G[e_{min}])\cap (L\setminus L_{i_1})$. Let us assume that $\{w\}= T^1[N_G[e_{min}]\setminus L_{i_1}]$. If $v=w$, then we are done. So, let $v\neq w$. Also, let $e_a$ is an edge such that $v\in N_G[e_a]$ and $a\neq i$. Therefore, $r(v)>l(e_a)$ and $l(v)<r(e_a)$. Suppose that $a<i$. Now, from Proposition \ref{Prop:Liar'sdomset}, after $(i-1)$-th iteration, for any edge in $e_a\in E_{i-1}$, we have $|N_G[e_a]\cap L_{i-1}|\geq 2$ and for any edge $e_b$ such that $b>(i-1)$ and $N_G[e_a]\cap N_G[e_b]\neq \emptyset$, we have $|(N_G[e_a]\cup N_G[e_b])\cap L_{i-1}|\geq 3$. This implies that the vertices of $L_{i-1}$, and hence vertices of $L_{i_1}$, are sufficient to satisfy the conditions of liar's ve-domination for the edge $e_a$. Now, for any edge $e_p$ with $i<p<min$, we have $|N_G[e_p]\cap L_{i_1}|\geq 3$. Therefore, if $i<a<min$, then $|N_G[e_a]\cap L_{i_1}|\geq 3$. Thus, vertices of $L_{i_1}$ are sufficient to satisfy the conditions of liar's ve-domination for the edge $e_a$. Finally, assume that $a\geq min$. Since $min>i$, $r(v)<r(w)$. Since $r(v)<r(w)$, we have $r(w)>l(e_a)$. Also, $l(v)<l(w)$ otherwise $I(v)\subseteq I(w)$. Since $w\in N_G[e_{min}]$, we have $l(w)<r(e_{min})\leq r(e_a)$. Hence $I(w_k)\cap I(e_a)\neq \emptyset$. Therefore, for every edge $e_a$ with $a>min$, which is ve-dominated by $v$, is also ve-dominated by $w$. Hence, $L'=(L\setminus\{v\})\cup \{w\}$ is a minimum liar's ve-dominating set of $G$.
\end{proof}



